/// `_player_max_energy` consumes `combat_sim.BASE_ENERGY` (frozen Python, deleted #2827).
const BASE_ENERGY: i16 = 3;

/// `_begin_player_turn_hand_draw` consumes `combat_sim.DRAWS_PER_TURN` (frozen Python, deleted #2827).
const DRAWS_PER_TURN: usize = 5;

pub(crate) fn knowledge_demon_state_is_exact(state: &HotState) -> bool {
    let [owner] = state.monsters.as_slice() else {
        return !state
            .monsters
            .iter()
            .any(|monster| monster.kind == MonsterKind::KnowledgeDemon)
            && [
                PowerId::Disintegration,
                PowerId::MindRot,
                PowerId::Sloth,
                PowerId::WasteAway,
            ]
            .into_iter()
            .all(|power| state.powers.get(power).is_none())
            && state.fanouts.sloth().is_none();
    };
    if owner.kind != MonsterKind::KnowledgeDemon {
        return [
            PowerId::Disintegration,
            PowerId::MindRot,
            PowerId::Sloth,
            PowerId::WasteAway,
        ]
        .into_iter()
        .all(|power| state.powers.get(power).is_none())
            && state.fanouts.sloth().is_none();
    }
    let Some(counter) = owner.knowledge_demon_curse_counter() else {
        return false;
    };
    if Some(owner.max_hp) != super::monsters::native_fixed_hp(state, MonsterKind::KnowledgeDemon)
        || owner.hp > owner.max_hp
        || state.multiplayer_ally_key != 0
        || state.fanouts.multiplayer_ally().key != 0
        || !(0..=3).contains(&owner.loop_pos)
        || counter == 0 && owner.loop_pos != 0
        || counter == 3 && owner.loop_pos == 0
        || !state.fanouts.cold_power_records_are_exact()
    {
        return false;
    }
    let amount = |power| match state.powers.get(power) {
        None => Some(0),
        Some(slot) if slot.wire == SlotWire::Int && slot.value > 0 => Some(slot.value),
        Some(_) => None,
    };
    let Some(tuple) = amount(PowerId::Disintegration)
        .zip(amount(PowerId::MindRot))
        .zip(amount(PowerId::Sloth))
        .zip(amount(PowerId::WasteAway))
        .map(|(((d, m), s), w)| (d, m, s, w))
    else {
        return false;
    };
    let reachable = match counter {
        0 => matches!(tuple, (0, 0, 0, 0)),
        1 => matches!(tuple, (6, 0, 0, 0) | (0, 1, 0, 0)),
        2 => matches!(
            tuple,
            (13, 0, 0, 0) | (6, 0, 3, 0) | (7, 1, 0, 0) | (0, 1, 3, 0)
        ),
        3 => matches!(
            tuple,
            (21, 0, 0, 0)
                | (13, 0, 0, 1)
                | (14, 0, 3, 0)
                | (6, 0, 3, 1)
                | (15, 1, 0, 0)
                | (7, 1, 0, 1)
                | (8, 1, 3, 0)
                | (0, 1, 3, 1)
        ),
        _ => false,
    };
    reachable
        && (tuple.2 == 3) == state.fanouts.sloth().is_some()
        && state
            .fanouts
            .sloth()
            .is_none_or(|private| private.cards_played_this_turn >= 0)
}

pub(crate) fn kd_pending_is_exact(state: &HotState) -> bool {
    if !knowledge_demon_state_is_exact(state) {
        return false;
    }
    let Some(pending) = state.pending.as_deref() else {
        return false;
    };
    let Some(record) = pending.enemy_phase_record(&state.frames) else {
        return false;
    };
    let [owner] = state.monsters.as_slice() else {
        return false;
    };
    owner.uid == record.actor_uid
        && owner.loop_pos == 0
        && owner
            .knowledge_demon_curse_counter()
            .is_some_and(|counter| counter < 3)
        && record.stage == 0
        && record.remaining_uids.is_empty()
}

pub(crate) fn after_player_turn_start_power_order_is_exact(state: &HotState) -> bool {
    let Some(order) = state.after_player_turn_start_order() else {
        return false;
    };
    if state.powers.is_empty() && order.is_empty() {
        // The getter has already authenticated the empty stored order and
        // generated-power metadata. With no slots, every listener and its
        // paired Inferno/Crimson private member is necessarily absent.
        return true;
    }
    let active = [
        (PowerId::Loop, state.powers.value(PowerId::Loop) > 0),
        (
            PowerId::RollingBoulder,
            state.powers.value(PowerId::RollingBoulder) > 0,
        ),
        (
            PowerId::SummonNextTurn,
            state.powers.value(PowerId::SummonNextTurn) > 0,
        ),
        (PowerId::Inferno, state.powers.value(PowerId::Inferno) > 0),
        (
            PowerId::CrimsonMantle,
            state.powers.value(PowerId::CrimsonMantle) > 0,
        ),
        (
            PowerId::ToolsOfTheTrade,
            state.powers.value(PowerId::ToolsOfTheTrade) > 0,
        ),
        (PowerId::Tyranny, state.powers.value(PowerId::Tyranny) > 0),
        (PowerId::Entropy, state.powers.value(PowerId::Entropy) > 0),
    ];
    state.fanouts.after_player_turn_start_order_is_exact()
        && order.len() == active.iter().filter(|(_, live)| *live).count()
        && active
            .iter()
            .all(|(power, live)| order.contains(power) == *live)
        && ((state.powers.value(PowerId::InfernoSelf) > 0)
            == (state.powers.value(PowerId::Inferno) > 0))
        && ((state.powers.value(PowerId::CrimsonSelf) > 0)
            == (state.powers.value(PowerId::CrimsonMantle) > 0))
}

pub(crate) fn turn_start_hand_choice_power_order_is_exact(state: &HotState) -> bool {
    after_player_turn_start_power_order_is_exact(state)
}

