/// Whether the frozen physical AutoPost walk can contain a local card.
///
/// The catalog bit is derived once at fight construction, so ordinary fights
/// pay one branch and never scan the catalog or live piles. A catalog-only
/// generated listener starts using this path automatically once it is minted into
/// any local pile.
#[inline]
fn card_auto_post_is_reachable(state: &HotState, catalog: &Catalog) -> bool {
    catalog.has_auto_post_card_listener()
        && [
            PileId::Hand,
            PileId::Draw,
            PileId::Discard,
            PileId::Exhaust,
            PileId::Play,
        ]
        .into_iter()
        .any(|pile| {
            state.piles.get(pile).as_slice().iter().any(|card| {
                catalog.spec(card.atom).is_some_and(|spec| {
                    matches!(
                        spec.identity.id,
                        CardId::HowlFromBeyond | CardId::IAmInvincible
                    )
                })
            })
        })
}

#[inline]
fn bombardment_auto_pre_is_reachable(state: &HotState, catalog: &Catalog) -> bool {
    PileId::ALL.into_iter().any(|pile| {
        state.piles.get(pile).as_slice().iter().any(|card| {
            catalog
                .spec(card.atom)
                .is_some_and(|spec| matches!(spec.identity.id, CardId::Bombardment))
        })
    })
}

fn capture_bombardment_auto_pre_listeners(
    state: &mut HotState,
    catalog: &Catalog,
) -> Result<Vec<u32>, EngineRefusal> {
    super::cards::normalize_card_identities(state)?;
    let mut listeners = Vec::new();
    for pile in [
        PileId::Hand,
        PileId::Draw,
        PileId::Discard,
        PileId::Exhaust,
        PileId::Play,
    ] {
        for card in state.piles.get(pile).as_slice() {
            let spec = catalog
                .spec(card.atom)
                .ok_or(EngineRefusal::UnknownAtom(card.atom))?;
            if matches!(spec.identity.id, CardId::Bombardment) {
                if !super::admission::bombardment_program_is_supported(spec.row)
                    || !matches!(spec.identity.upgrade, 0 | 1)
                {
                    return Err(EngineRefusal::MalformedArgs("Bombardment physical source"));
                }
                listeners.push(card.uid);
            }
        }
    }
    for uid in &listeners {
        let matches = PileId::ALL
            .into_iter()
            .flat_map(|pile| state.piles.get(pile).as_slice())
            .filter(|card| card.uid == *uid)
            .count();
        if matches != 1 {
            return Err(EngineRefusal::ActiveCardNotUnique { uid: *uid, matches });
        }
    }
    Ok(listeners)
}

pub(crate) fn exact_stampede_amount(state: &HotState) -> Result<Option<u32>, EngineRefusal> {
    match state.powers.get(PowerId::Stampede) {
        None => Ok(None),
        Some(slot) if slot.wire == SlotWire::Int && slot.value == 0 => Ok(None),
        Some(slot) if slot.wire == SlotWire::Int && slot.value > 0 => u32::try_from(slot.value)
            .map(Some)
            .map_err(|_| EngineRefusal::CounterOverflow("Stampede amount")),
        Some(_) => Err(EngineRefusal::MalformedArgs("StampedePower amount")),
    }
}

/// Authenticate every live late side-end carrier while an AutoPost
/// continuation is parked.
///
/// Stampede children may kill an owner or increment Tender before the Phase
/// resumes, so these are live reads rather than phase-entry booleans.  The
/// cold continuation path reuses the same owner/private-state predicates as
/// the eventual suffix before a resumed action can advance its cursor, RNG,
/// piles, or event stream.
pub(crate) fn auto_post_suffix_carriers_are_exact(state: &HotState) -> Result<(), EngineRefusal> {
    super::monsters::require_monster_turn_entry_state(state)?;
    match crate::moves::spawned::constrict_carrier_state(state) {
        crate::moves::spawned::ConstrictCarrierState::Absent => {}
        crate::moves::spawned::ConstrictCarrierState::Reachable => {
            if !crate::moves::spawned::constrict_private_state_is_exact(state) {
                return Err(EngineRefusal::MalformedArgs("constrict private state"));
            }
        }
        crate::moves::spawned::ConstrictCarrierState::Malformed => {
            return Err(EngineRefusal::MalformedArgs("ConstrictPower amount"));
        }
    }
    match crate::moves::spawned::tender_carrier_state(state) {
        crate::moves::spawned::TenderCarrierState::Absent => {}
        crate::moves::spawned::TenderCarrierState::Reachable => {
            if !crate::moves::spawned::tender_side_end_entry_is_exact(state) {
                return Err(EngineRefusal::MalformedArgs("tender side-end state"));
            }
        }
        crate::moves::spawned::TenderCarrierState::Malformed => {
            return Err(EngineRefusal::MalformedArgs("TenderPower state"));
        }
    }
    Ok(())
}

/// Freeze exact physical Howl and I Am Invincible identities in native pile order.
///
/// Current `sts2.dll` SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `Hook/<AfterAutoPostPlayPhaseEntered>d__57::MoveNext` RVA `0x3cb794`
/// obtains one `Hook::IterateCombatHookListeners` enumerator and awaits every
/// captured model serially. `CombatState/<IterateHookListeners>d__69::MoveNext`
/// RVA `0x3f9720` snapshots owner powers/relics/potions/orbs before the
/// player's `AllPiles`, then each pile's card list in order. Python
/// `_auto_phase_snapshot` (frozen, deleted #2827) preserves the relevant card suffix as
/// Hand, Draw, Discard, Exhaust, Play and normalizes physical identities
/// before freezing uids.
#[cold]
fn capture_card_auto_post_listeners(
    state: &mut HotState,
    catalog: &Catalog,
) -> Result<Vec<AutoPostListener>, EngineRefusal> {
    super::cards::normalize_card_identities(state)?;
    let mut listeners = Vec::new();
    for pile in [
        PileId::Hand,
        PileId::Draw,
        PileId::Discard,
        PileId::Exhaust,
        PileId::Play,
    ] {
        for card in state.piles.get(pile).as_slice() {
            let spec = catalog
                .spec(card.atom)
                .ok_or(EngineRefusal::UnknownAtom(card.atom))?;
            if matches!(
                spec.identity.id,
                CardId::HowlFromBeyond | CardId::IAmInvincible
            ) {
                if !(super::admission::howl_from_beyond_program_is_supported(spec.row)
                    || super::admission::i_am_invincible_program_is_supported(spec.row))
                    || !matches!(spec.identity.upgrade, 0 | 1)
                {
                    return Err(EngineRefusal::MalformedArgs(
                        "AutoPost physical card source",
                    ));
                }
                listeners.push(match spec.identity.id {
                    CardId::HowlFromBeyond => AutoPostListener::Howl { uid: card.uid },
                    CardId::IAmInvincible => AutoPostListener::Invincible { uid: card.uid },
                    _ => unreachable!("validated AutoPost physical source"),
                });
            }
        }
    }
    for listener in &listeners {
        let uid = listener.card_uid().expect("physical card listener");
        let matches = PileId::ALL
            .into_iter()
            .flat_map(|pile| state.piles.get(pile).as_slice())
            .filter(|card| card.uid == uid)
            .count();
        if matches != 1 {
            return Err(EngineRefusal::ActiveCardNotUnique { uid, matches });
        }
    }
    Ok(listeners)
}

/// Execute the captured Normal AutoPost card suffix in order.
#[cold]
fn run_card_auto_post_listeners(
    state: &mut HotState,
    catalog: &Catalog,
    listeners: &[AutoPostListener],
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    for listener in listeners {
        let AutoPostListener::Howl { uid } = listener else {
            return Err(EngineRefusal::ContinuationNotModeled);
        };
        // The native Hook walk rechecks object membership before invoking the
        // callback; the callback then independently requires live Exhaust.
        // The direct play entry itself suppresses bodies after combat ending,
        // so keep walking the frozen suffix even after a lethal earlier Howl.
        super::play::autoplay_howl_from_exhaust(state, catalog, *uid, events)?;
    }
    Ok(())
}

/// End the player turn and run everything through to the next turn's start.
pub fn end_player_turn(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if !after_side_turn_end_power_order_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "after-side-turn-end player-power object ledger",
        ));
    }
    let knowledge_demon_reachable = state
        .monsters
        .iter()
        .any(|monster| monster.kind == MonsterKind::KnowledgeDemon)
        || [
            PowerId::Disintegration,
            PowerId::MindRot,
            PowerId::Sloth,
            PowerId::WasteAway,
        ]
        .into_iter()
        .any(|power| state.powers.get(power).is_some())
        || state.fanouts.sloth().is_some();
    if knowledge_demon_reachable && !knowledge_demon_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs("Knowledge Demon state"));
    }
    if !enemy_potion_debuff_side_end_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "enemy potion-debuff side-end state",
        ));
    }
    if !super::admission::delayed_block_power_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "after-block-cleared power order",
        ));
    }
    let poison_reachable = state.monsters.iter().any(|monster| {
        monster.powers.get(PowerId::Poison).is_some()
            || monster.poison_uid != -1
            || monster
                .misery_debuff_order
                .as_slice()
                .contains(&MiseryToken::Poison)
    });
    if poison_reachable {
        if !super::damage::poison_identity_state_is_exact(state) {
            return Err(EngineRefusal::MalformedArgs("Poison identity universe"));
        }
        super::damage::null_applier_power_amount_changed_is_exact(state)?;
    }
    if state.fanouts.regen() > 0 {
        // Regen's later Decrement publishes the same null-applier
        // AfterPowerAmountChanged hook as other PowerCmd amount writes. Prove
        // that listener order before TurnEnded, phase, or Plating mutates.
        super::damage::null_applier_power_amount_changed_is_exact(state)?;
    }
    if !after_player_turn_start_power_order_is_exact(state)
        || !turn_start_hand_choice_power_order_is_exact(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "after-player-turn-start power order",
        ));
    }
    if !corrosive_wave_side_end_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "Corrosive Wave draw listener order",
        ));
    }
    if (state.card_states.hopper().is_some()
        || state
            .monsters
            .iter()
            .any(|monster| monster.kind == MonsterKind::ThievingHopper))
        && (!super::monsters::thieving_hopper_state_is_valid(state)
            || !super::monsters::thieving_hopper_deck_payload_is_exact(state, catalog))
    {
        return Err(EngineRefusal::MalformedArgs(
            "Thieving Hopper public turn entry",
        ));
    }
    let dampen_reachable = state.card_states.dampen().is_some();
    if dampen_reachable && !super::cards::dampen_state_is_exact(state, catalog) {
        return Err(EngineRefusal::MalformedArgs("Dampen public turn entry"));
    }
    let aeonglass_reachable = super::cards::aeonglass_reachable(state, catalog);
    if aeonglass_reachable && !super::cards::aeonglass_state_is_exact(state, catalog) {
        return Err(EngineRefusal::MalformedArgs("Aeonglass public turn entry"));
    }
    if state.monsters.iter().any(|monster| {
        matches!(
            monster.kind,
            MonsterKind::Queen | MonsterKind::TorchHeadAmalgam
        )
    }) && !super::monsters::queen_roster_state_is_valid(state)
    {
        return Err(EngineRefusal::MalformedArgs("Queen/Amalgam turn entry"));
    }
    let hex_reachable = state.powers.value(PowerId::HexPower) > 0;
    if hex_reachable && !super::cards::hex_power_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs("Spectral Hex turn entry"));
    }
    if state.powers.value(PowerId::ChainsOfBinding) > 0
        && !super::cards::chains_power_state_is_exact(state)
    {
        return Err(EngineRefusal::MalformedArgs("Chains turn entry"));
    }
    let before_side_order = state.fanouts.before_side_turn_end_order();
    let hailstorm_tokens = before_side_order
        .iter()
        .filter(|token| matches!(token, BeforeSideTurnEndToken::Hailstorm))
        .count();
    let bomb_reachable = !state.fanouts.the_bomb_instances_are_empty()
        || before_side_order
            .iter()
            .any(|token| matches!(token, BeforeSideTurnEndToken::TheBomb(_)))
        || state.powers.get(PowerId::TheBomb).is_some();
    if !state.fanouts.the_bomb_state_is_exact()
        || hailstorm_tokens != usize::from(state.powers.value(PowerId::Hailstorm) > 0)
        || state.powers.get(PowerId::TheBomb).is_some()
    {
        return Err(EngineRefusal::MalformedArgs(
            "before-side-turn-end power order",
        ));
    }
    if bomb_reachable && state.multiplayer_ally_key != 0 {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    let stampede_auto_post_reachable = exact_stampede_amount(state)?.is_some();
    if stampede_auto_post_reachable
        && !super::admission::stampede_power_model_identity_closure_is_exact(state, catalog)
        && !super::replay_lifecycle_is_active()
    {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    let before_hand_draw_reachability = before_hand_draw_turn_reachability(state);
    if before_hand_draw_reachability != 0 {
        require_before_hand_draw_turn_entry(state, catalog, before_hand_draw_reachability)?;
    }
    let void_form_reachable = crate::steps::regent_uncommon::void_form_listener_is_reachable(state);
    if void_form_reachable {
        if !crate::steps::regent_uncommon::void_form_private_state_is_exact(state) {
            return Err(EngineRefusal::MalformedArgs("void form private state"));
        }
        if state.fanouts.void_form_end_turn_requested() {
            return Err(EngineRefusal::MalformedArgs(
                "unresolved void form end-turn request",
            ));
        }
    }
    // Furnace's turn-start Forge is reached only after TurnEnded, hand
    // cleanup, enemy actions/RNG, duration expiry, and turn increments. Its
    // exact private state must therefore be authenticated before any public
    // prefix, and its late suffix shares this outer whole-action checkpoint.
    let furnace_reachable = furnace_turn_is_reachable(state);
    if furnace_reachable {
        require_furnace_turn_entry(state, catalog)?;
    }
    let monologue_reachable = crate::steps::regent_uncommon::monologue_listener_is_reachable(state);
    if monologue_reachable
        && !crate::steps::regent_uncommon::monologue_side_end_entry_is_exact(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "monologue side-end listener state",
        ));
    }
    let monologue_applied = state.fanouts.monologue_strength_applied();
    if state.powers.value(PowerId::Monologue) > 0
        && monologue_applied > 0
        && !state.history.over
        && state
            .powers
            .value(PowerId::Strength)
            .checked_sub(monologue_applied)
            .is_none()
    {
        return Err(EngineRefusal::CounterOverflow("player strength"));
    }
    let (constrict_reachable, constrict_first_acquisition) =
        match crate::moves::spawned::constrict_carrier_state(state) {
            crate::moves::spawned::ConstrictCarrierState::Absent => {
                // Preserve the inactive O(1) hot path: the frozen catalog
                // already proves whether this encounter can execute the
                // Strangler table. Only that rare path scans the live roster.
                // A dead exact applier remains as a corpse row after its
                // AfterDeath callback clears Constrict, but can never acquire
                // the listener again.
                let catalog_has_strangler =
                    !catalog.moves(MonsterKind::SlitheringStrangler).is_empty();
                let prospective = catalog_has_strangler
                    && state.monsters.iter().any(|monster| {
                        monster.kind == MonsterKind::SlitheringStrangler && monster.hp > 0
                    });
                let retained_dead_owner = catalog_has_strangler
                    && !prospective
                    && crate::moves::spawned::constrict_absent_dead_strangler_history_is_exact(
                        state,
                    );
                if catalog_has_strangler
                    && !retained_dead_owner
                    && !(prospective
                        && crate::moves::spawned::constrict_absent_strangler_entry_is_exact(state))
                {
                    return Err(EngineRefusal::MalformedArgs(
                        "constrict prospective owner/state",
                    ));
                }
                (false, prospective)
            }
            crate::moves::spawned::ConstrictCarrierState::Reachable => (true, false),
            crate::moves::spawned::ConstrictCarrierState::Malformed => {
                return Err(EngineRefusal::MalformedArgs("ConstrictPower amount"));
            }
        };
    if constrict_reachable && !crate::moves::spawned::constrict_private_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs("constrict private state"));
    }
    let tender_reachable = match crate::moves::spawned::tender_carrier_state(state) {
        crate::moves::spawned::TenderCarrierState::Absent => false,
        crate::moves::spawned::TenderCarrierState::Reachable => {
            if !crate::moves::spawned::tender_side_end_entry_is_exact(state) {
                return Err(EngineRefusal::MalformedArgs("tender side-end state"));
            }
            true
        }
        crate::moves::spawned::TenderCarrierState::Malformed => {
            return Err(EngineRefusal::MalformedArgs("TenderPower state"));
        }
    };
    let card_auto_post_reachable = card_auto_post_is_reachable(state, catalog);
    let bombardment_auto_pre_reachable = bombardment_auto_pre_is_reachable(state, catalog);
    let ethereal_drum_reachable = ordinary_ethereal_drum_transaction_needed(state, catalog)?;
    let monster_strength_move_reachable = monster_strength_move_transaction_needed(state, catalog);
    let after_side_turn_start_reachable = after_side_turn_start_is_reachable(state);
    let dark_embrace_ethereal_reachable = dark_embrace_ethereal_turn_end_reachable(state, catalog);
    // Keep every late-failing power-owned action behind one COW checkpoint so
    // any fail-closed listener/RNG edge preserves the complete public entry
    // state and event prefix.
    let other_late_failure_reachable = monologue_reachable
        || aggression_turn_is_reachable(state)
        || state.after_damage_received_order_is_reachable()
        || void_form_reachable
        || furnace_reachable
        || after_side_turn_start_reachable
        || dark_embrace_ethereal_reachable
        || catalog.dark_embrace_side_end_can_suspend()
        || before_hand_draw_reachability != 0
        || card_auto_post_reachable
        || bombardment_auto_pre_reachable
        || stampede_auto_post_reachable
        || constrict_reachable
        || constrict_first_acquisition
        || tender_reachable
        || ethereal_drum_reachable
        || monster_strength_move_reachable
        || hex_reachable
        || dampen_reachable
        || knowledge_demon_reachable;
    let other_late_failure_reachable = other_late_failure_reachable || state.fanouts.regen() > 0;
    if turn_end_transaction_needed(state, other_late_failure_reachable) {
        let mut next = state.clone();
        let mut emitted = Vec::new();
        // Native freezes this list on phase-4 entry. Capture immediately
        // outside the inner body so normalization/refusal stays inside the
        // public COW transaction. This placement is equivalent only while
        // `end_player_turn_inner` performs validation plus the passive
        // TurnEnded publication/phase-marker write before invoking this list:
        // no admitted command may move, transform, or mint a card in between.
        // Stampede and both physical card listeners join this one frozen
        // sequence; no command executes between capture and phase entry.
        let card_listeners = if card_auto_post_reachable {
            capture_card_auto_post_listeners(&mut next, catalog)?
        } else {
            Vec::new()
        };
        end_player_turn_inner(
            &mut next,
            catalog,
            constrict_reachable,
            tender_reachable,
            &card_listeners,
            stampede_auto_post_reachable,
            &mut emitted,
        )?;
        *state = next;
        events.extend(emitted);
        return Ok(());
    }
    end_player_turn_inner(
        state,
        catalog,
        constrict_reachable,
        tender_reachable,
        &[],
        false,
        events,
    )
}

#[inline]
fn turn_end_transaction_needed(state: &HotState, other_late_failure_reachable: bool) -> bool {
    !state.fanouts.after_side_turn_end_power_order().is_empty()
        || state.fanouts.next_after_side_turn_end_power_uid() == u32::MAX
        || state.powers.value(PowerId::ConsumingShadow) > 0
        || state.monsters.iter().any(|monster| {
            matches!(
                monster.kind,
                MonsterKind::GremlinMerc | MonsterKind::FatGremlin
            )
        })
        || state
            .monsters
            .iter()
            .any(|monster| monster.kind == MonsterKind::ThievingHopper)
        || state.monsters.iter().any(|monster| {
            monster.powers.get(PowerId::Poison).is_some()
                || monster.poison_uid != -1
                || monster
                    .misery_debuff_order
                    .as_slice()
                    .contains(&MiseryToken::Poison)
        })
        || state.monsters.iter().any(|monster| {
            matches!(
                monster.kind,
                MonsterKind::Queen | MonsterKind::TorchHeadAmalgam
            )
        })
        || state.powers.value(PowerId::CreativeAi) > 0
        || state.powers.value(PowerId::Mayhem) > 0
        || state.powers.value(PowerId::DoubleDamage) > 0
        || state.powers.value(PowerId::ShadowStep) > 0
        || state.powers.value(PowerId::SpectrumShift) > 0
        || state.powers.value(PowerId::SummonNextTurn) != 0
        || state.powers.value(PowerId::HexPower) > 0
        || state.card_states.dampen().is_some()
        || state.fanouts.withering_cards_left() != 0
        || state
            .monsters
            .iter()
            .any(|monster| monster.kind == MonsterKind::Aeonglass)
        || state.monsters.iter().any(|monster| {
            !monster.misery_debuff_order.knockdown().is_empty()
                || monster.powers.get(PowerId::Knockdown).is_some()
                || monster
                    .misery_debuff_order
                    .as_slice()
                    .contains(&MiseryToken::Knockdown)
        })
        || state
            .monsters
            .iter()
            .any(|monster| monster.powers.value(PowerId::Demise) > 0)
        || state
            .monsters
            .iter()
            .any(|monster| monster.hp > 0 && monster.powers.value(PowerId::TempStrength) < 0)
        || monster_side_end_strength_writer_reachable(state)
        || state
            .after_player_turn_start_order()
            .is_some_and(|order| !order.is_empty())
        || state.fanouts.toric_toughness().is_some()
        || !state.fanouts.the_bomb_instances_are_empty()
        || other_late_failure_reachable
}

fn dark_embrace_ethereal_turn_end_reachable(state: &HotState, catalog: &Catalog) -> bool {
    if state.fanouts.dark_embrace_ethereal() != 0 {
        return true;
    }
    state.powers.value(PowerId::DarkEmbrace) > 0
        && state.piles.get(PileId::Hand).as_slice().iter().any(|card| {
            catalog.spec(card.atom).is_some_and(|spec| {
                let row = spec.row;
                super::cards::effective_ethereal(state, spec, card.uid)
                    && row.turn_end_dmg == 0
                    && row.turn_end_hp_loss == 0
                    && row.turn_end_weak == 0
                    && row.turn_end_frail == 0
                    && !row.turn_end_hp_loss_hand
                    && !catalog
                        .steps(spec)
                        .iter()
                        .any(|step| step.kind == StepKind::TurnEndGoldLossExact)
            })
        })
}

// A prospective Dark Embrace side-end Draw needs no player-power order wall
// of its own (#3383). Every AfterSideTurnEnd player power, Tender included,
// runs from the acquisition-ordered object ledger
// (`after_side_turn_end_power_order`), so a Hellraiser Strike the Draw plays
// lands before or after Tender's reset exactly where native's listener walk
// puts it. `TenderPower/<AfterSideTurnEnd>d__13::MoveNext` RVA `0x348fb4`
// (v0.111.0, SHA-256 `9cb4f1ad…`) re-reads `CardsPlayedThisTurn` for its
// Strength (IL_0049) and Dexterity (IL_00c3) Applies and zeroes it after
// them (IL_012e-012f); `<AfterCardPlayed>d__12` RVA `0x348e10` increments it
// for any owner card, AutoPlay included (owner test IL_0028-0042, write
// IL_004a-0054), then Applies -1 Strength and -1 Dexterity. The Tender arm of
// `run_after_side_turn_end_power` refreshes its payload from the live counter
// at dispatch, which is that re-read.

/// Select COW for the two uncommon owner-side-end Strength writers.
///
/// ACT may synchronously raise a later carrier (for example The Obscura's
/// team buff), so entry arithmetic cannot soundly predict the final amount.
/// These powers are rare; carrying either exact live writer selects the whole
/// public turn's existing COW path while the ordinary no-power path remains
/// allocation-free.
fn monster_side_end_strength_writer_reachable(state: &HotState) -> bool {
    state.monsters.iter().any(|monster| {
        monster.hp > 0
            && (monster.powers.value(PowerId::HighVoltage) != 0
                || (monster.powers.value(PowerId::Ritual) > 0 && !monster.ritual_fresh))
    })
}

/// Positive monster-Strength move bodies can fail after earlier native
/// mutations (attacks, block, player afflictions, or team-prefix writes).
/// Resolve each live actor's exact current table row and select the public
/// turn COW for the complete generated writer inventory. The move bodies keep
/// their native live reads at each write seam; this guard supplies atomicity
/// without freezing a scalar across a mutating prefix.
fn monster_strength_move_transaction_needed(state: &HotState, catalog: &Catalog) -> bool {
    state.monsters.iter().any(|monster| {
        if monster.hp <= 0
            || monster.spawn_noop
            || monster.override_state != MonsterOverride::None
            || monster.forced_follow_up != MonsterFollowUp::None
        {
            return false;
        }
        current_table_move(monster, catalog).is_ok_and(|(entry, _, _)| {
            matches!(
                entry.kind,
                MoveKind::AttackStrength
                    | MoveKind::AttackStrengthBranch
                    | MoveKind::AxebotBootup
                    | MoveKind::BlockStrength
                    | MoveKind::BuffStrength
                    | MoveKind::BuffTeamStrength
                    | MoveKind::EntoSpit
                    | MoveKind::LouseCurlGrow
                    | MoveKind::Ponder
                    | MoveKind::PossessStrength
                    | MoveKind::QueenBurnBright
                    | MoveKind::SoulSiphon
                    | MoveKind::TestSubjectBurningGrowl
                    | MoveKind::WeakPlayerStrength
                    | MoveKind::Wriggle
            )
        })
    })
}

/// Detect a frozen ordinary-Ethereal Drum before turn mutation.
///
/// Its plan is deliberately not evaluated here: an earlier lethal
/// BeforeSideTurnEnd listener gates the whole Ethereal snapshot. Any
/// reachable row selects the outer whole-turn checkpoint; the exact plan is
/// validated at the post-listener, pre-removal seam below.
fn ordinary_ethereal_drum_transaction_needed(
    state: &HotState,
    catalog: &Catalog,
) -> Result<bool, EngineRefusal> {
    let mut reachable = false;
    for card in state.piles.get(PileId::Hand).as_slice() {
        let Some(spec) = catalog.spec(card.atom) else {
            continue;
        };
        if matches!(spec.identity.id, CardId::DrumOfBattle)
            && super::cards::effective_ethereal(state, spec, card.uid)
        {
            reachable = true;
        }
    }
    Ok(reachable)
}

/// Execute the captured SummonNextTurn AfterPlayerTurnStart callback.
///
/// `AmountOnTurnStart` is only the native nonzero gate; the summon operand is
/// the power's live Amount when this listener begins. Keeping those inputs
/// distinct avoids freezing a value the DLL explicitly re-reads.
///
/// `SummonNextTurnPower/<AfterPlayerTurnStart>d__6::MoveNext` (v0.111.0 RVA
/// `0x346ecc`): the owner test (IL_0028-IL_0038) and the
/// `AmountOnTurnStart` test (IL_003f-IL_0045) are its only gates before
/// `OstyCmd.Summon(Owner.Player, Amount)` at IL_0069. `<Summon>d__0`
/// (`0x3ee040`) reads `IsInProgress` only for its SFX (IL_00c6-IL_00d0), so a
/// peer that ended the combat earlier in the walk leaves the summon running
/// under IsEnding: [`super::summon_osty`] (#3279), which grows a live Osty's
/// MaxHp only and refuses the add/revive branch by name.
fn tick_summon_next_turn(
    state: &mut HotState,
    was_live_on_turn_start: bool,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if !was_live_on_turn_start {
        return Ok(());
    }
    let summon_amount = state.powers.value(PowerId::SummonNextTurn);
    if summon_amount <= 0 {
        return Err(EngineRefusal::MalformedArgs("summon next turn live amount"));
    }
    super::summon_osty(state, summon_amount, "summon next turn Osty")?;
    state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, 0);
    if !state.unregister_after_player_turn_start(PowerId::SummonNextTurn) {
        return Err(EngineRefusal::PowerOrderNotModeled(
            "SummonNextTurn listener removal",
        ));
    }
    super::damage::note_power(events, Subject::Player, PowerId::SummonNextTurn, 0);
    Ok(())
}

fn tick_loop(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let amount = state.powers.value(PowerId::Loop);
    if amount > 0 && !state.orbs.as_slice().is_empty() && !state.history.over {
        for _ in 0..amount {
            if state.history.over {
                break;
            }
            super::orbs::passive_at(state, catalog, 0, events)?;
            if state.pending.is_some() {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
        }
    }
    Ok(())
}

/// `RollingBoulderPower/<AfterPlayerTurnStart>d__8::MoveNext` RVA `0x342bdc`
/// (v0.111.0 DLL 9cb4f1ad…) awaits `DoDamage(HittableEnemies)` (IL_008b-0095),
/// and `RollingBoulderPower::DoDamage` RVA `0xa6e0b` is ONE
/// `CreatureCmd.Damage(choiceContext, targets, Amount, ValueProp 4, Owner)`
/// (IL_0001-0015). Every target is committed before any result or death
/// listener runs; each death's AfterDeath walk keeps the turn start's catalog
/// for Gremlin Horn's Draw (#3172). Same batch shape as Hailstorm.
fn tick_rolling_boulder(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let amount = state.powers.value(PowerId::RollingBoulder);
    if amount <= 0 {
        return Ok(());
    }
    if !state.history.over {
        let targets = super::damage::alive_targets(state);
        super::damage::damage_monsters_after_catalog_auth(
            state,
            catalog,
            &targets,
            DotNetDecimal::from_i64(i64::from(amount)),
            true,
            events,
        )?;
        if state.pending.is_some() {
            return Err(EngineRefusal::ContinuationNotModeled);
        }
    }
    let grown = amount
        .checked_add(5)
        .ok_or(EngineRefusal::CounterOverflow("rolling boulder"))?;
    state
        .powers
        .set(PowerId::RollingBoulder, SlotWire::Int, grown);
    super::damage::note_power(events, Subject::Player, PowerId::RollingBoulder, grown);
    Ok(())
}

fn tick_inferno(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<bool, EngineRefusal> {
    let self_damage = state.powers.value(PowerId::InfernoSelf);
    if self_damage > 0 && !state.history.over {
        let completed = super::damage::damage_player_from_card_with_catalog(
            state,
            catalog,
            i64::from(self_damage),
            false,
            events,
        )?;
        if state.pending.is_some() {
            return Err(EngineRefusal::ContinuationNotModeled);
        }
        if !completed {
            return Ok(false);
        }
    }
    Ok(state.hp > 0)
}

/// Execute Creative AI's complete live-Amount BeforeHandDraw listener.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `CreativeAiPower/<BeforeHandDraw>d__4::MoveNext` RVA `0x338180` checks the
/// owner at IL `0x0020-0x0033`, performs one full-pool Generation shuffle at
/// IL `0x0044-0x00b9`, awaits owner-generated Hand insertion at
/// IL `0x00bf-0x0127`, then re-reads live Amount at IL `0x0128-0x0146`.
fn run_creative_ai_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    fn apply(
        state: &mut HotState,
        catalog: &Catalog,
        events: &mut Vec<Event>,
    ) -> Result<(), EngineRefusal> {
        let mut iteration = 0i32;
        loop {
            let amount = state.powers.value(PowerId::CreativeAi);
            if amount < 0 {
                return Err(EngineRefusal::MalformedArgs(
                    "Creative AI live power amount",
                ));
            }
            if iteration >= amount {
                return Ok(());
            }
            let identity = super::cards::select_creative_ai_power(state, catalog)?;
            // Native publishes the loop cursor and selected identity before
            // awaiting the generated-card transaction. The transaction has
            // therefore begun even when an earlier generated listener ended
            // combat: history/hook epochs still publish, while the nested Add
            // independently suppresses allocation and insertion.
            super::cards::inject_before_hand_draw_generated_bottom(
                state, catalog, identity, events,
            )?;
            iteration = iteration
                .checked_add(1)
                .ok_or(EngineRefusal::CounterOverflow("Creative AI iteration"))?;
        }
    }

    // A later iteration can fail through RNG, uid/history capacity, or a
    // generated-card listener after earlier iterations have published. The
    // native awaited listener is one public turn-action suffix; rehearse the
    // complete live-Amount loop before exposing any of it.
    let mut probe = state.clone();
    apply(&mut probe, catalog, &mut Vec::new())?;
    apply(state, catalog, events)
}

/// Execute Hello World's frozen-Amount distinct Common generation listener.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `HelloWorldPower/<BeforeHandDraw>d__4::MoveNext` RVA `0x33bfd0` reads
/// AmountOnTurnStart at IL `0x0038-0x003f`, performs one full distinct shuffle
/// at `0x00ba-0x00da`, then awaits one plural generated-card command at
/// `0x00e0-0x00f3`. Python correspondence is
/// `_advance_before_hand_draw_power_frame` (frozen Python, deleted #2827).
fn run_hello_world_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    fn apply(
        state: &mut HotState,
        catalog: &Catalog,
        events: &mut Vec<Event>,
    ) -> Result<(), EngineRefusal> {
        let current_amount = state.powers.value(PowerId::HelloWorld);
        let frozen_amount = state
            .hello_world_amount_on_turn_start(current_amount)
            .ok_or(EngineRefusal::MalformedArgs(
                "hello world amount-on-turn-start snapshot",
            ))?;
        let identities = super::cards::select_hello_world_cards(state, catalog, frozen_amount)?;
        super::cards::inject_before_hand_draw_generated_batch_bottom(
            state,
            catalog,
            &identities,
            events,
        )
    }
    let mut probe = state.clone();
    apply(&mut probe, catalog, &mut Vec::new())?;
    apply(state, catalog, events)
}

/// Execute Spectrum Shift's one-shuffle, distinct-prefix BeforeHandDraw listener.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `SpectrumShiftPower/<BeforeHandDraw>d__4::MoveNext` RVA `0x345978`
/// snapshots live Amount, performs one complete Colorless Generation shuffle,
/// then serially awaits owner-generated Hand/Bottom insertion for the selected
/// prefix before flashing at IL `0x0083-0x016c`.
/// Python `_advance_before_hand_draw_power_frame` (frozen, deleted #2827) freezes the same
/// shuffled prefix before entering its serial `spectrum_shift_generated` walk.
fn run_spectrum_shift_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    fn apply(
        state: &mut HotState,
        catalog: &Catalog,
        events: &mut Vec<Event>,
    ) -> Result<(), EngineRefusal> {
        let amount = state.powers.value(PowerId::SpectrumShift);
        let identities = super::cards::select_spectrum_shift_cards(state, catalog, amount)?;
        for identity in identities {
            super::cards::inject_before_hand_draw_generated_bottom(
                state, catalog, identity, events,
            )?;
        }
        Ok(())
    }

    // The selected prefix is one awaited listener transaction. Rehearse the
    // complete shuffle and every serial generated-card suffix before exposing
    // RNG, uids, hook epochs, history, pile mutations, or events.
    let mut probe = state.clone();
    apply(&mut probe, catalog, &mut Vec::new())?;
    apply(state, catalog, events)
}

/// Execute Foregone Conclusion's synchronous FromCombatPile auto-take arm.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `ForegoneConclusionPower/<BeforeHandDraw>d__4::MoveNext` RVA `0x33a8e8`
/// awaits ShuffleIfNecessary, selects exactly Amount from Draw, adds the
/// selected enumeration to Hand/Bottom, then removes the whole power.
/// `FromCombatPile` d__20 MoveNext RVA `0x3e5e84` returns the live Draw-pile
/// order when `count <= MinSelect` and no manual confirmation is required;
/// its manual branch sorts displayed candidates by rarity then model id.
/// Enumerable `CardPileCmd.Add` d__10 MoveNext RVA `0x3e1ba4` completes the
/// serial Hand/Bottom moves before its separate changed-pile listener pass.
/// This is Add, rather than Draw: it must not invoke draw hooks. CardPileCmd
/// redirects serial Hand overflow to Discard.
/// The frozen Python simulator's `_fire_foregone_conclusion`
/// (frozen Python, deleted #2827) is retained as a compatibility counterpart only; the
/// native IL above is the behavior authority for this resumable port.
#[cold]
#[inline(never)]
fn run_foregone_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    listeners: &[PowerId],
    cursor: u32,
    events: &mut Vec<Event>,
) -> Result<bool, EngineRefusal> {
    let amount = foregone_live_amount(state)?;
    if state.piles.get(PileId::Draw).is_empty() && !state.piles.get(PileId::Discard).is_empty() {
        let pre_shuffle = crate::hot::BeforeHandDrawPowerRecord {
            listeners: listeners.to_vec(),
            cursor,
            amount: u32::try_from(amount)
                .map_err(|_| EngineRefusal::CounterOverflow("foregone amount"))?,
            candidates: Vec::new(),
        };
        state
            .frames
            .push_before_hand_draw_power(&pre_shuffle)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        if super::draw::reshuffle_for_foregone(state, catalog, events)? {
            return Ok(true);
        }
        let restored = state
            .frames
            .pop_top_before_hand_draw_power()
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        if restored != pre_shuffle {
            return Err(EngineRefusal::ContinuationNotModeled);
        }
    }
    if state.piles.get(PileId::Draw).len() <= amount {
        super::draw::auto_take_draw_to_hand(state, amount, "foregone selection", events)?;
    } else {
        let candidates: Vec<crate::hot::FrozenAutoBatchEntry> =
            super::draw::stratagem_exact_candidates(state, catalog)?
                .into_iter()
                .map(|card| crate::hot::FrozenAutoBatchEntry {
                    card,
                    state: state
                        .card_states
                        .get_ref(card.uid)
                        .cloned()
                        .unwrap_or_default(),
                })
                .collect();
        // The public action surface is u32-indexed. Refuse before publishing
        // a frame (or changing the power) when the ordered native choices do
        // not fit it, so the whole EndTurn remains atomic.
        foregone_selection_cardinality(candidates.len(), amount)?;
        let record = crate::hot::BeforeHandDrawPowerRecord {
            listeners: listeners.to_vec(),
            cursor,
            amount: u32::try_from(amount)
                .map_err(|_| EngineRefusal::CounterOverflow("foregone amount"))?,
            candidates,
        };
        let record = state
            .frames
            .push_before_hand_draw_power(&record)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        state.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
            frame_uid: crate::hot::FOREGONE_SELECTION_PENDING_UID,
            frame_record: record,
        }));
        return Ok(true);
    }
    state.powers.set(PowerId::Foregone, SlotWire::Int, 0);
    state.fanouts.unregister_before_hand_draw(PowerId::Foregone);
    super::damage::note_power(events, Subject::Player, PowerId::Foregone, 0);
    Ok(false)
}

pub(crate) fn resume_foregone_after_shuffle(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let record = state
        .frames
        .pop_top_before_hand_draw_power()
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if !record.candidates.is_empty() {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    if run_foregone_before_hand_draw(state, catalog, &record.listeners, record.cursor, events)? {
        return Ok(());
    }
    if run_before_hand_draw_power_suffix(
        state,
        catalog,
        &record.listeners,
        record.cursor as usize,
        events,
    )? {
        return Ok(());
    }
    super::cards::complete_self_return_before_hand_draw(state, catalog, events)?;
    let pollinous_activated = super::relics::before_hand_draw(catalog, state, events)?;
    if state.pending.is_none() {
        finish_player_turn_start_after_before_hand_draw_relics(
            state,
            catalog,
            state.powers.value(PowerId::Hibernate) > 0,
            pollinous_activated,
            events,
        )?;
    }
    Ok(())
}

/// Continue a frozen native `BeforeHandDraw` power snapshot.  A listener is
/// addressed by its snapshot position, never rediscovered from the mutable
/// fanout, so Foregone's removal and a cold reload cannot replay an earlier
/// generator or its RNG work.
fn run_before_hand_draw_power_suffix(
    state: &mut HotState,
    catalog: &Catalog,
    listeners: &[PowerId],
    start: usize,
    events: &mut Vec<Event>,
) -> Result<bool, EngineRefusal> {
    for (listener_index, power) in listeners.iter().copied().enumerate().skip(start) {
        match power {
            PowerId::InfiniteBlades => {
                let amount: usize = state
                    .powers
                    .value(power)
                    .try_into()
                    .map_err(|_| EngineRefusal::CounterOverflow("infinite blades"))?;
                super::cards::inject_generated_bottom(
                    state,
                    catalog,
                    CardIdentity {
                        id: CardId::Shiv,
                        upgrade: 0,
                        enchantment: None,
                    },
                    amount,
                    PileId::Hand,
                    events,
                )?;
            }
            PowerId::CreativeAi => run_creative_ai_before_hand_draw(state, catalog, events)?,
            PowerId::HelloWorld => run_hello_world_before_hand_draw(state, catalog, events)?,
            PowerId::CallOfTheVoid => {
                run_call_of_the_void_before_hand_draw(state, catalog, events)?
            }
            PowerId::SpectrumShift => run_spectrum_shift_before_hand_draw(state, catalog, events)?,
            PowerId::Foregone => {
                if run_foregone_before_hand_draw(
                    state,
                    catalog,
                    listeners,
                    u32::try_from(listener_index + 1)
                        .map_err(|_| EngineRefusal::CounterOverflow("BeforeHandDraw cursor"))?,
                    events,
                )? {
                    return Ok(true);
                }
            }
            PowerId::SentryMode => {
                crate::steps::templates::run_sentry_mode_before_hand_draw(state, catalog, events)?;
            }
            _ => {
                return Err(EngineRefusal::PowerHookNotModeled {
                    power,
                    event: HookEvent::BeforeHandDraw,
                });
            }
        }
    }
    Ok(false)
}

fn foregone_selection_at(
    candidates: &[crate::hot::FrozenAutoBatchEntry],
    amount: usize,
    mut ordinal: u32,
) -> Result<Vec<crate::hot::FrozenAutoBatchEntry>, EngineRefusal> {
    let total = foregone_selection_cardinality(candidates.len(), amount)?;
    if ordinal >= total {
        return Err(EngineRefusal::MalformedArgs("selection option index"));
    }
    let mut available = candidates.to_vec();
    let mut selected = Vec::with_capacity(amount);
    for position in 0..amount {
        let remaining = amount - position - 1;
        let mut suffix = 1_u32;
        for factor in 0..remaining {
            suffix = suffix
                .checked_mul(
                    u32::try_from(available.len() - factor - 1)
                        .map_err(|_| EngineRefusal::CounterOverflow("foregone options"))?,
                )
                .ok_or(EngineRefusal::CounterOverflow("foregone options"))?;
        }
        let index = usize::try_from(ordinal / suffix)
            .map_err(|_| EngineRefusal::CounterOverflow("foregone option index"))?;
        ordinal %= suffix;
        selected.push(available.remove(index));
    }
    Ok(selected)
}

pub(crate) fn foregone_selected_cards(
    record: &crate::hot::BeforeHandDrawPowerRecord,
    ordinal: u32,
) -> Result<Vec<crate::hot::FrozenAutoBatchEntry>, EngineRefusal> {
    foregone_selection_at(&record.candidates, record.amount as usize, ordinal)
}

pub(crate) fn foregone_selection_action_count(state: &HotState) -> Result<u32, EngineRefusal> {
    let record = state
        .pending
        .as_deref()
        .and_then(|pending| pending.foregone_before_hand_draw_record(&state.frames))
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    foregone_selection_cardinality(record.candidates().len(), record.amount as usize)
}

fn foregone_selection_cardinality(candidates: usize, amount: usize) -> Result<u32, EngineRefusal> {
    if amount == 0 || candidates <= amount {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    let mut total = 1_u32;
    for offset in 0..amount {
        total = total
            .checked_mul(
                u32::try_from(candidates - offset)
                    .map_err(|_| EngineRefusal::CounterOverflow("foregone options"))?,
            )
            .ok_or(EngineRefusal::CounterOverflow("foregone options"))?;
    }
    Ok(total)
}

pub(crate) fn resume_foregone_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    ordinal: u32,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let pending = state
        .pending
        .as_deref()
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let record = pending
        .foregone_before_hand_draw_record(&state.frames)
        .ok_or(EngineRefusal::ContinuationNotModeled)?
        .to_owned();
    let live = super::draw::stratagem_exact_candidates(state, catalog)?
        .into_iter()
        .map(|card| crate::hot::FrozenAutoBatchEntry {
            card,
            state: state
                .card_states
                .get_ref(card.uid)
                .cloned()
                .unwrap_or_default(),
        })
        .collect::<Vec<_>>();
    if live != record.candidates || foregone_live_amount(state)? != record.amount as usize {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    let selected = foregone_selection_at(&record.candidates, record.amount as usize, ordinal)?;
    state.pending = None;
    for frozen in selected {
        let index = state
            .piles
            .get(PileId::Draw)
            .as_slice()
            .iter()
            .position(|card| *card == frozen.card)
            .ok_or(EngineRefusal::FrozenCardVanished {
                uid: frozen.card.uid,
                pile: PileId::Draw,
            })?;
        let destination = if state.piles.get(PileId::Hand).len() < super::draw::MAX_CARDS_IN_HAND {
            PileId::Hand
        } else {
            PileId::Discard
        };
        super::draw::repair_card_play_after_physical_move(
            state,
            frozen.card,
            PileId::Draw,
            destination,
        )?;
        let card = state.piles.get_mut(PileId::Draw).make_mut().remove(index);
        state.piles.get_mut(destination).make_mut().push(card);
        events.push(Event::CardResolved {
            uid: card.uid,
            pile: destination,
        });
    }
    state.powers.set(PowerId::Foregone, SlotWire::Int, 0);
    state.fanouts.unregister_before_hand_draw(PowerId::Foregone);
    super::damage::note_power(events, Subject::Player, PowerId::Foregone, 0);
    let popped = state
        .frames
        .pop_top_before_hand_draw_power()
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if popped != record {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    if run_before_hand_draw_power_suffix(
        state,
        catalog,
        &record.listeners,
        record.cursor as usize,
        events,
    )? {
        return Ok(());
    }
    super::cards::complete_self_return_before_hand_draw(state, catalog, events)?;
    let pollinous_activated = super::relics::before_hand_draw(catalog, state, events)?;
    if state.pending.is_some() {
        return Ok(());
    }
    finish_player_turn_start_after_before_hand_draw_relics(
        state,
        catalog,
        state.powers.value(PowerId::Hibernate) > 0,
        pollinous_activated,
        events,
    )
}

#[cold]
#[inline(never)]
fn run_call_of_the_void_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    require_call_of_the_void_turn_entry(state, catalog)?;
    run_authenticated_call_of_the_void_before_hand_draw(state, catalog, events)
}

fn run_authenticated_call_of_the_void_before_hand_draw(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if state.powers.value(PowerId::CallOfTheVoid)
        > crate::steps::necrobinder_rare::MAX_CALL_OF_THE_VOID_GENERATED_PER_TURN
    {
        return Err(EngineRefusal::MalformedArgs(
            "Call of the Void generation batch exceeds 256 cards",
        ));
    }
    let amount: usize = state
        .powers
        .value(PowerId::CallOfTheVoid)
        .try_into()
        .map_err(|_| EngineRefusal::CounterOverflow("Call of the Void amount"))?;
    super::cards::preflight_call_of_the_void_batch(state, amount)?;
    let pool = super::cards::exact_owner_listener_pool(state, catalog, PowerId::CallOfTheVoid)?;
    let mut identities = Vec::with_capacity(amount);
    for _ in 0..amount {
        let shuffled = super::cards::shuffle_generation_slice(state, &pool)?;
        identities.push(CardIdentity {
            id: shuffled[0],
            upgrade: 0,
            enchantment: None,
        });
    }
    super::cards::inject_call_of_the_void_batch_bottom(state, catalog, &identities, events)
}

/// Authenticate the AfterPowerAmountChanged walk that a local temporary
/// Strength/Dexterity expiry publishes, and admit it as inert (#2951).
///
/// Current-build authority is `sts2.dll` SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`.
///
/// **What the expiry publishes.**
/// `TemporaryStrengthPower/<AfterSideTurnEnd>d__22::MoveNext` `0x348ba8`
/// awaits `PowerCmd::Remove(this)` (IL_0042-IL_0043), then
/// `PowerCmd::Apply<StrengthPower>(Owner, -Sign * Amount, applier: Owner,
/// cardSource: null)` (IL_00a3-IL_00c4).
/// `TemporaryDexterityPower/<AfterSideTurnEnd>d__22::MoveNext` `0x348498` has
/// the same shape: `Remove` at IL_0043 and `Apply<DexterityPower>` with
/// `Owner` as applier at IL_00a4-IL_00c4. None of their 18 subclasses in this
/// build (Flex Potion, Setup Strike, Coordinate, Anticipate, Speed Potion,
/// ..., one a test mock) overrides `AfterSideTurnEnd`; the negative ones override only
/// `get_IsPositive`, which flips `Sign` and so the delta's sign. Of
/// `PowerCmd`, only `Apply` and `ModifyAmount` reach
/// `Hook::AfterPowerAmountChanged` `0x1045ec` (`scan_calls.py
/// AfterPowerAmountChanged`: `<Apply>d__2` and `<ModifyAmount>d__6`), so the
/// `Remove` publishes nothing here. The one event is therefore: a player-owned
/// `StrengthPower`/`DexterityPower`, a nonzero delta of either sign, with the
/// player as applier.
///
/// **Every represented listener is inert for that event**, whatever its sign:
/// - `ViciousPower/<AfterPowerAmountChanged>d__6::MoveNext` `0x34a6f8`
///   returns unless the changed power `isinst VulnerablePower`
///   (IL_004a-IL_0057), ahead of its awaited `Draw`.
/// - `ShroudPower/<AfterPowerAmountChanged>d__6::MoveNext` `0x3446a4`
///   returns unless it `isinst DoomPower` (IL_0030-IL_003d), ahead of its
///   `GainBlock`.
/// - `SleightOfFleshPower/<AfterPowerAmountChanged>d__6::MoveNext`
///   `0x344dc4` returns unless `power.Owner.IsEnemy` (IL_0050-IL_0062). The
///   applier test after it (IL_0067-IL_0075) would pass — the player applied
///   it — so the enemy-owner test is the load-bearing one.
/// - `SwordSagePower::AfterPowerAmountChanged` `0xa902c` returns a completed
///   task unless the changed power `isinst SwordSagePower` (IL_000c-IL_0019).
///
/// No callback mutates state or awaits, so the native serial walk completes
/// synchronously and the side-end suffix is unchanged. The represented fanout
/// holds only those four members (`PowerAmountChangedPower`), so there is no
/// further listener to name. The #1539 gate this replaces mirrored the frozen
/// Python refusal; it was not an IL finding. A malformed recorded order still
/// refuses, before any mutation, as every other inert walk in `damage.rs`
/// does.
fn temporary_stat_expiry_power_amount_changed_is_exact(
    state: &HotState,
) -> Result<(), EngineRefusal> {
    if (state.temp_strength != 0
        || state.powers.value(PowerId::TempStrength) != 0
        || state.powers.value(PowerId::TempDexterity) != 0)
        && !state.fanouts.after_power_amount_changed_order().is_empty()
        && !super::damage::player_type_one_listener_order_is_exact(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "after-power-amount-changed listener order",
        ));
    }
    Ok(())
}

fn end_player_turn_inner(
    state: &mut HotState,
    catalog: &Catalog,
    constrict_reachable_at_entry: bool,
    tender_reachable_at_entry: bool,
    card_auto_post_listeners: &[AutoPostListener],
    stampede_auto_post_reachable: bool,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    // This public action is also entered directly by embedders, outside
    // canonical admission. Authenticate every occupied Conqueror wire and
    // sign before the first turn event/mutation; `Slots::value` would erase
    // Bool versus Int and make a negative duration look inactive. Folding the
    // check into the original Plating roster preflight keeps refusal ordering
    // and the absent path's one entry scan unchanged.
    let conqueror_reachable_at_entry = super::monsters::require_monster_turn_entry_state(state)?;
    if state
        .monsters
        .iter()
        .any(|monster| monster.kind == MonsterKind::SoulFysh)
        && !super::monsters::soul_fysh_state_is_valid(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "Soul Fysh Intangible owner/state",
        ));
    }
    if state.monsters.iter().any(|monster| {
        monster.kind == MonsterKind::TheInsatiable || monster.powers.value(PowerId::Sandpit) != 0
    }) {
        super::monsters::require_insatiable_state(state)?;
    }

    let prior_ethereal_tally = state.fanouts.dark_embrace_ethereal();
    let dark_embrace = state.powers.value(PowerId::DarkEmbrace);
    if prior_ethereal_tally < 0 || prior_ethereal_tally > 0 && dark_embrace <= 0 {
        return Err(EngineRefusal::MalformedArgs("dark embrace ethereal tally"));
    }

    temporary_stat_expiry_power_amount_changed_is_exact(state)?;

    let player_ritual = state.fanouts.player_ritual();
    if player_ritual > 0 {
        state
            .powers
            .value(PowerId::Strength)
            .checked_add(player_ritual)
            .ok_or(EngineRefusal::CounterOverflow("Ritual strength"))?;
    }
    let double_damage = state.powers.value(PowerId::DoubleDamage);

    // Consuming Shadow publishes its dispatcher epoch before the native
    // initial-empty gate. If the queue starts nonempty, its live Amount also
    // bounds the authenticated EvokeLast child receipts. Validate both
    // allocators before TurnEnded so malformed/overflowing entry is atomic.
    let consuming_shadow = state.powers.value(PowerId::ConsumingShadow);
    if consuming_shadow > 0 {
        state
            .orbs
            .next_consuming_shadow_side_end_auth_uid()
            .checked_add(1)
            .ok_or(EngineRefusal::CounterOverflow(
                "next_consuming_shadow_side_end_auth_uid",
            ))?;
        if !state.orbs.as_slice().is_empty() {
            state
                .orbs
                .next_random_orb_progress_uid()
                .checked_add(
                    consuming_shadow
                        .try_into()
                        .map_err(|_| EngineRefusal::CounterOverflow("consuming shadow amount"))?,
                )
                .ok_or(EngineRefusal::CounterOverflow(
                    "next_random_orb_progress_uid",
                ))?;
        }
    }

    events.push(Event::TurnEnded { turn: state.turn });

    // `end_player_turn`'s validation wall runs first, then the AutoPost phase
    // marker and the captured physical card suffix. A lethal listener leaves the
    // player in phase 4 and suppresses every turn-end command, while later
    // captured callbacks still enter and no-op through CardCmd::AutoPlay.
    state.player_phase = PHASE_AUTO_POST;
    if stampede_auto_post_reachable
        || card_auto_post_listeners
            .iter()
            .any(|listener| matches!(listener, AutoPostListener::Invincible { .. }))
    {
        let mut listeners = Vec::with_capacity(1 + card_auto_post_listeners.len());
        if stampede_auto_post_reachable {
            listeners.push(AutoPostListener::Stampede);
        }
        listeners.extend_from_slice(card_auto_post_listeners);
        state
            .frames
            .push_auto_post_phase(&AutoPostPhaseRecord {
                cursor: 0,
                listeners,
            })
            .ok_or(EngineRefusal::CounterOverflow("AutoPost phase record"))?;
        let _ = super::play::drive_until_depth(state, catalog, events, 0)?;
        return Ok(());
    }
    run_card_auto_post_listeners(state, catalog, card_auto_post_listeners, events)?;
    if !card_auto_post_listeners.is_empty() {
        // The same AutoPost dispatch boundary the Phase frame observes
        // (`native_checkpoint`, #3242); with no listener native's hook task
        // completes synchronously and writes no checkpoint.
        super::native_checkpoint::observe(
            super::native_checkpoint::NativeCheckpointKind::AutoPostHookFinished,
            state,
        );
    }
    if state.history.over {
        return Ok(());
    }
    finish_player_turn_after_auto_post_with_carriers(
        state,
        catalog,
        events,
        conqueror_reachable_at_entry,
        constrict_reachable_at_entry,
        tender_reachable_at_entry,
        double_damage,
    )
}

#[cold]
#[inline(never)]
pub(crate) fn finish_player_turn_after_auto_post(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let conqueror_reachable_at_entry = super::monsters::require_monster_turn_entry_state(state)?;
    let constrict_reachable_at_entry =
        crate::moves::spawned::constrict_listener_is_reachable(state);
    let tender_reachable_at_entry = state.fanouts.tender_is_active();
    let double_damage = state.powers.value(PowerId::DoubleDamage);
    finish_player_turn_after_auto_post_with_carriers(
        state,
        catalog,
        events,
        conqueror_reachable_at_entry,
        constrict_reachable_at_entry,
        tender_reachable_at_entry,
        double_damage,
    )
}

fn after_side_turn_end_token_count(state: &HotState, token: AfterSideTurnEndPowerToken) -> usize {
    use AfterSideTurnEndPowerToken as Token;
    match token {
        Token::Panache => state.fanouts.panache_instances().count(),
        Token::Monologue => state.fanouts.monologue_instances().count(),
        Token::Constrict => usize::from(crate::moves::spawned::constrict_listener_is_reachable(
            state,
        )),
        Token::Duplication => usize::from(state.fanouts.duplication() > 0),
        Token::NoEnergyGain => usize::from(state.fanouts.no_energy_gain()),
        Token::Ringing => usize::from(state.ringing()),
        Token::Ritual => usize::from(state.fanouts.player_ritual() > 0),
        Token::TemporaryFocus => usize::from(state.orbs.temp_focus() != 0),
        Token::TemporaryStrength => usize::from(state.temp_strength != 0),
        Token::Tender => usize::from(state.fanouts.tender_is_active()),
        token => usize::from(
            after_side_turn_end_scalar_power(token)
                .is_some_and(|power| state.powers.value(power) != 0),
        ),
    }
}

fn after_side_turn_end_scalar_power(token: AfterSideTurnEndPowerToken) -> Option<PowerId> {
    use AfterSideTurnEndPowerToken as Token;
    Some(match token {
        Token::BorrowedTime => PowerId::BorrowedTime,
        Token::Burst => PowerId::Burst,
        Token::ConsumingShadow => PowerId::ConsumingShadow,
        Token::CorrosiveWave => PowerId::CorrosiveWave,
        Token::DarkEmbrace => PowerId::DarkEmbrace,
        Token::Doom => PowerId::Doom,
        Token::DoubleDamage => PowerId::DoubleDamage,
        Token::Hellraiser => PowerId::Hellraiser,
        Token::Juggling => PowerId::Juggling,
        Token::NoDraw => PowerId::NoDraw,
        Token::OneTwoPunch => PowerId::OneTwoPunch,
        Token::PaleBlueDot => PowerId::PaleBlueDot,
        Token::Rage => PowerId::Rage,
        Token::Rebound => PowerId::Rebound,
        Token::RetainHand => PowerId::RetainHand,
        Token::Shadowmeld => PowerId::Shadowmeld,
        Token::Smoggy => PowerId::Smoggy,
        Token::Tangled => PowerId::Tangled,
        Token::TemporaryDexterity => PowerId::TempDexterity,
        Token::Constrict
        | Token::Duplication
        | Token::Monologue
        | Token::NoEnergyGain
        | Token::Panache
        | Token::Ringing
        | Token::Ritual
        | Token::TemporaryFocus
        | Token::TemporaryStrength
        | Token::Tender => return None,
    })
}

/// Authenticate the complete current-build native object ledger against all
/// 29 local-player power carriers.  Acquisition UIDs are globally monotone;
/// keyed objects have one row and the two InstanceType-1 families have one
/// row per exact cold object.
pub(crate) fn after_side_turn_end_power_order_is_exact(state: &HotState) -> bool {
    let order = state.fanouts.after_side_turn_end_power_order();
    // The benchmark's normal player has neither power slots nor a recorded
    // object listener. Check the non-slot carriers once, then avoid the
    // complete 29-token census. Any live scalar member or malformed stored
    // order continues through the exhaustive validation below.
    if order.is_empty()
        && state.powers.is_empty()
        && state.fanouts.panache_instances().next().is_none()
        && state.fanouts.monologue_instances().next().is_none()
        && !crate::moves::spawned::constrict_listener_is_reachable(state)
        && state.fanouts.duplication() == 0
        && !state.fanouts.no_energy_gain()
        && !state.ringing()
        && state.fanouts.player_ritual() == 0
        && state.orbs.temp_focus() == 0
        && state.temp_strength == 0
        && !state.fanouts.tender_is_active()
    {
        return true;
    }
    let juggling_attacks = state.powers.value(PowerId::JugglingAttacks);
    if juggling_attacks < 0 || juggling_attacks != 0 && state.powers.value(PowerId::Juggling) <= 0 {
        return false;
    }
    if order.iter().enumerate().any(|(index, entry)| {
        entry.uid >= state.fanouts.next_after_side_turn_end_power_uid()
            || index > 0 && order[index - 1].uid >= entry.uid
    }) {
        return false;
    }
    for token in AfterSideTurnEndPowerToken::ALL {
        let rows = order.iter().filter(|entry| entry.token == token).count();
        if rows != after_side_turn_end_token_count(state, token) {
            return false;
        }
    }
    order.iter().all(|entry| match entry.token {
        AfterSideTurnEndPowerToken::Panache => state.fanouts.panache_instance(entry.uid).is_some(),
        AfterSideTurnEndPowerToken::Monologue => {
            state.fanouts.monologue_instance(entry.uid).is_some()
        }
        _ => true,
    })
}

/// Test-fixture migration helper for cases whose assertion is unrelated to
/// native acquisition order. Existing instanced rows and explicitly ordered
/// singleton rows are preserved; missing live singleton rows append in the
/// frozen census order with fresh UIDs. Malformed-ledger tests deliberately
/// do not call this helper.
#[cfg(test)]
pub(crate) fn hydrate_after_side_turn_end_power_order_for_test(state: &mut HotState) {
    for token in AfterSideTurnEndPowerToken::ALL {
        if token.is_instanced()
            || after_side_turn_end_token_count(state, token) == 0
            || state.fanouts.after_side_turn_end_power_uid(token).is_some()
        {
            continue;
        }
        state
            .fanouts
            .register_after_side_turn_end_power(token)
            .expect("test side-end UID allocator");
    }
    assert!(
        after_side_turn_end_power_order_is_exact(state),
        "test fixture has malformed live side-end carriers"
    );
}

pub(crate) fn current_after_side_turn_end_payload(
    state: &HotState,
    object: AfterSideTurnEndPowerEntry,
) -> Result<[i32; 4], EngineRefusal> {
    use AfterSideTurnEndPowerToken as Token;
    Ok(match object.token {
        Token::Panache => {
            let instance =
                state
                    .fanouts
                    .panache_instance(object.uid)
                    .ok_or(EngineRefusal::MalformedArgs(
                        "Panache side-end object ledger",
                    ))?;
            [
                instance.amount,
                instance.cards_left,
                i32::from(instance.already_applied),
                0,
            ]
        }
        Token::Monologue => {
            let instance = state.fanouts.monologue_instance(object.uid).ok_or(
                EngineRefusal::MalformedArgs("Monologue side-end object ledger"),
            )?;
            [
                instance.amount,
                instance.power,
                instance.strength_applied,
                0,
            ]
        }
        Token::Constrict => [state.fanouts.constrict_amount(), 0, 0, 0],
        Token::Duplication => [state.fanouts.duplication(), 0, 0, 0],
        Token::NoEnergyGain => [i32::from(state.fanouts.no_energy_gain()), 0, 0, 0],
        Token::Ringing => [i32::from(state.ringing()), 0, 0, 0],
        Token::Ritual => [state.fanouts.player_ritual(), 0, 0, 0],
        Token::TemporaryFocus => [state.orbs.temp_focus(), 0, 0, 0],
        Token::TemporaryStrength => [state.temp_strength, 0, 0, 0],
        Token::Tender => [state.fanouts.tender_cards_played(), 0, 0, 0],
        Token::DarkEmbrace => [
            state.powers.value(PowerId::DarkEmbrace),
            state.fanouts.dark_embrace_ethereal(),
            0,
            0,
        ],
        Token::Juggling => [
            state.powers.value(PowerId::Juggling),
            state.powers.value(PowerId::JugglingAttacks),
            0,
            0,
        ],
        Token::PaleBlueDot => [
            state.powers.value(PowerId::PaleBlueDot),
            i32::from(state.fanouts.pale_blue_dot_used()),
            0,
            0,
        ],
        Token::Smoggy => [
            state.powers.value(PowerId::Smoggy),
            state.powers.value(PowerId::SmogLock),
            0,
            0,
        ],
        token => [
            state
                .powers
                .value(after_side_turn_end_scalar_power(token).expect("scalar token")),
            0,
            0,
            0,
        ],
    })
}

fn capture_after_side_turn_end_power_record(
    state: &HotState,
    conqueror_reachable_at_entry: bool,
) -> Result<Option<AfterSideTurnEndPowerRecord>, EngineRefusal> {
    if !after_side_turn_end_power_order_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "after-side-turn-end player-power object ledger",
        ));
    }
    let mut listeners = Vec::with_capacity(state.fanouts.after_side_turn_end_power_order().len());
    for object in state
        .fanouts
        .after_side_turn_end_power_order()
        .iter()
        .copied()
    {
        let payload = current_after_side_turn_end_payload(state, object)?;
        listeners.push(AfterSideTurnEndPowerSnapshot { object, payload });
    }
    Ok(
        (!listeners.is_empty()).then_some(AfterSideTurnEndPowerRecord {
            listeners,
            cursor: 0,
            dark_pending_uid: None,
            ordinary_suffix_invoked: false,
            conqueror_reachable_at_entry,
        }),
    )
}

#[inline]
#[allow(clippy::too_many_arguments)]
fn finish_player_turn_after_auto_post_with_carriers(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
    conqueror_reachable_at_entry: bool,
    _constrict_reachable_at_entry: bool,
    _tender_reachable_at_entry: bool,
    _double_damage: i32,
) -> Result<(), EngineRefusal> {
    state.player_phase = PHASE_TURN_END;

    // The VeryEarly, Early and ordinary passes of the deferred-choice
    // `Hook.BeforeSideTurnEnd`, which `WhenAll`s once after all three
    // (#3386, `puzzle::DeferredChoiceListener`).
    let before_side_turn_end_listener =
        DeferredChoiceListener::enter(Some(BEFORE_SIDE_TURN_END_WALL));

    // Orichalcum's VeryEarly pass observes Block before Plating, Regen, or
    // ordinary owner-power listeners. Its later body consumes this latch.
    let (orichalcum_latched, fake_orichalcum_latched) =
        super::relics::orichalcum_latches(catalog, state);

    // PlatingPower is the player-power member of BeforeSideTurnEndEarly. It
    // grants flat block before the relic group and before orb passives.
    let plating = state.powers.value(PowerId::Plating);
    if plating > 0 {
        super::orbs::gain_flat_block(state, catalog, i64::from(plating), events)?;
    }

    // RegenPower.BeforeSideTurnEndEarly (RVA 0x388cd0) heals its living
    // owner for the current Intensity, then decrements exactly one stack.
    // It runs in the same Early pass after Plating and before the ordinary
    // player-power listener walk.
    let regen = state.fanouts.regen();
    if regen > 0 && state.hp > 0 {
        let hp_before = state.hp;
        state.hp = i64::from(state.max_hp)
            .min(i64::from(state.hp) + i64::from(regen))
            .try_into()
            .map_err(|_| EngineRefusal::CounterOverflow("regen heal"))?;
        // The Regen heal is a `CreatureCmd.Heal` (`0x3eb4b0`); Red Skull's
        // `AfterCurrentHpChanged` runs inside it, before the decrement
        // (#3044).
        super::damage::red_skull_after_player_hp_changed(state, hp_before, state.max_hp, events)?;
        assert!(state.fanouts.set_regen(regen - 1));
    }

    // Regret's BeforeSideTurnEnd count (#2561) reads the live Hand; take the
    // Hand before any BeforeSideTurnEnd listener in this pass can move it.
    let regret_hand_before = regret_hand_snapshot(state, catalog);

    // Ordinary BeforeSideTurnEnd player powers follow the Early Plating pass
    // and precede relic listeners and DoTurnEnd's orb passives.
    run_before_side_turn_end_player_powers(state, catalog, events)?;

    // Pael's Eye freezes the live Hand after the player-power Early pass and
    // exhausts that exact order before the remaining relic listeners.
    if super::relics::paels_eye_extra_turn_gate(state, catalog) && !state.history.over {
        // A Joss Paper Draw parked by one of these Exhausts pauses Pael's
        // Eye's Early listener, and native starts every later Early and
        // ordinary BeforeSideTurnEnd listener (Regret's Hand count, Screaming
        // Flagon's empty-Hand test, Pael's Tears) before the choice (#3386).
        let _listener = DeferredChoiceListener::enter(Some(PAELS_EYE_JOSS_WALL));
        super::cards::normalize_card_identities(state)?;
        let frozen = state.piles.get(PileId::Hand).as_slice().to_vec();
        for card in frozen {
            let hand = state.piles.get(PileId::Hand).as_slice();
            let index = hand
                .iter()
                .position(|candidate| candidate.uid == card.uid)
                .ok_or(EngineRefusal::ContinuationNotModeled)?;
            // PaelsEye/<BeforeSideTurnEndEarly>d__16 (RVA 0x32c36c) IL_0072
            // snapshots the Hand and IL_00a1 awaits CardCmd.Exhaust per card
            // with no loop gate of its own; Exhaust's IsOverOrEnding gate
            // (RVA 0x3e06c8, IL_0020–0034) leaves every card after a
            // fight-ending exhaust listener in Hand (#3041).
            let Some(card) = super::draw::detach_card_for_exhaust(state, PileId::Hand, index)?
            else {
                continue;
            };
            super::draw::card_exhausted(state, catalog, card, events)?;
            if state.pending.is_some() {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
        }
        crate::coverage::record_relic(RelicId::RelicPaelsEye);
    }

    super::relics::before_side_turn_end_hand(
        catalog,
        state,
        orichalcum_latched,
        fake_orichalcum_latched,
        events,
    )?;

    // `_end_player_turn_after_auto_post` fires BeforeSideTurnEnd here (D5).
    fire_hook(catalog, HookEvent::BeforeSideTurnEnd, state, events)?;
    super::relics::after_before_side_turn_end(catalog, state);
    drop(before_side_turn_end_listener);
    let regret_hand_count = regret_before_side_turn_end_count(
        regret_hand_before,
        regret_hand_snapshot(state, catalog),
    )?;

    // `OrbQueue::BeforeTurnEnd` is the first command in native DoTurnEnd.
    // It snapshots all five admitted kinds and persists Dark/Glass mutation.
    super::orbs::turn_end_passives(state, catalog, events)?;
    if state.history.over {
        return Ok(());
    }

    // DoTurnEnd takes disjoint snapshots from the same live Hand. Ordinary
    // Ethereal cards exhaust first in captured Hand order; turn-end-in-hand
    // cards then move to Play before their bodies run. Dazed is the only
    // admitted ordinary-Ethereal row, while Infection is one turn-end body.
    super::cards::normalize_card_identities(state)?;
    run_ordinary_ethereal_cards(state, catalog, events)?;
    if state.history.over {
        return Ok(());
    }
    run_turn_end_in_hand_cards_with_regret(state, catalog, regret_hand_count, events)?;
    if state.history.over {
        return Ok(());
    }

    // Chains of Binding, The Bomb, Pael's Eye, the remaining
    // orb kinds, and the Ethereal wrappers all still need refused content.
    if should_flush_player_hand(state, catalog) {
        flush_hand(state, catalog, events)?;
    } else if state.powers.value(PowerId::WellLaidPlans) == 0
        && state.powers.value(PowerId::RetainHand) == 0
        && catalog.hooks().owns(crate::ids::RelicId::RelicRunicPyramid)
    {
        crate::coverage::record_relic(crate::ids::RelicId::RelicRunicPyramid);
    }
    // `CardModel.CleanupAfterTurn` follows the hand flush and removes every
    // local Energy-cost row whose expiration mask contains ThisTurn.
    state
        .card_states
        .cleanup_local_cost_modifiers(LocalCostExpiration::ThisTurn);
    // `CardModel.CleanupAfterTurn` clears every transient keyword across all
    // five live piles after the Retain-aware hand flush. Combat-local Retain
    // remains attached to its exact physical instance. Python's cleanup uses
    // the ordinary (non-force-exact) commit: clearing a keyword cannot create
    // a new distinguishable tie, while exact mode established by a keyword
    // writer is one-way and remains set here.
    state.card_states.cleanup_transient_keywords();

    // Rust's admitted Consuming Shadow body has no suspension source: orb
    // eviction and the no-relic monster-death suffix complete before return.
    // With no later captured player-power object, its precommitted iterator
    // state therefore fits on this stack. Avoid materializing an otherwise
    // immediately discarded owner frame; this preserves the frozen bounded
    // COW cost of the existing synchronous turn transaction. Object identity
    // still matters inside the callback, which re-reads the live Amount only
    // while this exact uid remains attached.
    if !after_side_turn_end_power_order_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "after-side-turn-end player-power object ledger",
        ));
    }
    if let [object] = state.fanouts.after_side_turn_end_power_order()
        && object.token == AfterSideTurnEndPowerToken::ConsumingShadow
    {
        let object = *object;
        let payload = current_after_side_turn_end_payload(state, object)?;
        if !state.history.over {
            let _listener = DeferredChoiceListener::enter(Some(AFTER_SIDE_TURN_END_WALL));
            super::orbs::consuming_shadow_side_end_with_captured_amount(
                state, catalog, events, object.uid, payload[0],
            )?;
        }
        run_after_side_turn_end_ordinary_nonlocal(state, catalog, events)?;
        return finish_player_turn_after_ordinary_side_end(
            state,
            catalog,
            events,
            conqueror_reachable_at_entry,
        );
    }

    // Positive TemporaryStrengthPower is an owner-power member of the same
    // AfterSideTurnEnd group (`_dispatch_after_side_turn_end_power`, frozen Python, deleted #2827). Its additive contribution is held separately from
    // permanent Strength. Ordinary expiry applies the inverse before clearing;
    // an ending-gated inverse transfers the wrapper contribution into Strength.
    // The captured ledger routes that exact object through the dispatcher below.
    // DuplicatorPower removes every unspent Intensity stack at owner side
    // end. Individual GeneratePlayCount callbacks consume one stack earlier.
    let Some(record) =
        capture_after_side_turn_end_power_record(state, conqueror_reachable_at_entry)?
    else {
        run_after_side_turn_end_ordinary_nonlocal(state, catalog, events)?;
        return finish_player_turn_after_ordinary_side_end(
            state,
            catalog,
            events,
            conqueror_reachable_at_entry,
        );
    };
    let record_index = state.frames.push_after_side_turn_end_power(&record).ok_or(
        EngineRefusal::CounterOverflow("AfterSideTurnEnd power snapshot"),
    )?;
    if drive_after_side_turn_end_power(state, catalog, events, record_index)? {
        return Ok(());
    }
    let conqueror_reachable_at_entry = state
        .frames
        .pop_top_after_side_turn_end_power_completion()
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    finish_player_turn_after_ordinary_side_end(state, catalog, events, conqueror_reachable_at_entry)
}

#[inline]
fn should_flush_player_hand(state: &HotState, catalog: &Catalog) -> bool {
    state.powers.value(PowerId::WellLaidPlans) == 0
        && state.powers.value(PowerId::RetainHand) == 0
        && !catalog.hooks().owns(crate::ids::RelicId::RelicRunicPyramid)
        && !(state.turn <= 1
            && catalog
                .hooks()
                .owns(crate::ids::RelicId::RelicRingingTriangle))
}

fn captured_after_side_turn_end_object_is_current(
    state: &HotState,
    object: AfterSideTurnEndPowerEntry,
) -> bool {
    state
        .fanouts
        .after_side_turn_end_power_order()
        .contains(&object)
}

fn unregister_captured_after_side_turn_end_object(
    state: &mut HotState,
    object: AfterSideTurnEndPowerEntry,
) -> Result<(), EngineRefusal> {
    if !captured_after_side_turn_end_object_is_current(state, object) {
        return Err(EngineRefusal::MalformedArgs(
            "after-side-turn-end object removal",
        ));
    }
    // A native object reference remains callable after detachment. Preserve
    // its last live fields in every outstanding captured iterator before the
    // keyed/instanced live ledger forgets the uid.
    let payload = current_after_side_turn_end_payload(state, object)?;
    let frame_count = state.frames.as_slice().len();
    for frame_index in 0..frame_count {
        let Some(crate::frame::Frame::AfterSideTurnEndPower {
            record: record_index,
        }) = state.frames.as_slice().get(frame_index).copied()
        else {
            continue;
        };
        let owner = state
            .frames
            .after_side_turn_end_power(record_index)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        let cursor = owner.cursor as usize;
        let Some(listener_index) = owner.listeners().enumerate().find_map(|(index, listener)| {
            (index >= cursor && listener.object == object).then_some(index)
        }) else {
            continue;
        };
        state
            .frames
            .set_after_side_turn_end_power_payload(record_index, listener_index, payload)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
    }
    state
        .fanouts
        .unregister_after_side_turn_end_power(object.token, object.uid)
        .map_err(|_| EngineRefusal::MalformedArgs("after-side-turn-end object removal"))
}

/// Writer-side tombstone barrier for removing one currently attached keyed
/// member. Call this immediately before clearing the carrier; it is a no-op
/// only when the keyed object is already absent.
pub(crate) fn detach_current_after_side_turn_end_power(
    state: &mut HotState,
    token: AfterSideTurnEndPowerToken,
) -> Result<(), EngineRefusal> {
    let Some(uid) = state.fanouts.after_side_turn_end_power_uid(token) else {
        return Ok(());
    };
    let object = AfterSideTurnEndPowerEntry { token, uid };
    let payload = current_after_side_turn_end_payload(state, object)?;
    let callback_is_pending = state.frames.as_slice().iter().any(|frame| {
        let crate::frame::Frame::AfterSideTurnEndPower { record } = *frame else {
            return false;
        };
        state
            .frames
            .after_side_turn_end_power(record)
            .is_some_and(|owner| {
                owner.listeners().enumerate().any(|(index, listener)| {
                    listener.object == object && index >= owner.cursor as usize
                })
            })
    });
    let transfer = callback_is_pending
        .then(|| temporary_wrapper_transfer(state, token, payload[0]))
        .transpose()?
        .flatten();
    unregister_captured_after_side_turn_end_object(state, object)?;
    if let Some((power, amount)) = transfer {
        state.powers.set(power, SlotWire::Int, amount);
    }
    Ok(())
}

/// Maintain the keyed ordinary side-end object identity for one scalar power
/// mutation. Call after all fallible arithmetic has succeeded and immediately
/// before writing the scalar carrier. A restack retains the existing object;
/// zero-to-nonzero appends one fresh native acquisition uid; removal first
/// writes the last live fields through to every not-yet-started snapshot.
pub(crate) fn prepare_after_side_turn_end_scalar_write(
    state: &mut HotState,
    power: PowerId,
    current: i32,
    updated: i32,
) -> Result<(), EngineRefusal> {
    let Some(token) = AfterSideTurnEndPowerToken::from_power(power) else {
        return Ok(());
    };
    prepare_after_side_turn_end_singleton_write(state, token, current != 0, updated != 0)
}

/// Dedicated-carrier counterpart of
/// [`prepare_after_side_turn_end_scalar_write`].
pub(crate) fn prepare_after_side_turn_end_singleton_write(
    state: &mut HotState,
    token: AfterSideTurnEndPowerToken,
    current: bool,
    updated: bool,
) -> Result<(), EngineRefusal> {
    if token.is_instanced() {
        return Err(EngineRefusal::MalformedArgs(
            "instanced after-side-turn-end object writer",
        ));
    }
    match (current, updated) {
        (false, false) => Ok(()),
        (false, true) => state
            .fanouts
            .register_after_side_turn_end_power(token)
            .map(|_| ())
            .map_err(|_| EngineRefusal::CounterOverflow("after-side-turn-end listener order")),
        (true, false) => {
            if state.fanouts.after_side_turn_end_power_uid(token).is_none() {
                return Err(EngineRefusal::MalformedArgs(
                    "after-side-turn-end scalar object ledger",
                ));
            }
            detach_current_after_side_turn_end_power(state, token)
        }
        (true, true) => {
            if state.fanouts.after_side_turn_end_power_uid(token).is_some() {
                Ok(())
            } else {
                Err(EngineRefusal::MalformedArgs(
                    "after-side-turn-end scalar object ledger",
                ))
            }
        }
    }
}

fn temporary_wrapper_transfer(
    state: &HotState,
    token: AfterSideTurnEndPowerToken,
    amount: i32,
) -> Result<Option<(PowerId, i32)>, EngineRefusal> {
    use AfterSideTurnEndPowerToken as Token;
    let persistent = match token {
        Token::TemporaryDexterity => PowerId::Dexterity,
        Token::TemporaryFocus => PowerId::Focus,
        Token::TemporaryStrength => PowerId::Strength,
        _ => return Ok(None),
    };
    let updated = state.powers.value(persistent).checked_add(amount).ok_or(
        EngineRefusal::CounterOverflow("temporary stat detach transfer"),
    )?;
    Ok(Some((persistent, updated)))
}

fn remove_captured_scalar_power(
    state: &mut HotState,
    object: AfterSideTurnEndPowerEntry,
    power: PowerId,
    wire: SlotWire,
    events: &mut Vec<Event>,
) -> Result<bool, EngineRefusal> {
    if !captured_after_side_turn_end_object_is_current(state, object) {
        super::damage::note_power(events, Subject::Player, power, 0);
        return Ok(false);
    }
    unregister_captured_after_side_turn_end_object(state, object)?;
    state.powers.set(power, wire, 0);
    super::damage::note_power(events, Subject::Player, power, 0);
    Ok(true)
}

fn store_after_side_turn_end_payload(
    state: &mut HotState,
    record_index: crate::hot::WordRecordIndex,
    listener_index: usize,
    payload: [i32; 4],
) -> Result<(), EngineRefusal> {
    state
        .frames
        .set_after_side_turn_end_power_payload(record_index, listener_index, payload)
        .ok_or(EngineRefusal::ContinuationNotModeled)
}

fn dispatch_after_side_turn_end_power(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
    record_index: crate::hot::WordRecordIndex,
    listener_index: usize,
) -> Result<bool, EngineRefusal> {
    use AfterSideTurnEndPowerToken as Token;
    let mut listener = state
        .frames
        .after_side_turn_end_power(record_index)
        .ok_or(EngineRefusal::ContinuationNotModeled)?
        .listeners()
        .nth(listener_index)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let object = listener.object;
    let current = captured_after_side_turn_end_object_is_current(state, object);
    if current {
        listener.payload = current_after_side_turn_end_payload(state, object)?;
        state
            .frames
            .set_after_side_turn_end_power_payload(record_index, listener_index, listener.payload)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
    }
    let mut payload = listener.payload;
    match object.token {
        Token::BorrowedTime => {
            remove_captured_scalar_power(
                state,
                object,
                PowerId::BorrowedTime,
                SlotWire::Int,
                events,
            )?;
            payload[0] = 0;
        }
        Token::Burst => {
            remove_captured_scalar_power(state, object, PowerId::Burst, SlotWire::Int, events)?;
            payload[0] = 0;
        }
        Token::Constrict => {
            if !state.history.over && payload[0] > 0 {
                // `ConstrictPower/<AfterSideTurnEnd>d__4` damages its owner
                // through the listener's own choice context, so a Centennial
                // Puzzle Draw parked here would publish before every later
                // ordinary side-end listener (#3386).
                let _listener = DeferredChoiceListener::enter(Some(CONSTRICT_PUZZLE_WALL));
                super::damage::damage_player_from_power_with_catalog(
                    state,
                    catalog,
                    i64::from(payload[0]),
                    true,
                    events,
                )?;
            }
        }
        Token::ConsumingShadow => {
            if !state.history.over {
                super::orbs::consuming_shadow_side_end_with_captured_amount(
                    state, catalog, events, object.uid, payload[0],
                )?;
            }
        }
        Token::CorrosiveWave => {
            if current {
                expire_corrosive_wave_side_end(state, events)?;
                unregister_captured_after_side_turn_end_object(state, object)?;
            } else {
                super::damage::note_power(events, Subject::Player, PowerId::CorrosiveWave, 0);
            }
            payload[0] = 0;
        }
        Token::DarkEmbrace => {
            let ethereal_tally = payload[1];
            if ethereal_tally > 0 {
                let requested = payload[0]
                    .checked_mul(ethereal_tally)
                    .and_then(|value| usize::try_from(value).ok())
                    .ok_or(EngineRefusal::CounterOverflow("dark embrace ethereal draw"))?;
                state
                    .frames
                    .set_after_side_turn_end_power_dark_pending_uid(record_index, Some(object.uid))
                    .ok_or(EngineRefusal::ContinuationNotModeled)?;
                state.frames.push(crate::frame::Frame::DarkEmbraceSideEnd {
                    record: record_index,
                });
                if draw_cards_for_potion(
                    state,
                    catalog,
                    requested,
                    DrawCaller::DarkEmbraceSideEnd,
                    events,
                )? == PotionDrawResult::Suspended
                {
                    return Ok(true);
                }
                if state.frames.pop()
                    != Some(crate::frame::Frame::DarkEmbraceSideEnd {
                        record: record_index,
                    })
                {
                    return Err(EngineRefusal::ContinuationNotModeled);
                }
                state
                    .frames
                    .set_after_side_turn_end_power_dark_pending_uid(record_index, None)
                    .ok_or(EngineRefusal::ContinuationNotModeled)?;
                payload[1] = 0;
                if captured_after_side_turn_end_object_is_current(state, object) {
                    state.fanouts.set_dark_embrace_ethereal(0);
                }
                state
                    .frames
                    .set_after_side_turn_end_power_payload(record_index, listener_index, payload)
                    .ok_or(EngineRefusal::ContinuationNotModeled)?;
            }
        }
        Token::Doom => {
            let amount = payload[0];
            if !state.history.over && state.hp > 0 && amount > 0 && state.hp <= amount {
                super::damage::doom_kill_player(state, Some(catalog), events)?;
            }
        }
        Token::DoubleDamage => {
            if !state.history.over && payload[0] > 0 {
                if current {
                    super::damage::modify_shadow_step_power_amount(
                        state,
                        PowerId::DoubleDamage,
                        -1,
                        events,
                    )?;
                    payload[0] = state.powers.value(PowerId::DoubleDamage);
                } else {
                    payload[0] -= 1;
                    super::damage::note_power(
                        events,
                        Subject::Player,
                        PowerId::DoubleDamage,
                        payload[0],
                    );
                }
            }
        }
        Token::Duplication => {
            if current {
                unregister_captured_after_side_turn_end_object(state, object)?;
                state.fanouts.set_duplication(0);
            }
            payload[0] = 0;
        }
        Token::Hellraiser => {
            payload[1] = 0;
            payload[2] = 0;
        }
        Token::Juggling => {
            if current && state.powers.value(PowerId::JugglingAttacks) != 0 {
                state.powers.set(PowerId::JugglingAttacks, SlotWire::Int, 0);
                super::damage::note_power(events, Subject::Player, PowerId::JugglingAttacks, 0);
            }
            payload[1] = 0;
        }
        Token::Monologue => {
            if current {
                let instance = state
                    .fanouts
                    .remove_monologue_instance(object.uid)
                    .map_err(|_| EngineRefusal::MalformedArgs("Monologue object removal"))?;
                let remaining = state
                    .powers
                    .value(PowerId::Monologue)
                    .checked_sub(instance.amount)
                    .ok_or(EngineRefusal::CounterOverflow("monologue amount"))?;
                state
                    .powers
                    .set(PowerId::Monologue, SlotWire::Int, remaining);
                super::damage::note_power(events, Subject::Player, PowerId::Monologue, 0);
            }
            if payload[2] > 0 && !state.history.over {
                super::damage::apply_owner_strength(state, -payload[2], events)?;
            }
        }
        Token::NoDraw => {
            remove_captured_scalar_power(state, object, PowerId::NoDraw, SlotWire::Int, events)?;
            payload[0] = 0;
        }
        Token::NoEnergyGain => {
            if current {
                unregister_captured_after_side_turn_end_object(state, object)?;
                state.fanouts.set_no_energy_gain(false);
            }
            payload[0] = 0;
        }
        Token::OneTwoPunch => {
            remove_captured_scalar_power(
                state,
                object,
                PowerId::OneTwoPunch,
                SlotWire::Int,
                events,
            )?;
            payload[0] = 0;
        }
        Token::PaleBlueDot => {
            if current {
                state.fanouts.set_pale_blue_dot_used(false);
            }
            payload[1] = 0;
        }
        Token::Panache => {
            if current {
                let mut instances = state.fanouts.panache_instances().collect::<Vec<_>>();
                let instance = instances
                    .iter_mut()
                    .find(|instance| instance.uid == object.uid)
                    .ok_or(EngineRefusal::MalformedArgs("Panache side-end object"))?;
                instance.cards_left = 5;
                let monologue = state.fanouts.monologue_instances().collect::<Vec<_>>();
                if !state
                    .fanouts
                    .set_instanced_player_power_instances(&instances, &monologue)
                {
                    return Err(EngineRefusal::MalformedArgs("Panache side-end object"));
                }
            }
            payload[1] = 5;
        }
        Token::Rage => {
            if current {
                let amount = state.powers.value(PowerId::Rage);
                super::play::prepare_after_card_played_scalar_write(
                    state,
                    PowerId::Rage,
                    amount,
                    0,
                )?;
                state.powers.set(PowerId::Rage, SlotWire::Int, 0);
            }
            super::damage::note_power(events, Subject::Player, PowerId::Rage, 0);
            payload[0] = 0;
        }
        Token::Rebound => {
            if remove_captured_scalar_power(state, object, PowerId::Rebound, SlotWire::Int, events)?
            {
                state
                    .fanouts
                    .unregister_result_location_power(PowerId::Rebound);
            }
            payload[0] = 0;
        }
        Token::RetainHand => {
            if !state.history.over && payload[0] > 0 {
                let updated = payload[0] - 1;
                if current {
                    if updated == 0 {
                        unregister_captured_after_side_turn_end_object(state, object)?;
                    }
                    state
                        .powers
                        .set(PowerId::RetainHand, SlotWire::Int, updated);
                }
                super::damage::note_power(events, Subject::Player, PowerId::RetainHand, updated);
                payload[0] = updated;
            }
        }
        Token::Ringing => {
            if current {
                unregister_captured_after_side_turn_end_object(state, object)?;
                super::cards::remove_ringing_power(state);
            } else {
                super::cards::clear_ringing_from_current_cards(state);
            }
            payload[0] = 0;
        }
        Token::Ritual => {
            if !state.history.over && payload[0] > 0 {
                super::damage::apply_owner_strength(state, payload[0], events)?;
            }
        }
        Token::Shadowmeld => {
            remove_captured_scalar_power(
                state,
                object,
                PowerId::Shadowmeld,
                SlotWire::Int,
                events,
            )?;
            payload[0] = 0;
        }
        Token::Smoggy => {
            // Smoggy's captured old object still walks the owner's cards when
            // detached; `Contains` is owner-active, not live-list membership.
            if state.powers.value(PowerId::SmogLock) != 0 {
                state.powers.set(PowerId::SmogLock, SlotWire::Bool, 0);
                super::damage::note_power(events, Subject::Player, PowerId::SmogLock, 0);
            }
            payload[1] = 0;
        }
        Token::Tangled => {
            if !current
                && state
                    .fanouts
                    .after_side_turn_end_power_uid(Token::Tangled)
                    .is_some()
            {
                // Removing the captured old native object clears Entangled
                // from current cards while leaving a distinct replacement
                // attached. This quotient has no per-card Entangled carrier.
                return Err(EngineRefusal::PowerRestackNotModeled(PowerId::Tangled));
            }
            remove_captured_scalar_power(state, object, PowerId::Tangled, SlotWire::Int, events)?;
            payload[0] = 0;
        }
        Token::TemporaryDexterity => {
            if current {
                let transfer = state
                    .history
                    .over
                    .then(|| temporary_wrapper_transfer(state, object.token, payload[0]))
                    .transpose()?
                    .flatten();
                unregister_captured_after_side_turn_end_object(state, object)?;
                if let Some((power, amount)) = transfer {
                    state.powers.set(power, SlotWire::Int, amount);
                }
                state.powers.set(PowerId::TempDexterity, SlotWire::Int, 0);
                super::damage::note_power(events, Subject::Player, PowerId::TempDexterity, 0);
            } else if !state.history.over && payload[0] != 0 {
                super::damage::apply_signed_player_stat(
                    state,
                    PowerId::Dexterity,
                    -payload[0],
                    events,
                )?;
            }
            payload[0] = 0;
        }
        Token::TemporaryFocus => {
            if current {
                let transfer = state
                    .history
                    .over
                    .then(|| temporary_wrapper_transfer(state, object.token, payload[0]))
                    .transpose()?
                    .flatten();
                unregister_captured_after_side_turn_end_object(state, object)?;
                if let Some((power, amount)) = transfer {
                    state.powers.set(power, SlotWire::Int, amount);
                }
                state.orbs.set_temp_focus(0);
            } else if !state.history.over && payload[0] != 0 {
                super::damage::apply_signed_player_stat(
                    state,
                    PowerId::Focus,
                    -payload[0],
                    events,
                )?;
            }
            payload[0] = 0;
        }
        Token::TemporaryStrength => {
            if current {
                let transfer = state
                    .history
                    .over
                    .then(|| temporary_wrapper_transfer(state, object.token, payload[0]))
                    .transpose()?
                    .flatten();
                unregister_captured_after_side_turn_end_object(state, object)?;
                if let Some((power, amount)) = transfer {
                    state.powers.set(power, SlotWire::Int, amount);
                }
                state.temp_strength = 0;
            } else if !state.history.over && payload[0] != 0 {
                super::damage::apply_owner_strength(state, -payload[0], events)?;
            }
            payload[0] = 0;
        }
        Token::Tender => {
            let frozen = payload[0];
            if frozen > 0 && !state.history.over {
                super::damage::apply_signed_player_stat(state, PowerId::Strength, frozen, events)?;
                if !state.history.over {
                    let reread = if captured_after_side_turn_end_object_is_current(state, object) {
                        state.fanouts.tender_cards_played()
                    } else {
                        frozen
                    };
                    super::damage::apply_signed_player_stat(
                        state,
                        PowerId::Dexterity,
                        reread,
                        events,
                    )?;
                }
            }
            if current {
                let written = state.fanouts.set_tender_state(true, 0);
                debug_assert!(written);
            }
            payload[0] = 0;
        }
    }
    if captured_after_side_turn_end_object_is_current(state, object) {
        payload = current_after_side_turn_end_payload(state, object)?;
    }
    store_after_side_turn_end_payload(state, record_index, listener_index, payload)?;
    Ok(false)
}

fn run_after_side_turn_end_ordinary_nonlocal(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    // The ordinary pass of the deferred-choice `Hook.AfterSideTurnEnd`
    // (#3386, `puzzle::DeferredChoiceListener`).
    let _listener = DeferredChoiceListener::enter(Some(AFTER_SIDE_TURN_END_WALL));
    // The relic listeners, in the vouched inventory order or the fixed order
    // with its unproven interleavings refused (#3400).
    super::relics::after_side_turn_end_relics(catalog, state, events)?;
    if !state.history.over && state.multiplayer_ally_key == 1 {
        let ally = state.fanouts.multiplayer_ally_mut();
        ally.temp_strength = 0;
        ally.temp_dexterity = 0;
    }
    expire_oblivion_after_player_side_end(state, events);
    Ok(())
}

/// Advance every remaining captured ordinary listener.  A Dark child may be
/// parked below the currently exposed selector, but native starts this whole
/// suffix before awaiting Hook/WhenAll; the same-width record update is valid
/// below those descendant frames.
fn drive_after_side_turn_end_power(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
    record_index: crate::hot::WordRecordIndex,
) -> Result<bool, EngineRefusal> {
    // The same ordinary pass (#3386). A receipt-owned park under a captured
    // power listener would publish before the later listeners native starts
    // first; Dark Embrace's own frame-owned park runs them (above).
    let _listener = DeferredChoiceListener::enter(Some(AFTER_SIDE_TURN_END_WALL));
    loop {
        let record = state
            .frames
            .after_side_turn_end_power(record_index)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        let cursor = usize::try_from(record.cursor)
            .map_err(|_| EngineRefusal::CounterOverflow("AfterSideTurnEnd cursor"))?;
        let listener_count = record.listeners().len();
        let dark_pending = record.dark_pending_uid.is_some();
        if cursor == listener_count {
            run_after_side_turn_end_ordinary_nonlocal(state, catalog, events)?;
            if dark_pending {
                state
                    .frames
                    .set_after_side_turn_end_power_ordinary_suffix_invoked(record_index)
                    .ok_or(EngineRefusal::ContinuationNotModeled)?;
                return Ok(true);
            }
            return Ok(false);
        }
        let next_cursor = record
            .cursor
            .checked_add(1)
            .ok_or(EngineRefusal::CounterOverflow("AfterSideTurnEnd cursor"))?;
        state
            .frames
            .set_after_side_turn_end_power_cursor(record_index, next_cursor)
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        let _dark_suspended =
            dispatch_after_side_turn_end_power(state, catalog, events, record_index, cursor)?;
        // Deliberately continue after a parked Dark child and after terminal
        // effects. Native precommits the captured enumerator and invokes all
        // later ordinary callbacks before awaiting the aggregate.
    }
}

/// Resume Hook/WhenAll after Dark Embrace's exact captured object has
/// completed. The local/global ordinary suffix was already invoked before
/// the suspended state became observable.
pub(crate) fn resume_dark_embrace_side_end(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let Some(crate::frame::Frame::DarkEmbraceSideEnd { record }) = state.frames.top() else {
        return Err(EngineRefusal::ContinuationNotModeled);
    };
    let owner = state
        .frames
        .after_side_turn_end_power(record)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let listener_count = owner.listeners().len();
    let dark_uid = owner
        .dark_pending_uid
        .filter(|_| owner.cursor as usize == listener_count && owner.ordinary_suffix_invoked)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let dark = owner
        .listeners()
        .find(|listener| {
            listener.object.uid == dark_uid
                && listener.object.token == AfterSideTurnEndPowerToken::DarkEmbrace
        })
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if state.frames.pop() != Some(crate::frame::Frame::DarkEmbraceSideEnd { record }) {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    if captured_after_side_turn_end_object_is_current(state, dark.object) {
        state.fanouts.set_dark_embrace_ethereal(0);
    }
    let conqueror_reachable_at_entry = state
        .frames
        .pop_top_after_side_turn_end_power_completion()
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    finish_player_turn_after_ordinary_side_end(state, catalog, events, conqueror_reachable_at_entry)
}

pub(crate) fn dark_embrace_suspended_suffix_carriers_are_default(
    state: &HotState,
    _catalog: &Catalog,
) -> bool {
    if !after_side_turn_end_power_order_is_exact(state) {
        return false;
    }
    let Some(crate::frame::Frame::DarkEmbraceSideEnd { record }) =
        state.frames.as_slice().get(2).copied()
    else {
        return false;
    };
    if state.frames.as_slice().get(1).copied()
        != Some(crate::frame::Frame::AfterSideTurnEndPower { record })
    {
        return false;
    }
    state
        .frames
        .after_side_turn_end_power(record)
        .is_some_and(|owner| {
            owner.cursor as usize == owner.listeners().len()
                && owner.dark_pending_uid.is_some()
                && owner.ordinary_suffix_invoked
        })
}

/// CorrosiveWavePower owner-side end removes the whole singleton and all hook
/// registrations. Its `AfterCardDrawn` token must disappear with the power so
/// later draws cannot retain the expired poison callback.
fn corrosive_wave_side_end_state_is_exact(state: &HotState) -> bool {
    let order = state.fanouts.after_card_drawn_order();
    let corrosive = state.powers.get(PowerId::CorrosiveWave);
    let reachable = corrosive.is_some() || order.contains(&PowerId::CorrosiveWave);
    if !reachable {
        return true;
    }
    corrosive.is_some_and(|slot| slot.wire == SlotWire::Int && slot.value > 0)
        && super::draw::after_card_drawn_power_order_is_exact(state)
}

fn expire_corrosive_wave_side_end(
    state: &mut HotState,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if !corrosive_wave_side_end_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "Corrosive Wave draw listener order",
        ));
    }
    if state.powers.value(PowerId::CorrosiveWave) == 0 {
        return Ok(());
    }
    let mut order = state.fanouts.after_card_drawn_order().to_vec();
    order.retain(|power| *power != PowerId::CorrosiveWave);
    if !state.fanouts.set_after_card_drawn_order(&order) {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    state.powers.set(PowerId::CorrosiveWave, SlotWire::Int, 0);
    super::damage::note_power(events, Subject::Player, PowerId::CorrosiveWave, 0);
    Ok(())
}

fn finish_player_turn_after_ordinary_side_end(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
    conqueror_reachable_at_entry: bool,
) -> Result<(), EngineRefusal> {
    // The sole current AfterSideTurnEndLate override. It runs only after the
    // complete ordinary group above and before SwitchSides begins.
    let disintegration = state.powers.value(PowerId::Disintegration);
    if disintegration > 0 && !state.history.over {
        super::damage::damage_player_from_power_with_catalog(
            state,
            catalog,
            i64::from(disintegration),
            true,
            events,
        )?;
    }
    if state.history.over {
        return Ok(());
    }

    let paels_eye_extra = super::relics::paels_eye_extra_turn_gate(state, catalog);

    // SwitchFromPlayerToEnemySide checks cancellation after the complete
    // ordinary and late hooks. A lethal callback returns before this quotient
    // rollover just as it returns before SwitchSides.
    reset_own_side_end_counters(state, events);
    // `CombatManager/<SwitchFromPlayerToEnemySide>d__141::MoveNext` (RVA
    // `0x3f87dc`) clears `PlayersTakingExtraTurn` (IL_0059-005e) and re-adds
    // each player `Hook::ShouldTakeExtraTurn` approves (IL_0095-010a), before
    // `SwitchSides`. Pael's Eye is the represented approver (#3049).
    state.fanouts.set_players_taking_extra_turn(paels_eye_extra);

    if paels_eye_extra {
        state.turn = state
            .turn
            .checked_add(1)
            .ok_or(EngineRefusal::CounterOverflow("turn"))?;
        state.fanouts.set_paels_eye_used(true);
        state.history.manual_card_plays_finished_this_turn = 0;
        crate::coverage::record_relic(RelicId::RelicPaelsEye);
        return begin_player_turn_inner(state, catalog, events);
    }

    // --- side switch: the monster side begins ---------------------------
    // `CombatManager.SwitchSides` has completed the player's whole side-end
    // cascade; `_finish_side_switch_after_disintegration` marks the side (frozen Python, deleted #2827) and `begin_player_turn` unmarks it at the next player turn. The
    // marker is invisible unless the combat ends
    // *inside* the enemy phase, which is precisely the state the R0.7
    // differential caught this engine projecting wrongly.
    state.player_side_active = false;
    // `CombatManager::SwitchSides` clears every monster's `SpawnedThisTurn`
    // here (`MonsterModel::OnSideSwitch` RVA `0x82745` IL_0007-IL_0009); a
    // creature the enemy side start adds below is still flagged when the act
    // walk reaches it (see [`enemy_side_start_act_roster`]).
    let switched_roster = SwitchedRoster {
        len: state.monsters.len(),
        max_uid: state.monsters.iter().map(|monster| monster.uid).max(),
    };
    // `BurrowedPower.ShouldClearBlock` is the only admitted listener that
    // keeps its owner's block. Monster Plating's side-start half runs after
    // this clear and only decrements (never on round one); its Block is
    // gained at the round-one player-side start and at each enemy side end
    // (`monster_plating_after_enemy_side_start`, #2809).
    let round_number = state.history.round_number;
    for monster in state.monsters_mut().iter_mut() {
        if monster.hp <= 0 {
            continue;
        }
        if monster.powers.value(PowerId::Burrowed) == 0 {
            monster.block = 0;
        }
        // Both resets sit inside the same `hp > 0` guard as the block clear
        // and outside the Burrowed conditional
        // (`_finish_side_switch_after_disintegration` (frozen Python, deleted #2827)).
        //
        // SlowPower.AfterSideTurnStart (v0.111.0 RVA `0xa7e84`) zeroes
        // `SlowAmount` and its cosmetic `DisplayAmount` when
        // `participants.Contains(Owner)` (IL_000c-IL_0018); every living
        // monster is a participant of the side starting here, so the gate is
        // discharged. Skulking Colony's window is the same shape: the
        // hardened-shell cap is per side turn, so the accumulator resets with
        // the side.
        //
        // The two counters share one packed word with the Waterfall/Test
        // Subject/Queen/Merc payloads, so each write is kind-gated at the call
        // site: an unguarded `set_` here would clear another tenant's state.
        if monster.kind == MonsterKind::BygoneEffigy {
            monster.set_bygone_effigy_slow(0);
        }
        if monster.kind == MonsterKind::SkulkingColony {
            monster.set_skulking_colony_shell_window(0);
        }
    }

    monster_plating_after_enemy_side_start(state, round_number, events);

    // `_finish_side_switch_after_disintegration` runs
    // `PoisonPower.AfterSideTurnStart` (frozen Python, deleted #2827), after the block
    // clear and before the ACT walk. Sandpit follows it. (Rampart is a
    // player-side listener, `rampart_after_player_side_start`, #3049.) A
    // poison kill that ends the fight stops the side start outright, so the
    // enemy phase does not act.
    if !tick_monster_poison_after_catalog_auth(state, catalog, events)? {
        return Ok(());
    }
    if !tick_insatiable_sandpit(state, events)? {
        return Ok(());
    }

    match enemy_side_start_act_roster(state, switched_roster)? {
        None => {
            run_enemy_phase_after_player_turn(state, catalog, conqueror_reachable_at_entry, events)
        }
        Some(roster) => run_enemy_phase_inner(
            state,
            catalog,
            Some(conqueror_reachable_at_entry),
            Some(roster),
            events,
        ),
    }
}

/// The enemy act walk's roster when the enemy side start added a creature
/// (census 0QQ4T432GXT6 node 11: a Phrog Parasite killed by the enemy-side
/// Poison tick), else `None` for the ordinary whole-roster walk.
///
/// Native authority: v0.111.0 DLL SHA256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`.
/// `CombatManager::AddCreature` calls `MonsterModel::SetUpForCombat` (RVA
/// `0x825b3`), which sets `SpawnedThisTurn` (IL_000d-IL_000f); only
/// `MonsterModel::OnSideSwitch` (RVA `0x82745` IL_0007-IL_0009, from
/// `CombatManager::SwitchSides`) clears it. `Creature/<TakeTurn>d__140::
/// MoveNext` (RVA `0x3db0d0`) skips `PerformMove` for a monster whose
/// `SpawnedThisTurn` is set (IL_003a-IL_0044), and
/// `CombatManager/<ExecuteEnemyTurn>d__126::MoveNext` (RVA `0x3f597c`
/// IL_00e4-IL_01c4) calls `TakeTurn` on every contained enemy. A creature
/// added after the side switch — here by `InfestedPower.AfterDeath` inside
/// `PoisonPower.AfterSideTurnStart` — therefore spends that enemy turn
/// without performing anything.
///
/// Skipping the walk also leaves native's machine unperformed, so the next
/// `PrepareForNextTurn` roll does not transition it (`MonsterMoveStateMachine
/// ::FindNextMoveState` RVA `0x78e94` IL_002d-IL_0042, see
/// [`advance_segment_dead_states`]). Only the Wriggler's shape is modeled:
/// its unperformed initial `SPAWNED_MOVE` (`Wriggler::GenerateMoveStateMachine`
/// RVA `0xc5630` IL_011f-IL_012c when `StartStunned`) is `spawn_noop`, which
/// the roll never touches and the next act consumes. Any other creature added
/// here refuses by name.
fn enemy_side_start_act_roster(
    state: &HotState,
    switched: SwitchedRoster,
) -> Result<Option<Vec<u32>>, EngineRefusal> {
    // Creation uids come from `monsters::allocate_creature_uids`, which never
    // returns one at or below a present monster's uid, so the creatures added
    // since the switch are exactly those above its highest uid. The count
    // check refuses any removal that could hide one.
    let added = |uid: u32| switched.max_uid.is_none_or(|max| uid > max);
    let added_count = state
        .monsters
        .iter()
        .filter(|monster| added(monster.uid))
        .count();
    if added_count == 0 && state.monsters.len() == switched.len {
        return Ok(None);
    }
    if state.monsters.len() != switched.len + added_count {
        return Err(EngineRefusal::MalformedArgs(
            "enemy side start removed a creature",
        ));
    }
    for monster in state.monsters.iter() {
        if added(monster.uid) && !(monster.kind == MonsterKind::Wriggler && monster.spawn_noop) {
            return Err(EngineRefusal::MonsterLoopNotModeled(monster.kind));
        }
    }
    Ok(Some(
        state
            .monsters
            .iter()
            .map(|monster| monster.uid)
            .filter(|uid| !added(*uid))
            .collect(),
    ))
}

/// The roster shape at `CombatManager::SwitchSides`, before the enemy side
/// start can add a creature ([`enemy_side_start_act_roster`]).
#[derive(Clone, Copy, Debug)]
struct SwitchedRoster {
    len: usize,
    max_uid: Option<u32>,
}

/// Living Shield's `RampartPower.AfterSideTurnStart` (#2672, #3049).
///
/// Native authority: v0.111.0 DLL SHA256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`,
/// `RampartPower/<AfterSideTurnStart>d__6::MoveNext` RVA `0x3416a0`:
///
/// * `side == 1` (`CombatSide.Player`; None=0, Player=1, Enemy=2) at
///   IL_001e-0024, else return. The grant is a **player**-side-start
///   listener, so it protects the Operator through the player's turn and the
///   enemy side's own block clear removes it. It runs on turn one too: the
///   opening's player side start fires the same hook.
/// * `CombatManager.PlayersTakingExtraTurn.Count > 0` returns at
///   IL_002b-003d: a Pael's Eye extra turn grants nothing
///   ([`crate::hot::HotFanouts::players_taking_extra_turn`]).
/// * Otherwise every enemy passing `<>c::<AfterSideTurnStart>b__6_0` (RVA
///   `0x34168e`, `Monster is TurretOperator`) gets
///   `CreatureCmd::GainBlock(creature, Amount, ValueProp 4 (Unpowered), null)`
///   at IL_0092-009f. `Amount` is the admitted fixed 25.
///   `CreatureCmd/<GainBlock>d__18::MoveNext` (RVA `0x3eaec0`) returns on
///   `IsOverOrEnding` (IL_002d-0041) and on a dead target (IL_004c-005b).
///
/// The owner is re-read live: the hook rechecks listener membership before
/// each callback, and Shield death cleanup zeroes Rampart
/// (`damage::finish_monster_death`), so a Shield killed earlier in the walk
/// (or on the enemy side) never grants again.
fn rampart_after_player_side_start(state: &mut HotState) -> Result<(), EngineRefusal> {
    let rampart_owner_is_live = state
        .monsters
        .iter()
        .any(|monster| monster.powers.value(PowerId::Rampart) != 0);
    if !rampart_owner_is_live {
        return Ok(());
    }
    // The roster shape the grant writes through. This is narrower than the
    // public `turret_operator_state_is_valid`: mid-command a Rust corpse may
    // carry negative (overkill) HP, which that boundary validator rejects.
    let roster_is_exact = matches!(
        state.monsters.as_slice(),
        [shield, operator]
            if shield.kind == MonsterKind::LivingShield
                && operator.kind == MonsterKind::TurretOperator
                && shield.hp > 0
                && shield.powers.value(PowerId::Rampart) == 25
                && operator.powers.value(PowerId::Rampart) == 0
    );
    if !roster_is_exact {
        return Err(EngineRefusal::MalformedArgs("Rampart owner/state"));
    }
    if state.fanouts.players_taking_extra_turn() || state.history.over {
        return Ok(());
    }
    let operator = &mut state.monsters_mut()[1];
    if operator.hp > 0 {
        operator.block = operator
            .block
            .checked_add(25)
            .filter(|block| *block <= super::monsters::MONSTER_BLOCK_CAP)
            .ok_or(EngineRefusal::CounterOverflow("Rampart block"))?;
    }
    Ok(())
}

/// Monster-owned `PlatingPower` (`Mplating`): the three native bodies (#2809).
///
/// Native authority: v0.111.0 DLL SHA256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`.
///
/// * **Round-one player-side start.** `PlatingPower::BeforeSideTurnStart` RVA
///   `0xa5b9c` continues only for `side == Player` (`IL_000c`-`IL_000e`) and a
///   non-player owner (`IL_0017`-`IL_0021`); `RoundNumber <= 1`
///   (`IL_0029`-`IL_0031`) then reaches `CreatureCmd::GainBlock(Owner,
///   Amount, Unpowered, null)` (`IL_0039`-`IL_004d`). Later rounds return.
///   [`monster_plating_before_player_side_start`].
/// * **Owner side end.** `PlatingPower/<BeforeSideTurnEndEarly>d__13::MoveNext`
///   RVA `0x340754`: when the owner is among the side's participants
///   (`IL_001d`-`IL_002e`), `Flash` then `GainBlock(Owner, Amount, Unpowered,
///   null)` (`IL_0035`-`IL_004f`). The enemy side's participants are
///   `CombatState::GetCreaturesOnSide(Enemy)` (`EndEnemyTurnInternal` RVA
///   `0x3f4784` `IL_0029`), and `Hook::BeforeSideTurnEnd` (`d__80` RVA
///   `0x3d34f4`) runs the whole `…VeryEarly` pass (`IL_00b0`), then the whole
///   `…Early` pass (`IL_01c9`), then the ordinary pass (`IL_02e7`, enemy Doom).
///   [`monster_plating_before_enemy_side_end`].
/// * **Owner side start: the decrement.**
///   `PlatingPower/<AfterSideTurnStart>d__14::MoveNext` RVA `0x340584`: owner
///   among participants (`IL_0027`-`IL_003a`); a player owner on turn one
///   returns (`IL_003f`-`IL_0064`); an enemy owner (`Side == 2`) on
///   `RoundNumber == 1` returns (`IL_0069`-`IL_0085`); an enemy owner then
///   `PowerCmd::ModifyAmount(this, -Decrement)` (`IL_008a`-`IL_00be`), where
///   `PlatingPower::AfterApplied` RVA `0xa5b48` sets `Decrement` to the
///   player count for an enemy owner (`IL_000c`-`IL_0049`) — one here.
///   [`monster_plating_after_enemy_side_start`].
///
/// So native gives Lagavulin Matriarch (Plating 12) Block 12 through the
/// whole of round one's player turn, 0 after its first side start (no
/// decrement), and 12 again from that side's end, 11 from round two's.
/// `GainBlock` with `Unpowered` has no admitted modifier or `AfterBlockGained`
/// monster listener, so the grant is the flat amount.
fn gain_monster_plating_block(monster: &mut HotMonster) -> Result<(), EngineRefusal> {
    let plating = monster.powers.value(PowerId::Mplating);
    if monster.hp <= 0 || plating <= 0 {
        return Ok(());
    }
    monster.block = monster
        .block
        .checked_add(plating)
        .filter(|block| *block <= super::monsters::MONSTER_BLOCK_CAP)
        .ok_or(EngineRefusal::CounterOverflow("monster Plating block"))?;
    Ok(())
}

/// `PlatingPower::BeforeSideTurnStart` for monster owners: Block equal to the
/// live Plating at the **player** side's start while `RoundNumber <= 1`. See
/// [`gain_monster_plating_block`] for the citation. A Pael's Eye extra turn
/// does not advance `RoundNumber` (`CombatManager::SwitchSides` RVA `0x136b08`
/// increments it only on the enemy-to-player switch, `IL_0079`-`IL_0097`), so
/// a round-one extra turn grants again, exactly as native.
///
/// It is the last member of the player-side `BeforeSideTurnStart` walk: the
/// generic listener snapshot is creature order, the player's powers and relics
/// before any monster's. No represented earlier member of that walk reads or
/// writes monster Block, so its position among them is not observable.
pub(crate) fn monster_plating_before_player_side_start(
    state: &mut HotState,
) -> Result<(), EngineRefusal> {
    if state.history.round_number > 1 {
        return Ok(());
    }
    for monster in state.monsters_mut().iter_mut() {
        gain_monster_plating_block(monster)?;
    }
    Ok(())
}

/// `PlatingPower/<BeforeSideTurnEndEarly>d__13` for monster owners: every
/// living enemy participant gains Block equal to its live Plating, before the
/// ordinary enemy `BeforeSideTurnEnd` pass (Doom). See
/// [`gain_monster_plating_block`].
fn monster_plating_before_enemy_side_end(state: &mut HotState) -> Result<(), EngineRefusal> {
    for monster in state.monsters_mut().iter_mut() {
        gain_monster_plating_block(monster)?;
    }
    Ok(())
}

/// `PlatingPower/<AfterSideTurnStart>d__14` for monster owners: from round two
/// on, each living owner loses one Plating (`Decrement` = one player) at its
/// own side start; round one returns without decrementing. A zero amount is the
/// removed power. See [`gain_monster_plating_block`].
fn monster_plating_after_enemy_side_start(
    state: &mut HotState,
    round_number: i16,
    events: &mut Vec<Event>,
) {
    if round_number <= 1 {
        return;
    }
    for monster in state.monsters_mut().iter_mut() {
        if monster.hp <= 0 {
            continue;
        }
        let plating = monster.powers.value(PowerId::Mplating);
        if plating <= 0 {
            continue;
        }
        monster
            .powers
            .set(PowerId::Mplating, SlotWire::Int, plating - 1);
        super::damage::note_power(
            events,
            Subject::Monster(monster.uid),
            PowerId::Mplating,
            plating - 1,
        );
    }
}

/// Execute the captured ordinary owner-power BeforeSideTurnEnd order.
///
/// Native enters this pass only while combat is live. Once its snapshot has
/// started, later listener bodies are still entered after a terminal prefix;
/// each nested command independently honors its own ending gate.
fn run_before_side_turn_end_player_powers(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let order = state.fanouts.before_side_turn_end_order().to_vec();
    for power in order {
        match power {
            BeforeSideTurnEndToken::ChainsOfBinding => {
                if state.powers.value(PowerId::ChainsOfBinding) > 0 {
                    state.set_bound_card_played(false);
                    state.set_bound_afflictions_this_turn(0);
                    for pile in super::cards::CARD_AFFLICTION_PILES {
                        for card in state.piles.get_mut(pile).make_mut() {
                            card.flags &= !crate::hot::CARD_FLAG_BOUND;
                        }
                    }
                }
            }
            BeforeSideTurnEndToken::Hailstorm => {
                let amount = state.powers.value(PowerId::Hailstorm);
                if !state.history.over
                    && amount > 0
                    && state
                        .orbs
                        .as_slice()
                        .iter()
                        .any(|orb| orb.kind() == OrbKind::Frost)
                {
                    // `HailstormPower/<BeforeSideTurnEnd>d__10::MoveNext` RVA
                    // `0x33ba50` (v0.111.0 DLL 9cb4f1ad…) awaits ONE
                    // `CreatureCmd.Damage(choiceContext, HittableEnemies,
                    // Amount, ValueProp 4, Owner)` (IL_009f-IL_00bb): the
                    // whole roster is committed before any result or death
                    // listener runs, then each death's AfterDeath walk runs
                    // with the parent command's catalog — Gremlin Horn draws
                    // there (#3166). Same batch shape as Glass's passive.
                    let targets = super::damage::alive_targets(state);
                    super::damage::damage_monsters_after_catalog_auth(
                        state,
                        catalog,
                        &targets,
                        DotNetDecimal::from_i64(i64::from(amount)),
                        true,
                        events,
                    )?;
                }
            }
            BeforeSideTurnEndToken::TheBomb(uid) => {
                let instance =
                    state
                        .fanouts
                        .the_bomb_instance(uid)
                        .ok_or(EngineRefusal::MalformedArgs(
                            "before-side-turn-end bomb order",
                        ))?;
                if instance.turns > 1 {
                    if !state.history.over {
                        let remaining = state.fanouts.decrement_the_bomb(uid).map_err(|_| {
                            EngineRefusal::MalformedArgs("the bomb countdown state")
                        })?;
                        super::damage::note_power(
                            events,
                            Subject::Player,
                            PowerId::TheBomb,
                            remaining,
                        );
                    }
                } else {
                    // `TheBombPower/<BeforeSideTurnEnd>d__9::MoveNext` RVA
                    // `0x349244` (v0.111.0 DLL 9cb4f1ad…) awaits ONE
                    // `CreatureCmd.Damage(choiceContext, HittableEnemies,
                    // DynamicVars.Damage, Owner)` (IL_01f7-IL_0212), a
                    // DamageVar carrying ValueProp 4 (`get_CanonicalVars` RVA
                    // `0xa9ee0` IL_0008), and only then `Remove` (IL_0271). The roster is frozen
                    // and every target committed before any result or death
                    // listener runs, so replacements or appended rows are not
                    // admitted; each death's AfterDeath walk then runs with
                    // the parent command's catalog — Gremlin Horn's
                    // GainEnergy + Draw (#3172). Same batch shape as Hailstorm.
                    if !state.history.over {
                        let targets = super::damage::alive_targets(state);
                        super::damage::damage_monsters_after_catalog_auth(
                            state,
                            catalog,
                            &targets,
                            DotNetDecimal::from_i64(i64::from(instance.damage)),
                            true,
                            events,
                        )?;
                    }
                    // This is native's direct instance removal after the
                    // awaited Damage command: it is not ending-gated and does
                    // not publish AfterPowerAmountChanged.
                    state
                        .fanouts
                        .remove_the_bomb(uid)
                        .map_err(|_| EngineRefusal::MalformedArgs("the bomb detonation state"))?;
                }
            }
        }
    }
    Ok(())
}

fn expire_oblivion_after_player_side_end(state: &mut HotState, events: &mut Vec<Event>) {
    for monster in state.monsters_mut().iter_mut() {
        let oblivion = monster.powers.value(PowerId::Oblivion);
        if monster.hp > 0 && oblivion > 0 {
            monster.powers.set(PowerId::Oblivion, SlotWire::Int, 0);
            monster
                .misery_debuff_order
                .remove_all(MiseryToken::Oblivion);
            super::damage::note_power(events, Subject::Monster(monster.uid), PowerId::Oblivion, 0);
        }
    }
}

#[cfg(test)]
fn run_constrict_side_end(
    state: &mut HotState,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if !crate::moves::spawned::constrict_listener_is_reachable(state) {
        return Ok(());
    }
    if !crate::moves::spawned::constrict_private_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs("constrict side-end state"));
    }
    let amount = state.fanouts.constrict_amount();
    super::damage::damage_player_from_power(state, i64::from(amount), true, events)?;
    Ok(())
}

#[cfg(test)]
fn run_tender_side_end(state: &mut HotState, events: &mut Vec<Event>) -> Result<(), EngineRefusal> {
    if !state.fanouts.tender_is_active() {
        return Ok(());
    }
    if !crate::moves::spawned::tender_side_end_entry_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs("tender side-end state"));
    }
    let frozen = state.fanouts.tender_cards_played();
    if frozen == 0 {
        return Ok(());
    }
    super::damage::apply_signed_player_stat(state, PowerId::Strength, frozen, events)?;
    if !crate::moves::spawned::tender_private_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs("tender side-end reread"));
    }
    let live = state.fanouts.tender_cards_played();
    super::damage::apply_signed_player_stat(state, PowerId::Dexterity, live, events)?;
    let written = state.fanouts.set_tender_state(true, 0);
    debug_assert!(written);
    Ok(())
}

#[cfg(test)]
fn expire_monologue_side_end(
    state: &mut HotState,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if state.powers.value(PowerId::Monologue) <= 0 {
        return Ok(());
    }
    let applied = state.fanouts.monologue_strength_applied();
    if !crate::steps::regent_uncommon::monologue_side_end_entry_is_exact(state)
        || !super::damage::player_type_one_listener_order_is_exact(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "monologue side-end listener state",
        ));
    }
    if applied > 0
        && !state.history.over
        && state
            .powers
            .value(PowerId::Strength)
            .checked_sub(applied)
            .is_none()
    {
        return Err(EngineRefusal::CounterOverflow("player strength"));
    }
    let uids = state
        .fanouts
        .monologue_instances()
        .map(|instance| instance.uid)
        .collect::<Vec<_>>();
    let mut remaining = state.powers.value(PowerId::Monologue);
    for uid in uids {
        let instance = state
            .fanouts
            .remove_monologue_instance(uid)
            .map_err(|_| EngineRefusal::MalformedArgs("monologue instance removal"))?;
        remaining = remaining
            .checked_sub(instance.amount)
            .ok_or(EngineRefusal::CounterOverflow("monologue amount"))?;
        state
            .powers
            .set(PowerId::Monologue, SlotWire::Int, remaining);
        // Native removes this exact fresh object; the established instanced
        // event quotient reports the removed object's resulting Amount (0),
        // not the aggregate of surviving sibling objects.
        super::damage::note_power(events, Subject::Player, PowerId::Monologue, 0);
        if instance.strength_applied > 0 && !state.history.over {
            // Native removes this exact object before its awaited reversal.
            super::damage::apply_owner_strength(state, -instance.strength_applied, events)?;
        }
    }
    debug_assert_eq!(state.fanouts.monologue_strength_applied(), 0);
    Ok(())
}

/// SandpitPower.AfterSideTurnStartLate and the AfterRemoved kill it reaches
/// (#3331).
///
/// Current-build authority is `sts2.dll` SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`.
/// Poison has already run and can clear Sandpit through ordinary owner death.
/// `SandpitPower/<AfterSideTurnStartLate>d__12::MoveNext` RVA `0x343788`
/// IL_001d-IL_0029 decrements on the enemy side (2) only. A decrement to zero
/// removes the power, and `SandpitPower/<AfterRemoved>d__14::MoveNext` RVA
/// `0x343428` does the rest:
///
/// - IL_002c-IL_004b return when the old owner or the Target (the player) is
///   already dead. A Poison-killed owner took the earlier exit above.
/// - IL_01df-IL_01e6 enumerate `AllAffectedCreatures` (RVA `0xa7220`
///   IL_000c-IL_0074): a fresh array holding the player's creature followed
///   by its `Pets`, snapshotted before any kill.
/// - IL_022c-IL_0246 call `CreatureCmd.Kill(creature, force: true)` for the
///   player and then for every pet whose `Monster` is `Osty`, one at a time.
///   Everything else in the body (IL_0050-IL_01d8, IL_020a-IL_0227) is
///   tweens, SFX, animation and a 0.5 s wait.
///
/// The player's own Kill ([`super::damage::force_kill_player`]) already
/// kills a still-live Osty (`<KillWithoutCheckingWinCondition>d__15` RVA
/// `0x3ebe90` IL_06ac-IL_06ca, passing the same `force`) before
/// `DeactivateHooks` at IL_072d. A live Osty therefore dies inside the
/// player's death exactly as it does under Doom. The later explicit Osty Kill
/// is a second `KillWithoutCheckingWinCondition` on an already-dead pet, with
/// the player's hooks deactivated:
///
/// - `forceKill` skips `ShouldDie` (IL_02d4), and the HP loss at IL_01dc is
///   zero.
/// - `PlayerCombatState::OnPetDied` RVA `0x11844c` either finds the pet
///   already unsubscribed and removed, or keeps a DieForYou-retained one.
/// - That leaves the monster-side `AfterCurrentHpChanged`, `BeforeDeath` and
///   `AfterDeath` listeners, and the Insatiable roster is the exact singleton
///   (`insatiable_state_is_valid`). `TheInsatiable::AfterDeath` RVA `0xc1632`
///   IL_0001-IL_000f returns unless its own creature died, and even then it
///   only sets a music parameter. The only other power the player can put on
///   it that implements those hooks is `ShrinkPower`, and the player's death
///   has already removed every instance.
///
/// So the second pass writes no represented state. A pet that died earlier in
/// the fight is the same no-op. The combat-ending projection is the player's:
/// `history.over` is set and the enemy side does not act.
fn tick_insatiable_sandpit(
    state: &mut HotState,
    events: &mut Vec<Event>,
) -> Result<bool, EngineRefusal> {
    let Some(index) = state
        .monsters
        .iter()
        .position(|monster| monster.kind == MonsterKind::TheInsatiable)
    else {
        if state
            .monsters
            .iter()
            .any(|monster| monster.powers.value(PowerId::Sandpit) != 0)
        {
            return Err(EngineRefusal::MalformedArgs(
                "The Insatiable/Sandpit lifecycle",
            ));
        }
        return Ok(true);
    };
    if state.monsters[index].hp <= 0 {
        return Ok(true);
    }
    let amount = state.monsters[index].powers.value(PowerId::Sandpit);
    if amount <= 0 {
        return Ok(true);
    }
    let updated = amount - 1;
    let uid = state.monsters[index].uid;
    state.monsters_mut()[index]
        .powers
        .set(PowerId::Sandpit, SlotWire::Int, updated);
    super::damage::note_power(events, Subject::Monster(uid), PowerId::Sandpit, updated);
    if updated == 0 && state.hp > 0 {
        super::damage::force_kill_player(state, events)?;
        return Ok(false);
    }
    Ok(true)
}

/// The counters that roll over at the player's *own* side end
/// (`_finish_side_switch_after_disintegration`, frozen Python, deleted #2827).
fn reset_own_side_end_counters(state: &mut HotState, _events: &mut Vec<Event>) {
    let history = &mut state.history;
    history.card_block_gains = 0;
    history.plays_this_turn = 0;
    history.attack_skill_plays_started_this_turn = 0;
    history.owner_attack_plays_started_this_turn = 0;
    // Python resets `normality_card_plays_started_this_turn` in
    // `_finish_side_switch_after_disintegration` (frozen Python, deleted #2827) with the counters
    // above. Zero is always representable; an untracked fight is already
    // zero and pays no cold copy-on-write.
    let reset = state.fanouts.set_normality_card_plays_started_this_turn(0);
    debug_assert!(reset);
}

/// Exhaust the initial Hand's ordinary-Ethereal snapshot in Hand order.
///
/// Python `_end_player_turn_after_auto_post` (frozen, deleted #2827) classifies cards
/// with an `OnTurnEndInHand` body into the separate wrapper snapshot first;
/// every remaining Ethereal card is removed from Hand immediately before its
/// serial `CardCmd.Exhaust`. The snapshot retains CardModel references rather
/// than cloned card values: immutable physical UID preserves capture order,
/// while each cursor re-reads the unique live Hand payload after prior
/// listeners have had a chance to mutate it.
///
/// Primary source: the archived v0.111.0 DLL (SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`)
/// `CombatManager/<DoTurnEnd>d__131::MoveNext` RVA `0x3f374c` builds the
/// ordered Hand snapshot at IL `0x00bf-0x0144` and passes each captured object
/// reference to `CardCmd.Exhaust` at IL `0x0158-0x01df`. Exhaust's state
/// machine RVA `0x3e06c8` performs the terminal check and exact-card move at
/// IL `0x0020-0x0107`; `CardPileCmd/<Add>d__10::MoveNext` RVA `0x3e1ba4`
/// removes and inserts that same object at IL `0x053b-0x062e`. Python
/// `_turn_end_snapshot_card` likewise locates the captured UID and returns its
/// current payload. Missing, duplicated, or non-Hand identities remain
/// fail-closed; legitimate listener mutation of a later sibling remains live.
fn run_ordinary_ethereal_cards(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let frozen = ordinary_ethereal_snapshot(state, catalog)?;
    if frozen.is_empty() {
        return Ok(());
    }
    for uid in frozen {
        if state.history.over {
            break;
        }
        let position = ordinary_ethereal_frozen_uid_position(state, uid)?;
        let card = state.piles.get_mut(PileId::Hand).as_slice()[position];
        let spec = catalog
            .spec(card.atom)
            .ok_or(EngineRefusal::UnknownAtom(card.atom))?;
        if matches!(spec.identity.id, CardId::DrumOfBattle) {
            super::draw::drum_of_battle_plan(state, spec, card, spec.identity.upgrade)?;
        }
        let card = state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .remove(position);
        super::draw::card_exhausted_by_ethereal(state, catalog, card, events)?;
    }
    Ok(())
}

fn ordinary_ethereal_frozen_uid_position(
    state: &HotState,
    uid: u32,
) -> Result<usize, EngineRefusal> {
    let matches = PileId::ALL
        .into_iter()
        .flat_map(|pile| state.piles.get(pile).as_slice())
        .filter(|card| card.uid == uid)
        .count();
    if matches > 1 {
        return Err(EngineRefusal::ActiveCardNotUnique { uid, matches });
    }
    let position = state
        .piles
        .get(PileId::Hand)
        .as_slice()
        .iter()
        .position(|card| card.uid == uid)
        .ok_or(EngineRefusal::FrozenCardVanished {
            uid,
            pile: PileId::Hand,
        })?;
    Ok(position)
}

fn ordinary_ethereal_snapshot(
    state: &HotState,
    catalog: &Catalog,
) -> Result<Vec<u32>, EngineRefusal> {
    let mut frozen = Vec::new();
    for card in state.piles.get(PileId::Hand).as_slice() {
        let Some(spec) = catalog.spec(card.atom) else {
            continue;
        };
        let row = spec.row;
        let has_turn_end_body = row.turn_end_dmg > 0
            || row.turn_end_hp_loss > 0
            || row.turn_end_weak > 0
            || row.turn_end_frail > 0
            || row.turn_end_hp_loss_hand
            || catalog
                .steps(spec)
                .iter()
                .any(|step| step.kind == StepKind::TurnEndGoldLossExact);
        if super::cards::effective_ethereal(state, spec, card.uid) && !has_turn_end_body {
            let matches = PileId::ALL
                .into_iter()
                .flat_map(|pile| state.piles.get(pile).as_slice())
                .filter(|live| live.uid == card.uid)
                .count();
            if matches != 1 {
                return Err(EngineRefusal::ActiveCardNotUnique {
                    uid: card.uid,
                    matches,
                });
            }
            frozen.push(card.uid);
        }
    }
    Ok(frozen)
}

/// Run the admitted `OnTurnEndInHand` wrappers in snapshot order.
///
/// Result pile (#3042). Primary source: the archived v0.111.0 DLL (SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`)
/// `CombatManager/<DoTurnEnd>d__131::MoveNext` RVA `0x3f374c` routes every
/// `HasTurnEndInHandEffect` card to the wrapper list at IL `0x00f7-0x0106`
/// before the ordinary Ethereal test, so these cards never reach the ordinary
/// Ethereal pass (nor its `Hook.ShouldEtherealTrigger` gate) and Retain is
/// read by neither list. `<ResolveTurnEndCardEffects>d__134::MoveNext` RVA
/// `0x3f64bc` awaits `OnTurnEndInHandWrapper` (IL `0x0090`), then reads the
/// card's CURRENT `Keywords` for Ethereal (IL `0x00f3-0x00fe`): Ethereal
/// calls `CardCmd.Exhaust(card, causedByEthereal: true, skipVisuals: true)`
/// (IL `0x0100-0x010e`), otherwise `CardPileCmd.Add(card, Discard)` (IL
/// `0x0172-0x018c`). `CardModel.get_Keywords` (RVA `0x7cbc4`) is
/// `GetKeywordsWithSources`, which folds in `Hook.ModifyKeywordsInCombat`;
/// `HexPower::TryModifyKeywordsInCombat` (RVA `0xa3755`, IL `0x0016-0x0027`)
/// adds Ethereal to its owner's Hexed cards. `effective_ethereal` is that
/// union (canonical row, combat-local Ethereal, Hexed under Hex).
/// `CardCmd/<Exhaust>d__6` forwards `causedByEthereal` to
/// `Hook.AfterCardExhausted` (IL `0x0102-0x0107`), which is exactly
/// `card_exhausted_by_ethereal`; `skipVisuals` only reaches the visual
/// argument of `CardPileCmd.Add` (IL `0x006d`).
/// The live Hand's uids, or `None` when no Regret is in it (#2561).
///
/// Only a Regret in Hand makes the Hand's composition observable across the
/// BeforeSideTurnEnd pass, so a fight without one pays one scan and no copy.
fn regret_hand_snapshot(state: &HotState, catalog: &Catalog) -> Option<Vec<u32>> {
    let hand = state.piles.get(PileId::Hand).as_slice();
    hand.iter()
        .any(|card| {
            catalog
                .spec(card.atom)
                .is_some_and(|spec| matches!(spec.identity.id, CardId::Regret))
        })
        .then(|| hand.iter().map(|card| card.uid).collect())
}

/// Regret's recorded `CardsInHand` for this side end (#2561).
///
/// Current v0.111.0 `sts2.dll` SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `Regret::BeforeSideTurnEnd` RVA `0xe9638` returns at IL_000c-IL_0024
/// unless the ending side holds Regret's owner, returns at IL_0025-IL_0038
/// unless Regret's own pile is Hand (`PileType` 2), and otherwise stores
/// `Pile.Cards.Count` — the whole live Hand, itself included — through
/// `set_CardsInHand` (IL_0039-IL_004a, RVA `0xe9624`). Its
/// `<OnTurnEndInHand>d__12::MoveNext` RVA `0x3b6ce8` later deals that stored
/// value, not a fresh count, then resets it to 0 (IL_0095-IL_0097).
///
/// Regret is one listener of the ordinary `Hook.BeforeSideTurnEnd` pass
/// (player powers, relics, and the generic hook here), and Rust does not
/// serialize card listeners against the other members. The count is exact
/// when the Hand is the same physical sequence on both sides of the pass:
/// then every listener position records the same number. A pass that moves
/// the Hand while a Regret is in it — before or after — refuses by name.
/// (Pael's Eye's Early exhaust sits inside this window in Rust, so a Regret
/// under an extra-turn Pael's Eye refuses too rather than trusting that
/// ordering.)
fn regret_before_side_turn_end_count(
    before: Option<Vec<u32>>,
    after: Option<Vec<u32>>,
) -> Result<Option<(i64, Vec<u32>)>, EngineRefusal> {
    match (before, after) {
        (None, None) => Ok(None),
        (Some(before), Some(after)) if before == after => Ok(Some((
            i64::try_from(after.len())
                .map_err(|_| EngineRefusal::CounterOverflow("Regret hand count"))?,
            after,
        ))),
        _ => Err(EngineRefusal::PowerOrderNotModeled(
            "Regret BeforeSideTurnEnd hand count",
        )),
    }
}

#[cfg(test)]
fn run_turn_end_in_hand_cards(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let regret_hand_count = regret_before_side_turn_end_count(
        regret_hand_snapshot(state, catalog),
        regret_hand_snapshot(state, catalog),
    )?;
    run_turn_end_in_hand_cards_with_regret(state, catalog, regret_hand_count, events)
}

/// `regret_hand_count` is the Hand size Regret recorded at this side end's
/// BeforeSideTurnEnd ([`regret_before_side_turn_end_count`]) with the Hand's
/// uids then; `None` means no Regret was in Hand then. A Regret here that was
/// not in that Hand (one that reached Hand after the pass) refuses rather
/// than guessing its stale count.
fn run_turn_end_in_hand_cards_with_regret(
    state: &mut HotState,
    catalog: &Catalog,
    regret_hand_count: Option<(i64, Vec<u32>)>,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let mut uids = Vec::new();
    for card in state.piles.get(crate::hot::PileId::Hand).as_slice() {
        let Some(spec) = catalog.spec(card.atom) else {
            continue;
        };
        let carries_gold_loss = catalog
            .steps(spec)
            .iter()
            .any(|step| step.kind == StepKind::TurnEndGoldLossExact);
        if carries_gold_loss {
            crate::steps::curses::exact_turn_end_gold_loss_step(catalog, spec)?;
            let matches = PileId::ALL
                .into_iter()
                .flat_map(|pile| state.piles.get(pile).as_slice())
                .filter(|live| live.uid == card.uid)
                .count();
            if matches != 1 {
                return Err(EngineRefusal::ActiveCardNotUnique {
                    uid: card.uid,
                    matches,
                });
            }
            uids.push(card.uid);
        } else if spec.row.turn_end_dmg > 0
            || spec.row.turn_end_hp_loss > 0
            || spec.row.turn_end_weak > 0
            || spec.row.turn_end_frail > 0
        {
            uids.push(card.uid);
        } else if spec.row.turn_end_hp_loss_hand {
            if !matches!(spec.identity.id, CardId::Regret)
                || !regret_hand_count
                    .as_ref()
                    .is_some_and(|(_, hand)| hand.contains(&card.uid))
            {
                return Err(EngineRefusal::PowerOrderNotModeled(
                    "Regret BeforeSideTurnEnd hand count",
                ));
            }
            uids.push(card.uid);
        }
    }
    if uids.is_empty() {
        return Ok(());
    }
    state.exact_piles = true;
    for uid in uids {
        // v0.111.0 starts each delayed Hand -> Play Add immediately before
        // that wrapper's body. Without a suspended selection in this admitted
        // slice, a lethal body therefore leaves later snapshot cards in Hand.
        let position = state
            .piles
            .get(crate::hot::PileId::Hand)
            .as_slice()
            .iter()
            .position(|card| card.uid == uid)
            .ok_or(EngineRefusal::FrozenCardVanished {
                uid,
                pile: crate::hot::PileId::Hand,
            })?;
        let card = state
            .piles
            .get_mut(crate::hot::PileId::Hand)
            .make_mut()
            .remove(position);
        state
            .piles
            .get_mut(crate::hot::PileId::Play)
            .make_mut()
            .push(card);
        let position = state
            .piles
            .get(crate::hot::PileId::Play)
            .as_slice()
            .iter()
            .position(|card| card.uid == uid)
            .ok_or(EngineRefusal::FrozenCardVanished {
                uid,
                pile: crate::hot::PileId::Play,
            })?;
        let card = state.piles.get(crate::hot::PileId::Play).as_slice()[position];
        let spec = *catalog
            .spec(card.atom)
            .ok_or(EngineRefusal::UnknownAtom(card.atom))?;
        if catalog
            .steps(&spec)
            .iter()
            .any(|step| step.kind == StepKind::TurnEndGoldLossExact)
        {
            let step = crate::steps::curses::exact_turn_end_gold_loss_step(catalog, &spec)?;
            let mut ctx = StepCtx {
                state: &mut *state,
                catalog,
                spec: &spec,
                source_uid: uid,
                target: None,
                selection: None,
                x_value: 0,
                args: catalog.args(step.args),
                events: &mut *events,
            };
            super::play::dispatch_step(step.kind, &mut ctx)?;
        }
        if spec.row.turn_end_weak > 0 {
            let mark_fresh = state.powers.value(PowerId::PlayerWeak) <= 0;
            super::damage::apply_player_duration_affliction(
                state,
                PowerId::PlayerWeak,
                PowerId::PlayerWeakFresh,
                spec.row
                    .turn_end_weak
                    .try_into()
                    .map_err(|_| EngineRefusal::CounterOverflow("turn-end Weak"))?,
                mark_fresh,
                events,
            )?;
        }
        if spec.row.turn_end_frail > 0 {
            let mark_fresh = state.powers.value(PowerId::PlayerFrail) <= 0;
            super::damage::apply_player_duration_affliction(
                state,
                PowerId::PlayerFrail,
                PowerId::PlayerFrailFresh,
                spec.row
                    .turn_end_frail
                    .try_into()
                    .map_err(|_| EngineRefusal::CounterOverflow("turn-end Frail"))?,
                mark_fresh,
                events,
            )?;
        }
        let turn_end_damage = if matches!(spec.identity.id, CardId::Wither) {
            spec.row
                .turn_end_dmg
                .checked_add(i64::from(state.card_states.get(uid).damage_growth))
                .ok_or(EngineRefusal::CounterOverflow("Wither turn-end damage"))?
        } else {
            spec.row.turn_end_dmg
        };
        if turn_end_damage > 0
            && !super::damage::damage_player_from_card_with_catalog(
                state,
                catalog,
                turn_end_damage,
                true,
                events,
            )?
        {
            return Ok(());
        }
        if spec.row.turn_end_hp_loss > 0
            && !super::damage::damage_player_from_card_with_catalog(
                state,
                catalog,
                spec.row.turn_end_hp_loss,
                false,
                events,
            )?
        {
            // Native has already moved this source Hand -> Play, but does not
            // run its discard suffix or start any later frozen wrapper after
            // a terminal unblockable Beckon result.
            return Ok(());
        }
        // Regret (#2561): `<OnTurnEndInHand>d__12::MoveNext` RVA `0x3b6ce8`
        // IL_001d-IL_003d is `CreatureCmd.Damage(choiceContext,
        // Owner.Creature, (decimal)CardsInHand, ValueProp 14, this, null)` —
        // Beckon's props (`<OnTurnEndInHand>d__7` RVA `0x38c0b4` IL_003e)
        // with the recorded BeforeSideTurnEnd count as the amount.
        if spec.row.turn_end_hp_loss_hand {
            let amount = regret_hand_count.as_ref().map(|(count, _)| *count).ok_or(
                EngineRefusal::PowerOrderNotModeled("Regret BeforeSideTurnEnd hand count"),
            )?;
            if !super::damage::damage_player_from_card_with_catalog(
                state, catalog, amount, false, events,
            )? {
                return Ok(());
            }
        }
        let position = state
            .piles
            .get(crate::hot::PileId::Play)
            .as_slice()
            .iter()
            .position(|live| live.uid == uid)
            .ok_or(EngineRefusal::FrozenCardVanished {
                uid,
                pile: crate::hot::PileId::Play,
            })?;
        // The Ethereal test reads the keywords after the body has run.
        let ethereal = super::cards::effective_ethereal(state, &spec, uid);
        let card = state
            .piles
            .get_mut(crate::hot::PileId::Play)
            .make_mut()
            .remove(position);
        if ethereal {
            super::draw::card_exhausted_by_ethereal(state, catalog, card, events)?;
            // An exhaust relic (Charon's Ashes, Forgotten Soul) can end
            // combat here. Stop like the lethal-body arm above and like the
            // ordinary Ethereal pass: later snapshot cards stay in Hand.
            if state.history.over {
                return Ok(());
            }
            continue;
        }
        state
            .piles
            .get_mut(crate::hot::PileId::Discard)
            .make_mut()
            .push(card);
        events.push(Event::CardResolved {
            uid,
            pile: crate::hot::PileId::Discard,
        });
    }
    Ok(())
}

/// The enemy phase (`_run_enemy_phase`, frozen Python, deleted #2827).
///
/// The ACT stage snapshots the roster's stable slot order, looking each uid up
/// fresh (mid-phase spawns insert slot-sorted); the SIDE_END stage is the debuff
/// tick and the next-intent roll. A move can suspend the phase on a blocking
/// player choice, which is why Python threads a stage and a remaining-uid
/// tail; `_ENEMY_CHOICES` is empty for every admitted monster kind, so the
/// walk here cannot suspend.
#[cfg(test)]
fn run_enemy_phase(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    run_enemy_phase_inner(state, catalog, None, None, events)
}

fn run_enemy_phase_after_player_turn(
    state: &mut HotState,
    catalog: &Catalog,
    conqueror_reachable_at_entry: bool,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    run_enemy_phase_inner(
        state,
        catalog,
        Some(conqueror_reachable_at_entry),
        None,
        events,
    )
}

/// Validate the complete persistent Demise/Shrink owner-side lifecycle.
///
/// Current v0.111.0 ARM64 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// Demise's side-end body is RVA `0x338c88`; Shrink's finite-duration body is
/// RVA `0x3445c0`; the Hook/iterator walk is `0x3d11c0`/`0x3f9720`.
fn enemy_potion_debuff_side_end_is_exact(state: &HotState) -> bool {
    state.monsters.iter().all(|monster| {
        let demise = monster.powers.value(PowerId::Demise);
        let shrink = monster.powers.value(PowerId::Shrink);
        let intangible = monster.powers.value(PowerId::Intangible);
        let ritual = monster.powers.value(PowerId::Ritual);
        let demise_state_exact = demise >= 0
            && (!monster.demise_after_intangible() || demise > 0 && intangible > 0)
            && (!monster.demise_before_ritual() || demise > 0 && ritual > 0)
            && (demise == 0 || super::damage::misery_order_projection_is_exact(monster).is_ok());
        let shrink_state_exact = (0..999_999_999).contains(&shrink);
        // A Waterfall Giant's SteamEruption revival is not refused here: the
        // Demise anchor decides it at the tick itself (#3428,
        // `waterfall_demise_revival_suffix_is_empty`).
        demise_state_exact && shrink_state_exact && monster.owner_latches_are_exact()
    })
}

fn run_enemy_phase_inner(
    state: &mut HotState,
    catalog: &Catalog,
    conqueror_reachable_at_entry: Option<bool>,
    resumed_roster: Option<Vec<u32>>,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let roster = resumed_roster
        .unwrap_or_else(|| state.monsters.iter().map(|monster| monster.uid).collect());
    for (cursor, uid) in roster.iter().copied().enumerate() {
        let Some(index) = state.monsters.iter().position(|m| m.uid == uid) else {
            continue; // a replaced or bumped creature
        };
        monster_act(state, catalog, index, events)?;
        if state.history.over {
            return Ok(());
        }
        if state.pending.is_some() {
            if !kd_pending_is_exact(state) {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            let pending = state.pending.as_deref().expect("checked pending");
            let mut record = pending
                .enemy_phase_record(&state.frames)
                .expect("authenticated KD frame");
            record.remaining_uids = roster[cursor + 1..].to_vec();
            state
                .frames
                .replace_top_enemy_phase(&record)
                .ok_or(EngineRefusal::CounterOverflow("enemy phase record"))?;
            return Ok(());
        }
    }

    if state
        .monsters
        .iter()
        .any(|monster| monster.kind == MonsterKind::SoulFysh)
        && !super::monsters::soul_fysh_side_end_state_is_valid(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "Soul Fysh Intangible side-end state",
        ));
    }

    // --- end of the enemy side turn -------------------------------------
    // Asleep is the represented `BeforeSideTurnEndVeryEarly` member: a
    // Matriarch about to wake loses Plating before the Early pass (#2814).
    lagavulin_asleep_before_enemy_side_end_very_early(state, events)?;
    // Monster Plating is the represented `BeforeSideTurnEndEarly` member; the
    // Early pass completes before the ordinary pass that carries Doom (#2809).
    monster_plating_before_enemy_side_end(state)?;
    // Enemy DoomPower fires at BeforeSideTurnEnd after every monster acted.
    // It snapshots the complete roster-order batch, then kills without a
    // damage result. Death cascades run between members of that snapshot.
    doom_enemy_side_end(state, catalog, events)?;
    if state.history.over {
        return Ok(());
    }

    // CoveredPower and its owner-side InterceptPower both remove at enemy
    // side end, after Doom and before the ordinary AfterSideTurnEnd walk.
    // Their shared projection has no remaining consumer once both removals
    // finish, so the clear is exact and order-independent.
    expire_intercept_covered(state);

    // Underworld/Concoct,
    // Nemesis, Hopper, temporary Strength, Sic Em, Strangle, Demise,
    // Shrink, Conqueror, Knockdown, Flanking,
    // Skittish and Slumber all dispatch in this
    // walk and still need a refused power or monster kind. Territorial,
    // High Voltage and Lagavulin's Asleep (#2814) now have readers below. Weak and
    // Vulnerable tick for each creature that is still alive, on the exact
    // roster snapshot the walk captured.
    // Conqueror is card-sourced; no admitted enemy action can acquire it.
    // The public end-turn validation therefore proves an absent carrier stays
    // absent through ACT and avoids paying a second roster scan on the common
    // path. Direct private phase tests have no such entry proof and retain the
    // live scan. A positive entry still re-reads after ACT because its owner
    // may have died in the meantime.
    let conqueror_reachable = conqueror_reachable_at_entry != Some(false)
        && state
            .monsters
            .iter()
            .any(|monster| monster.hp > 0 && monster.powers.value(PowerId::Conqueror) > 0);
    if conqueror_reachable {
        super::damage::null_applier_power_amount_changed_is_exact(state)?;
    }
    if !enemy_potion_debuff_side_end_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "enemy potion-debuff side-end state",
        ));
    }
    // Native has six board slots. Freeze the complete Creature listener
    // identity roster on the stack: a Demise death can insert or replace a
    // creature, but neither new identity joins this already-started walk.
    const SIDE_END_ROSTER_CAPACITY: usize = 6;
    if state.monsters.len() > SIDE_END_ROSTER_CAPACITY {
        return Err(EngineRefusal::MalformedArgs(
            "enemy side-end roster capacity",
        ));
    }
    let mut side_end_roster = [(0_i32, 0_u32); SIDE_END_ROSTER_CAPACITY];
    let side_end_roster_len = state.monsters.len();
    for (frozen, monster) in side_end_roster
        .iter_mut()
        .zip(state.monsters.iter())
        .take(side_end_roster_len)
    {
        *frozen = (monster.slot, monster.uid);
    }
    for (frozen_slot, frozen_uid) in side_end_roster.into_iter().take(side_end_roster_len) {
        let Some(index) = state
            .monsters
            .iter()
            .position(|monster| (monster.slot, monster.uid) == (frozen_slot, frozen_uid))
        else {
            continue;
        };
        if state.monsters[index].hp <= 0 {
            continue;
        }

        // BattlewornDummyTimeLimitPower is the Battle Friend's intrinsic
        // power, so it leads the owner's listeners (#3357): decrement, or at
        // one escape the dummy and end the combat before any later listener.
        if super::monsters::battleworn_time_limit_after_enemy_side_end(state, index, events)? {
            return Ok(());
        }

        // Test Subject Nemesis is acquired before player-applied powers. Its
        // freshly-created Intangible therefore precedes neither an existing
        // Demise nor its same-side tick; the private toggle suppresses only
        // that new stack's immediate decrement.
        let nemesis_applied = state.monsters[index].kind == MonsterKind::TestSubject
            && state.monsters[index].test_subject_respawns() == 2
            && !state.monsters[index].test_subject_nemesis_apply_intangible();
        if state.monsters[index].kind == MonsterKind::TestSubject
            && state.monsters[index].test_subject_respawns() == 2
        {
            let amount = super::monsters::test_subject_nemesis_side_end(state, index)?;
            if amount > 0 && state.monsters[index].powers.value(PowerId::Demise) > 0 {
                state.monsters_mut()[index].set_demise_after_intangible(false);
            }
            super::damage::note_power(
                events,
                Subject::Monster(frozen_uid),
                PowerId::Intangible,
                amount,
            );
        }

        // AsleepPower is Lagavulin Matriarch's intrinsic power, like Slumber
        // below: decrement, and wake at zero with no stun action (#2814).
        lagavulin_asleep_after_enemy_side_end(state, index, events)?;
        if state.monsters[index].powers.value(PowerId::Slumber) > 0 {
            super::damage::null_applier_power_amount_changed_is_exact(state)?;
        }
        // SlumberPower.AfterSideTurnEnd 0x34519c runs as an intrinsic
        // power, before all player-applied powers on this owner. At zero it
        // calls WakeUpMove directly (no extra stun action). PrepareForNextTurn
        // then resolves SNORE_NEXT to ROLL_OUT (Creature 0x11d85c).
        let upkeep = state.fanouts.misery_attachment_upkeep();
        let monster = &mut state.monsters_mut()[index];
        if monster.kind == MonsterKind::SlumberingBeetle {
            let slumber = monster.powers.value(PowerId::Slumber);
            if slumber > 0 {
                monster
                    .powers
                    .set(PowerId::Slumber, SlotWire::Int, slumber - 1);
                super::damage::note_power(
                    events,
                    Subject::Monster(monster.uid),
                    PowerId::Slumber,
                    slumber - 1,
                );
                if slumber == 1 {
                    super::monsters::wake_beetle(monster, events);
                }
            }
        }
        let escape_artist = monster.powers.value(PowerId::EscapeArtist);
        if escape_artist > 1 {
            if monster.kind != MonsterKind::ThievingHopper
                || escape_artist > super::monsters::THIEVING_HOPPER_ESCAPE_ARTIST
            {
                return Err(EngineRefusal::MalformedArgs(
                    "EscapeArtistPower owner/amount",
                ));
            }
            monster
                .powers
                .set(PowerId::EscapeArtist, SlotWire::Int, escape_artist - 1);
            super::damage::note_power(
                events,
                Subject::Monster(monster.uid),
                PowerId::EscapeArtist,
                escape_artist - 1,
            );
        }
        let hatch = monster.powers.value(PowerId::HatchPower);
        if hatch > 0 {
            if monster.kind != MonsterKind::ToughEgg || monster.powers.value(PowerId::IsHatched) > 0
            {
                return Err(EngineRefusal::MalformedArgs("HatchPower owner/state"));
            }
            monster
                .powers
                .set(PowerId::HatchPower, SlotWire::Int, hatch - 1);
        }
        // `TemporaryStrengthPower/<AfterSideTurnEnd>d__22::MoveNext`
        // `0x348ba8` removes the wrapper first (IL_0043) and then re-applies
        // `-Sign * Amount` Strength with the **Owner** as applier
        // (IL_009d-IL_00c4), not the wrapper's original one — once per live
        // wrapper instance, in `Creature.Powers` order. #2693 S2 records the
        // concrete instances, so the whole lifecycle now lives in one writer;
        // `TempStrength != 0` keeps `Misery` refusing until S3 reads them.
        // Rust unwinds every wrapper here, ahead of every Demise anchor, but
        // a wrapper's native listener position relative to Demise is not
        // recorded. Only a revived Waterfall can observe the difference, so
        // only that owner remembers that one existed (#3428).
        let unordered_wrapper = monster.kind == MonsterKind::WaterfallGiant
            && (monster.powers.value(PowerId::TempStrength) != 0
                || super::monsters::temp_strength_wrapper_rows(monster)
                    .next()
                    .is_some());
        super::damage::unwind_monster_temp_strength_wrappers(monster, upkeep)?;
        let has_demise = monster.powers.value(PowerId::Demise) > 0;
        // On the no-Demise static path below, the following fixed order remains:
        // SicEmPower belongs to the monster owner's AfterSideTurnEnd walk,
        // after that owner has acted. It therefore remains live through the
        // side-start Poison pass and ACT, and is removed before the adjacent
        // Strangle/Weak/Vulnerable suffix (`_run_enemy_phase`, frozen Python, deleted #2827).
        let sic_em = monster.powers.value(PowerId::SicEm);
        if sic_em > 0 && !has_demise {
            expire_monster_side_end_token(monster, MiseryToken::SicEm, false, events);
        }
        // With live Demise, the Misery ledger instead authenticates the complete
        // acquisition order and the Python oracle executes that ordered block.
        // Type-2 powers share one acquisition-ordered owner listener group.
        // Most of these ticks commute, so the no-Demise path retains its
        // historical static dispatch. Demise does not commute: a lethal tick
        // suppresses every later PowerCmd, and its damage/death events are
        // observable between PowerChanged events. Authenticate the existing
        // Misery ledger above. At Demise's separately-authenticated anchor,
        // drain its ordered prefix, tick Demise, then drain the live suffix.
        // A stack mask lets the live COW order be rescanned after removals
        // without cloning its Vec or changing any frozen layout.
        if !has_demise {
            expire_monster_pre_intangible_debuffs(monster, events);
        }

        let demise_before_intangible = monster.powers.value(PowerId::Demise) > 0
            && monster.powers.value(PowerId::Intangible) > 0
            && !monster.demise_after_intangible();
        if demise_before_intangible {
            // The live Intangible is this anchor's later listener.
            let owner_survived = run_monster_demise_ledger_at_anchor(
                state,
                catalog,
                index,
                (frozen_slot, frozen_uid),
                conqueror_reachable,
                true,
                events,
            )?;
            if state.history.over {
                return Ok(());
            }
            if !owner_survived {
                continue;
            }
        }

        let monster = &mut state.monsters_mut()[index];
        let intangible = monster.powers.value(PowerId::Intangible);
        if intangible > 0 && !nemesis_applied {
            monster
                .powers
                .set(PowerId::Intangible, SlotWire::Int, intangible - 1);
            if intangible == 1 {
                monster.set_demise_after_intangible(false);
            }
            super::damage::note_power(
                events,
                Subject::Monster(monster.uid),
                PowerId::Intangible,
                intangible - 1,
            );
        }
        if !has_demise {
            expire_monster_post_intangible_debuffs(monster, conqueror_reachable, events);
        }

        // SkittishPower's once-per-turn latch clears at this same walk,
        // immediately before Territorial (`_run_enemy_phase` (frozen Python, deleted #2827)). Native
        // `SkittishPower::AfterSideTurnEnd` RVA `0xa7b10` zeroes
        // `Data.hasGainedBlockThisTurn`. Unconditional on the power: Python
        // clears the field on every monster in the walk, not only owners.
        monster.set_skittish_used(false);

        // TerritorialPower: Strength equal to Amount at the end of each side
        // the owner participates in. `_run_enemy_phase` (frozen Python, deleted #2827),
        // immediately before High Voltage in the same walk, and this keeps
        // that order.
        //
        // Current-build IL (v0.111.0, DLL 9cb4f1ad):
        // `TerritorialPower::AfterSideTurnEnd` RVA `0xa9e7c`, body
        // `TerritorialPower/<AfterSideTurnEnd>d__6::MoveNext` RVA `0x349144`.
        // The body gates on `participants.Contains(PowerModel::get_Owner)`
        // (IL_001d-IL_002e, `leave` when absent), then `Flash()`, then
        // `Apply<StrengthPower>(choiceContext, Owner, (Decimal)Amount, Owner,
        // null, 0)` (IL_0035-IL_005a) — the owner is both source and target.
        // Python narrows `participants.Contains(owner)` to `kind == BYRDONIS
        // and hp > 0` because Byrdonis is the only owner the content builds;
        // `PowerCmd.Apply` being live-gated is what the `hp > 0` encodes.
        // A non-Byrdonis owner is refused rather than applied, so a future
        // owner cannot be silently folded in on this path.
        let territorial = monster.powers.value(PowerId::Territorial);
        if territorial != 0 {
            if monster.kind != MonsterKind::Byrdonis
                || territorial != super::admission::BYRDONIS_TERRITORIAL
            {
                return Err(EngineRefusal::MalformedArgs(
                    "TerritorialPower owner/amount",
                ));
            }
            if monster.hp > 0 {
                let strength = monster
                    .powers
                    .value(PowerId::Strength)
                    .checked_add(territorial)
                    .ok_or(EngineRefusal::CounterOverflow("Territorial strength"))?;
                let owner = crate::hot::Applier::Monster(monster.uid);
                super::damage::write_monster_strength(monster, strength, owner, upkeep);
                super::damage::note_power(
                    events,
                    Subject::Monster(monster.uid),
                    PowerId::Strength,
                    strength,
                );
            }
        }

        let high_voltage = monster.powers.value(PowerId::HighVoltage);
        if high_voltage != 0 {
            if monster.kind != MonsterKind::Zapbot || high_voltage != 2 {
                return Err(EngineRefusal::MalformedArgs(
                    "HighVoltagePower owner/amount",
                ));
            }
            let strength = monster
                .powers
                .value(PowerId::Strength)
                .checked_add(high_voltage)
                .ok_or(EngineRefusal::CounterOverflow("High Voltage strength"))?;
            // `HighVoltagePower/<AfterSideTurnEnd>d__6::MoveNext`
            // IL_003b-IL_005a applies to `Owner` with `Owner` as applier, as
            // Territorial's identical body above does.
            let owner = crate::hot::Applier::Monster(monster.uid);
            super::damage::write_monster_strength(monster, strength, owner, upkeep);
            super::damage::note_power(
                events,
                Subject::Monster(monster.uid),
                PowerId::Strength,
                strength,
            );
        }
        let demise_before_ritual = !demise_before_intangible
            && monster.powers.value(PowerId::Demise) > 0
            && monster.demise_before_ritual();
        if demise_before_ritual {
            // The live Ritual (`enemy_potion_debuff_side_end_is_exact`
            // proves it) is this anchor's later listener.
            let owner_survived = run_monster_demise_ledger_at_anchor(
                state,
                catalog,
                index,
                (frozen_slot, frozen_uid),
                conqueror_reachable,
                true,
                events,
            )?;
            if state.history.over {
                return Ok(());
            }
            if !owner_survived {
                continue;
            }
        }

        let monster = &mut state.monsters_mut()[index];
        tick_monster_ritual(monster, upkeep, events)?;

        if has_demise && !demise_before_intangible && !demise_before_ritual {
            let owner_survived = run_monster_demise_ledger_at_anchor(
                state,
                catalog,
                index,
                (frozen_slot, frozen_uid),
                conqueror_reachable,
                unordered_wrapper,
                events,
            )?;
            if state.history.over {
                return Ok(());
            }
            if !owner_survived {
                continue;
            }
        }
    }
    // Duration-bearing player afflictions tick in native player-power order.
    // A just-applied enemy duration skips this first enemy-side tick by
    // consuming only its latch; a card-owned exception arrives without one
    // and therefore decrements immediately.
    //
    // Smoggy is NOT a duration (#3161). v0.111.0 `SmoggyPower::
    // AfterSideTurnEnd` (RVA 0xa804c) is synchronous: IL_000c-0018 returns
    // unless `participants.Contains(Owner)`, then IL_0020-0083 only walks the
    // owner's cards and `ClearAffliction`s each `Smog`. It never calls
    // `PowerModel.TickDownDuration` (compare `VulnerablePower.
    // <AfterSideTurnEnd>d__8` RVA 0x34ad74 IL_0029), and `get_StackType`
    // (RVA 0xa7fae) is 2 = `PowerStackType.Single`. Smoggy therefore keeps
    // its amount until something removes it; its SkipNextDurationTick latch
    // (set on a new instance like any player Debuff) is never consumed.
    for (power, fresh) in [
        (PowerId::PlayerVuln, PowerId::PlayerVulnFresh),
        (PowerId::PlayerWeak, PowerId::PlayerWeakFresh),
        (PowerId::PlayerFrail, PowerId::PlayerFrailFresh),
    ] {
        let amount = state.powers.value(power);
        if amount <= 0 {
            continue;
        }
        if state.powers.value(fresh) > 0 {
            state.powers.set(fresh, SlotWire::Bool, 0);
            super::damage::note_power(events, Subject::Player, fresh, 0);
        } else {
            let updated = amount - 1;
            super::play::prepare_after_card_played_scalar_write(state, power, amount, updated)?;
            state.powers.set(power, SlotWire::Int, updated);
            super::damage::note_power(events, Subject::Player, power, updated);
        }
    }
    if state.powers.value(PowerId::Tainted) > 0 {
        state.powers.set(PowerId::Tainted, SlotWire::Int, 0);
        super::damage::note_power(events, Subject::Player, PowerId::Tainted, 0);
    }
    // Player Intangible and Colossus cover the enemy side that just finished,
    // then decrement one duration stack. Flame Barrier is intensity rather
    // than duration and removes the whole live amount at the same boundary.
    for power in [PowerId::Intangible, PowerId::Colossus] {
        let amount = state.powers.value(power);
        if amount > 0 {
            state.powers.set(power, SlotWire::Int, amount - 1);
            super::damage::note_power(events, Subject::Player, power, amount - 1);
        }
    }
    if state.powers.value(PowerId::FlameBarrier) > 0 {
        if !state.unregister_after_damage_received_power(PowerId::FlameBarrier) {
            return Err(EngineRefusal::PowerOrderNotModeled(
                "after-damage-received power removal",
            ));
        }
        state.powers.set(PowerId::FlameBarrier, SlotWire::Int, 0);
        super::damage::note_power(events, Subject::Player, PowerId::FlameBarrier, 0);
    }
    // NoBlockPower covers the enemy side that just finished and decrements
    // one duration stack without a fresh-application skip.
    let no_block = state.powers.value(PowerId::NoBlock);
    if no_block > 0 {
        state
            .powers
            .set(PowerId::NoBlock, SlotWire::Int, no_block - 1);
        super::damage::note_power(events, Subject::Player, PowerId::NoBlock, no_block - 1);
    }
    // Ovicopter's SUMMON_BRANCH is intentionally resolved after the complete
    // side-end listener/duration walk, so deaths earlier in this phase decide
    // whether the parent can lay again.
    super::monsters::resolve_ovicopter_after_side_end(state)?;

    // PrepareForNextTurn walks every living random-AI monster in stable roster
    // order, sharing the one MonsterAi stream.
    prepare_random_ai(state, catalog)?;

    state.turn = state
        .turn
        .checked_add(1)
        .ok_or(EngineRefusal::CounterOverflow("turn"))?;
    state.history.round_number = state
        .history
        .round_number
        .checked_add(1)
        .ok_or(EngineRefusal::CounterOverflow("round_number"))?;
    state.history.manual_card_plays_finished_this_turn = 0;
    // `end_player_turn` already owns the outer whole-action checkpoint for
    // every reachable Furnace shape, so do not take the direct-entry nested
    // clone here. The reader still authenticates its live Amount at callback
    // time.
    begin_player_turn_inner(state, catalog, events)
}

pub(crate) fn resume_kd_curse(
    state: &mut HotState,
    catalog: &Catalog,
    ordinal: u32,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if ordinal >= 2 || !kd_pending_is_exact(state) {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    let pending = state.pending.as_deref().expect("authenticated KD pending");
    let record = pending
        .enemy_phase_record(&state.frames)
        .expect("authenticated KD frame");
    if !record.remaining_uids.is_empty() {
        return Err(EngineRefusal::MalformedArgs(
            "Knowledge Demon remaining UID tail",
        ));
    }
    let counter = state.monsters[0]
        .knowledge_demon_curse_counter()
        .expect("authenticated KD counter");
    let selected = match (counter, ordinal) {
        (0..=2, 0) => (PowerId::Disintegration, i32::from(6 + counter)),
        (0, 1) => (PowerId::MindRot, 1),
        (1, 1) => (PowerId::Sloth, 3),
        (2, 1) => (PowerId::WasteAway, 1),
        _ => return Err(EngineRefusal::ContinuationNotModeled),
    };
    let current = state.powers.value(selected.0);
    let updated = current
        .checked_add(selected.1)
        .ok_or(EngineRefusal::CounterOverflow(
            "Knowledge Demon curse power",
        ))?;
    let next_counter = counter
        .checked_add(1)
        .ok_or(EngineRefusal::CounterOverflow(
            "Knowledge Demon curse counter",
        ))?;
    if selected.0 == PowerId::Sloth
        && !state.fanouts.set_sloth(Some(SlothInstance {
            cards_played_this_turn: 0,
        }))
    {
        return Err(EngineRefusal::MalformedArgs("Sloth private state"));
    }
    state
        .frames
        .pop_top_enemy_phase()
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    state.pending = None;
    state.powers.set(selected.0, SlotWire::Int, updated);
    super::damage::note_power(events, Subject::Player, selected.0, updated);
    if !state.monsters_mut()[0].set_knowledge_demon_curse_counter(next_counter) {
        return Err(EngineRefusal::MalformedArgs(
            "Knowledge Demon curse counter",
        ));
    }
    state.monsters_mut()[0].loop_pos = 1;
    if !knowledge_demon_state_is_exact(state) {
        return Err(EngineRefusal::MalformedArgs(
            "Knowledge Demon choice result",
        ));
    }
    run_enemy_phase_inner(state, catalog, None, Some(record.remaining_uids), events)
}

/// Decrement the represented living-owner monster durations in native order.
///
/// Current v0.111.0 ARM64 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `ConquerorPower.AfterSideTurnEnd` RVA `0xa08e4` dispatches body RVA
/// `0x3372f4`, which checks that the owner is a living participant and then
/// issues one decrement. Its listener position is after Shrink and before
/// Debilitate in the owner-side walk.
fn expire_monster_pre_intangible_debuffs(monster: &mut HotMonster, events: &mut Vec<Event>) {
    expire_monster_side_end_token(monster, MiseryToken::Strangle, false, events);
    for (power, token) in [
        (PowerId::Weak, MiseryToken::Weak),
        (PowerId::Vuln, MiseryToken::Vuln),
    ] {
        let amount = monster.powers.value(power);
        if amount > 0 {
            monster.powers.set(power, SlotWire::Int, amount - 1);
            if amount - 1 == 0 {
                monster.misery_debuff_order.remove_all(token);
            }
        }
    }
}

/// Stack-mask bit for each represented Misery-ledger owner-side listener.
///
/// The ledger is already authenticated as a singleton for every scalar and
/// as repeated concrete instances only for Knockdown. The bit therefore
/// means "this listener family ran" while rescanning after COW removals.
fn monster_side_end_ledger_bit(token: MiseryToken) -> Option<u16> {
    Some(match token {
        MiseryToken::SicEm => 1 << 0,
        MiseryToken::Strangle => 1 << 1,
        MiseryToken::Weak => 1 << 2,
        MiseryToken::Vuln => 1 << 3,
        MiseryToken::Demise => 1 << 4,
        MiseryToken::Shrink => 1 << 5,
        MiseryToken::Conqueror => 1 << 6,
        MiseryToken::Debilitate => 1 << 7,
        MiseryToken::Knockdown => 1 << 8,
        _ => return None,
    })
}

fn next_monster_side_end_ledger_token(monster: &HotMonster, processed: u16) -> Option<MiseryToken> {
    let order = monster
        .misery_debuff_order
        .as_slice()
        .iter()
        .copied()
        .find(|token| monster_side_end_ledger_bit(*token).is_some_and(|bit| processed & bit == 0));
    if order.is_none()
        && monster.misery_debuff_order.as_slice().is_empty()
        && monster.powers.value(PowerId::Demise) > 0
        && processed & monster_side_end_ledger_bit(MiseryToken::Demise).unwrap() == 0
    {
        // The authenticated legacy singleton has a uniquely inferred order;
        // match `misery_scalar_snapshot` without publishing cold metadata.
        Some(MiseryToken::Demise)
    } else {
        order
    }
}

fn expire_monster_side_end_ledger_until_demise(
    monster: &mut HotMonster,
    processed: &mut u16,
    conqueror_reachable: bool,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    loop {
        let Some(token) = next_monster_side_end_ledger_token(monster, *processed) else {
            return Err(EngineRefusal::MalformedArgs(
                "Demise listener acquisition order",
            ));
        };
        let bit = monster_side_end_ledger_bit(token).expect("filtered ledger token");
        *processed |= bit;
        if token == MiseryToken::Demise {
            return Ok(());
        }
        expire_monster_side_end_token(monster, token, conqueror_reachable, events);
    }
}

fn expire_monster_side_end_ledger_suffix(
    monster: &mut HotMonster,
    processed: &mut u16,
    conqueror_reachable: bool,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    while let Some(token) = next_monster_side_end_ledger_token(monster, *processed) {
        let bit = monster_side_end_ledger_bit(token).expect("filtered ledger token");
        *processed |= bit;
        if token == MiseryToken::Demise {
            return Err(EngineRefusal::MalformedArgs(
                "Demise listener acquisition order",
            ));
        }
        expire_monster_side_end_token(monster, token, conqueror_reachable, events);
    }
    Ok(())
}

/// Whether a lethal hit on this owner would revive it through its own
/// SteamEruption instead of removing it: the arm of the shared death body in
/// `damage.rs` that forms the ABOUT sentinel.
fn waterfall_revival_is_armed(monster: &HotMonster) -> bool {
    monster.kind == MonsterKind::WaterfallGiant
        && monster.hp > 0
        && monster.powers.value(PowerId::SteamPressure) > 0
        && !monster.is_about_to_blow()
}

/// Whether a Demise tick that revives a Waterfall Giant leaves no later
/// listener of the same owner in the already-started `AfterSideTurnEnd` walk.
///
/// Current v0.111.0 ARM64 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
///
/// - The walk does not skip a power its owner lost. `Hook/<AfterSideTurnEnd>
///   d__81::MoveNext` RVA `0x3d11c0` enumerates
///   `CombatState/<IterateHookListeners>d__69::MoveNext` RVA `0x3f9720`,
///   which copies every creature's `Powers` into a list at iteration start
///   (IL_008f-IL_0097) and re-tests each element only with
///   `CombatState::Contains` (IL_02a3-IL_02ab). `Contains` RVA `0x137564`
///   IL_00ad-IL_00d1 tests a power's `Owner.CombatState != null`, not its
///   membership in `Owner.Powers`. An ordinary dead owner is removed from
///   combat, so its later listeners are skipped. A revived Waterfall is not:
///   `SteamEruptionPower::ShouldCreatureBeRemovedFromCombatAfterDeath` RVA
///   `0xa85fe` keeps its owner, and `<AfterDeath>d__4::MoveNext` RVA
///   `0x34618c` IL_003d-IL_004d revives it through `TriggerAboutToBlowState`.
///   So a power the death just removed would still run its listener, on the
///   sentinel. That is the shape Rust does not represent, and it refuses.
/// - An empty suffix is exact. `dump_method.py AfterSideTurnEnd` lists 61
///   non-mock power types that override the hook. `SteamEruptionPower`,
///   `StrengthPower`, `PoisonPower` and `ArtifactPower` are not among them,
///   and neither is `WaterfallGiant` nor `MonsterModel` (only
///   `AbstractModel`'s no-op). `DoomPower/<AfterSideTurnEnd>d__9::MoveNext`
///   RVA `0x3390f0` IL_001d-IL_0026 leaves when `side == 2` (Enemy), so a
///   Doom listener is inert in this walk. Every other surviving power must be
///   an acquisition-ordered listener that already ran: a Misery-ledger
///   family whose token precedes Demise (a live later token is a suffix), or
///   Intangible/Ritual, which callers report through `later_listeners` when
///   the anchor precedes them.
/// - The revived owner then keeps ABOUT. `TriggerAboutToBlowState`'s body
///   RVA `0x3762a8` IL_00a9-IL_00b1 calls `SetMoveImmediate(AboutToBlowState)`,
///   and `GenerateMoveStateMachine` RVA `0xc4eb0` IL_0162-IL_0169 builds that
///   state with `MustPerformOnceBeforeTransitioning`, so the side-end
///   `RollMove` (`FindNextMoveState` RVA `0x78e94` IL_001f-IL_002c) leaves it
///   in place. This is the same timing as the Doom kill earlier in this
///   side end.
fn waterfall_demise_revival_suffix_is_empty(monster: &HotMonster, processed: u16) -> bool {
    next_monster_side_end_ledger_token(monster, processed).is_none()
        && monster.powers.as_slice().iter().all(|slot| {
            matches!(
                slot.key,
                PowerId::SteamPressure
                    | PowerId::Demise
                    | PowerId::Strength
                    | PowerId::Poison
                    | PowerId::Artifact
                    | PowerId::Doom
                    | PowerId::Intangible
                    | PowerId::Ritual
                    | PowerId::SicEm
                    | PowerId::Strangle
                    | PowerId::Weak
                    | PowerId::Vuln
                    | PowerId::Shrink
                    | PowerId::Conqueror
                    | PowerId::Debilitate
                    | PowerId::Knockdown
            )
        })
}

/// Run one owner's acquisition-ordered Demise block at its anchor.
///
/// `later_listeners` reports a same-owner listener outside the Misery ledger
/// that runs after this anchor or whose position is unrecorded (Intangible
/// before the first anchor, Ritual before the second, a temporary-Strength
/// wrapper at any). It matters only when the tick revives a Waterfall Giant;
/// see [`waterfall_demise_revival_suffix_is_empty`].
fn run_monster_demise_ledger_at_anchor(
    state: &mut HotState,
    catalog: &Catalog,
    index: usize,
    frozen: (i32, u32),
    conqueror_reachable: bool,
    later_listeners: bool,
    events: &mut Vec<Event>,
) -> Result<bool, EngineRefusal> {
    let mut processed = 0_u16;
    expire_monster_side_end_ledger_until_demise(
        &mut state.monsters_mut()[index],
        &mut processed,
        conqueror_reachable,
        events,
    )?;
    let owner = &state.monsters[index];
    let amount = owner.powers.value(PowerId::Demise);
    let revival_is_unrepresented = waterfall_revival_is_armed(owner)
        && (later_listeners || !waterfall_demise_revival_suffix_is_empty(owner, processed));
    // `DemisePower/<AfterSideTurnEnd>d__4::MoveNext` RVA `0x338c88` (v0.111.0
    // DLL 9cb4f1ad…) awaits one `CreatureCmd.Damage(Owner, Amount, ValueProp
    // 6)` (IL_0042-IL_0055); a lethal one runs `Hook.AfterDeath`, so it keeps
    // the enemy phase's catalog for Gremlin Horn's Draw (#3172).
    super::damage::damage_monster_after_catalog_auth(
        state,
        catalog,
        index,
        DotNetDecimal::from_i64(i64::from(amount)),
        false,
        false,
        events,
    )?;
    if revival_is_unrepresented
        && state.monsters.get(index).is_some_and(|monster| {
            (monster.slot, monster.uid) == frozen && monster.is_about_to_blow()
        })
    {
        return Err(EngineRefusal::MalformedArgs(
            "Demise Waterfall revival listener suffix",
        ));
    }
    if state.history.over
        || state
            .monsters
            .get(index)
            .is_none_or(|monster| monster.hp <= 0 || (monster.slot, monster.uid) != frozen)
    {
        return Ok(false);
    }
    expire_monster_side_end_ledger_suffix(
        &mut state.monsters_mut()[index],
        &mut processed,
        conqueror_reachable,
        events,
    )?;
    Ok(true)
}

fn expire_monster_side_end_token(
    monster: &mut HotMonster,
    token: MiseryToken,
    conqueror_reachable: bool,
    events: &mut Vec<Event>,
) {
    let (power, removes_whole, publishes_event) = match token {
        MiseryToken::SicEm => (PowerId::SicEm, true, true),
        MiseryToken::Strangle => (PowerId::Strangle, true, true),
        MiseryToken::Weak => (PowerId::Weak, false, false),
        MiseryToken::Vuln => (PowerId::Vuln, false, false),
        MiseryToken::Shrink => (PowerId::Shrink, false, true),
        MiseryToken::Conqueror if conqueror_reachable => (PowerId::Conqueror, false, true),
        MiseryToken::Conqueror => return,
        MiseryToken::Debilitate => (PowerId::Debilitate, false, false),
        MiseryToken::Knockdown => {
            if !monster.misery_debuff_order.knockdown().is_empty() {
                monster
                    .misery_debuff_order
                    .remove_all(MiseryToken::Knockdown);
            }
            return;
        }
        _ => return,
    };
    let amount = monster.powers.value(power);
    if amount <= 0 {
        return;
    }
    let next = if removes_whole { 0 } else { amount - 1 };
    monster.powers.set(power, SlotWire::Int, next);
    if next == 0 {
        monster.misery_debuff_order.remove_all(token);
    }
    if publishes_event {
        super::damage::note_power(events, Subject::Monster(monster.uid), power, next);
    }
}

fn expire_monster_post_intangible_debuffs(
    monster: &mut HotMonster,
    conqueror_reachable: bool,
    events: &mut Vec<Event>,
) {
    // ShrinkPower.AfterSideTurnEnd RVA 0x3445c0 decrements one positive
    // finite duration after this owner's Intangible listener. Re-stacking
    // does not add or move a second listener.
    let shrink = monster.powers.value(PowerId::Shrink);
    if shrink > 0 {
        monster
            .powers
            .set(PowerId::Shrink, SlotWire::Int, shrink - 1);
        if shrink == 1 {
            monster.misery_debuff_order.remove_all(MiseryToken::Shrink);
        }
        super::damage::note_power(
            events,
            Subject::Monster(monster.uid),
            PowerId::Shrink,
            shrink - 1,
        );
    }
    // Conqueror is after Shrink and before Debilitate in the native owner-side
    // listener order. The represented neighbors before it are inert/refused.
    if conqueror_reachable {
        let amount = monster.powers.value(PowerId::Conqueror);
        if amount > 0 {
            monster
                .powers
                .set(PowerId::Conqueror, SlotWire::Int, amount - 1);
            if amount - 1 == 0 {
                monster
                    .misery_debuff_order
                    .remove_all(MiseryToken::Conqueror);
            }
            super::damage::note_power(
                events,
                Subject::Monster(monster.uid),
                PowerId::Conqueror,
                amount - 1,
            );
        }
    }
    // `DebilitatePower/<AfterSideTurnEnd>d__8::MoveNext` (`0x338bb0`):
    // participants.Contains(owner), then one `PowerCmd::Decrement`.
    let debilitate = monster.powers.value(PowerId::Debilitate);
    if debilitate > 0 {
        monster
            .powers
            .set(PowerId::Debilitate, SlotWire::Int, debilitate - 1);
        if debilitate - 1 == 0 {
            monster
                .misery_debuff_order
                .remove_all(MiseryToken::Debilitate);
        }
    }
    // Every distinct KnockdownPower instance removes itself at its living
    // owner's enemy-side end, after Debilitate and before Flanking. The
    // shared one-word ledger clears both the amounts and every repeated
    // acquisition token together.
    if !monster.misery_debuff_order.knockdown().is_empty() {
        monster
            .misery_debuff_order
            .remove_all(MiseryToken::Knockdown);
    }
}

/// Resolve the ordered enemy-side Doom kill batch.
///
/// Both native `DoomPower.BeforeSideTurnEnd` and End of Days take this fresh
/// roster snapshot after every preceding Doom application/listener has
/// completed. Each death is then resolved serially against the live roster,
/// so an earlier death cascade can suppress a later member of the snapshot.
/// Book Repair Knife observes the complete frozen batch after all serialized
/// deaths, then heals once from the surviving fatal-predicate result.
pub(crate) fn doom_enemy_side_end(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let queen_roster = state.monsters.iter().any(|monster| {
        matches!(
            monster.kind,
            MonsterKind::Queen | MonsterKind::TorchHeadAmalgam
        )
    });
    let hex_reachable = state.powers.value(PowerId::HexPower) > 0;
    let gremlin_merc_reachable = state.monsters.iter().any(|monster| {
        matches!(
            monster.kind,
            MonsterKind::GremlinMerc | MonsterKind::FatGremlin
        )
    });
    let dampen_reachable = state.card_states.dampen().is_some();
    if queen_roster || hex_reachable || gremlin_merc_reachable || dampen_reachable {
        if queen_roster && !super::monsters::queen_roster_state_is_valid(state) {
            return Err(EngineRefusal::MalformedArgs("Queen/Amalgam Doom entry"));
        }
        if hex_reachable && !super::cards::hex_power_state_is_exact(state) {
            return Err(EngineRefusal::MalformedArgs("Spectral Hex Doom entry"));
        }
        if gremlin_merc_reachable && !super::monsters::gremlin_merc_state_is_valid(state) {
            return Err(EngineRefusal::MalformedArgs("Gremlin Merc Doom entry"));
        }
        if dampen_reachable && !super::cards::dampen_internal_state_is_exact(state) {
            return Err(EngineRefusal::MalformedArgs("Dampen Doom entry"));
        }
        let mut next = state.clone();
        let mut emitted = Vec::new();
        doom_enemy_side_end_apply(&mut next, catalog, &mut emitted)?;
        *state = next;
        events.extend(emitted);
        return Ok(());
    }
    doom_enemy_side_end_apply(state, catalog, events)
}

fn doom_enemy_side_end_apply(
    state: &mut HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if state.history.over {
        return Ok(());
    }
    let doomed: Vec<(usize, u32, MonsterKind, bool)> = state
        .monsters
        .iter()
        .enumerate()
        .filter_map(|(index, monster)| {
            let amount = monster.powers.value(PowerId::Doom);
            (monster.hp > 0 && amount > 0 && monster.hp <= amount).then_some((
                index,
                monster.uid,
                monster.kind,
                super::monsters::is_secondary_enemy(monster),
            ))
        })
        .collect();
    for &(index, uid, _, _) in &doomed {
        if !frozen_monster_is_live(state, index, uid) {
            continue;
        }
        state.monsters_mut()[index].hp = 0;
        // `DoomPower/<DoomKill>d__6::MoveNext` RVA `0x3392c8` awaits one
        // `CreatureCmd.Kill` per doomed creature (IL_00df), so each death's
        // AfterDeath walk (Gremlin Horn's GainEnergy + Draw, #3166) completes
        // before the next member of the frozen batch is killed.
        super::damage::finish_monster_death_after_catalog_auth(state, catalog, index, events)?;
    }
    if state.book_repair_knife_owned() {
        let count = doomed
            .iter()
            .filter(|(_, uid, kind, secondary)| {
                if *secondary {
                    return false;
                }
                if *kind == MonsterKind::DecimillipedeSegment {
                    return state.monsters.iter().all(|other| {
                        other.kind != MonsterKind::DecimillipedeSegment
                            || other.uid == *uid
                            || other.hp <= 0
                    });
                }
                true
            })
            .count();
        if count > 0 {
            let heal = i32::try_from(count)
                .ok()
                .and_then(|count| count.checked_mul(3))
                .ok_or(EngineRefusal::CounterOverflow("Book Repair Knife heal"))?;
            let hp_before = state.hp;
            state.hp = state.hp.saturating_add(heal).min(state.max_hp);
            crate::coverage::record_relic(RelicId::RelicBookRepairKnife);
            // A heal's `AfterCurrentHpChanged` reaches Red Skull (#3044).
            super::damage::red_skull_after_player_hp_changed(
                state,
                hp_before,
                state.max_hp,
                events,
            )?;
        }
    }
    Ok(())
}

fn frozen_monster_is_live(state: &HotState, index: usize, uid: u32) -> bool {
    state
        .monsters
        .get(index)
        .is_some_and(|monster| monster.hp > 0 && monster.uid == uid)
}

pub(crate) fn expire_intercept_covered(state: &mut HotState) {
    if state.fanouts.intercept_covered_mask() != 0 {
        let written = state.fanouts.set_intercept_covered_mask(0);
        debug_assert!(written);
    }
}

/// RitualPower.AfterSideTurnEnd (`_run_enemy_phase`, frozen Python, deleted #2827).
///
/// The first owner-side end after enemy application consumes only
/// `WasJustAppliedByEnemy`; every later one applies the full Ritual amount as
/// Strength. This runs after temporary-Strength cleanup, matching native
/// power ordering, and dead owners never receive the command.
fn tick_monster_ritual(
    monster: &mut crate::hot::HotMonster,
    upkeep: bool,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let ritual = monster.powers.value(PowerId::Ritual);
    if ritual <= 0 || monster.hp <= 0 {
        return Ok(());
    }
    if monster.ritual_fresh {
        monster.ritual_fresh = false;
        return Ok(());
    }
    let strength = monster
        .powers
        .value(PowerId::Strength)
        .checked_add(ritual)
        .ok_or(EngineRefusal::CounterOverflow("Ritual strength"))?;
    // `RitualPower/<AfterSideTurnEnd>d__11::MoveNext` `0x342a94`
    // IL_0052-IL_0071 is `Apply<StrengthPower>(ctx, Owner, Amount, Owner,
    // null, 0)` — the owner is both target and applier.
    let owner = crate::hot::Applier::Monster(monster.uid);
    super::damage::write_monster_strength(monster, strength, owner, upkeep);
    super::damage::note_power(
        events,
        Subject::Monster(monster.uid),
        PowerId::Strength,
        strength,
    );
    Ok(())
}

/// One monster move (`monster_act`).
///
/// Python's 93-branch dispatch chain lives in the generated [`crate::moves`]
/// tree (D4): this function resolves the loop entry and hands it to
/// `apply_move`, which owns the whole `match`. What stays here is what Python
/// keeps outside its own chain — the liveness gate, the intent event, and the
/// loop advance. The Eel's stunned/terror override is modeled here; the other
/// forced-state machines, random-AI machines, and forced follow-up paths still
/// gate on refused monster kinds or powers.
/// Lagavulin Matriarch's `SLEEP_MOVE`: a sleeping Matriarch spends its whole
/// enemy action doing nothing, and its move machine does not advance (#2814).
///
/// Native authority: v0.111.0 DLL SHA256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`.
///
/// * `LagavulinMatriarch::GenerateMoveStateMachine` RVA `0xb8124` builds
///   `SLEEP_MOVE` (`IL_0012`-`IL_0031`, a lone `SleepIntent`), wires its
///   `FollowUpState` to the `SLEEP_BRANCH` `ConditionalBranchState`
///   (`IL_00f6`-`IL_0105`), and hands `SLEEP_MOVE` to the machine as its
///   initial state (`IL_017f`-`IL_0181`). The branch returns to `SLEEP_MOVE`
///   while `HasPower<AsleepPower>` (`<GenerateMoveStateMachine>b__43_0` RVA
///   `0xb85d8`, added at `IL_012a`-`IL_0139`) and goes to `SLASH_MOVE` once it
///   is gone (`b__43_1` RVA `0xb85e5`, `IL_013e`-`IL_014d`).
/// * `LagavulinMatriarch::SleepMove` RVA `0xb82ab` is
///   `Task::get_CompletedTask` (`IL_0001`-`IL_0006`): no command at all.
/// * The branch is read only when the machine rolls:
///   `Creature::PrepareForNextTurn` RVA `0x11d85c` calls
///   `MonsterModel::RollMove` (`IL_0016`-`IL_002a`) after the whole enemy side
///   end, and `MonsterMoveStateMachine::FindNextMoveState` RVA `0x78e94`
///   returns the first move state it reaches through branch states
///   (`IL_0045`-`IL_00c1`). While Asleep lives that is `SLEEP_MOVE` again, so
///   the SLASH loop position a sleeping Matriarch carries is untouched here;
///   the natural wake ([`lagavulin_asleep_after_enemy_side_end`]) resolves
///   the branch to SLASH.
///
/// Admission (`PowerId::Asleep` in `admission.rs`) forbids a live Asleep with
/// any override or forced follow-up, and the damage wake removes Asleep before
/// it installs its stun, so a sleeper carrying either is malformed.
/// Lagavulin Matriarch's native `SLEEP_MOVE` state id
/// (`GenerateMoveStateMachine` RVA `0xb8124` `IL_0012`), as the intent query
/// names it.
pub(crate) const LAGAVULIN_SLEEP_MOVE: &str = "SLEEP_MOVE";

fn lagavulin_sleep_move(
    override_state: MonsterOverride,
    forced_follow_up: MonsterFollowUp,
    spawn_noop: bool,
) -> Result<(), EngineRefusal> {
    if override_state != MonsterOverride::None
        || forced_follow_up != MonsterFollowUp::None
        || spawn_noop
    {
        return Err(EngineRefusal::MalformedArgs(
            "sleeping Lagavulin forced state",
        ));
    }
    Ok(())
}

/// `AsleepPower/<BeforeSideTurnEndVeryEarly>d__5::MoveNext` for the enemy
/// side (#2814): when this side end will remove Asleep, Plating goes first.
///
/// Native authority: v0.111.0 DLL SHA256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`,
/// stub `AsleepPower::BeforeSideTurnEndVeryEarly` RVA `0x9f95c`, body RVA
/// `0x335494`:
///
/// * `IL_001d`-`IL_0030`: returns unless `participants.Contains(Owner)`. The
///   enemy side's participants are `GetCreaturesOnSide(Enemy)`
///   (`EndEnemyTurnInternal` RVA `0x3f4784` `IL_0029`); on the player side it
///   never fires for a monster owner.
/// * `IL_0035`-`IL_003c`: returns while `Amount > 1`. So it acts only on the
///   side end whose `AfterSideTurnEnd` decrement will take Asleep to zero.
/// * `IL_003e`-`IL_0056`: if the owner `HasPower<PlatingPower>`,
///   `PowerCmd::Remove(GetPower<PlatingPower>())`. Block already gained is
///   not touched.
///
/// This is the `…VeryEarly` pass of `Hook::BeforeSideTurnEnd` (`d__80` RVA
/// `0x3d34f4` `IL_00b0`), which completes before the `…Early` pass
/// (`IL_01c9`) where Plating grants its side-end Block, so a Matriarch waking
/// naturally gets no Plating Block that side end. `AsleepPower` is only ever
/// applied by `LagavulinMatriarch/<Sleep>d__40::MoveNext` RVA `0x3613b8`
/// (`Apply<PlatingPower>(12)` at `IL_00ba`, then `Apply<AsleepPower>(3)` at
/// `IL_0131`), so a live owner is always a Matriarch; any other carrier, or a
/// corpse still carrying it while combat continues, refuses.
fn lagavulin_asleep_before_enemy_side_end_very_early(
    state: &mut HotState,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    for monster in state.monsters_mut().iter_mut() {
        let asleep = monster.powers.value(PowerId::Asleep);
        if asleep == 0 {
            continue;
        }
        if monster.hp <= 0 || monster.kind != MonsterKind::LagavulinMatriarch || asleep < 0 {
            return Err(EngineRefusal::MalformedArgs("Asleep owner/state"));
        }
        if asleep > 1 || monster.powers.value(PowerId::Mplating) == 0 {
            continue;
        }
        monster.powers.set(PowerId::Mplating, SlotWire::Int, 0);
        super::damage::note_power(events, Subject::Monster(monster.uid), PowerId::Mplating, 0);
    }
    Ok(())
}

/// `AsleepPower/<AfterSideTurnEnd>d__6::MoveNext` for one enemy-side owner
/// (#2814): decrement, and at zero wake straight away.
///
/// Native authority: v0.111.0 DLL SHA256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`,
/// stub `AsleepPower::AfterSideTurnEnd` RVA `0x9f9a8`, body RVA `0x335334`:
///
/// * `IL_0024`-`IL_0037`: returns unless `participants.Contains(Owner)`.
/// * `IL_003c`: `PowerCmd::Decrement(this)`, which delegates to
///   `PowerCmd::ModifyAmount` `0x3f032c` (null applier; the caller proves that
///   hook's listener order). At zero the power is removed.
/// * `IL_0097`-`IL_009e`: while `Amount > 0` it returns.
/// * `IL_00a0`-`IL_00b7`: otherwise it awaits `LagavulinMatriarch::WakeUpMove`
///   directly, with no `CreatureCmd::Stun` — unlike the damage wake
///   (`AsleepPower/<AfterDamageReceived>d__4` RVA `0x335094` `IL_0162`-
///   `IL_017e`), so no extra `WAKE_UP` action is spent.
///   `LagavulinMatriarch/<WakeUpMove>d__45::MoveNext` RVA `0x361874` only
///   plays the SFX and the `Wake` animation, stops the sleeping VFX and sets
///   `IsAwake` (`IL_001d`-`IL_00b8`); `IsAwake` is read only by the
///   animator (`<GenerateAnimator>b__50_0..2` RVAs `0xb85f5`-`0xb8608`).
///
/// The next `PrepareForNextTurn` roll then leaves `SLEEP_MOVE` through
/// `SLEEP_BRANCH` with Asleep gone, i.e. to `SLASH_MOVE` (see
/// [`lagavulin_sleep_move`]); the loop position is set to SLASH here, at
/// the wake, which is the same thing because nothing between this walk and
/// that roll can re-apply Asleep.
///
/// `AsleepPower` is applied (`<Sleep>d__40` `IL_0131`) before any power the
/// player can put on the Matriarch, so it precedes every player-applied
/// listener in this owner's `AfterSideTurnEnd` walk — the same position
/// `SlumberPower` takes.
fn lagavulin_asleep_after_enemy_side_end(
    state: &mut HotState,
    index: usize,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let asleep = state.monsters[index].powers.value(PowerId::Asleep);
    if asleep == 0 {
        return Ok(());
    }
    if state.monsters[index].kind != MonsterKind::LagavulinMatriarch || asleep < 0 {
        return Err(EngineRefusal::MalformedArgs("Asleep owner/state"));
    }
    super::damage::null_applier_power_amount_changed_is_exact(state)?;
    let monster = &mut state.monsters_mut()[index];
    monster
        .powers
        .set(PowerId::Asleep, SlotWire::Int, asleep - 1);
    super::damage::note_power(
        events,
        Subject::Monster(monster.uid),
        PowerId::Asleep,
        asleep - 1,
    );
    if asleep == 1 {
        monster.loop_pos = LAGAVULIN_SLASH_INDEX;
    }
    Ok(())
}

fn monster_act(
    state: &mut HotState,
    catalog: &Catalog,
    index: usize,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let (kind, uid, hp, spawn_noop, revive_stage, override_state, forced_follow_up) = {
        let monster = &state.monsters[index];
        (
            monster.kind,
            monster.uid,
            monster.hp,
            monster.spawn_noop,
            monster.revive_stage,
            monster.override_state,
            monster.forced_follow_up,
        )
    };
    if hp <= 0 {
        if kind == MonsterKind::TestSubject {
            if !super::monsters::test_subject_state_is_valid(state)
                || index != 0
                || !state.monsters[index].test_subject_adaptable_reviving()
            {
                return Err(EngineRefusal::MalformedArgs(
                    "Test Subject retained-corpse action",
                ));
            }
            let entry = *catalog
                .moves(kind)
                .first()
                .filter(|entry| entry.kind == MoveKind::TestSubjectRespawn)
                .ok_or(EngineRefusal::MonsterLoopNotModeled(kind))?;
            let mut ctx = MoveCtx {
                state,
                catalog,
                actor: index,
                args: catalog.args(entry.args),
                events,
            };
            crate::coverage::record_move(entry.kind);
            crate::moves::apply_move(entry.kind, &mut ctx)?;
            return Ok(());
        }
        // IllusionPower.ReviveMove clears its retained corpse latch and fully
        // heals the same slot/uid creature, spending the whole action
        // (`monster_act`, frozen Python, deleted #2827).
        if matches!(kind, MonsterKind::Parafright | MonsterKind::EyeWithTeeth) && revive_stage == 1
        {
            let monster = &mut state.monsters_mut()[index];
            monster.hp = monster.max_hp;
            monster.revive_stage = 0;
        }
        // A Decimillipede corpse stays in the roster and keeps taking turns:
        // `CombatManager/<ExecuteEnemyTurn>d__126::MoveNext` RVA `0x3f597c`
        // IL_00e4-IL_01c4 calls `TakeTurn` on every enemy the combat still
        // contains, and `MonsterModel/<PerformMove>d__105::MoveNext` RVA
        // `0x31d794` IL_00bc performs whatever `NextMove` holds. It never
        // rolls: the state only moves at `PrepareForNextTurn`
        // (`advance_segment_dead_states` below, #3251).
        //
        // `DEAD_MOVE`'s body (`DecimillipedeSegment::DeadMove` RVA `0xb2e7f`)
        // is `Task.CompletedTask`, so a segment still showing DEAD spends the
        // action and changes nothing — the stage stays DEAD until the next
        // roll moves it. `REATTACH_MOVE` runs
        // `ReattachPower/<DoReattach>d__10::MoveNext` RVA `0x341e90`, which
        // heals the owner for the power's Amount (IL_0081-IL_0093), from HP 0
        // exactly `min(25, max_hp)`. The RAND that follows is NOT spent here:
        // `REATTACH_MOVE` carries `MustPerformOnceBeforeTransitioning`
        // (`DecimillipedeSegment::GenerateMoveStateMachine` RVA `0xb2c04`
        // IL_00eb-IL_00ec), so its successor is resolved at the next
        // `PrepareForNextTurn` — stage 3, rolled in `prepare_random_ai`, in
        // shared roster order with the other `MonsterAi` consumers.
        if kind == MonsterKind::DecimillipedeSegment
            && revive_stage == super::monsters::SEGMENT_REVIVE_REATTACH
        {
            let monster = &mut state.monsters_mut()[index];
            monster.hp = super::monsters::SEGMENT_REATTACH_HEAL.min(monster.max_hp);
            monster.revive_stage = super::monsters::SEGMENT_REVIVE_RAND;
        }
        return Ok(());
    }
    if kind == MonsterKind::LagavulinMatriarch
        && state.monsters[index].powers.value(PowerId::Asleep) > 0
    {
        return lagavulin_sleep_move(override_state, forced_follow_up, spawn_noop);
    }
    if forced_follow_up != MonsterFollowUp::None {
        if kind == MonsterKind::ThievingHopper
            && override_state == MonsterOverride::Stunned
            && matches!(
                (state.monsters[index].loop_pos, forced_follow_up),
                (2, MonsterFollowUp::HopperNab) | (3 | 4, MonsterFollowUp::HopperEscape)
            )
            && super::monsters::thieving_hopper_state_is_valid(state)
        {
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.forced_follow_up = MonsterFollowUp::None;
            monster.loop_pos = match forced_follow_up {
                MonsterFollowUp::HopperNab => 3,
                MonsterFollowUp::HopperEscape => 4,
                _ => unreachable!("authenticated Hopper follow-up"),
            };
            return Ok(());
        }
        if override_state == MonsterOverride::Stunned
            && matches!(kind, MonsterKind::Queen | MonsterKind::TorchHeadAmalgam)
            && super::monsters::queen_amalgam_stun_state_is_exact(state, index)
        {
            // Native STUNNED consumes this action and restores the exact move
            // it interrupted. Amalgam death may have marked that Burn as
            // retained; the latch is deliberately left for the next action.
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.forced_follow_up = MonsterFollowUp::None;
            return Ok(());
        }
        // Corpse Slug's Ravenous stun. Like every other
        // registered one-shot body (`_validate_monster_stun_request` (frozen Python, deleted #2827)) its
        // body is
        // `("none", ())`: the dynamic state consumes this whole enemy action,
        // then `SetMoveImmediate` restores the ordinary telegraph the stun
        // interrupted. All three of the Slug's loop moves are reachable
        // follow-ups because the stun parks whatever that sibling was already
        // showing.
        if kind == MonsterKind::CorpseSlug && override_state == MonsterOverride::RavenousStun {
            let restored = match forced_follow_up {
                MonsterFollowUp::SlugWhipSlap => CORPSE_SLUG_WHIP_SLAP_INDEX,
                MonsterFollowUp::SlugGlomp => CORPSE_SLUG_GLOMP_INDEX,
                MonsterFollowUp::SlugGoop => CORPSE_SLUG_GOOP_INDEX,
                _ => {
                    return Err(EngineRefusal::MalformedArgs(
                        "Corpse Slug Ravenous stun follow-up",
                    ));
                }
            };
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.forced_follow_up = MonsterFollowUp::None;
            monster.loop_pos = restored;
            return Ok(());
        }
        // Lagavulin's wake. `AsleepPower/<AfterDamageReceived>d__4::MoveNext`
        // RVA `0x335094` (v0.111.0) `IL_0162`-`IL_017e` runs
        // `CreatureCmd::Stun(Owner, WakeUpMove, "SLASH_MOVE")`: the cosmetic
        // `WAKE_UP_MOVE` with a SLASH follow-up. `Creature::StunInternal`
        // `0x11d7cc` marks that state `MustPerformOnceBeforeTransitioning`
        // (`IL_0077`-`IL_0079`), so a wake installed during the enemy side end
        // survives the `PrepareForNextTurn` roll. The body is `("none", ())`
        // like every other registered one-shot body (`_validate_monster_stun_request` (frozen Python, deleted #2827)), so
        // it burns one enemy action
        // and then restores SLASH.
        if kind == MonsterKind::LagavulinMatriarch
            && override_state == MonsterOverride::LagavulinWakeUp
        {
            if forced_follow_up != MonsterFollowUp::LagavulinSlash {
                return Err(EngineRefusal::MalformedArgs("Lagavulin wake follow-up"));
            }
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.forced_follow_up = MonsterFollowUp::None;
            monster.loop_pos = LAGAVULIN_SLASH_INDEX;
            return Ok(());
        }
        // The generic `CreatureCmd::Stun(creature, null)` state (#2647 slice
        // A). `Creature::StunInternal` `0x11d7cc` installs a `STUNNED`
        // `MoveState` whose `onPerform` is the completed-task delegate
        // `0x3e8f83` and whose `FollowUpStateId` is `StateLog.Last().Id` — so
        // it consumes exactly this enemy action and then restores the very
        // telegraph it interrupted. `ForceCurrentState` `0x78f6b` never appends
        // to `StateLog`, so that telegraph is the row `loop_pos` already names:
        // unlike the four bespoke arms above, this one must NOT move
        // `loop_pos`.
        //
        // Deliberately placed after those arms, so every kind that owns a
        // bespoke arm keeps reaching it first, and before the Ceremonial Beast
        // fallthrough, which stays the refusal for everything else.
        // `generic_stun_state_is_exact` excludes every bespoke owner by kind,
        // so this cannot become a second reader of their wire states.
        if override_state == MonsterOverride::Stunned
            && super::monsters::generic_stun_state_is_exact(state, index)
        {
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.forced_follow_up = MonsterFollowUp::None;
            return Ok(());
        }
        if (kind, override_state, forced_follow_up)
            != (
                MonsterKind::CeremonialBeast,
                MonsterOverride::BeastStun,
                MonsterFollowUp::BeastCry,
            )
        {
            return Err(EngineRefusal::MalformedArgs(
                "monster forced follow-up owner/state",
            ));
        }
        // The dynamic STUN_MOVE body is empty and consumes this whole enemy
        // action before SetMoveImmediate installs BEAST_CRY_MOVE.
        let monster = &mut state.monsters_mut()[index];
        monster.override_state = MonsterOverride::None;
        monster.forced_follow_up = MonsterFollowUp::None;
        monster.loop_pos = 2;
        return Ok(());
    }
    match override_state {
        MonsterOverride::BeetleSnore | MonsterOverride::BeetleWake => {
            if kind != MonsterKind::SlumberingBeetle
                || !super::monsters::beetle_state_is_valid(&state.monsters[index])
            {
                return Err(EngineRefusal::MalformedArgs(
                    "Slumbering Beetle sleep/wake state",
                ));
            }
            if override_state == MonsterOverride::BeetleWake {
                super::monsters::wake_beetle(&mut state.monsters_mut()[index], events);
            }
            return Ok(());
        }
        MonsterOverride::BeastStun => {
            return Err(EngineRefusal::MalformedArgs(
                "Ceremonial Beast stun lacks forced follow-up",
            ));
        }
        MonsterOverride::RavenousStun => {
            return Err(EngineRefusal::MalformedArgs(
                "Corpse Slug Ravenous stun lacks forced follow-up",
            ));
        }
        MonsterOverride::LagavulinWakeUp => {
            return Err(EngineRefusal::MalformedArgs(
                "Lagavulin wake lacks forced follow-up",
            ));
        }
        MonsterOverride::Stunned => {
            state.monsters_mut()[index].override_state = MonsterOverride::Terror;
            return Ok(());
        }
        MonsterOverride::Terror => {
            // Terror is an ordinary PowerCmd.Apply (#3158). v0.111.0
            // `TerrorEel.<TerrorMove>d__30::MoveNext` (RVA 0x36d22c)
            // IL_018b-01a5 calls `PowerCmd.Apply<VulnerablePower>(targets,
            // 99, Creature, null, false)` (MethodSpec 0x2b002563, generic
            // arg TypeDef VulnerablePower). A new instance on the player
            // therefore takes the Side==Player/Debuff SkipNextDurationTick
            // latch at `<Apply>d__2` IL_0429-044c and skips this enemy
            // side end's tick; a live instance stacks with no latch. The
            // helper's absence gate is exactly that rule.
            super::damage::apply_player_duration_affliction(
                state,
                PowerId::PlayerVuln,
                PowerId::PlayerVulnFresh,
                99,
                true,
                events,
            )?;
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.loop_pos = 0;
            return Ok(());
        }
        MonsterOverride::Dizzy => {
            let monster = &mut state.monsters_mut()[index];
            monster.override_state = MonsterOverride::None;
            monster.loop_pos = 0;
            return Ok(());
        }
        MonsterOverride::None => {}
    }
    // Python `monster_act` consumes `spawn_noop` (frozen Python, deleted #2827) BEFORE its override
    // chain; this function resolves the override first. The transposition
    // is unobservable only because admission pins `spawn_noop` to its Python
    // writer kinds (Wriggler, Fat/Sneaky Gremlin), none of which can carry an
    // override (#1387). Keep that pin if this order is ever revisited.
    if spawn_noop {
        state.monsters_mut()[index].spawn_noop = false;
        return Ok(());
    }
    let (entry, random_ai, moves_len) = current_table_move(&state.monsters[index], catalog)?;

    // TwoTailedRat decrements TurnsUntilSummonable when Scratch, Disease
    // Bite, or Screech EXECUTES. CALL_FOR_BACKUP is the sole exception. The
    // signed counter deliberately keeps decreasing after it reaches zero;
    // its canonical value is search state, not a clamped readiness flag.
    if kind == MonsterKind::TwoTailedRat && entry.kind != MoveKind::SummonRat {
        let next = state.monsters[index]
            .rat_turns_until_summonable()
            .checked_sub(1)
            .ok_or(EngineRefusal::CounterOverflow("rat turns until summonable"))?;
        state.monsters_mut()[index].set_rat_turns_until_summonable(next);
    }

    events.push(Event::MonsterMoved {
        uid,
        kind: entry.kind,
    });
    {
        let mut ctx = MoveCtx {
            state: &mut *state,
            catalog,
            actor: index,
            args: catalog.args(entry.args),
            events: &mut *events,
        };
        // The single monster-move dispatch site, and so the single place a
        // move kind can be observed to have run (PORT_PLAN §4).
        crate::coverage::record_move(entry.kind);
        crate::moves::apply_move(entry.kind, &mut ctx)?;
    }

    // CURSE_OF_KNOWLEDGE blocks inside its move. Native does not advance the
    // machine until the choice's OnChosen and counter increment complete.
    if state.pending.is_some() {
        if entry.kind == MoveKind::KdCurse && kd_pending_is_exact(state) {
            return Ok(());
        }
        return Err(EngineRefusal::ContinuationNotModeled);
    }

    // Native authority: v0.111.0 DLL SHA256
    // 9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4,
    // `LivingShield::ShieldSlamMove` RVA 0x362570; its state-machine
    // predicate is at 0xb8df7/0xb8e02 and `CombatManager.StartTurn`
    // PrepareForNextTurn enters the successor roll at RVA 0x3f781c.
    // `LivingShield::ShieldSlamMove` completes its attack now, but its
    // `GetAllyCount` conditional belongs to the state machine's next
    // PrepareForNextTurn roll.  A later Turret Operator action can therefore
    // die to player retaliation before the branch is read.  Keep only this
    // typed completed-move receipt. The receipt is unreachable without this
    // exact completed attack body, and no admitted Living Shield Stun source
    // may manufacture it.
    if kind == MonsterKind::LivingShield
        && entry.kind == MoveKind::Attack
        && entry.repeats
            == crate::content_tables::Repeats::Conditional(&[
                crate::content_tables::Arg::S("living_shield_has_ally"),
                crate::content_tables::Arg::I(0),
                crate::content_tables::Arg::I(1),
            ])
        && !state.history.over
        && super::monsters::turret_operator_slam_roster_is_exact(state)
        && state
            .monsters
            .iter()
            .position(|monster| monster.uid == uid)
            .is_some_and(|current| {
                state.monsters[current].hp > 0
                    && state.monsters[current].override_state == MonsterOverride::None
                    && state.monsters[current].forced_follow_up == MonsterFollowUp::None
            })
    {
        let current = state
            .monsters
            .iter()
            .position(|monster| monster.uid == uid)
            .expect("checked Living Shield owner");
        state.monsters_mut()[current].forced_follow_up = MonsterFollowUp::LivingShieldSlam;
        return Ok(());
    }

    // Loop advance (`monster_act`'s tail, frozen Python, deleted #2827). Re-resolve the immutable
    // acting uid because a move such as BLOAT can insert a lower-slot enemy
    // before this tail resumes. Ovicopter's deferred branch owns its later
    // side-end advance; the admission gate refuses other conditional
    // follow-ups. A fixed fourth
    // element is a successor loop index (the generated field's legacy name
    // is `repeats`), while an absent one takes the plain rotation.
    let over = state.history.over;
    let Some(index) = state.monsters.iter().position(|monster| monster.uid == uid) else {
        // Escape/removal moves can legitimately erase their owner before the
        // generic tail resumes.
        return Ok(());
    };
    // #2647 — a generic stun the actor installed on ITSELF during this move
    // (an Imbalanced carrier dealing a fully blocked hit, `ImbalancedPower`
    // `0x33cd60` IL_0068-IL_006f) parks the row that was running, and the
    // machine must not advance past it. `MonsterModel/<PerformMove>d__105::
    // MoveNext` `0x31d794` IL_017f-IL_0184 ends a move with only
    // `MonsterMoveStateMachine::OnMovePerformed` `0x78e88` (sets
    // `_performedFirstMove`); the advance belongs to the next roll, where
    // `FindNextMoveState` `0x78e94` IL_001f-IL_002c leaves the unperformed
    // `MustPerformOnceBeforeTransitioning` STUNNED state in place
    // (`Creature::StunInternal` `0x11d7cc` IL_0078, `MoveState::
    // get_CanTransitionAway` `0x78ff3`). `loop_pos` therefore stays on the
    // parked row, which is exactly what the stun arm above restores.
    // The monster could not have entered this move already stunned — that
    // arm returned before the body ran — so a stun here was installed by it.
    if actor_self_stun_parks_its_row(state, index) {
        return Ok(());
    }
    let monster = &mut state.monsters_mut()[index];
    if !random_ai
        && !matches!(
            entry.kind,
            MoveKind::AttackScrollBranch
                | MoveKind::AttackStrengthBranch
                | MoveKind::AttackVulnerableDeferredOvicopter
        )
        && !over
        && monster.hp > 0
    {
        monster.loop_pos = match entry.repeats {
            crate::content_tables::Repeats::Absent => (monster.loop_pos + 1) % (moves_len as i32),
            crate::content_tables::Repeats::Fixed(next) => i32::try_from(next)
                .ok()
                .filter(|next| usize::try_from(*next).is_ok_and(|next| next < moves_len))
                .ok_or(EngineRefusal::CounterOverflow("monster fixed successor"))?,
            crate::content_tables::Repeats::Conditional(args)
                if kind == MonsterKind::KnowledgeDemon
                    && entry.kind == MoveKind::Ponder
                    && args
                        == [
                            crate::content_tables::Arg::S("kd_counter_lt3"),
                            crate::content_tables::Arg::I(0),
                            crate::content_tables::Arg::I(1),
                        ] =>
            {
                if monster
                    .knowledge_demon_curse_counter()
                    .is_some_and(|counter| counter < 3)
                {
                    0
                } else {
                    1
                }
            }
            crate::content_tables::Repeats::Conditional(args)
                if kind == MonsterKind::FrogKnight
                    && entry.kind == MoveKind::BuffStrength
                    && args
                        == [
                            crate::content_tables::Arg::S("hp_below_half_once"),
                            crate::content_tables::Arg::S("beetle_charged"),
                            crate::content_tables::Arg::I(3),
                            crate::content_tables::Arg::I(0),
                        ] =>
            {
                if !monster.louse_curled() && monster.hp < monster.max_hp / 2 {
                    3
                } else {
                    0
                }
            }
            crate::content_tables::Repeats::Conditional(args)
                if kind == MonsterKind::Queen
                    && matches!(
                        entry.kind,
                        MoveKind::QueenYoureMine | MoveKind::QueenBurnBright
                    )
                    && args
                        == [
                            crate::content_tables::Arg::S("queen_amalgam_alive"),
                            crate::content_tables::Arg::I(2),
                            crate::content_tables::Arg::I(3),
                        ] =>
            {
                if monster.queen_amalgam_dead() {
                    3
                } else {
                    2
                }
            }
            crate::content_tables::Repeats::Conditional(_) => {
                return Err(EngineRefusal::MonsterLoopNotModeled(kind));
            }
        };
    }
    Ok(())
}

/// Did the actor at `index` end its own move in a stun whose parked telegraph
/// is the row it just performed (#2647)?
///
/// Only the generic `CreatureCmd::Stun(creature, null)` state qualifies —
/// [`super::monsters::generic_stun_state_is_exact`] excludes every bespoke
/// owner by kind, so none of their existing tails change.
fn actor_self_stun_parks_its_row(state: &HotState, index: usize) -> bool {
    state.monsters[index].override_state == MonsterOverride::Stunned
        && super::monsters::generic_stun_state_is_exact(state, index)
}

/// Run the one public, state-authenticated Queen move witness approved by
/// #1967.
///
/// Ordinary Queen encounters now use the shared R42 card-affliction
/// foundation. This deliberately narrow witness remains useful for exercising
/// Burn Bright through the ordinary move dispatcher and coverage recorder on
/// the exact stable two-creature roster at loop row 2. It rehearses the whole
/// action on a clone and publishes neither state nor events on refusal.
pub fn queen_burn_bright_smoke(
    state: &HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<HotState, EngineRefusal> {
    if !super::monsters::queen_roster_state_is_valid(state)
        || state.monsters.len() != 2
        || state.monsters[1].kind != MonsterKind::Queen
        || state.monsters[1].loop_pos != 2
        || state.monsters[1].override_state != MonsterOverride::None
        || state.monsters[1].forced_follow_up != MonsterFollowUp::None
    {
        return Err(EngineRefusal::MalformedArgs(
            "Queen Burn Bright smoke state",
        ));
    }
    let (entry, random_ai, _) = current_table_move(&state.monsters[1], catalog)?;
    if random_ai || entry.kind != MoveKind::QueenBurnBright {
        return Err(EngineRefusal::MalformedArgs("Queen Burn Bright smoke move"));
    }

    let mut successor = state.clone();
    let mut emitted = Vec::new();
    monster_act(&mut successor, catalog, 1, &mut emitted)?;
    events.extend(emitted);
    Ok(successor)
}

/// Run the coordinator-approved narrow Queen PuppetStrings move witness.
///
/// The witness accepts only the exact fresh, solo, stable Queen/Amalgam row
/// with exact piles and no prior card-affliction state. It then clone-runs the
/// ordinary [`monster_act`] dispatcher so failures publish neither state nor
/// events and executable coverage is recorded at the production move arm.
pub fn queen_puppet_strings_smoke(
    state: &HotState,
    catalog: &Catalog,
    events: &mut Vec<Event>,
) -> Result<HotState, EngineRefusal> {
    if !super::monsters::queen_roster_state_is_valid(state)
        || state.monsters.len() != 2
        || state.monsters[1].kind != MonsterKind::Queen
        || state.monsters[1].loop_pos != 0
        || state.monsters[1].override_state != MonsterOverride::None
        || state.monsters[1].forced_follow_up != MonsterFollowUp::None
        || !super::cards::fresh_card_affliction_application_is_exact(state)
    {
        return Err(EngineRefusal::MalformedArgs(
            "Queen PuppetStrings smoke state",
        ));
    }
    let (entry, random_ai, _) = current_table_move(&state.monsters[1], catalog)?;
    if random_ai || entry.kind != MoveKind::QueenPuppetStrings {
        return Err(EngineRefusal::MalformedArgs(
            "Queen PuppetStrings smoke move",
        ));
    }

    let mut successor = state.clone();
    let mut emitted = Vec::new();
    monster_act(&mut successor, catalog, 1, &mut emitted)?;
    events.extend(emitted);
    Ok(successor)
}

/// Run the coordinator-approved narrow Spectral Knight Hex witness without
