    fn run_after_side_turn_end_hook_for_test(
        state: &mut HotState,
        catalog: &Catalog,
        events: &mut Vec<Event>,
    ) -> Result<(), EngineRefusal> {
        let Some(record) = capture_after_side_turn_end_power_record(state, false)? else {
            return run_after_side_turn_end_ordinary_nonlocal(state, catalog, events);
        };
        let record_index = state.frames.push_after_side_turn_end_power(&record).ok_or(
            EngineRefusal::CounterOverflow("AfterSideTurnEnd power snapshot"),
        )?;
        if drive_after_side_turn_end_power(state, catalog, events, record_index)? {
            return Err(EngineRefusal::ContinuationNotModeled);
        }
        state
            .frames
            .pop_top_after_side_turn_end_power()
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        Ok(())
    }

    #[test]
    fn empty_side_end_ledger_fast_path_rejects_live_unrecorded_members() {
        let mut state = HotState::at_defaults();
        assert!(after_side_turn_end_power_order_is_exact(&state));

        // A scalar power without its required object-ledger entry is still
        // malformed; populated slots must not take the empty shortcut.
        state.powers.set(PowerId::Burst, SlotWire::Int, 1);
        assert!(!after_side_turn_end_power_order_is_exact(&state));

        // The non-slot temporary-strength carrier is likewise covered by the
        // guard before the shortcut can accept an empty ledger.
        let mut temporary = HotState::at_defaults();
        temporary.temp_strength = 1;
        assert!(!after_side_turn_end_power_order_is_exact(&temporary));
    }

    #[test]
    fn wither_turn_end_reads_exact_uid_growth_and_routes_lethal_blockable_damage() {
        let identity = CardIdentity {
            id: CardId::Wither,
            upgrade: 0,
            enchantment: None,
        };
        let mut builder = crate::catalog::CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Aeonglass).unwrap();
        let atom = builder.intern_reachable(identity).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 5;
        state.max_hp = 50;
        state.block = 4;
        state.next_card_uid = 1;
        state.exact_piles = true;
        state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 0,
                atom,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        assert_eq!(state.card_states.add_damage_growth(0, 6), Some(6));
        let mut boss = HotMonster::new(MonsterKind::Aeonglass, 535);
        boss.max_hp = 535;
        boss.powers.set(PowerId::Artifact, SlotWire::Int, 3);
        state.monsters_mut().push(boss);
        assert!(state.fanouts.set_withering_cards_left(6));

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!((state.block, state.hp), (0, 0));
        assert!(state.history.over);
        assert!(state.piles.get(PileId::Hand).is_empty());
        assert_eq!(state.piles.get(PileId::Play).as_slice()[0].uid, 0);
        assert_eq!(state.card_states.get(0).damage_growth, 6);
    }

    #[test]
    fn aeonglass_public_smoke_runs_exact_cycle_intents_and_intensity() {
        let identity = CardIdentity {
            id: CardId::Wither,
            upgrade: 0,
            enchantment: None,
        };
        let mut builder = crate::catalog::CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Aeonglass).unwrap();
        builder.intern_reachable(identity).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 300;
        state.max_hp = 300;
        state.player_phase = boundary_gate::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.rng.set(
            RngStream::Niche,
            crate::hot::RngStreamState {
                words: [11, 22, 33, 44],
                counter: 7,
            },
        );
        let niche_before = state.rng.get(RngStream::Niche).counter;
        super::super::monsters::construct_aeonglass_boss(&mut state, &catalog, &mut Vec::new())
            .unwrap();
        assert_eq!(state.rng.get(RngStream::Niche).counter, niche_before + 1);
        assert!(monster_intends_to_attack(&state, &catalog, 0).unwrap());

        let mut probe = state.clone();
        end_player_turn(&mut probe, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(probe.monsters[0].loop_pos, 1);
        assert!(monster_intends_to_attack(&probe, &catalog, 0).unwrap());
        end_player_turn(&mut probe, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(probe.monsters[0].loop_pos, 2);
        assert!(!monster_intends_to_attack(&probe, &catalog, 0).unwrap());

        let mut events = Vec::new();
        let successor = aeonglass_intensity_smoke(&state, &catalog, &mut events).unwrap();
        assert_eq!(successor.monsters[0].loop_pos, 0);
        assert_eq!(successor.monsters[0].block, 0);
        assert_eq!(successor.hp, 250);
        assert!(events.iter().any(|event| matches!(
            event,
            Event::MonsterMoved {
                kind: MoveKind::AeonglassIntensity,
                ..
            }
        )));
    }

