    #[test]
    fn catalog_authenticated_end_turn_routes_rolling_boulder_damage_into_hopper() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::ThievingHopper).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 80;
        state.max_hp = 80;
        state.exact_piles = true;
        state
            .card_states
            .set_hopper(Some(crate::hot::HopperDeckState::default()));
        let mut hopper = crate::hot::HotMonster::new(
            MonsterKind::ThievingHopper,
            crate::engine::monsters::THIEVING_HOPPER_HP,
        );
        hopper.max_hp = crate::engine::monsters::THIEVING_HOPPER_HP;
        hopper.loop_pos = 1;
        hopper.powers.set(
            PowerId::EscapeArtist,
            SlotWire::Int,
            crate::engine::monsters::THIEVING_HOPPER_ESCAPE_ARTIST - 1,
        );
        state.monsters_mut().push(hopper);
        state.powers.set(PowerId::RollingBoulder, SlotWire::Int, 5);
        assert!(
            state
                .fanouts
                .set_after_player_turn_start_order(&[PowerId::RollingBoulder])
        );

        let mut poison = state.clone();
        poison.monsters_mut()[0]
            .powers
            .set(PowerId::Poison, SlotWire::Int, 2);
        poison.monsters_mut()[0].poison_uid = 0;
        poison.monsters_mut()[0]
            .misery_debuff_order
            .push(crate::hot::MiseryToken::Poison);
        poison.next_poison_uid = 1;
        let poison_before = poison.clone();
        let mut poison_events = vec![Event::TurnBegan { turn: 99 }];
        let poison_events_before = poison_events.clone();
        assert_eq!(
            super::super::damage::tick_monster_poison(&mut poison, &mut poison_events),
            Err(EngineRefusal::MalformedArgs(
                "Thieving Hopper Poison catalog"
            ))
        );
        assert_eq!(poison, poison_before);
        assert_eq!(poison_events, poison_events_before);
        end_player_turn(&mut poison, &catalog, &mut poison_events).unwrap();
        assert_eq!(
            poison.monsters[0].hp,
            crate::engine::monsters::THIEVING_HOPPER_HP - 7,
            "Poison precedes the authenticated Rolling Boulder suffix"
        );
        assert_eq!(poison.monsters[0].powers.value(PowerId::Poison), 1);

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(
            state.monsters[0].hp,
            crate::engine::monsters::THIEVING_HOPPER_HP - 5
        );
        assert_eq!(state.monsters[0].loop_pos, 2);
        assert_eq!(state.powers.value(PowerId::RollingBoulder), 10);

        let mut reflect = state.clone();
        reflect.block = 3;
        reflect.powers.set(PowerId::Reflect, SlotWire::Bool, 1);
        assert!(
            reflect
                .fanouts
                .register_after_side_turn_start(PowerId::Reflect)
        );
        end_player_turn(&mut reflect, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(reflect.hp, 60, "three of HAT_TRICK's 23 were blocked");
        assert_eq!(
            reflect.monsters[0].hp,
            crate::engine::monsters::THIEVING_HOPPER_HP - 18
        );

        state.powers.set(PowerId::Thorns, SlotWire::Int, 4);
        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.hp, 57);
        assert_eq!(
            state.monsters[0].hp,
            crate::engine::monsters::THIEVING_HOPPER_HP - 19
        );
        assert_eq!(state.monsters[0].loop_pos, 3);
    }

    /// #3357: Mysterious Knight rolls Flail Knight's machine. For every legal
    /// StateLog and a spread of `RngStream::Ai` states, the two kinds pick the
    /// same move, log it identically and spend the same draw.
    #[test]
    fn mysterious_knight_rolls_the_flail_knight_machine() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::FlailKnight).unwrap();
        builder
            .intern_monster(MonsterKind::MysteriousKnight)
            .unwrap();
        let catalog = builder.build();
        let logs: [&[u8]; 6] = [&[2], &[2, 2], &[2, 0], &[2, 1, 1], &[0, 1, 2], &[1, 2, 2]];
        for log in logs {
            for seed in 0..32_u64 {
                let roll = |kind: MonsterKind| {
                    let mut state = HotState::at_defaults();
                    let mut knight = HotMonster::new(kind, 101);
                    knight.max_hp = 101;
                    assert!(knight.random_ai.set_next(log.last().copied()));
                    assert!(knight.random_ai.set_log(log));
                    state.monsters_mut().push(knight);
                    state.rng.set(
                        RngStream::Ai,
                        RngStreamState {
                            words: [
                                seed.wrapping_mul(0x9e37_79b9_7f4a_7c15) | 1,
                                seed ^ 0xdead_beef,
                                seed.rotate_left(17) | 2,
                                0x1234_5678 + seed,
                            ],
                            counter: 0,
                        },
                    );
                    roll_random_intent(&mut state, &catalog, 0).unwrap();
                    let monster = &state.monsters[0];
                    let log: Vec<_> = (0..monster.random_ai.log_len())
                        .filter_map(|position| monster.random_ai.log_at(position))
                        .collect();
                    (monster.random_ai.next(), log, state.rng.get(RngStream::Ai))
                };
                assert_eq!(
                    roll(MonsterKind::FlailKnight),
                    roll(MonsterKind::MysteriousKnight),
                    "log {log:?} seed {seed}"
                );
            }
        }
    }

