    #[test]
    fn tyranny_nested_dark_owner_is_rootless_canonical_and_resumes_once() {
        let mut builder = crate::catalog::CatalogBuilder::new();
        let strike = builder
            .intern_reachable(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let defend = builder
            .intern_reachable(CardIdentity {
                id: CardId::DefendIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let sculpting = builder
            .intern_reachable(CardIdentity {
                id: CardId::SeekerStrike,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        builder.mark_live_dark_embrace_reachable();
        builder.mark_live_stratagem_reachable();
        let catalog = builder.build();
        assert!(!catalog.requires_action_replay());
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.turn = 1;
        state.player_phase = PHASE_ORDINARY_ACTIONS;
        state.player_side_active = true;
        state.exact_piles = true;
        state.next_card_uid = 11;
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((0..8).map(|uid| crate::hot::HotCard {
                uid,
                atom: if uid % 2 == 0 { strike } else { defend },
                flags: 0,
            }));
        state.piles.get_mut(PileId::Discard).make_mut().extend([
            crate::hot::HotCard {
                uid: 8,
                atom: sculpting,
                flags: 0,
            },
            crate::hot::HotCard {
                uid: 9,
                atom: defend,
                flags: 0,
            },
            crate::hot::HotCard {
                uid: 10,
                atom: strike,
                flags: 0,
            },
        ]);
        state.powers.set(PowerId::Tyranny, SlotWire::Int, 2);
        state.powers.set(PowerId::DarkEmbrace, SlotWire::Int, 1);
        state.powers.set(PowerId::Stratagem, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_turn_start_hand_choice_order(&[PowerId::Tyranny])
        );
        assert!(
            state
                .fanouts
                .set_after_card_exhausted_order(&[PowerId::DarkEmbrace])
        );
        state
            .fanouts
            .register_after_side_turn_end_power(crate::hot::AfterSideTurnEndPowerToken::DarkEmbrace)
            .unwrap();

        let initial_wire =
            crate::boundary::HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = crate::boundary::HotBoundary::catalog_from_canonical(&initial_wire).unwrap();
        let state = crate::boundary::HotBoundary::from_canonical(&initial_wire, &catalog).unwrap();
        crate::engine::admit(&initial_wire, &state, &catalog).unwrap();

        let selecting =
            crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn)
                .unwrap()
                .state;
        let choices = crate::engine::legal_actions(&selecting, &catalog);
        assert_eq!(choices.len(), 42);
        let parked_result = crate::engine::apply_action(&selecting, &catalog, &choices[0]).unwrap();
        let parked = parked_result.state;
        assert!(parked.pending.is_some());
        assert!(matches!(
            parked.frames.as_slice(),
            [
                crate::frame::Frame::TurnStartHandChoice { .. },
                crate::frame::Frame::AfterCardExhaustedPower { .. },
                crate::frame::Frame::Draw { .. },
            ]
        ));
        assert!(
            crate::engine::play::rootless_tyranny_after_card_exhausted_stack_is_exact(
                &parked, &catalog,
            )
            .is_ok()
        );

        let rewrite_parent = |rewrite: fn(&mut crate::hot::TurnStartHandChoiceRecord)| {
            let [
                crate::frame::Frame::TurnStartHandChoice {
                    record: parent_index,
                },
                crate::frame::Frame::AfterCardExhaustedPower {
                    record: owner_index,
                },
                crate::frame::Frame::Draw { record: draw_index },
            ] = parked.frames.as_slice()
            else {
                panic!("expected rootless Tyranny owner stack")
            };
            let mut parent = parked
                .frames
                .turn_start_hand_choice(*parent_index)
                .unwrap()
                .to_owned();
            let owner = parked
                .frames
                .after_card_exhausted_power(*owner_index)
                .unwrap()
                .to_owned();
            let draw = parked.frames.draw(*draw_index).unwrap().to_owned();
            rewrite(&mut parent);
            let mut forged = parked.clone();
            let mut frames = crate::hot::Frames::new();
            frames.push_turn_start_hand_choice(&parent).unwrap();
            frames.push_after_card_exhausted_power(&owner).unwrap();
            let pending_record = frames.push_draw(&draw).unwrap();
            forged.frames = frames;
            forged.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
                frame_uid: crate::hot::STRATAGEM_SELECTION_PENDING_UID,
                frame_record: pending_record,
            }));
            forged
        };
        let forged_parent = rewrite_parent(|parent| {
            parent.cursor = 0;
        });
        {
            let forged = forged_parent;
            assert!(
                crate::engine::play::rootless_tyranny_after_card_exhausted_stack_is_exact(
                    &forged, &catalog,
                )
                .is_err()
            );
            assert!(crate::engine::legal_actions(&forged, &catalog).is_empty());
            let forged_wire =
                crate::boundary::HotBoundary::try_to_canonical(&forged, &catalog).unwrap();
            let forged_catalog =
                crate::boundary::HotBoundary::catalog_from_canonical(&forged_wire).unwrap();
            if let Ok(forged_state) =
                crate::boundary::HotBoundary::from_canonical(&forged_wire, &forged_catalog)
            {
                assert!(
                    crate::engine::admit(&forged_wire, &forged_state, &forged_catalog).is_err(),
                    "structural round-trip must not authenticate a forged Tyranny parent"
                );
            }
        }
        let crate::frame::Frame::TurnStartHandChoice { record } = parked.frames.as_slice()[0]
        else {
            panic!("expected rootless Tyranny parent")
        };
        let mut impossible_phase = parked
            .frames
            .turn_start_hand_choice(record)
            .unwrap()
            .to_owned();
        impossible_phase.phase = TurnStartHandChoicePhase::Selecting;
        assert!(
            crate::hot::Frames::new()
                .push_turn_start_hand_choice(&impossible_phase)
                .is_none(),
            "a completed Tyranny prefix cannot be forged back into Selecting"
        );

        let wire = crate::boundary::HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = crate::boundary::HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt =
            crate::boundary::HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let stratagem_actions = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog);
        assert!(!stratagem_actions.is_empty());
        let completed =
            crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &stratagem_actions[0]).unwrap();
        assert!(completed.state.pending.is_none());
        assert!(completed.state.frames.is_empty());
        assert_eq!(
            completed
                .state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [0, 1]
        );
        assert_eq!(completed.state.history.owner_cards_exhausted_combat, 2);
        assert_eq!(
            completed
                .events
                .iter()
                .filter(|event| matches!(event, Event::TurnBegan { .. }))
                .count(),
            1
        );
    }

