    #[test]
    fn both_choice_acquisition_orders_add_to_the_same_turn_start_hand_draw() {
        for order in [
            [PowerId::ToolsOfTheTrade, PowerId::Tyranny],
            [PowerId::Tyranny, PowerId::ToolsOfTheTrade],
        ] {
            let (mut state, catalog) = hand_choice_fixture(7);
            let cards = state.piles.get(PileId::Hand).as_slice().to_vec();
            state.piles.get_mut(PileId::Hand).make_mut().clear();
            state.piles.get_mut(PileId::Draw).make_mut().extend(cards);
            state.powers.set(PowerId::ToolsOfTheTrade, SlotWire::Int, 1);
            state.powers.set(PowerId::Tyranny, SlotWire::Int, 1);
            assert!(state.fanouts.set_turn_start_hand_choice_order(&order));

            begin_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();

            assert_eq!(state.piles.get(PileId::Hand).len(), 7);
            assert_eq!(crate::engine::legal_actions(&state, &catalog).len(), 7);
            let pending = state
                .pending
                .as_deref()
                .and_then(|pending| pending.turn_start_hand_choice_record(&state.frames))
                .unwrap();
            assert_eq!(
                pending.kind,
                if order[0] == PowerId::ToolsOfTheTrade {
                    TurnStartHandChoiceKind::ToolsOfTheTrade
                } else {
                    TurnStartHandChoiceKind::Tyranny
                }
            );
        }
    }

