    #[test]
    fn hello_world_turn_listener_consumes_full_shuffle_and_generates_frozen_prefix() {
        let mut builder = CatalogBuilder::new();
        for id in crate::content_tables::HELLO_WORLD_COMMON_POOL_V1101 {
            builder
                .intern(CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap();
        }
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.reward_card_pool = Some(crate::catalog::RewardPool::Defect);
        state.publish_hello_world_generation_pool();
        state.fully_unlocked_card_pool_epochs = true;
        state.powers.set(PowerId::HelloWorld, SlotWire::Int, 2);
        state.rng.set(
            RngStream::Generation,
            crate::hot::RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        let before = state.rng.get(RngStream::Generation).counter;

        run_hello_world_before_hand_draw(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(state.piles.get(PileId::Hand).len(), 2);
        assert_eq!(state.history.owner_generated_cards_combat, 2);
        assert_eq!(
            state.rng.get(RngStream::Generation).counter,
            before + 19,
            "GetDistinctForCombat shuffles all twenty Common identities"
        );
        assert!(
            state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .all(|card| catalog.spec(card.atom).unwrap().identity.upgrade == 0)
        );

        // Canonical reload between application and the next owner turn can
        // carry current=2/snapshot=1. The turn boundary replaces that native
        // snapshot before BeforeHandDraw, so the listener must add two—not
        // one—and the packed delta must return to zero.
        assert!(state.set_hello_world_amount_on_turn_start(2, 1));
        assert!(state.fanouts.register_before_hand_draw(PowerId::HelloWorld));
        begin_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.piles.get(PileId::Hand).len(), 4);
        assert_eq!(
            state.hello_world_amount_on_turn_start(state.powers.value(PowerId::HelloWorld)),
            Some(2)
        );
        assert!(state.hello_world_snapshot_is_current());
    }

    fn void_form_turn_state(completed: i32, requested: bool) -> HotState {
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.powers.set(PowerId::VoidForm, SlotWire::Int, 2);
        state.fanouts.set_void_form_hooks_registered(true);
        assert!(
            state
                .fanouts
                .set_void_form_cards_played_this_turn(completed)
        );
        state.fanouts.set_void_form_end_turn_requested(requested);
        assert!(crate::steps::regent_uncommon::void_form_private_state_is_exact(&state));
        state
    }

    #[test]
    fn void_form_owner_side_start_resets_only_its_private_counter() {
        let mut state = void_form_turn_state(1_000_000_000, false);
        let catalog = CatalogBuilder::new().build();
        begin_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.powers.value(PowerId::VoidForm), 2);
        assert_eq!(state.fanouts.void_form_cards_played_this_turn(), 0);
        assert!(state.fanouts.void_form_hooks_are_registered());
        assert!(!state.fanouts.void_form_end_turn_requested());
        assert!(crate::steps::regent_uncommon::void_form_private_state_is_exact(&state));
    }

    #[test]
    fn void_form_unresolved_request_refuses_direct_end_and_turn_start_atomically() {
        let state = void_form_turn_state(999_999_999, true);
        let catalog = CatalogBuilder::new().build();
        for begin in [false, true] {
            let mut candidate = state.clone();
            let before = candidate.clone();
            let mut events = vec![Event::TurnEnded { turn: 99 }];
            let before_events = events.clone();
            let result = if begin {
                begin_player_turn(&mut candidate, &catalog, &mut events)
            } else {
                end_player_turn(&mut candidate, &catalog, &mut events)
            };
            assert_eq!(
                result,
                Err(EngineRefusal::MalformedArgs(
                    "unresolved void form end-turn request"
                ))
            );
            assert_eq!(candidate, before);
            assert_eq!(events, before_events);
        }
    }

