    fn monologue_expiry_state(applied: i32, strength: i32) -> HotState {
        let mut state = HotState::at_defaults();
        state.fanouts.set_next_after_side_turn_end_power_uid(1);
        assert!(
            state
                .fanouts
                .set_monologue_instances(&[crate::hot::MonologueInstance {
                    uid: 0,
                    amount: 1,
                    power: 1,
                    strength_applied: applied,
                }])
        );
        assert!(
            state
                .fanouts
                .set_after_side_turn_end_power_order(&[AfterSideTurnEndPowerEntry {
                    token: AfterSideTurnEndPowerToken::Monologue,
                    uid: 0,
                },])
        );
        assert!(state.fanouts.set_after_card_played_power_order(&[
            crate::hot::AfterCardPlayedPowerEntry {
                token: crate::hot::AfterCardPlayedPowerToken::Monologue,
                uid: 0,
            },
        ]));
        state.hp = 50;
        state.powers.set(PowerId::Monologue, SlotWire::Int, 1);
        state.powers.set(PowerId::Strength, SlotWire::Int, strength);
        state
    }

    #[test]
    fn monologue_side_end_removes_only_its_ledger_and_all_hooks() {
        let mut state = monologue_expiry_state(1, 2);
        let mut events = Vec::new();
        expire_monologue_side_end(&mut state, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::Monologue), 0);
        assert_eq!(state.powers.value(PowerId::Strength), 1);
        assert_eq!(state.fanouts.monologue_strength_applied(), 0);
        assert!(!state.fanouts.monologue_hooks_are_registered());
        assert!(crate::steps::regent_uncommon::monologue_private_state_is_exact(&state));

        let mut terminal = monologue_expiry_state(1, 2);
        terminal.history.over = true;
        expire_monologue_side_end(&mut terminal, &mut Vec::new()).unwrap();
        assert_eq!(terminal.powers.value(PowerId::Monologue), 0);
        assert_eq!(terminal.powers.value(PowerId::Strength), 2);
        assert_eq!(terminal.fanouts.monologue_strength_applied(), 0);
    }

    #[test]
    fn monologue_side_end_removes_each_object_and_reverses_each_private_ledger() {
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.fanouts.set_next_after_side_turn_end_power_uid(2);
        assert!(state.fanouts.set_monologue_instances(&[
            crate::hot::MonologueInstance {
                uid: 0,
                amount: 1,
                power: 1,
                strength_applied: 1,
            },
            crate::hot::MonologueInstance {
                uid: 1,
                amount: 1,
                power: 1,
                strength_applied: 2,
            },
        ]));
        assert!(state.fanouts.set_after_side_turn_end_power_order(&[
            AfterSideTurnEndPowerEntry {
                token: AfterSideTurnEndPowerToken::Monologue,
                uid: 0,
            },
            AfterSideTurnEndPowerEntry {
                token: AfterSideTurnEndPowerToken::Monologue,
                uid: 1,
            },
        ]));
        assert!(state.fanouts.set_after_card_played_power_order(&[
            crate::hot::AfterCardPlayedPowerEntry {
                token: crate::hot::AfterCardPlayedPowerToken::Monologue,
                uid: 0,
            },
            crate::hot::AfterCardPlayedPowerEntry {
                token: crate::hot::AfterCardPlayedPowerToken::Monologue,
                uid: 1,
            },
        ]));
        state.powers.set(PowerId::Monologue, SlotWire::Int, 2);
        state.powers.set(PowerId::Strength, SlotWire::Int, 3);
        let mut events = Vec::new();

        expire_monologue_side_end(&mut state, &mut events).unwrap();

        assert_eq!(state.powers.value(PowerId::Monologue), 0);
        assert_eq!(state.powers.value(PowerId::Strength), 0);
        assert_eq!(state.fanouts.monologue_instances().count(), 0);
        assert_eq!(state.fanouts.monologue_strength_applied(), 0);
        assert_eq!(
            events
                .iter()
                .filter_map(|event| match event {
                    Event::PowerChanged {
                        power: PowerId::Monologue,
                        amount,
                        ..
                    } => Some(*amount),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [0, 0],
            "each removed native object reports its own resulting Amount"
        );
    }

    #[test]
    fn monologue_negative_type_one_and_strength_underflow_refuse_before_removal() {
        let mut underflow = monologue_expiry_state(1, i32::MIN);
        let before = underflow.clone();
        let mut events = Vec::new();
        assert_eq!(
            expire_monologue_side_end(&mut underflow, &mut events),
            Err(EngineRefusal::CounterOverflow("player strength"))
        );
        assert_eq!(underflow, before);
        assert!(events.is_empty());

        let mut forgeries = Vec::new();
        let mut orphan = monologue_expiry_state(1, 1);
        orphan.powers.set(PowerId::Vicious, SlotWire::Int, 1);
        forgeries.push(orphan);
        let mut wrong_wire = monologue_expiry_state(1, 1);
        wrong_wire.powers.set(PowerId::Shroud, SlotWire::Bool, 1);
        assert!(
            wrong_wire
                .fanouts
                .set_after_power_amount_changed_order(&[PowerId::Shroud])
        );
        forgeries.push(wrong_wire);
        let mut alien = monologue_expiry_state(1, 1);
        assert!(
            alien
                .fanouts
                .set_after_power_amount_changed_order(&[PowerId::SleightOfFlesh])
        );
        forgeries.push(alien);
        let mut duplicate = monologue_expiry_state(1, 1);
        duplicate.powers.set(PowerId::Vicious, SlotWire::Int, 1);
        assert!(
            duplicate
                .fanouts
                .set_after_power_amount_changed_order(&[PowerId::Vicious, PowerId::Vicious])
        );
        forgeries.push(duplicate);

        for mut forged in forgeries {
            let before = forged.clone();
            let mut events = vec![Event::PowerChanged {
                subject: Subject::Player,
                power: PowerId::Strength,
                amount: 9,
            }];
            let before_events = events.clone();
            assert_eq!(
                expire_monologue_side_end(&mut forged, &mut events),
                Err(EngineRefusal::MalformedArgs(
                    "monologue side-end listener state"
                ))
            );
            assert_eq!(forged, before);
            assert_eq!(events, before_events);
        }
    }

    #[test]
    fn debilitate_expires_on_its_living_owner_enemy_side_and_removes_misery_token() {
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 30);
        monster.uid = 19;
        monster.powers.set(PowerId::Conqueror, SlotWire::Int, 2);
        monster.powers.set(PowerId::Debilitate, SlotWire::Int, 2);
        monster.misery_debuff_order.push(MiseryToken::Weak);
        monster.misery_debuff_order.push(MiseryToken::Conqueror);
        monster.misery_debuff_order.push(MiseryToken::Debilitate);

        let mut events = Vec::new();
        expire_monster_post_intangible_debuffs(&mut monster, true, &mut events);
        assert_eq!(monster.powers.value(PowerId::Conqueror), 1);
        assert_eq!(monster.powers.value(PowerId::Debilitate), 1);
        assert_eq!(
            monster.misery_debuff_order.as_slice(),
            &[
                MiseryToken::Weak,
                MiseryToken::Conqueror,
                MiseryToken::Debilitate
            ]
        );
        assert_eq!(
            events,
            [Event::PowerChanged {
                subject: Subject::Monster(19),
                power: PowerId::Conqueror,
                amount: 1,
            }]
        );
        expire_monster_post_intangible_debuffs(&mut monster, true, &mut events);
        assert_eq!(monster.powers.value(PowerId::Conqueror), 0);
        assert_eq!(monster.powers.value(PowerId::Debilitate), 0);
        assert_eq!(monster.misery_debuff_order.as_slice(), &[MiseryToken::Weak]);
        assert_eq!(
            events.last(),
            Some(&Event::PowerChanged {
                subject: Subject::Monster(19),
                power: PowerId::Conqueror,
                amount: 0,
            })
        );
    }

    #[test]
    fn knockdown_expires_together_and_public_turn_refuses_or_rolls_back_atomically() {
        let mut owner = HotMonster::new(MonsterKind::Toadpole, 30);
        owner.uid = 19;
        owner.misery_debuff_order.push(MiseryToken::Weak);
        owner.misery_debuff_order.push_knockdown(2);
        owner.misery_debuff_order.push_knockdown(3);
        expire_monster_post_intangible_debuffs(&mut owner, false, &mut Vec::new());
        assert_eq!(owner.misery_debuff_order.as_slice(), [MiseryToken::Weak]);
        assert!(owner.misery_debuff_order.knockdown().is_empty());

        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        for malformed_owner in {
            let mut token_only = HotMonster::new(MonsterKind::Toadpole, 30);
            token_only.misery_debuff_order.push(MiseryToken::Knockdown);
            let mut amount_only = HotMonster::new(MonsterKind::Toadpole, 30);
            amount_only.misery_debuff_order.set_knockdown(vec![2]);
            let mut scalar = HotMonster::new(MonsterKind::Toadpole, 30);
            scalar.powers.set(PowerId::Knockdown, SlotWire::Int, 2);
            [token_only, amount_only, scalar]
        } {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            state.max_hp = 100;
            state.monsters_mut().push(malformed_owner);
            let before = state.clone();
            let mut events = vec![Event::TurnBegan { turn: 79 }];
            let events_before = events.clone();
            assert_eq!(
                end_player_turn(&mut state, &catalog, &mut events),
                Err(EngineRefusal::MalformedArgs(
                    "Knockdown distinct-instance state"
                ))
            );
            assert_eq!(state, before);
            assert_eq!(events, events_before);
        }

        let mut rollback = HotState::at_defaults();
        rollback.hp = 100;
        rollback.max_hp = 100;
        rollback.history.round_number = i16::MAX;
        let mut target = HotMonster::new(MonsterKind::Toadpole, 30);
        target.misery_debuff_order.push_knockdown(2);
        rollback.monsters_mut().push(target);
        let before = rollback.clone();
        let mut events = vec![Event::TurnBegan { turn: 80 }];
        let events_before = events.clone();
        assert_eq!(
            end_player_turn(&mut rollback, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("round_number"))
        );
        assert_eq!(rollback, before);
        assert_eq!(events, events_before);
    }

    #[test]
    fn conqueror_turn_entry_refuses_malformed_live_or_dead_owner_before_publication() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        for (wire, value) in [(SlotWire::Bool, 1), (SlotWire::Int, -1)] {
            for hp in [30, 0] {
                let mut state = HotState::at_defaults();
                state.hp = 100;
                state.max_hp = 100;
                let mut monster = HotMonster::new(MonsterKind::Toadpole, hp);
                monster.uid = 19;
                monster.powers.set(PowerId::Conqueror, wire, value);
                state.monsters_mut().push(monster);
                let before = state.clone();
                let mut events = vec![Event::TurnBegan { turn: 77 }];
                let before_events = events.clone();

                assert_eq!(
                    end_player_turn(&mut state, &catalog, &mut events),
                    Err(EngineRefusal::MalformedArgs("Conqueror power state")),
                    "wire={wire:?}, value={value}, hp={hp}"
                );
                assert_eq!(state, before, "wire={wire:?}, value={value}, hp={hp}");
                assert_eq!(
                    events, before_events,
                    "wire={wire:?}, value={value}, hp={hp}"
                );
            }
        }
    }

    #[test]
    fn conqueror_turn_entry_preserves_same_and_later_owner_plating_precedence() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        for same_owner in [true, false] {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            state.max_hp = 100;

            let mut conqueror_owner = HotMonster::new(MonsterKind::Toadpole, 30);
            conqueror_owner.uid = 19;
            conqueror_owner
                .powers
                .set(PowerId::Conqueror, SlotWire::Bool, 1);
            if same_owner {
                conqueror_owner
                    .powers
                    .set(PowerId::Mplating, SlotWire::Int, 1);
            }
            state.monsters_mut().push(conqueror_owner);

            if !same_owner {
                let mut plating_owner = HotMonster::new(MonsterKind::Toadpole, 30);
                plating_owner.uid = 20;
                plating_owner
                    .powers
                    .set(PowerId::Mplating, SlotWire::Int, 1);
                state.monsters_mut().push(plating_owner);
            }

            let before = state.clone();
            let mut events = vec![Event::TurnBegan { turn: 78 }];
            let before_events = events.clone();
            assert_eq!(
                end_player_turn(&mut state, &catalog, &mut events),
                Err(EngineRefusal::MalformedArgs("monster Plating owner/state")),
                "same_owner={same_owner}"
            );
            assert_eq!(state, before, "same_owner={same_owner}");
            assert_eq!(events, before_events, "same_owner={same_owner}");
        }
    }

    #[test]
    fn conqueror_turn_entry_accepts_occupied_zero_and_expires_positive_int() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        let mut zero = HotState::at_defaults();
        zero.hp = 100;
        zero.max_hp = 100;
        let mut zero_owner = HotMonster::new(MonsterKind::Toadpole, 30);
        zero_owner.uid = 19;
        zero_owner.powers = crate::powers::Slots::from_unsorted(vec![crate::powers::Slot {
            key: PowerId::Conqueror,
            wire: SlotWire::Int,
            value: 0,
        }])
        .unwrap();
        zero.monsters_mut().push(zero_owner);
        end_player_turn(&mut zero, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(
            zero.monsters[0].powers.get(PowerId::Conqueror),
            Some(crate::powers::Slot {
                key: PowerId::Conqueror,
                wire: SlotWire::Int,
                value: 0,
            })
        );

        let mut positive = HotState::at_defaults();
        positive.hp = 100;
        positive.max_hp = 100;
        let mut positive_owner = HotMonster::new(MonsterKind::Toadpole, 30);
        positive_owner.uid = 20;
        positive_owner
            .powers
            .set(PowerId::Conqueror, SlotWire::Int, 2);
        positive_owner
            .misery_debuff_order
            .push(MiseryToken::Conqueror);
        positive.monsters_mut().push(positive_owner);
        let mut events = Vec::new();
        end_player_turn(&mut positive, &catalog, &mut events).unwrap();
        assert_eq!(positive.monsters[0].powers.value(PowerId::Conqueror), 1);
        assert!(events.iter().any(|event| {
            matches!(
                event,
                Event::PowerChanged {
                    subject: Subject::Monster(20),
                    power: PowerId::Conqueror,
                    amount: 1,
                }
            )
        }));
    }

    #[test]
    fn crimson_mantle_turn_tick_orders_self_loss_before_block_and_is_cold_when_absent() {
        let catalog = CatalogBuilder::new().build();
        let mut inactive = HotState::at_defaults();
        inactive.hp = 20;
        CRIMSON_MANTLE_TRANSACTIONS.with(|count| count.set(0));
        assert!(tick_crimson_mantle(&mut inactive, &catalog, &mut Vec::new()).unwrap());
        CRIMSON_MANTLE_TRANSACTIONS.with(|count| assert_eq!(count.get(), 0));

        let mut state = HotState::at_defaults();
        state.hp = 20;
        state.max_hp = 20;
        state.block = 2;
        state.powers.set(PowerId::CrimsonMantle, SlotWire::Int, 7);
        state.powers.set(PowerId::CrimsonSelf, SlotWire::Int, 1);
        let mut events = Vec::new();

        assert!(tick_crimson_mantle(&mut state, &catalog, &mut events).unwrap());

        assert_eq!(state.hp, 19);
        assert_eq!(state.block, 9);
        assert_eq!(
            events,
            vec![
                Event::PlayerDamaged {
                    blocked: 0,
                    hp_lost: 1,
                    hp: 19,
                },
                Event::PlayerBlockGained {
                    amount: 7,
                    block: 9,
                },
            ]
        );
        CRIMSON_MANTLE_TRANSACTIONS.with(|count| assert_eq!(count.get(), 1));
    }

    #[test]
    fn crimson_mantle_turn_tick_is_terminal_and_overflow_atomic() {
        let catalog = CatalogBuilder::new().build();
        let mut lethal = HotState::at_defaults();
        lethal.hp = 1;
        lethal.max_hp = 1;
        lethal.block = 3;
        lethal.powers.set(PowerId::CrimsonMantle, SlotWire::Int, 10);
        lethal.powers.set(PowerId::CrimsonSelf, SlotWire::Int, 1);
        let mut events = Vec::new();

        assert!(!tick_crimson_mantle(&mut lethal, &catalog, &mut events).unwrap());
        assert_eq!(lethal.hp, 0);
        assert_eq!(lethal.block, 3, "lethal self-loss suppresses Block");
        assert_eq!(
            events.last(),
            Some(&Event::CombatOver { player_won: false })
        );
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, Event::PlayerBlockGained { .. }))
        );

        let mut overflow = HotState::at_defaults();
        overflow.hp = 20;
        overflow.max_hp = 20;
        overflow.block = i32::MAX;
        overflow
            .powers
            .set(PowerId::CrimsonMantle, SlotWire::Int, 7);
        overflow.powers.set(PowerId::CrimsonSelf, SlotWire::Int, 1);
        let before = overflow.clone();
        let mut events = Vec::new();
        assert_eq!(
            tick_crimson_mantle(&mut overflow, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("player block"))
        );
        assert_eq!(overflow, before);
        assert!(events.is_empty());
    }
