    #[test]
    fn live_intent_resolver_shares_loop_random_and_forced_execution_state() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        builder.intern_monster(MonsterKind::Mawler).unwrap();
        builder
            .intern_monster(MonsterKind::CeremonialBeast)
            .unwrap();
        builder.intern_monster(MonsterKind::Ovicopter).unwrap();
        let catalog = builder.build();

        let mut state = HotState::at_defaults();
        let mut toad = HotMonster::new(MonsterKind::Toadpole, 20);
        toad.loop_pos = 1;
        state.monsters_mut().push(toad);
        assert!(monster_intends_to_attack(&state, &catalog, 0).unwrap());
        state.monsters_mut()[0].loop_pos = 2;
        assert!(!monster_intends_to_attack(&state, &catalog, 0).unwrap());

        let mut mawler = HotMonster::new(MonsterKind::Mawler, 20);
        assert!(mawler.random_ai.set_next(Some(MAWLER_RIP_INDEX)));
        state.monsters_mut()[0] = mawler;
        assert!(monster_intends_to_attack(&state, &catalog, 0).unwrap());
        assert!(
            state.monsters_mut()[0]
                .random_ai
                .set_next(Some(MAWLER_ROAR_INDEX))
        );
        assert!(!monster_intends_to_attack(&state, &catalog, 0).unwrap());

        state.monsters_mut()[0] = HotMonster::new(MonsterKind::Toadpole, 20);
        state.monsters_mut()[0].override_state = MonsterOverride::Stunned;
        assert!(!monster_intends_to_attack(&state, &catalog, 0).unwrap());
        state.monsters_mut()[0].override_state = MonsterOverride::None;
        state.monsters_mut()[0].spawn_noop = true;
        assert!(!monster_intends_to_attack(&state, &catalog, 0).unwrap());

        let mut beast = HotMonster::new(MonsterKind::CeremonialBeast, 20);
        beast.override_state = MonsterOverride::BeastStun;
        beast.forced_follow_up = MonsterFollowUp::BeastCry;
        state.monsters_mut()[0] = beast;
        assert!(!monster_intends_to_attack(&state, &catalog, 0).unwrap());
        state.monsters_mut()[0].forced_follow_up = MonsterFollowUp::None;
        assert_eq!(
            monster_intends_to_attack(&state, &catalog, 0),
            Err(EngineRefusal::MalformedArgs(
                "Ceremonial Beast stun lacks forced follow-up"
            ))
        );

        let mut ovicopter = HotMonster::new(MonsterKind::Ovicopter, 20);
        ovicopter.loop_pos = super::super::monsters::OVICOPTER_BRANCH_POS;
        state.monsters_mut()[0] = ovicopter;
        assert!(!monster_intends_to_attack(&state, &catalog, 0).unwrap());
    }

