    fn turret_operator_catalog() -> Catalog {
        let mut builder = crate::catalog::CatalogBuilder::new();
        builder.intern_monster(MonsterKind::LivingShield).unwrap();
        builder.intern_monster(MonsterKind::TurretOperator).unwrap();
        builder.build()
    }

    /// The fixed A8+ roster produced by `TurretOperatorWeak`: native max HP
    /// delegates to the tiered min getter, so the modeled pair is 65 / 51.
    fn turret_operator_pair(shield_hp: i32, operator_hp: i32) -> HotState {
        let mut state = HotState::at_defaults();
        state.hp = 1_000;
        state.max_hp = 1_000;
        state.turn = 1;
        state.player_phase = PHASE_ORDINARY_ACTIONS;
        state.player_side_active = true;
        state.exact_piles = true;

        let mut shield = HotMonster::new(MonsterKind::LivingShield, shield_hp);
        shield.max_hp = 65;
        shield.slot = 0;
        shield.uid = 0;
        if shield_hp > 0 {
            shield.powers.set(PowerId::Rampart, SlotWire::Int, 25);
        }
        let mut operator = HotMonster::new(MonsterKind::TurretOperator, operator_hp);
        operator.max_hp = 51;
        operator.slot = 1;
        operator.uid = 1;
        state.monsters_mut().extend([shield, operator]);
        state
    }

    /// Cross the same public boundary a solver caller uses both before and
    /// after `EndTurn`.  The output check is deliberately not an internal
    /// phase assertion: the fixed pair must be accepted after cold reload.
    fn public_turret_end_turn(
        state: HotState,
        catalog: &Catalog,
    ) -> (HotState, Catalog, Vec<Event>) {
        let entry = HotBoundary::try_to_canonical(&state, catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&entry).unwrap();
        let state = HotBoundary::from_canonical(&entry, &catalog).unwrap();
        crate::engine::admit(&entry, &state, &catalog).unwrap();

        let transition =
            crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn).unwrap();
        let output = HotBoundary::try_to_canonical(&transition.state, &catalog).unwrap();
        let output_catalog = HotBoundary::catalog_from_canonical(&output).unwrap();
        let reloaded = HotBoundary::from_canonical(&output, &output_catalog).unwrap();
        crate::engine::admit(&output, &reloaded, &output_catalog).unwrap();
        assert_eq!(reloaded, transition.state);
        (reloaded, output_catalog, transition.events)
    }

    #[test]
    fn living_shield_defers_slam_branch_until_after_operator_retaliation() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(65, 1);
        // The Shield's Slam completes first.  The later Operator attack is
        // killed by player Thorns, so native PrepareForNextTurn sees no ally
        // and selects Smash for the following enemy phase.
        // Rampart's Block is a player-side grant that the enemy side's own
        // block clear has already removed (#3049), so one Thorns kills the
        // one-HP Operator exactly.
        state.powers.set(PowerId::Thorns, SlotWire::Int, 1);

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(state.monsters[1].hp, 0);
        assert_eq!(state.monsters[0].loop_pos, 1);
        assert_eq!(
            state.monsters[0].forced_follow_up,
            MonsterFollowUp::None,
            "the completed-Slam receipt is internal and consumed before EndTurn returns"
        );
    }

    /// #3287 (1KJJGR1GFZR6 node 37): an Operator overkilled on the player's
    /// turn leaves a Rust corpse below zero HP. The Shield's Slam still
    /// completes, and the successor roll sees no living ally, so the next
    /// intent is SMASH (`LivingShield/<GetAllyCount>b__18_0` RVA `0xb8e0d`).
    #[test]
    fn living_shield_slams_then_smashes_after_operator_overkill() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(65, 51);
        state.monsters_mut()[1].hp = -18;
        crate::engine::damage::finish_monster_death(&mut state, 1, &mut Vec::new()).unwrap();
        assert!(!crate::engine::monsters::turret_operator_state_is_valid(
            &state
        ));
        assert!(crate::engine::monsters::turret_operator_slam_roster_is_exact(&state));

        let mut events = Vec::new();
        end_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert!(events.contains(&Event::MonsterMoved {
            uid: 0,
            kind: MoveKind::Attack,
        }));
        assert_eq!(state.monsters[0].loop_pos, 1, "no living ally: SMASH");
        assert_eq!(state.monsters[0].forced_follow_up, MonsterFollowUp::None);
    }

    #[test]
    fn living_shield_retaliation_output_is_publicly_reloadable() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(65, 1);
        state.powers.set(PowerId::Thorns, SlotWire::Int, 1);

        let (state, _, events) = public_turret_end_turn(state, &catalog);

        assert!(events.contains(&Event::MonsterMoved {
            uid: 0,
            kind: MoveKind::Attack,
        }));
        assert_eq!(state.monsters[1].hp, 0);
        assert_eq!(state.monsters[0].loop_pos, 1);
        assert_eq!(state.monsters[0].forced_follow_up, MonsterFollowUp::None);
    }

    #[test]
    fn turret_operator_pair_cycles_two_unloads_reload_then_smash_after_clean_death() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(65, 51);

        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(
            (state.monsters[0].loop_pos, state.monsters[1].loop_pos),
            (0, 1)
        );
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(
            (state.monsters[0].loop_pos, state.monsters[1].loop_pos),
            (0, 2)
        );
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.monsters[1].loop_pos, 0);
        assert_eq!(state.monsters[1].powers.value(PowerId::Strength), 1);

        state.monsters_mut()[1].hp = 0;
        crate::engine::damage::finish_monster_death(&mut state, 1, &mut Vec::new()).unwrap();
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.monsters[0].loop_pos, 1);
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(
            state.monsters[0].loop_pos, 1,
            "SMASH remains its fixed successor"
        );
        assert_eq!(state.monsters[0].powers.value(PowerId::Strength), 3);
    }

    #[test]
    fn turret_operator_loop_and_rampart_poison_order_follow_native_phase_boundaries() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(1, 51);
        // Preserve the actual Poison instance metadata rather than forging a
        // scalar slot. The enemy-side Poison tick kills Rampart's owner and
        // ordinary death cleanup clears Rampart, so the next player side
        // start grants the Operator nothing (#3049).
        crate::engine::damage::apply_power_monster_debuff(
            &mut state,
            0,
            PowerId::Poison,
            MiseryToken::Poison,
            1,
            &mut Vec::new(),
        )
        .unwrap();

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(state.monsters[0].hp, 0);
        assert_eq!(state.monsters[0].powers.value(PowerId::Rampart), 0);
        assert_eq!(state.monsters[1].block, 0);
        assert_eq!(
            state.monsters[1].loop_pos, 1,
            "Operator still completes 4x5"
        );
    }

