    #[test]
    fn rampart_skips_extra_player_turns_and_a_player_killed_shield_never_grants_again() {
        let mut builder = crate::catalog::CatalogBuilder::new();
        builder.intern_monster(MonsterKind::LivingShield).unwrap();
        builder.intern_monster(MonsterKind::TurretOperator).unwrap();
        builder.set_relics(&[RelicId::RelicPaelsEye]).unwrap();
        let catalog = builder.build();
        let mut extra = turret_operator_pair(65, 51);
        extra.history.round_number = 2;
        extra
            .fanouts
            .set_paels_eye_was_owner_part_last_player_turn(true);

        end_player_turn(&mut extra, &catalog, &mut Vec::new()).unwrap();
        // `RampartPower/<AfterSideTurnStart>d__6` IL_002b-003d: the extra
        // player turn's side start grants nothing.
        assert_eq!(extra.monsters[1].block, 0);
        assert!(extra.player_side_active);
        assert!(extra.fanouts.paels_eye_used());
        assert!(extra.fanouts.players_taking_extra_turn());
        assert_eq!((extra.turn, extra.history.round_number), (2, 2));
        // The flag is public state: an extra turn parked at a player action
        // must reload as an extra turn, and it cannot exist without Pael's
        // Eye having been spent.
        let entry = HotBoundary::try_to_canonical(&extra, &catalog).unwrap();
        assert_eq!(
            entry.player.get("players_taking_extra_turn"),
            Some(&serde_json::Value::Bool(true))
        );
        let entry_catalog = HotBoundary::catalog_from_canonical(&entry).unwrap();
        let reloaded = HotBoundary::from_canonical(&entry, &entry_catalog).unwrap();
        assert!(reloaded.fanouts.players_taking_extra_turn());
        let mut forged = extra.clone();
        forged.fanouts.set_paels_eye_used(false);
        assert!(HotBoundary::try_to_canonical(&forged, &catalog).is_err());

        // The extra turn's end clears PlayersTakingExtraTurn, and the next
        // ordinary player side start grants again.
        end_player_turn(&mut extra, &catalog, &mut Vec::new()).unwrap();
        assert!(!extra.fanouts.players_taking_extra_turn());
        assert!(extra.player_side_active);
        assert_eq!((extra.turn, extra.history.round_number), (3, 3));
        assert_eq!(extra.monsters[1].block, 25);

        let plain_catalog = turret_operator_catalog();
        let mut dead_before_side_start = turret_operator_pair(1, 51);
        crate::engine::damage::damage_monster(
            &mut dead_before_side_start,
            0,
            crate::decimal::DotNetDecimal::from_i64(1),
            false,
            false,
            &mut Vec::new(),
        )
        .unwrap();
        end_player_turn(&mut dead_before_side_start, &plain_catalog, &mut Vec::new()).unwrap();
        assert_eq!(dead_before_side_start.monsters[0].hp, 0);
        assert_eq!(
            dead_before_side_start.monsters[0]
                .powers
                .value(PowerId::Rampart),
            0
        );
        assert_eq!(dead_before_side_start.monsters[1].block, 0);
    }

    /// #3049: `RampartPower/<AfterSideTurnStart>d__6` (RVA `0x3416a0`)
    /// proceeds only for `side == Player` (IL_001e-0024). The grant lands at
    /// the player side start that follows the enemy phase, and the enemy side
    /// start's own block clear is what removes it.
    #[test]
    fn rampart_grants_at_player_side_start_and_the_enemy_side_clears_it() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(65, 51);
        state.monsters_mut()[1].block = 25;

        let (state, catalog, _) = public_turret_end_turn(state, &catalog);
        assert!(state.player_side_active);
        assert_eq!(state.turn, 2);
        assert!(!state.fanouts.players_taking_extra_turn());
        assert_eq!(state.monsters[1].block, 25, "one fresh grant, not 50");
        assert_eq!(state.monsters[0].block, 0, "the Shield itself gets none");

        // The Operator's block during the enemy phase is observable through
        // player Thorns: the grant is gone before the Operator attacks.
        let mut thorny = state;
        thorny.monsters_mut()[1].hp = 1;
        thorny.powers.set(PowerId::Thorns, SlotWire::Int, 1);
        end_player_turn(&mut thorny, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(thorny.monsters[1].hp, 0);
        assert_eq!(thorny.monsters[1].block, 0, "a dead Operator gains nothing");
    }

    /// #3049: the grant fires on turn one too, from the opening's own player
    /// side start.
    #[test]
    fn rampart_grants_on_the_turn_one_player_side_start() {
        let catalog = turret_operator_catalog();
        let mut state = turret_operator_pair(65, 51);
        state.player_phase = 0;
        begin_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.turn, 1);
        assert_eq!(state.monsters[1].block, 25);
        assert_eq!(state.monsters[0].block, 0);
    }

    #[test]
    fn pair_turn_can_park_at_nested_foregone_stratagem_without_leaking_slam_receipt() {
        let foregone = CardIdentity {
            id: CardId::ForegoneConclusion,
            upgrade: 0,
            enchantment: None,
        };
        let mut builder = crate::catalog::CatalogBuilder::new();
        let atom = builder.intern(foregone).unwrap();
        builder.intern_monster(MonsterKind::LivingShield).unwrap();
        builder.intern_monster(MonsterKind::TurretOperator).unwrap();
        builder.mark_live_stratagem_reachable();
        let catalog = builder.build();
        let mut state = turret_operator_pair(65, 51);
        state.next_card_uid = 300;
        state.powers.set(PowerId::Foregone, SlotWire::Int, 2);
        state.powers.set(PowerId::Stratagem, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::Foregone])
        );
        state
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .extend((0..4).map(|offset| crate::hot::HotCard {
                uid: 100 + offset,
                atom,
                flags: 0,
            }));

        let entry = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&entry).unwrap();
        let state = HotBoundary::from_canonical(&entry, &catalog).unwrap();
        crate::engine::admit(&entry, &state, &catalog).unwrap();
        let parked = crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn)
            .unwrap()
            .state;
        assert!(
            parked
                .pending
                .as_deref()
                .is_some_and(|pending| { pending.stratagem_draw_record(&parked.frames).is_some() })
        );
        assert_eq!(parked.monsters[0].forced_follow_up, MonsterFollowUp::None);

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let reloaded_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let reloaded = HotBoundary::from_canonical(&wire, &reloaded_catalog).unwrap();
        crate::engine::admit(&wire, &reloaded, &reloaded_catalog).unwrap();
        assert_eq!(reloaded, parked);
        assert_eq!(reloaded.monsters[0].forced_follow_up, MonsterFollowUp::None);

        let after_stratagem = crate::engine::apply_action(
            &reloaded,
            &reloaded_catalog,
            &crate::engine::Action::Select {
                answer: crate::engine::SelectionAnswer::OptionIndex(0),
            },
        )
        .unwrap()
        .state;
        assert!(after_stratagem.pending.as_deref().is_some_and(|pending| {
            pending
                .foregone_before_hand_draw_record(&after_stratagem.frames)
                .is_some()
        }));
        assert_eq!(
            after_stratagem.monsters[0].forced_follow_up,
            MonsterFollowUp::None
        );

        let wire = HotBoundary::try_to_canonical(&after_stratagem, &reloaded_catalog).unwrap();
        let final_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let final_reload = HotBoundary::from_canonical(&wire, &final_catalog).unwrap();
        crate::engine::admit(&wire, &final_reload, &final_catalog).unwrap();
        assert_eq!(final_reload, after_stratagem);

        let stable = crate::engine::apply_action(
            &final_reload,
            &final_catalog,
            &crate::engine::Action::Select {
                answer: crate::engine::SelectionAnswer::OptionIndex(0),
            },
        )
        .unwrap()
        .state;
        assert!(stable.pending.is_none());
        assert!(stable.frames.is_empty());
        assert_eq!(stable.monsters[0].forced_follow_up, MonsterFollowUp::None);
    }

    #[test]
    fn turret_pair_cold_boundary_admits_only_stable_receipt_free_state() {
        let catalog = turret_operator_catalog();
        let state = turret_operator_pair(65, 51);
        let wire = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();

        let mut forged = state;
        forged.monsters_mut()[0].forced_follow_up = MonsterFollowUp::LivingShieldSlam;
        let wire = HotBoundary::try_to_canonical(&forged, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        let refusal = crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap_err();
        assert!(
            refusal.contains(crate::engine::MissingCapability::ArgumentShape(
                "Turret Operator roster lifecycle"
            ))
        );
        assert!(
            refusal.contains(crate::engine::MissingCapability::ArgumentShape(
                "monster override"
            ))
        );
    }

