    #[test]
    fn queen_burn_bright_public_smoke_runs_ordinary_dispatch_atomically() {
        let catalog = queen_catalog();
        let state = queen_roster_for_turn(super::super::monsters::TORCH_HEAD_AMALGAM_HP, 2);
        let mut events = Vec::new();
        let successor = queen_burn_bright_smoke(&state, &catalog, &mut events).unwrap();
        assert_eq!(successor.monsters[0].powers.value(PowerId::Strength), 1);
        assert_eq!(successor.monsters[1].block, 20);
        assert_eq!(successor.monsters[1].loop_pos, 2);
        assert!(matches!(
            events.first(),
            Some(Event::MonsterMoved {
                uid: 1,
                kind: MoveKind::QueenBurnBright,
            })
        ));

        let mut malformed = state.clone();
        malformed.monsters_mut()[0].uid = 7;
        let before_events = events.clone();
        assert_eq!(
            queen_burn_bright_smoke(&malformed, &catalog, &mut events),
            Err(EngineRefusal::MalformedArgs(
                "Queen Burn Bright smoke state"
            ))
        );
        assert_eq!(events, before_events);
        assert_eq!(malformed.monsters[0].powers.value(PowerId::Strength), 0);

        let mut unsafe_successor = state;
        unsafe_successor.monsters_mut()[0].powers.set(
            PowerId::Strength,
            SlotWire::Int,
            i32::MAX - 1,
        );
        unsafe_successor.monsters_mut()[0]
            .powers
            .set(PowerId::TempStrength, SlotWire::Int, -1);
        let before = unsafe_successor.clone();
        let before_events = events.clone();
        assert_eq!(
            queen_burn_bright_smoke(&unsafe_successor, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("monster strength"))
        );
        assert_eq!(unsafe_successor, before);
        assert_eq!(events, before_events);
    }

