    #[test]
    fn queen_puppet_strings_runs_through_the_ordinary_enemy_phase() {
        let catalog = queen_catalog();
        let mut state = queen_roster_for_turn(super::super::monsters::TORCH_HEAD_AMALGAM_HP, 0);
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(state.powers.value(PowerId::ChainsOfBinding), 3);
        assert_eq!(
            state.fanouts.after_card_drawn_order(),
            &[PowerId::ChainsOfBinding]
        );
        assert_eq!(
            state.fanouts.before_side_turn_end_order(),
            &[BeforeSideTurnEndToken::ChainsOfBinding]
        );
        assert_eq!(state.bound_afflictions_this_turn(), 0);
        assert!(!state.bound_card_played());
        assert!(super::super::cards::chains_power_state_is_exact(&state));

        let canonical = crate::boundary::HotBoundary::to_canonical(&state, &catalog);
        assert_eq!(boundary_gate::admit(&canonical, &state, &catalog), Ok(()));
        let mut impossible_loop_zero = state.clone();
        impossible_loop_zero.monsters_mut()[1].loop_pos = 0;
        let forged = crate::boundary::HotBoundary::to_canonical(&impossible_loop_zero, &catalog);
        assert!(boundary_gate::admit(&forged, &impossible_loop_zero, &catalog).is_err());
    }

