        assert_eq!(normal.monsters[0].powers.value(PowerId::Sandpit), 3);
        assert_eq!(normal.monsters[0].loop_pos, 2);
        assert!(normal.hp < 100);

        let mut terminal = HotState::at_defaults();
        terminal.hp = 100;
        terminal.max_hp = 100;
        terminal.block = 999;
