    #[test]
    fn poison_side_turn_refuses_identity_and_listener_forgery_before_public_prefix() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let base = || {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.max_hp = 50;
            state.next_poison_uid = 1;
            let mut monster = HotMonster::new(MonsterKind::Toadpole, 30);
            monster.max_hp = 30;
            monster.override_state = MonsterOverride::Stunned;
            monster.powers.set(PowerId::Poison, SlotWire::Int, 4);
            monster.poison_uid = 0;
            monster.misery_debuff_order.push(MiseryToken::Poison);
            state.monsters_mut().push(monster);
            state
        };
        let refuse = |mut state: HotState| {
            let before = state.clone();
            let mut events = vec![Event::TurnBegan { turn: 51 }];
            let before_events = events.clone();
            assert!(end_player_turn(&mut state, &catalog, &mut events).is_err());
            assert_eq!(state, before);
            assert_eq!(events, before_events);
        };

        let mut future = base();
        future.next_poison_uid = 0;
        refuse(future);

        let mut duplicate = base();
        let mut second = duplicate.monsters[0].clone();
        second.slot = 1;
        second.uid = 1;
        duplicate.monsters_mut().push(second);
        refuse(duplicate);

        let mut listeners = base();
        listeners
            .powers
            .set(PowerId::SleightOfFlesh, SlotWire::Int, 1);
        assert!(listeners.fanouts.set_after_power_amount_changed_order(&[
            PowerId::SleightOfFlesh,
            PowerId::SleightOfFlesh,
        ]));
        refuse(listeners);
    }

    #[test]
    fn sic_em_and_strangle_expire_after_owner_act_and_terminal_act_preserves_them() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        let mut ordinary = HotState::at_defaults();
        ordinary.hp = 100;
        ordinary.max_hp = 100;
        let mut target = HotMonster::new(MonsterKind::Toadpole, 20);
        target.powers.set(PowerId::SicEm, SlotWire::Int, 3);
        target.powers.set(PowerId::Strangle, SlotWire::Int, 2);
        target.misery_debuff_order.push(MiseryToken::SicEm);
        target.misery_debuff_order.push(MiseryToken::Strangle);
        ordinary.monsters_mut().push(target);
        let mut events = Vec::new();
        end_player_turn(&mut ordinary, &catalog, &mut events).unwrap();
        let attack = events
            .iter()
            .position(|event| matches!(event, Event::PlayerDamaged { .. }))
            .expect("Toadpole ACT must publish damage before owner-side expiry");
        let expiry = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::PowerChanged {
                        subject: Subject::Monster(_),
                        power: PowerId::SicEm,
                        amount: 0,
                    }
                )
            })
            .expect("live owner removes Sic Em after ACT");
        assert!(attack < expiry);
        assert_eq!(ordinary.monsters[0].powers.value(PowerId::SicEm), 0);
        assert_eq!(ordinary.monsters[0].powers.value(PowerId::Strangle), 0);
        assert!(ordinary.monsters[0].misery_debuff_order.is_empty());

        let mut terminal = HotState::at_defaults();
        terminal.hp = 1;
        terminal.max_hp = 1;
        let mut target = HotMonster::new(MonsterKind::Toadpole, 20);
        target.powers.set(PowerId::SicEm, SlotWire::Int, 3);
        target.powers.set(PowerId::Strangle, SlotWire::Int, 2);
        target.misery_debuff_order.push(MiseryToken::SicEm);
        target.misery_debuff_order.push(MiseryToken::Strangle);
        terminal.monsters_mut().push(target);
        end_player_turn(&mut terminal, &catalog, &mut Vec::new()).unwrap();
        assert!(terminal.history.over);
        assert_eq!(terminal.monsters[0].powers.value(PowerId::SicEm), 3);
        assert_eq!(terminal.monsters[0].powers.value(PowerId::Strangle), 2);
        assert_eq!(
            terminal.monsters[0].misery_debuff_order.as_slice(),
            &[MiseryToken::SicEm, MiseryToken::Strangle],
            "terminal ACT suppresses the whole owner-power suffix"
        );
    }

