    /// #2809: `PlatingPower/<AfterSideTurnStart>d__14` (`0x340584`) skips the
    /// enemy owner's round-one decrement; `<BeforeSideTurnEndEarly>d__13`
    /// (`0x340754`) grants the live amount at every enemy side end. So the
    /// side-start clear leaves 0, the side end restores 19 for round two's
    /// player turn, and round two decrements before its own side-end grant.
    #[test]
    fn monster_plating_blocks_at_side_end_and_decrements_from_round_two() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::FrogKnight).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 999;
        state.max_hp = 999;
        let mut frog = frog_for_turn(199, 0, false);
        frog.block = 31;
        frog.powers.set(PowerId::Mplating, SlotWire::Int, 19);
        state.monsters_mut().push(frog);

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.history.round_number, 2);
        assert_eq!(state.monsters[0].powers.value(PowerId::Mplating), 19);
        assert_eq!(
            state.monsters[0].block, 19,
            "cleared at the side start, then the side-end grant; round two's \
             player-side start grants nothing"
        );
        assert!(super::super::monsters::frog_knight_state_is_valid(&state));

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.history.round_number, 3);
        assert_eq!(state.monsters[0].powers.value(PowerId::Mplating), 18);
        assert_eq!(state.monsters[0].block, 18);
        assert!(super::super::monsters::frog_knight_state_is_valid(&state));
    }

    /// #2809: `PlatingPower::BeforeSideTurnStart` (`0xa5b9c`) grants a monster
    /// owner its Plating at the player side's start only while
    /// `RoundNumber <= 1`. Lagavulin Matriarch (Plating 12) opens with Block
    /// 12 natively (`YLVVPKPH1MTW` floor 17's first checkpoint).
    #[test]
    fn monster_plating_grants_block_at_the_round_one_player_side_start_only() {
        let mut builder = CatalogBuilder::new();
        builder
            .intern_monster(MonsterKind::LagavulinMatriarch)
            .unwrap();
        let catalog = builder.build();
        let lagavulin = || {
            let mut monster = HotMonster::new(MonsterKind::LagavulinMatriarch, 233);
            monster.max_hp = 233;
            monster.powers.set(PowerId::Mplating, SlotWire::Int, 12);
            monster.powers.set(PowerId::Asleep, SlotWire::Int, 3);
            monster
        };

        let mut opening = HotState::at_defaults();
        opening.monsters_mut().push(lagavulin());
        assert_eq!(opening.history.round_number, 1);
        crate::engine::deal_opening_hand(&mut opening, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(opening.monsters[0].block, 12);
        assert_eq!(opening.monsters[0].powers.value(PowerId::Mplating), 12);

        // A second round-one player-side start (Pael's Eye keeps RoundNumber)
        // grants again; a round-two one does not.
        begin_player_turn(&mut opening, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(opening.monsters[0].block, 24);

        let mut later = HotState::at_defaults();
        later.history.round_number = 2;
        later.turn = 2;
        later.monsters_mut().push(lagavulin());
        begin_player_turn(&mut later, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(later.monsters[0].block, 0);

        // A dead owner holds no live Plating listener.
        let mut corpse = HotState::at_defaults();
        let mut dead = lagavulin();
        dead.hp = 0;
        corpse.monsters_mut().push(dead);
        crate::engine::deal_opening_hand(&mut corpse, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(corpse.monsters[0].block, 0);
    }

