    /// #2814: `AsleepPower` is applied only by
    /// `LagavulinMatriarch/<Sleep>d__40` (`0x3613b8` `IL_0131`) and removed
    /// with its owner's death, so the ported sleeping side covers a living
    /// Matriarch only. Any other carrier refuses before the turn end
    /// publishes anything.
    #[test]
    fn asleep_outside_a_living_matriarch_refuses_before_publication() {
        let mut builder = CatalogBuilder::new();
        builder
            .intern_monster(MonsterKind::LagavulinMatriarch)
            .unwrap();
        builder.intern_monster(MonsterKind::Axebot).unwrap();
        let catalog = builder.build();
        let mut corpse = HotMonster::new(MonsterKind::LagavulinMatriarch, 0);
        corpse.max_hp = 233;
        for mut carrier in [corpse, HotMonster::new(MonsterKind::Axebot, 86)] {
            carrier.powers.set(PowerId::Asleep, SlotWire::Int, 2);
            let mut state = HotState::at_defaults();
            state.hp = 999;
            state.max_hp = 999;
            state.monsters_mut().push(carrier);
            let before = state.clone();
            let mut events = Vec::new();
            assert_eq!(
                end_player_turn(&mut state, &catalog, &mut events),
                Err(EngineRefusal::MalformedArgs("Asleep owner/state"))
            );
            assert_eq!(state, before);
            assert!(events.is_empty());
        }
    }

