    fn fabricator_for_turn(intent: u8) -> HotMonster {
        let mut owner = HotMonster::new(MonsterKind::Fabricator, 155);
        owner.max_hp = 155;
        owner.slot = 2;
        assert!(owner.random_ai.set_next(Some(intent)));
        assert!(owner.random_ai.set_log(&[intent]));
        owner
    }

    fn rat_for_turn(position: usize, intent: u8, tus: i32) -> HotMonster {
        let mut rat = HotMonster::new(MonsterKind::TwoTailedRat, 18 + position as i32);
        rat.max_hp = rat.hp;
        rat.slot = position as i32;
        rat.uid = position as u32;
        rat.set_rat_turns_until_summonable(tus);
        assert!(rat.random_ai.set_next(Some(intent)));
        assert!(rat.random_ai.set_log(&[intent]));
        rat
    }

    #[test]
    fn fabricator_conditional_follow_pins_draw_and_no_draw_paths() {
        let mut state = HotState::at_defaults();
        let mut owner = fabricator_for_turn(super::super::monsters::FABRICATOR_FABRICATE_INDEX);
        owner.last_spawned = Some(MonsterKind::Zapbot);
        state.monsters_mut().push(owner);
        let seeded = Xoshiro256StarStar::from_seed(7);
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        roll_fabricator_intent(&mut state, 0).unwrap();
        assert_eq!(state.rng.get(RngStream::Ai).counter, 1);
        // CanRepeatForever (#2945): the draw is NextFloat(2.0) whatever the
        // last move was, FABRICATE on `<= 1`.
        let expected = if Xoshiro256StarStar::from_seed(7).next_float(2.0) <= 1.0 {
            super::super::monsters::FABRICATOR_FABRICATE_INDEX
        } else {
            super::super::monsters::FABRICATOR_STRIKE_INDEX
        };
        assert_eq!(state.monsters[0].random_ai.next(), Some(expected));
        assert_eq!(state.monsters[0].random_ai.log_len(), 2);
        assert!(super::super::monsters::fabricator_prepare_state_is_valid(
            &state
        ));

        for (slot, kind) in [
            (0, MonsterKind::Guardbot),
            (1, MonsterKind::Noisebot),
            (3, MonsterKind::Stabbot),
        ] {
            let mut bot = HotMonster::new(kind, 20);
            bot.max_hp = 20;
            bot.slot = slot;
            bot.uid = (slot + 1) as u32;
            bot.powers.set(PowerId::Secondary, SlotWire::Bool, 1);
            state.monsters_mut().push(bot);
        }
        state.monsters_mut().sort_by_key(|monster| monster.slot);
        let owner_index = state
            .monsters
            .iter()
            .position(|monster| monster.kind == MonsterKind::Fabricator)
            .unwrap();
        let before = state.rng.get(RngStream::Ai).counter;
        roll_fabricator_intent(&mut state, owner_index).unwrap();
        assert_eq!(state.rng.get(RngStream::Ai).counter, before);
        assert_eq!(
            state.monsters[owner_index].random_ai.next(),
            Some(super::super::monsters::FABRICATOR_DISINTEGRATE_INDEX)
        );
    }

    /// #2945: Fabricator's `RAND` branches are `CanRepeatForever` with weight
    /// 1.0 each (`Fabricator::GenerateMoveStateMachine` `0xb3bc0` IL_00a4 /
    /// IL_00cc, `AddBranch` `0x7925a`; `GetStateWeight` `0x79380` IL_0098).
    /// After either logged `RAND` move the roll is `NextFloat(2.0)` and the
    /// logged move itself can be selected again; the repeated log validates.
    #[test]
    fn fabricator_rand_can_repeat_either_move_after_it_is_logged() {
        use super::super::monsters::{
            FABRICATOR_FABRICATE_INDEX, FABRICATOR_STRIKE_INDEX, fabricator_ai_state_is_valid,
            fabricator_prepare_state_is_valid,
        };
        let mut repeated = [false; 2];
        for last in [FABRICATOR_FABRICATE_INDEX, FABRICATOR_STRIKE_INDEX] {
            for seed in 0..64u64 {
                let mut state = HotState::at_defaults();
                let mut owner = fabricator_for_turn(last);
                owner.last_spawned = Some(MonsterKind::Zapbot);
                state.monsters_mut().push(owner);
                let seeded = Xoshiro256StarStar::from_seed(seed);
                state.rng.set(
                    RngStream::Ai,
                    RngStreamState {
                        words: seeded.words,
                        counter: seeded.counter,
                    },
                );
                roll_fabricator_intent(&mut state, 0).unwrap();
                assert_eq!(state.rng.get(RngStream::Ai).counter, 1);
                let roll = Xoshiro256StarStar::from_seed(seed).next_float(2.0);
                let expected = if roll <= 1.0 {
                    FABRICATOR_FABRICATE_INDEX
                } else {
                    FABRICATOR_STRIKE_INDEX
                };
                let owner = &state.monsters[0];
                assert_eq!(owner.random_ai.next(), Some(expected), "seed {seed}");
                assert_eq!(owner.random_ai.log_len(), 2);
                assert_eq!(owner.random_ai.log_at(0), Some(last));
                assert_eq!(owner.random_ai.log_at(1), Some(expected));
                assert!(fabricator_prepare_state_is_valid(&state));
                // The committed (non-transient) validator admits the repeat
                // too, with the aggro bot the preceding move spawned.
                assert!(fabricator_ai_state_is_valid(owner, false));
                if expected == last {
                    repeated[last as usize] = true;
                }
            }
        }
        assert_eq!(
            repeated,
            [true, true],
            "both RAND moves must be able to repeat"
        );
    }

