    #[test]
    fn ritual_skips_its_application_side_end_then_grows_after_temp_strength_cleanup() {
        let mut builder = CatalogBuilder::new();
        builder
            .intern_monster(MonsterKind::CalcifiedCultist)
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        let mut cultist = HotMonster::new(MonsterKind::CalcifiedCultist, 60);
        cultist.max_hp = 60;
        cultist.uid = 11;
        state.monsters_mut().push(cultist);

        let mut first_events = Vec::new();
        run_enemy_phase(&mut state, &catalog, &mut first_events).unwrap();
        assert_eq!(state.monsters[0].powers.value(PowerId::Ritual), 2);
        assert!(!state.monsters[0].ritual_fresh);
        assert_eq!(state.monsters[0].powers.value(PowerId::Strength), 0);
        assert!(!first_events.iter().any(|event| matches!(
            event,
            Event::PowerChanged {
                power: PowerId::Strength,
                ..
            }
        )));

        state.monsters_mut()[0]
            .powers
            .set(PowerId::Strength, SlotWire::Int, 5);
        state.monsters_mut()[0]
            .powers
            .set(PowerId::TempStrength, SlotWire::Int, -3);
        let mut second_events = Vec::new();
        run_enemy_phase(&mut state, &catalog, &mut second_events).unwrap();
        assert_eq!(state.monsters[0].powers.value(PowerId::TempStrength), 0);
        assert_eq!(state.monsters[0].powers.value(PowerId::Strength), 10);
        assert!(second_events.contains(&Event::PowerChanged {
            subject: Subject::Monster(11),
            power: PowerId::Strength,
            amount: 10,
        }));
    }

