    #[test]
    fn attack_strength_rereads_ceremonial_beast_after_thorns_triggers_plow() {
        let mut builder = CatalogBuilder::new();
        builder
            .intern_monster(MonsterKind::CeremonialBeast)
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        state.max_hp = 100;
        state.block = i32::MAX;
        state.powers.set(PowerId::Thorns, SlotWire::Int, 1);
        let mut beast = HotMonster::new(MonsterKind::CeremonialBeast, 161);
        beast.max_hp = 262;
        beast.loop_pos = 1;
        beast.powers.set(PowerId::PlowThreshold, SlotWire::Int, 160);
        beast
            .powers
            .set(PowerId::Strength, SlotWire::Int, i32::MAX - 1);
        state.monsters_mut().push(beast);
        assert!(monster_strength_move_transaction_needed(&state, &catalog));

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();

        let beast = &state.monsters[0];
        assert_eq!(beast.hp, 160);
        assert_eq!(beast.powers.value(PowerId::PlowThreshold), 0);
        assert_eq!(beast.powers.value(PowerId::TempStrength), 0);
        assert_eq!(beast.powers.value(PowerId::Strength), 2);
        assert_eq!(beast.override_state, MonsterOverride::BeastStun);
        assert_eq!(beast.forced_follow_up, MonsterFollowUp::BeastCry);

        // One point above the threshold, retaliation does not fire Plow. The
        // same live post-attack read therefore overflows, and the public
        // strength-move COW restores the entire attack and event prefix.
        let mut refused = HotState::at_defaults();
        refused.hp = 100;
        refused.max_hp = 100;
        refused.block = i32::MAX;
        refused.powers.set(PowerId::Thorns, SlotWire::Int, 1);
        let mut beast = HotMonster::new(MonsterKind::CeremonialBeast, 162);
        beast.max_hp = 262;
        beast.loop_pos = 1;
        beast.powers.set(PowerId::PlowThreshold, SlotWire::Int, 160);
        beast
            .powers
            .set(PowerId::Strength, SlotWire::Int, i32::MAX - 1);
        refused.monsters_mut().push(beast);
        let before = refused.clone();
        let mut events = vec![Event::TurnBegan { turn: 100 }];
        let before_events = events.clone();
        assert_eq!(
            end_player_turn(&mut refused, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("attack_strength Strength"))
        );
        assert_eq!(refused, before);
        assert_eq!(events, before_events);
    }

    #[test]
    fn fixed_loop_branches_consume_one_ai_draw_and_skip_the_generic_tail() {
        let seeded = Xoshiro256StarStar::from_seed(0);

        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Fogmog).unwrap();
        let catalog = builder.build();
        let mut fogmog_state = HotState::at_defaults();
        fogmog_state.hp = 100;
        let mut fogmog = HotMonster::new(MonsterKind::Fogmog, 78);
        fogmog.loop_pos = 1;
        fogmog_state.monsters_mut().push(fogmog);
        fogmog_state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        let mut events = Vec::new();

        monster_act(&mut fogmog_state, &catalog, 0, &mut events).unwrap();

        assert_eq!(fogmog_state.hp, 91);
        assert_eq!(fogmog_state.rng.get(RngStream::Ai).counter, 1);
        assert_eq!(fogmog_state.monsters[0].loop_pos, 3);
        assert_eq!(fogmog_state.monsters[0].powers.value(PowerId::Strength), 1);

        // The third independent seed-0 draw lands below the binary32 0.4
        // boundary and therefore pins the other Fogmog branch as well.
        let mut low_seeded = Xoshiro256StarStar::from_seed(0);
        let _ = low_seeded.next_float(1.0);
        let _ = low_seeded.next_float(1.0);
        let mut low_state = HotState::at_defaults();
        low_state.hp = 100;
        let mut low_fogmog = HotMonster::new(MonsterKind::Fogmog, 78);
        low_fogmog.loop_pos = 1;
        low_state.monsters_mut().push(low_fogmog);
        low_state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: low_seeded.words,
                counter: low_seeded.counter,
            },
        );
        monster_act(&mut low_state, &catalog, 0, &mut events).unwrap();
        assert_eq!(low_state.rng.get(RngStream::Ai).counter, 3);
        assert_eq!(low_state.monsters[0].loop_pos, 2);

        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::ScrollOfBiting).unwrap();
        let catalog = builder.build();
        let scroll_fixture = |rng: &Xoshiro256StarStar| {
            let mut scroll_state = HotState::at_defaults();
            scroll_state.hp = 100;
            let mut scroll = HotMonster::new(MonsterKind::ScrollOfBiting, 49);
            scroll.loop_pos = 1;
            scroll_state.monsters_mut().push(scroll);
            scroll_state.rng.set(
                RngStream::Ai,
                RngStreamState {
                    words: rng.words,
                    counter: rng.counter,
                },
            );
            scroll_state
        };
        // #3026: post-CHEW `rand` is CHOMP (CannotRepeat) + CHEW
        // (`maxRepeats = 2`), both weight 1, so the draw is `NextFloat(2.0f)`.
        // Pick a seed whose draw lands in CHOMP's window.
        let chomp_seed = (0_u64..64)
            .find(|seed| {
                let draw = Xoshiro256StarStar::from_seed(*seed).next_float(2.0);
                draw - 1.0 <= 0.0 && draw > 0.5
            })
            .expect("a CHOMP draw that NextFloat(1.0) would not reproduce");
        let chomp = Xoshiro256StarStar::from_seed(chomp_seed);
        let mut scroll_state = scroll_fixture(&chomp);

        // #3304: CHEW itself draws nothing and stays parked on CHEW; the
        // `rand` traversal waits for PrepareForNextTurn.
        monster_act(&mut scroll_state, &catalog, 0, &mut events).unwrap();
        assert_eq!(scroll_state.hp, 88);
        assert_eq!(scroll_state.rng.get(RngStream::Ai).counter, 0);
        assert_eq!(scroll_state.monsters[0].loop_pos, 1);
        assert!(scroll_state.monsters[0].scroll_branch_pending());
        prepare_random_ai(&mut scroll_state, &catalog).unwrap();
        assert!(!scroll_state.monsters[0].scroll_branch_pending());

        assert_eq!(scroll_state.rng.get(RngStream::Ai).counter, 1);
        let mut expected = chomp;
        expected.next_double();
        assert_eq!(scroll_state.rng.get(RngStream::Ai).words, expected.words);
        assert_eq!(scroll_state.monsters[0].loop_pos, 0);
        assert!(!scroll_state.monsters[0].scroll_chew_repeated());

        // Seed 0 draws 1.2025 of 2.0: CHEW's window. CHEW repeats once and
        // the latch records that its two trailing StateLog entries are CHEW.
        let mut chew_state = scroll_fixture(&seeded);
        monster_act(&mut chew_state, &catalog, 0, &mut events).unwrap();
        prepare_random_ai(&mut chew_state, &catalog).unwrap();
        assert_eq!(chew_state.hp, 88);
        assert_eq!(chew_state.rng.get(RngStream::Ai).counter, 1);
        assert_eq!(chew_state.monsters[0].loop_pos, 1);
        assert!(chew_state.monsters[0].scroll_chew_repeated());

        // The repeated CHEW's own traversal has CHEW at weight 0: one
        // `NextFloat(1.0f)`, CHOMP whatever the draw, latch cleared.
        let second = chew_state.rng.get(RngStream::Ai);
        let mut second_rng = Xoshiro256StarStar {
            words: second.words,
            counter: second.counter,
        };
        assert!(
            {
                let mut peek = second_rng;
                peek.next_float(2.0)
            } > 1.0,
            "this draw would select CHEW again over a total of 2"
        );
        monster_act(&mut chew_state, &catalog, 0, &mut events).unwrap();
        assert_eq!(chew_state.rng.get(RngStream::Ai).counter, 1);
        prepare_random_ai(&mut chew_state, &catalog).unwrap();
        assert_eq!(chew_state.hp, 76);
        second_rng.next_double();
        assert_eq!(chew_state.rng.get(RngStream::Ai).words, second_rng.words);
        assert_eq!(chew_state.rng.get(RngStream::Ai).counter, 2);
        assert_eq!(chew_state.monsters[0].loop_pos, 0);
        assert!(!chew_state.monsters[0].scroll_chew_repeated());
    }

    /// #3304 (9U27KAL35CJY n42): a Scroll that performs CHEW and is then
    /// killed by Doom at BeforeSideTurnEnd is gone from `CombatState.Enemies`
    /// before `PrepareForNextTurn`, so its `rand` never draws. The surviving
    /// CHEW-er still spends exactly one MonsterAi draw, in roster order.
    #[test]
    fn scroll_killed_after_chew_spends_no_ai_draw_at_prepare() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::ScrollOfBiting).unwrap();
        let catalog = builder.build();
        let roster = |doomed_hp: i32| {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            let mut doomed = HotMonster::new(MonsterKind::ScrollOfBiting, doomed_hp);
            doomed.loop_pos = 1;
            doomed.powers.set(PowerId::Doom, SlotWire::Int, 20);
            let mut survivor = HotMonster::new(MonsterKind::ScrollOfBiting, 49);
            survivor.loop_pos = 1;
            survivor.uid = 1;
            survivor.slot = 1;
            state.monsters_mut().push(doomed);
            state.monsters_mut().push(survivor);
            let seeded = Xoshiro256StarStar::from_seed(0);
            state.rng.set(
                RngStream::Ai,
                RngStreamState {
                    words: seeded.words,
                    counter: seeded.counter,
                },
            );
            state
        };
        let mut events = Vec::new();

        // Doom kills the first Scroll after both CHEWed: one draw, the survivor's.
        let mut killed = roster(10);
        run_enemy_phase(&mut killed, &catalog, &mut events).unwrap();
        assert_eq!(killed.monsters[0].hp, 0);
        assert_eq!(killed.rng.get(RngStream::Ai).counter, 1);
        assert!(!killed.monsters[0].scroll_branch_pending());
        assert!(!killed.monsters[1].scroll_branch_pending());
        assert_eq!(killed.monsters[0].loop_pos, 1);

        // The control roster (Doom short of lethal) spends two draws, the
        // first on slot 0; here the survivor takes that same first draw, so
        // slot 0 there and slot 1 here select alike.
        let mut control = roster(30);
        run_enemy_phase(&mut control, &catalog, &mut events).unwrap();
        assert!(control.monsters[0].hp > 0);
        assert_eq!(control.rng.get(RngStream::Ai).counter, 2);
        assert_eq!(control.monsters[0].loop_pos, killed.monsters[1].loop_pos);
        assert_eq!(
            control.monsters[0].scroll_chew_repeated(),
            killed.monsters[1].scroll_chew_repeated()
        );
    }

    /// #3304: a stun left on a Scroll whose CHEW is still pending would park
