    #[test]
    fn slime_random_machines_keep_draws_on_forced_branches_and_stop_on_death() {
        let mut builder = CatalogBuilder::new();
        let mut state = HotState::at_defaults();
        state.hp = 999;
        state.max_hp = 999;
        for (kind, intent) in [
            (MonsterKind::TwigSlimeM, 1),
            (MonsterKind::LeafSlimeS, 1),
            (MonsterKind::LeafSlimeM, 0),
            (MonsterKind::TwigSlimeS, 0),
        ] {
            builder.intern_monster(kind).unwrap();
            let mut monster = HotMonster::new(kind, 30);
            if random_ai_is_allowlisted(kind) {
                assert!(monster.random_ai.set_next(Some(intent)));
                assert!(monster.random_ai.set_log(&[intent]));
            }
            monster.slot = state.monsters.len() as i32;
            monster.uid = state.monsters.len() as u32;
            state.monsters_mut().push(monster);
        }
        let catalog = builder.build();
        // #3026: Twig Slime M's POKEY_POUNCE is `maxRepeats = 2`, so after
        // `[STICKY, POKEY]` its roll is a real two-way draw. Pick a seed on
        // which both of those draws (turns 2 and 4, the first draw of each
        // roster pass) land in STICKY's window, so the alternation asserted
        // below still holds. Leaf Slime S's alternation is forced by
        // CannotRepeat on every seed.
        let seeded = (0_u64..256)
            .map(Xoshiro256StarStar::from_seed)
            .find(|rng| {
                let mut rng = *rng;
                let draws: Vec<f32> = (0..8).map(|_| rng.next_float(2.0)).collect();
                draws[2] - 1.0 > 0.0 && draws[6] - 1.0 > 0.0
            })
            .expect("a seed whose Twig two-way draws both select STICKY");
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: 1,
            },
        );
        let shuffle = state.rng.get(RngStream::Rng);
        let mut events = Vec::new();
        for turn in 1..=4 {
            // Isolate insertion from next player turn's draw/reshuffle.
            // The integration fixture separately checks complete end turns.
            for actor in 0..state.monsters.len() {
                monster_act(&mut state, &catalog, actor, &mut events).unwrap();
            }
            prepare_random_ai(&mut state, &catalog).unwrap();
            assert_eq!(state.rng.get(RngStream::Ai).counter, 1 + 2 * turn);
            assert_eq!(
                state.monsters[0].random_ai.next(),
                Some((turn % 2 == 0) as u8)
            );
            assert_eq!(
                state.monsters[1].random_ai.next(),
                Some((turn % 2 == 0) as u8)
            );
            assert_eq!(state.monsters[2].loop_pos, (turn % 2) as i32);
            assert_eq!(state.monsters[3].loop_pos, 0);
            assert_eq!(
                state.rng.get(RngStream::Rng),
                shuffle,
                "Slimed appends without shuffle"
            );
        }
        // Status turns insert 1 + 1 + 2 cards. Attack turns deal 12+4+9+5;
        // Twig S additionally attacks for 5 on both status turns.
        assert_eq!(state.hp, 999 - 2 * 30 - 2 * 5);
        assert_eq!(state.piles.get(PileId::Discard).len(), 8);
        for card in state.piles.get(PileId::Discard).as_slice() {
            assert_eq!(catalog.spec(card.atom).unwrap().identity.id, CardId::Slimed);
        }
        state.monsters_mut()[1].hp = 0;
        prepare_random_ai(&mut state, &catalog).unwrap();
        assert_eq!(state.rng.get(RngStream::Ai).counter, 10);
    }

