    /// Run one `roll_random_intent` for a lone random-AI monster from explicit
    /// MonsterAi words, after discarding `skip` draws that other monsters
    /// consumed first in the native roster pass. Returns the state and the
    /// draw the roll consumed.
    fn roll_lone_random_ai(
        kind: MonsterKind,
        next: u8,
        log: &[u8],
        words: [u64; 4],
        counter: u64,
        skip: usize,
    ) -> (HotState, f64) {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(kind).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        let mut monster = HotMonster::new(kind, 30);
        assert!(monster.random_ai.set_next(Some(next)));
        assert!(monster.random_ai.set_log(log));
        state.monsters_mut().push(monster);
        let mut rng = Xoshiro256StarStar { words, counter };
        for _ in 0..skip {
            rng.next_double();
        }
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: rng.words,
                counter: rng.counter,
            },
        );
        let draw = {
            let mut peek = rng;
            peek.next_double()
        };
        roll_random_intent(&mut state, &catalog, 0).unwrap();
        assert_eq!(state.rng.get(RngStream::Ai).counter, rng.counter + 1);
        (state, draw)
    }

    /// Native witness for #3026, `.mcr` `095750.715_mcr_5acc85fb` (fight
    /// `f1c50ac7cd7717ea`): the turn-3 roster pass starts at MonsterAi counter
    /// 3; Leaf Slime S draws 0.9696 first, then Twig Slime M draws 0.4149 with
    /// log `[STICKY_SHOT, POKEY_POUNCE]`. POKEY is `maxRepeats = 2`, so both
    /// branches weigh 1 and 0.4149 × 2 selects POKEY again, as the capture
    /// records. The old CannotRepeat reading zeroed POKEY and chose STICKY.
    #[test]
    fn twig_slime_pokey_repeats_once_on_the_native_turn_three_draw() {
        let pokey = super::super::admission::SLIME_ATTACK_INDEX;
        let sticky = super::super::admission::SLIME_STATUS_INDEX;
        let words = [
            0xe6ef_9a65_f78e_1bc9,
            0x9ae3_35bf_667e_5240,
            0x1b69_c1a5_acce_3b16,
            0x6310_5637_a927_0387,
        ];
        let (state, draw) = roll_lone_random_ai(
            MonsterKind::TwigSlimeM,
            pokey,
            &[sticky, pokey],
            words,
            3,
            1,
        );
        assert!((draw - 0.4149).abs() < 1e-4);
        let machine = state.monsters[0].random_ai;
        assert_eq!(machine.next(), Some(pokey));
        assert_eq!(machine.log_len(), 3);
        assert!(valid_random_ai_state(&state.monsters[0], 2));

        // A third POKEY has weight 0: from `[STICKY, POKEY, POKEY]` the same draw
        // walks past the zero first branch to STICKY.
        let (state, _) = roll_lone_random_ai(
            MonsterKind::TwigSlimeM,
            pokey,
            &[sticky, pokey, pokey],
            words,
            3,
            1,
        );
        assert_eq!(state.monsters[0].random_ai.next(), Some(sticky));
        // Leaf Slime S keeps both branches CannotRepeat: TACKLE after TACKLE
        // weighs 0, so the same draw selects GOOP.
        let (state, _) = roll_lone_random_ai(
            MonsterKind::LeafSlimeS,
            pokey,
            &[sticky, pokey],
            words,
            3,
            1,
        );
        assert_eq!(state.monsters[0].random_ai.next(), Some(sticky));
    }

    /// Native witness for #3026, `.mcr` `153157.101_mcr_13fbd46c` (fight
    /// `f6245269e95a2720`): Fossil Stalker opens on LATCH and draws 0.046 at
    /// MonsterAi counter 3. All three branches are `maxRepeats = 2`, in native
    /// order LATCH, TACKLE, LASH, so 0.046 × 3 selects LATCH again (the old
    /// table-order walk selected TACKLE). The next draw, 0.8974, has LATCH
    /// exhausted and selects LASH over a total of 2, as the capture records.
    #[test]
    fn fossil_stalker_walks_native_branch_order_with_two_repeats() {
        let words = [
            0xd972_5145_728f_6a5a,
            0xb96c_9cbc_4044_66aa,
            0xe741_46cf_6b83_ec4d,
            0x1fca_207d_3673_428a,
        ];
        let (mut state, draw) = roll_lone_random_ai(
            MonsterKind::FossilStalker,
            FOSSIL_STALKER_LATCH_INDEX,
            &[FOSSIL_STALKER_LATCH_INDEX],
            words,
            3,
            0,
        );
        assert!((draw - 0.046).abs() < 1e-3);
        let machine = state.monsters[0].random_ai;
        assert_eq!(machine.next(), Some(FOSSIL_STALKER_LATCH_INDEX));
        assert_eq!(machine.log_len(), 2);
        assert!(valid_random_ai_state(&state.monsters[0], 3));

        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::FossilStalker).unwrap();
        let catalog = builder.build();
        roll_random_intent(&mut state, &catalog, 0).unwrap();
        assert_eq!(
            state.monsters[0].random_ai.next(),
            Some(FOSSIL_STALKER_LASH_INDEX)
        );
        assert_eq!(state.rng.get(RngStream::Ai).counter, 5);
        assert!(valid_random_ai_state(&state.monsters[0], 3));

        // The constants name the generated table rows.
        let names: Vec<&str> = random_moves(MonsterKind::FossilStalker)
            .expect("Fossil Stalker has a random-AI table")
            .iter()
            .map(|entry| entry.name)
            .collect();
        assert_eq!(
            names[usize::from(FOSSIL_STALKER_TACKLE_INDEX)],
            "TACKLE_MOVE"
        );
        assert_eq!(names[usize::from(FOSSIL_STALKER_LATCH_INDEX)], "LATCH_MOVE");
        assert_eq!(names[usize::from(FOSSIL_STALKER_LASH_INDEX)], "LASH_MOVE");
    }

    #[test]
    fn can_repeat_x_times_weight_zeroes_only_a_full_trailing_run() {
        let mut machine = crate::hot::RandomAiState::new();
        assert_eq!(can_repeat_x_times_weight(machine, 1, 2), 1.0, "empty log");
        assert!(machine.set_log(&[1]));
        assert_eq!(can_repeat_x_times_weight(machine, 1, 2), 1.0, "Count < N");
        assert!(machine.set_log(&[0, 1]));
        assert_eq!(can_repeat_x_times_weight(machine, 1, 2), 1.0);
        assert!(machine.set_log(&[1, 1]));
        assert_eq!(can_repeat_x_times_weight(machine, 1, 2), 0.0);
        assert_eq!(can_repeat_x_times_weight(machine, 0, 2), 1.0);
        assert!(machine.set_log(&[1, 1, 0]));
        assert_eq!(can_repeat_x_times_weight(machine, 1, 2), 1.0);
        assert!(machine.set_log(&[0, 1, 1]));
        assert_eq!(can_repeat_x_times_weight(machine, 1, 2), 0.0);
        assert_eq!(
            can_repeat_x_times_weight(machine, 1, 1),
            0.0,
            "N = 1 is the CannotRepeat rule"
        );
    }

    #[test]
    fn random_branch_cooldown_weight_zeroes_inside_the_trailing_window_only() {
        let mut machine = crate::hot::RandomAiState::new();
        assert!(machine.set_log(&[1, 0, 2]));
        assert_eq!(
            random_branch_cooldown_weight(machine, 2, 0),
            1.0,
            "cooldown 0 skips the filter (GetStateWeight IL_015c)"
        );
        assert_eq!(random_branch_cooldown_weight(machine, 2, 1), 0.0);
        assert_eq!(random_branch_cooldown_weight(machine, 1, 2), 1.0);
        assert_eq!(random_branch_cooldown_weight(machine, 1, 3), 0.0);
        assert_eq!(random_branch_cooldown_weight(machine, 3, 3), 1.0);
        assert!(machine.set_log(&[1]));
        assert_eq!(
            random_branch_cooldown_weight(machine, 1, 3),
            0.0,
            "Take(cooldown) over a shorter log reads the whole log"
        );
    }

    /// Roll Flyconid's steady RAND once over `log` (whose last entry is the
    /// current intent) from the seed-0 AI stream; returns the selected intent,
    /// the retained log after the roll, and the AI draws spent.
    fn flyconid_roll(log: &[u8]) -> (u8, Vec<u8>, u64) {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Flyconid).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        let mut flyconid = HotMonster::new(MonsterKind::Flyconid, 50);
        assert!(flyconid.random_ai.set_next(log.last().copied()));
        assert!(flyconid.random_ai.set_log(log));
        state.monsters_mut().push(flyconid);
        let seeded = Xoshiro256StarStar::from_seed(0);
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        roll_random_intent(&mut state, &catalog, 0).unwrap();
        let machine = state.monsters[0].random_ai;
        let after = (0..machine.log_len())
            .map(|position| machine.log_at(position).unwrap())
            .collect();
        (
            machine.next().unwrap(),
            after,
            state.rng.get(RngStream::Ai).counter,
        )
    }

    #[test]
    fn flyconid_all_zero_weights_take_the_first_branch_and_spend_the_draw() {
        // #3252 (45N6WGTLD063 n5): VULNERABLE is inside its cooldown-3 window,
        // FRAIL inside its cooldown-2 window and SMASH is CannotRepeat, so all
        // three weights are 0. Native `NextFloat(0)` returns 0 and `0 - 0` is
        // not `> 0`, so the first AddBranch branch (VULNERABLE) is taken.
        let (next, log, draws) = flyconid_roll(&[
            FLYCONID_VULNERABLE_INDEX,
            FLYCONID_FRAIL_INDEX,
            FLYCONID_SMASH_INDEX,
        ]);
        assert_eq!(next, FLYCONID_VULNERABLE_INDEX);
        assert_eq!(
            log,
            [
                FLYCONID_FRAIL_INDEX,
                FLYCONID_SMASH_INDEX,
                FLYCONID_VULNERABLE_INDEX
            ]
        );
        assert_eq!(draws, 1, "NextFloat(0) still advances the counter");
    }

    #[test]
    fn flyconid_vulnerable_cooldown_reaches_three_entries_back() {
        // VULNERABLE is not the last entry (CannotRepeat passes) but sits in
        // its cooldown-3 window; FRAIL is last. Only SMASH is live.
        let (next, _, draws) = flyconid_roll(&[
            FLYCONID_VULNERABLE_INDEX,
            FLYCONID_SMASH_INDEX,
            FLYCONID_FRAIL_INDEX,
        ]);
        assert_eq!(next, FLYCONID_SMASH_INDEX);
        assert_eq!(draws, 1);
    }

    #[test]
    fn flyconid_frail_cooldown_ends_after_two_entries() {
        // FRAIL three back is outside its cooldown-2 window; VULNERABLE is
        // cooling and SMASH is last, so FRAIL is the only live branch.
        let (next, _, _) = flyconid_roll(&[
            FLYCONID_FRAIL_INDEX,
            FLYCONID_VULNERABLE_INDEX,
            FLYCONID_SMASH_INDEX,
        ]);
        assert_eq!(next, FLYCONID_FRAIL_INDEX);
        // FRAIL two back is inside it; with SMASH last, VULNERABLE is the only
        // live branch.
        let (next, _, _) = flyconid_roll(&[FLYCONID_FRAIL_INDEX, FLYCONID_SMASH_INDEX]);
        assert_eq!(next, FLYCONID_VULNERABLE_INDEX);
    }

    #[test]
    fn flyconid_smash_is_cannot_repeat_without_a_cooldown() {
        // SMASH last is zeroed by CannotRepeat; VULNERABLE is cooling, so
        // FRAIL is forced. (SMASH one entry back is live again: it has no
        // cooldown, which `flyconid_vulnerable_cooldown_reaches_three_entries_back`
        // witnesses by selecting it.)
        let (next, _, _) = flyconid_roll(&[FLYCONID_VULNERABLE_INDEX, FLYCONID_SMASH_INDEX]);
        assert_eq!(next, FLYCONID_FRAIL_INDEX);
    }

    #[test]
    fn flyconid_live_weights_sum_into_one_draw_in_addbranch_order() {
        // After SMASH, VULNERABLE and FRAIL both weigh 1.0 (the constant the
        // #5713 overload passes): seed 0 draws NextFloat(2.0) = 1.2025..., so
        // the walk passes VULNERABLE (1.2 - 1 > 0) and takes FRAIL.
        let (next, _, draws) = flyconid_roll(&[FLYCONID_SMASH_INDEX]);
        assert_eq!(next, FLYCONID_FRAIL_INDEX);
        assert_eq!(draws, 1);
    }

