    #[test]
    fn obscura_rolls_only_the_three_post_illusion_branches_without_repeat() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::TheObscura).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        let mut obscura = HotMonster::new(MonsterKind::TheObscura, 129);
        assert!(obscura.random_ai.set_next(Some(0)));
        assert!(obscura.random_ai.set_log(&[0]));
        state.monsters_mut().push(obscura);
        let seeded = Xoshiro256StarStar::from_seed(0);
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );

        roll_random_intent(&mut state, &catalog, 0).unwrap();
        let first = state.monsters[0].random_ai.next().unwrap();
        assert!((1..=3).contains(&first));
        assert_eq!(state.monsters[0].random_ai.log_at(0), Some(0));
        assert_eq!(state.monsters[0].random_ai.log_at(1), Some(first));
        assert_eq!(state.rng.get(RngStream::Ai).counter, 1);

        roll_random_intent(&mut state, &catalog, 0).unwrap();
        let second = state.monsters[0].random_ai.next().unwrap();
        assert!((1..=3).contains(&second));
        assert_ne!(second, first);
        assert_eq!(state.monsters[0].random_ai.log_at(2), Some(second));
        assert_eq!(state.rng.get(RngStream::Ai).counter, 2);
    }

    #[test]
    fn an_exact_zero_roll_can_select_the_first_zero_weight_mawler_row() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Mawler).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        let mut mawler = HotMonster::new(MonsterKind::Mawler, 76);
        assert!(mawler.random_ai.set_next(Some(MAWLER_RIP_INDEX)));
        assert!(mawler.random_ai.set_log(&[
            MAWLER_CLAW_INDEX,
            MAWLER_ROAR_INDEX,
            MAWLER_RIP_INDEX
        ]));
        assert!(mawler.random_ai.set_once(&[MAWLER_ROAR_INDEX]));
        state.monsters_mut().push(mawler);
        // xoshiro's output transform reads s1; zero there produces an exact
        // NextDouble/NextFloat zero while the full generator state is nonzero.
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: [1, 0, 0, 0],
                counter: 0,
            },
        );

        roll_random_intent(&mut state, &catalog, 0).unwrap();

        assert_eq!(state.rng.get(RngStream::Ai).counter, 1);
        assert_eq!(state.monsters[0].random_ai.next(), Some(MAWLER_RIP_INDEX));
        assert_eq!(
            (0..state.monsters[0].random_ai.log_len())
                .map(|position| state.monsters[0].random_ai.log_at(position).unwrap())
                .collect::<Vec<_>>(),
            [MAWLER_ROAR_INDEX, MAWLER_RIP_INDEX, MAWLER_RIP_INDEX]
        );
    }

