    #[test]
    fn well_laid_plans_keeps_the_whole_hand_and_juggling_data_resets() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.player_phase = PHASE_ORDINARY_ACTIONS;
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 9,
            atom: 0,
            flags: 0,
        });
        state.powers.set(PowerId::WellLaidPlans, SlotWire::Bool, 1);
        state.powers.set(PowerId::Juggling, SlotWire::Int, 1);
        state.powers.set(PowerId::JugglingAttacks, SlotWire::Int, 7);
        state.card_states.set_local_retain(9);
        state.card_states.set_transient_retain(9);
        // Production keyword writers force exact mode before publishing the
        // side-table bit; exercise CleanupAfterTurn from that reachable state.
        state.exact_piles = true;
        hydrate_after_side_turn_end_power_order_for_test(&mut state);
        let mut events = Vec::new();

        end_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 9);
        assert!(state.piles.get(PileId::Discard).is_empty());
        assert_eq!(state.powers.value(PowerId::JugglingAttacks), 0);
        assert_eq!(state.powers.value(PowerId::WellLaidPlans), 1);
        assert!(state.card_states.get(9).local_retain);
        assert!(!state.card_states.get(9).transient_retain);
        assert!(state.exact_piles, "cleanup must not demote exact mode");
    }

    #[test]
    fn retain_hand_suppresses_the_whole_flush_then_expires_after_cleanup() {
        let identity = CardIdentity {
            id: CardId::StrikeSilent,
            upgrade: 0,
            enchantment: None,
        };
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.player_phase = PHASE_ORDINARY_ACTIONS;
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 9,
            atom,
            flags: 0,
        });
        state.powers.set(PowerId::RetainHand, SlotWire::Int, 2);
        state.card_states.set_transient_retain(9);
        state.exact_piles = true;
        hydrate_after_side_turn_end_power_order_for_test(&mut state);
        let mut events = Vec::new();

        end_player_turn(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 9);
        assert_eq!(state.powers.value(PowerId::RetainHand), 1);
        assert!(!state.card_states.get(9).transient_retain);

        end_player_turn(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 9);
        assert_eq!(state.powers.value(PowerId::RetainHand), 0);

        end_player_turn(&mut state, &catalog, &mut events).unwrap();
        assert!(events.iter().any(|event| matches!(
            event,
            Event::CardResolved {
                uid: 9,
                pile: PileId::Discard,
            }
        )));
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(
                    event,
                    Event::PowerChanged {
                        power: PowerId::RetainHand,
                        ..
                    }
                ))
                .count(),
            2
        );
    }

