    /// #3024: Divine Right's AfterRoomEntered `GainStars(3)` is stamped
    /// (Round 1, Player, Turn 1), and no SwitchSides precedes turn one, so
    /// the opening's first turn keeps it and turn-1 Radiate swings three
    /// times (`roll_stars_gained_window`).
    #[test]
    fn divine_right_pre_turn_stars_survive_the_opening_turn_and_drive_radiate() {
        let mut builder = CatalogBuilder::new();
        builder
            .set_relics(&[crate::ids::RelicId::RelicDivineRight])
            .unwrap();
        let radiate = builder
            .intern(CardIdentity {
                id: CardId::Radiate,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.exact_piles = true;
        state.next_card_uid = 5;
        let mut target = HotMonster::new(MonsterKind::Toadpole, 40);
        target.max_hp = 40;
        state.monsters_mut().push(target);
        assert_eq!(state.turn, 1);
        let mut events = Vec::new();

        crate::engine::fire_after_room_entered(&catalog, &mut state, &mut events).unwrap();
        assert_eq!(state.stars, 3);
        assert_eq!(state.history.stars_gained_this_turn, 3);
        crate::engine::fire_before_combat_start(&catalog, &mut state, &mut events).unwrap();
        crate::engine::deal_opening_hand(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(
            state.history.stars_gained_this_turn, 3,
            "no side switch precedes turn one, so the pre-turn gain still counts"
        );

        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 4,
            atom: radiate,
            flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        let played = crate::engine::apply_action(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: 4,
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        assert_eq!(played.monsters[0].hp, 40 - 3 * 3, "three 3-damage hits");
    }

    /// The other arm of `roll_stars_gained_window`: a turn-one entry that is
    /// not the opening can still only be the first turn, so a preset count
    /// is kept, while the turn-two case below
    /// (`biased_cognition_reduces_signed_focus_before_the_side_start_hook`)
    /// rolls it.
    #[test]
    fn begin_player_turn_keeps_stars_gained_on_turn_one_and_rolls_them_after() {
        let catalog = CatalogBuilder::new().build();
        let mut first = HotState::at_defaults();
        first.hp = 50;
        first.history.stars_gained_this_turn = 3;
        let mut later = first.clone();
        later.turn = 2;

        begin_player_turn(&mut first, &catalog, &mut Vec::new()).unwrap();
        begin_player_turn(&mut later, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(first.history.stars_gained_this_turn, 3);
        assert_eq!(later.history.stars_gained_this_turn, 0);
    }

    #[test]
    fn biased_cognition_reduces_signed_focus_before_the_side_start_hook() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.turn = 2;
        state.stars = 6;
        state.history.stars_gained_this_turn = 4;
        state.powers.set(PowerId::Focus, SlotWire::Int, 1);
        state.powers.set(PowerId::BiasedCognition, SlotWire::Int, 3);
        assert!(
            state
                .fanouts
                .register_after_side_turn_start(PowerId::BiasedCognition)
        );
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(state.powers.value(PowerId::Focus), -2);
        assert_eq!(state.powers.value(PowerId::BiasedCognition), 3);
        assert_eq!(state.stars, 6, "the persistent balance survives turn start");
        assert_eq!(state.history.stars_gained_this_turn, 0);
    }

