    #[test]
    fn energy_next_turn_completes_before_a_later_orb_listener_ends_combat() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.turn = 1;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 1));
        state.orbs.set_slots(1);
        state
            .orbs
            .set_orbs(vec![HotOrb::from_parts(OrbKind::Dark, Some(1)).unwrap()]);
        state.powers.set(PowerId::LightningRod, SlotWire::Int, 1);
        state
            .orbs
            .set_reset_order(vec![crate::hot::OrbResetPower::LightningRod]);
        state.powers.set(PowerId::EnergyNextTurn, SlotWire::Int, 4);
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert!(state.history.over, "channeling evoked lethal Dark");
        assert_eq!(state.energy, 7, "base reset plus completed deferred grant");
        assert_eq!(state.powers.value(PowerId::EnergyNextTurn), 0);
        // #2703: native Decrement delegates to ModifyAmount (0x3f032c),
        // which returns at IsEnding (IL_003a) — the enemy-terminal evoke
        // retains the duration instead of completing the decrement.
        assert_eq!(
            state.powers.value(PowerId::LightningRod),
            1,
            "the ending walk retains the in-flight listener duration"
        );
    }

    #[test]
    fn summon_next_turn_ticks_after_rolling_boulder_then_removes_without_rng() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.turn = 2;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10));
        state.powers.set(PowerId::RollingBoulder, SlotWire::Int, 1);
        state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, 2);
        assert!(state.fanouts.set_after_player_turn_start_order(&[
            PowerId::RollingBoulder,
            PowerId::SummonNextTurn,
        ]));
        let rng_before = state.rng.clone();
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert!(!state.history.over);
        assert_eq!(
            state
                .fanouts
                .pet()
                .osty()
                .map(|osty| (osty.hp(), osty.max_hp())),
            Some((2, 2))
        );
        assert_eq!(state.powers.value(PowerId::SummonNextTurn), 0);
        assert_eq!(state.rng, rng_before, "summoning consumes no RNG stream");
        let boulder_growth = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::PowerChanged {
                        subject: Subject::Player,
                        power: PowerId::RollingBoulder,
                        amount: 6,
                    }
                )
            })
            .unwrap();
        let summon_removal = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::PowerChanged {
                        subject: Subject::Player,
                        power: PowerId::SummonNextTurn,
                        amount: 0,
                    }
                )
            })
            .unwrap();
        assert!(boulder_growth < summon_removal);
    }

    /// #3279: a peer that ends the combat before the captured SummonNextTurn
    /// leaves native `OstyCmd.Summon` (`SummonNextTurnPower/
    /// <AfterPlayerTurnStart>d__6` `0x346ecc` IL_0069) running under
    /// IsEnding: a live Osty gains MaxHp without the `Heal`
    /// (`<Heal>d__20` `0x3eb4b0` IL_0041-IL_005f), and an absent one refuses
    /// by name. Before #3279 both arms healed.
    #[test]
    fn terminal_before_summon_next_turn_grows_max_hp_only_or_refuses_the_add() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let fixture = |osty: Option<(i32, i32)>| {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            state.max_hp = 100;
            state.turn = 2;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 1));
            state.fanouts.set_osty(osty).unwrap();
            state.powers.set(PowerId::RollingBoulder, SlotWire::Int, 1);
            state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, 2);
            assert!(state.fanouts.set_after_player_turn_start_order(&[
                PowerId::RollingBoulder,
                PowerId::SummonNextTurn,
            ]));
            state
        };

        let mut live = fixture(Some((3, 5)));
        begin_player_turn(&mut live, &catalog, &mut Vec::new()).unwrap();
        assert!(live.history.over, "Rolling Boulder killed the last enemy");
        assert_eq!(
            live.fanouts
                .pet()
                .osty()
                .map(|osty| (osty.hp(), osty.max_hp())),
            Some((3, 7)),
            "the ending summon grows MaxHp and skips the heal"
        );
        assert_eq!(live.powers.value(PowerId::SummonNextTurn), 0);

        let mut absent = fixture(None);
        assert_eq!(
            begin_player_turn(&mut absent, &catalog, &mut Vec::new()),
            Err(EngineRefusal::EndingSummonNotModeled(
                "summon next turn Osty"
            ))
        );
    }

    /// Owner death (`PendingLoss`) is IsEnding too
    /// (`CombatManager::IsCombatEnding` `0x135854` IL_0016-IL_0024), and it
    /// kills Osty first (`<KillWithoutCheckingWinCondition>d__15` `0x3ebe90`
    /// IL_06ad-IL_06ca), so the captured summon that still runs after a
    /// lethal Inferno or Crimson Mantle self-hit reaches the refused
    /// add/revive branch (#3279). Before #3279 it created a 2/2 Osty.
    #[test]
    fn lethal_self_damage_before_summon_next_turn_refuses_the_ending_add() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        for (powers, osty) in [
            ([(PowerId::Inferno, 6), (PowerId::InfernoSelf, 1)], None),
            (
                [(PowerId::Inferno, 6), (PowerId::InfernoSelf, 1)],
                Some((3, 5)),
            ),
            (
                [(PowerId::CrimsonMantle, 4), (PowerId::CrimsonSelf, 1)],
                None,
            ),
        ] {
            let mut state = HotState::at_defaults();
            state.hp = 1;
            state.max_hp = 1;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 20));
            state.fanouts.set_osty(osty).unwrap();
            for (power, amount) in powers {
                state.powers.set(power, SlotWire::Int, amount);
            }
            state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, 2);
            assert!(
                state
                    .fanouts
                    .set_after_player_turn_start_order(&[powers[0].0, PowerId::SummonNextTurn])
            );

            assert_eq!(
                begin_player_turn(&mut state, &catalog, &mut Vec::new()),
                Err(EngineRefusal::EndingSummonNotModeled(
                    "summon next turn Osty"
                )),
                "{powers:?} with Osty {osty:?}"
            );
        }
    }

