    #[test]
    fn summon_next_turn_snapshot_is_only_a_gate_and_the_operand_is_live() {
        let mut state = HotState::at_defaults();
        state.hp = 50;
        // A live enemy keeps `damage_combat_is_ending` false (#3279).
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10));
        // Model an earlier, already-audited listener changing the live Amount
        // after Creature.BeforeTurnStart captured a positive snapshot.
        state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, 4);
        let mut events = Vec::new();

        tick_summon_next_turn(&mut state, true, &mut events).unwrap();

        assert_eq!(
            state
                .fanouts
                .pet()
                .osty()
                .map(|osty| (osty.hp(), osty.max_hp())),
            Some((4, 4)),
            "the listener passes its live Amount, not the earlier gate value"
        );
        assert_eq!(state.powers.value(PowerId::SummonNextTurn), 0);
        assert_eq!(
            events,
            [Event::PowerChanged {
                subject: Subject::Player,
                power: PowerId::SummonNextTurn,
                amount: 0,
            }]
        );
    }

