    #[test]
    fn malformed_hit_order_rolls_back_complete_public_side_boundaries() {
        let catalog = CatalogBuilder::new().build();

        let mut begin = HotState::at_defaults();
        begin.hp = 50;
        begin.powers.set(PowerId::FlameBarrier, SlotWire::Int, 4);
        begin.powers.set(PowerId::Reflect, SlotWire::Int, 1);
        assert!(
            begin
                .fanouts
                .register_after_side_turn_start(PowerId::Reflect)
        );
        assert!(begin.set_after_damage_received_power_order(&[
            crate::hot::AfterDamageReceivedPower::FlameBarrier,
            crate::hot::AfterDamageReceivedPower::Reflect,
        ]));
        // Preserve the authenticated two-listener carrier while forging one
        // member absent. Reflect's later start-turn removal must not publish
        // any earlier turn-start mutations or events before it refuses.
        begin.powers.set(PowerId::FlameBarrier, SlotWire::Int, 0);
        let begin_before = begin.clone();
        let mut begin_events = vec![Event::TurnBegan { turn: 77 }];
        let begin_events_before = begin_events.clone();
        assert_eq!(
            begin_player_turn(&mut begin, &catalog, &mut begin_events),
            Err(EngineRefusal::PowerOrderNotModeled(
                "after-damage-received power removal"
            ))
        );
        assert_eq!(begin, begin_before);
        assert_eq!(begin_events, begin_events_before);

        let mut end = HotState::at_defaults();
        end.hp = 50;
        end.powers.set(PowerId::FlameBarrier, SlotWire::Int, 4);
        end.powers.set(PowerId::Reflect, SlotWire::Int, 2);
        assert!(end.fanouts.register_after_side_turn_start(PowerId::Reflect));
        assert!(end.set_after_damage_received_power_order(&[
            crate::hot::AfterDamageReceivedPower::Reflect,
            crate::hot::AfterDamageReceivedPower::FlameBarrier,
        ]));
        // The symmetrical stale member makes Flame Barrier's enemy-side-end
        // unregister fail. The entire public end-turn command is atomic.
        end.powers.set(PowerId::Reflect, SlotWire::Int, 0);
        let end_before = end.clone();
        let mut end_events = vec![Event::TurnBegan { turn: 88 }];
        let end_events_before = end_events.clone();
        assert_eq!(
            end_player_turn(&mut end, &catalog, &mut end_events),
            Err(EngineRefusal::PowerOrderNotModeled(
                "after-damage-received power removal"
            ))
        );
        assert_eq!(end, end_before);
        assert_eq!(end_events, end_events_before);
    }

    #[test]
    fn player_affliction_ticks_skip_once_then_decrement_in_native_order() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        for (power, fresh) in [
            (PowerId::PlayerVuln, PowerId::PlayerVulnFresh),
            (PowerId::PlayerWeak, PowerId::PlayerWeakFresh),
            (PowerId::PlayerFrail, PowerId::PlayerFrailFresh),
            (PowerId::Smoggy, PowerId::SmoggyFresh),
        ] {
            state.powers.set(power, SlotWire::Int, 2);
            state.powers.set(fresh, SlotWire::Bool, 1);
        }
        hydrate_after_side_turn_end_power_order_for_test(&mut state);
        crate::engine::play::hydrate_after_card_played_power_order_for_test(&mut state);
        let mut events = Vec::new();

        run_enemy_phase(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::PlayerVuln), 2);
        assert_eq!(state.powers.value(PowerId::PlayerWeak), 2);
        assert_eq!(state.powers.value(PowerId::PlayerFrail), 2);
        assert_eq!(state.powers.value(PowerId::Smoggy), 2);
        assert_eq!(
            events
                .iter()
                .filter_map(|event| match event {
                    Event::PowerChanged { power, .. }
                        if matches!(
                            power,
                            PowerId::PlayerVulnFresh
                                | PowerId::PlayerWeakFresh
                                | PowerId::PlayerFrailFresh
                                | PowerId::SmoggyFresh
                        ) =>
                        Some(*power),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [
                PowerId::PlayerVulnFresh,
                PowerId::PlayerWeakFresh,
                PowerId::PlayerFrailFresh,
            ]
        );
        // #3161: Smoggy never ticks, so its latch is never consumed.
        assert_eq!(state.powers.value(PowerId::SmoggyFresh), 1);
        assert!(crate::engine::play::after_card_played_power_order_is_exact(
            &state
        ));

        events.clear();
        run_enemy_phase(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(
            [
                state.powers.value(PowerId::PlayerVuln),
                state.powers.value(PowerId::PlayerWeak),
                state.powers.value(PowerId::PlayerFrail),
                state.powers.value(PowerId::Smoggy),
            ],
            [1, 1, 1, 2]
        );
        assert_eq!(
            events
                .iter()
                .filter_map(|event| match event {
                    Event::PowerChanged { power, .. }
                        if matches!(
                            power,
                            PowerId::PlayerVuln
                                | PowerId::PlayerWeak
                                | PowerId::PlayerFrail
                                | PowerId::Smoggy
                        ) =>
                        Some(*power),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [
                PowerId::PlayerVuln,
                PowerId::PlayerWeak,
                PowerId::PlayerFrail
            ]
        );
    }

    #[test]
    fn native_player_power_after_side_turn_end_callback_census_is_exact() {
        use sha2::{Digest, Sha256};

        // Current v0.111.0 ARM64 authority, DLL SHA-256
        // 9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4.
        // Columns are canonical token|TypeDef|outer RVA|nested MoveNext or
        // '-'|StackType|InstanceType.  Keep the complete rows reviewable:
        // hashing only the short token list would miss an authority change.
        let rows = [
            "borrowed_time|BorrowedTimePower|0x9feec|0x336090|1|0",
            "burst|BurstPower|0xa00e0|0x3365c4|1|0",
            "constrict|ConstrictPower|0xa0940|0x3374ac|1|0",
            "consuming_shadow|ConsumingShadowPower|0xa09f8|0x3375a4|1|0",
            "corrosive_wave|CorrosiveWavePower|0xa0b48|0x337a60|1|0",
            "dark_embrace|DarkEmbracePower|0xa1418|0x338a84|1|0",
            "doom|DoomPower|0xa19ac|0x3390f0|1|0",
            "double_damage|DoubleDamagePower|0xa1cf8|0x33983c|1|0",
            "duplication|DuplicationPower|0xa1e38|0x339abc|1|0",
            "hellraiser|HellraiserPower|0xa3683|-|2|0",
            "juggling|JugglingPower|0xa4463|-|1|0",
            "monologue|MonologuePower|0xa4c18|0x33e7d8|dynamic|1",
            "no_draw|NoDrawPower|0xa4f44|0x33efbc|2|0",
            "no_energy_gain|NoEnergyGainPower|0xa4fc4|0x33f094|2|0",
            "one_two_punch|OneTwoPunchPower|0xa53f8|0x33f638|1|0",
            "pale_blue_dot|PaleBlueDotPower|0xa5650|-|1|0",
            "panache|PanachePower|0xa5777|-|1|1",
            "rage|RagePower|0xa62f0|0x3415a4|1|0",
            "rebound|ReboundPower|0xa68fc|0x34223c|1|0",
            "retain_hand|RetainHandPower|0xa6aa0|0x342694|1|0",
            "ringing|RingingPower|0xa6b8c|0x3429b4|2|0",
            "ritual|RitualPower|0xa6d40|0x342a94|1|0",
            "shadowmeld|ShadowmeldPower|0xa7528|0x344114|1|0",
            "smoggy|SmoggyPower|0xa804c|-|2|0",
            "tangled|TangledPower|0xa93b8|0x34812c|1|0",
            "temporary_dexterity|TemporaryDexterityPower|0xa97e8|0x348498|1|0",
            "temporary_focus|TemporaryFocusPower|0xa9a68|0x348820|1|0",
            "temporary_strength|TemporaryStrengthPower|0xa9ce0|0x348ba8|1|0",
            "tender|TenderPower|0xa9df8|0x348fb4|1|0",
        ];
        assert_eq!(rows.len(), 29);
        assert_eq!(
            format!("{:x}", Sha256::digest(rows.join("\n"))),
            "9642a2f79e8cb87dfff23a9abd52a2dbd8f3abc8f432d2b4ffe2af318b24f057"
        );
        let tokens = rows
            .iter()
            .map(|row| row.split('|').next().expect("census token"))
            .collect::<Vec<_>>();
        assert_eq!(
            format!("{:x}", Sha256::digest(tokens.join("\n"))),
            "c45e571bb5e8202bb9a384bb59b3a65c8a02c01d9f31d42d2e9813e3de30d584"
        );
    }

    #[test]
    fn static_and_call_local_ethereal_snapshot_exhausts_in_hand_order_through_live_hooks() {
        let mut builder = CatalogBuilder::new();
        let dazed = builder
            .intern(CardIdentity {
                id: CardId::Dazed,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let strike = builder
            .intern(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.powers.set(PowerId::FeelNoPain, SlotWire::Int, 2);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 3,
                atom: dazed,
                flags: 0,
            },
            HotCard {
                uid: 4,
                atom: strike,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 5,
                atom: dazed,
                flags: 0,
            },
            HotCard {
                uid: 6,
                atom: strike,
                flags: 0,
            },
            HotCard {
                uid: 7,
                atom: strike,
                flags: 0,
            },
        ]);
        let mut instance = state.card_states.get(4);
        instance.set_local_ethereal(true);
        state.card_states.set(4, instance);
        let mut events = Vec::new();

        run_ordinary_ethereal_cards(&mut state, &catalog, &mut events).unwrap();

        assert!(!state.exact_piles);
        assert_eq!(state.block, 6);
        assert_eq!(state.history.owner_cards_exhausted_combat, 3);
        assert!(state.history.owner_card_exhausted_this_turn);
        assert_eq!(
            state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [6, 7]
        );
        assert_eq!(
            state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [3, 4, 5]
        );
        assert_eq!(
            events
                .iter()
                .filter_map(|event| match event {
                    Event::CardResolved {
                        uid,
                        pile: PileId::Exhaust,
                    } => Some(*uid),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [3, 4, 5]
        );
    }

    #[test]
    fn ordinary_ethereal_snapshot_binds_ordered_unique_uids_and_reloads_live_payload() {
        let mut builder = CatalogBuilder::new();
        let dazed = builder
            .intern(CardIdentity {
                id: CardId::Dazed,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 10,
                atom: dazed,
                flags: 0,
            },
            HotCard {
                uid: 11,
                atom: dazed,
                flags: 0,
            },
        ]);
        let frozen = ordinary_ethereal_snapshot(&state, &catalog).unwrap();
        assert_eq!(frozen, [10, 11]);
        assert_eq!(
            ordinary_ethereal_frozen_uid_position(&state, frozen[0]),
            Ok(0)
        );
        assert_eq!(
            ordinary_ethereal_frozen_uid_position(&state, frozen[1]),
            Ok(1)
        );

        // CardModel snapshot entries are live references: payload mutation
        // does not invalidate the captured physical identity.
        state.card_states.set_local_retain(11);
        assert_eq!(
            ordinary_ethereal_frozen_uid_position(&state, frozen[1]),
            Ok(1)
        );

        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 10,
            atom: dazed,
            flags: 0,
        });
        assert_eq!(
            ordinary_ethereal_frozen_uid_position(&state, frozen[0]),
            Err(EngineRefusal::ActiveCardNotUnique {
                uid: 10,
                matches: 2,
            })
        );
        state.piles.get_mut(PileId::Hand).make_mut().remove(1);
        assert_eq!(
            ordinary_ethereal_frozen_uid_position(&state, frozen[1]),
            Err(EngineRefusal::FrozenCardVanished {
                uid: 11,
                pile: PileId::Hand,
            })
        );
    }

