    #[test]
    fn deferred_dark_embrace_multiplies_live_amount_after_serial_ethereal_hooks() {
        let mut builder = CatalogBuilder::new();
        let dazed = builder
            .intern(CardIdentity {
                id: CardId::Dazed,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let defend = builder
            .intern(CardIdentity {
                id: CardId::DefendIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 1;
        state.max_hp = 50;
        state.powers.set(PowerId::DarkEmbrace, SlotWire::Int, 2);
        state.powers.set(PowerId::FeelNoPain, SlotWire::Int, 3);
        assert!(
            state
                .fanouts
                .set_after_card_exhausted_order(&[PowerId::DarkEmbrace, PowerId::FeelNoPain,])
        );
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 1,
                atom: dazed,
                flags: 0,
            },
            HotCard {
                uid: 2,
                atom: dazed,
                flags: 0,
            },
        ]);
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((3..=8).map(|uid| HotCard {
                uid,
                atom: defend,
                flags: 0,
            }));
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        state.monsters_mut().push(monster);
        let mut events = Vec::new();

        run_ordinary_ethereal_cards(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.fanouts.dark_embrace_ethereal(), 2);
        assert_eq!(state.block, 6, "Feel No Pain follows each tally callback");
        hydrate_after_side_turn_end_power_order_for_test(&mut state);
        finish_player_turn_after_auto_post_with_carriers(
            &mut state,
            &catalog,
            &mut events,
            false,
            false,
            false,
            0,
        )
        .unwrap();

        assert_eq!(state.fanouts.dark_embrace_ethereal(), 0);
        assert_eq!(state.cards_drawn_combat, 4);
        assert!(state.history.over && state.hp <= 0);
        assert_eq!(state.history.owner_cards_exhausted_combat, 2);
        assert_eq!(
            state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [1, 2]
        );
    }

