    #[test]
    fn terminal_temporary_transfer_overflow_rolls_back_the_complete_public_turn() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 1;
        state.max_hp = 1;
        state.powers.set(PowerId::Doom, SlotWire::Int, 1);
        state.powers.set(PowerId::Strength, SlotWire::Int, i32::MAX);
        state.temp_strength = 1;
        assert_eq!(
            state
                .fanouts
                .register_after_side_turn_end_power(AfterSideTurnEndPowerToken::Doom),
            Ok(0)
        );
        assert_eq!(
            state
                .fanouts
                .register_after_side_turn_end_power(AfterSideTurnEndPowerToken::TemporaryStrength,),
            Ok(1)
        );
        assert!(turn_end_transaction_needed(&state, false));
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 99 }];
        let before_events = events.clone();

        assert_eq!(
            end_player_turn(&mut state, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow(
                "temporary stat detach transfer"
            ))
        );
        assert_eq!(state, before);
        assert_eq!(events, before_events);
    }

