    #[test]
    fn corrosive_wave_side_end_removes_power_and_draw_token_or_refuses_atomically() {
        let mut state = HotState::at_defaults();
        state.powers.set(PowerId::CorrosiveWave, SlotWire::Int, 2);
        assert_eq!(
            state
                .fanouts
                .register_after_side_turn_end_power(AfterSideTurnEndPowerToken::CorrosiveWave),
            Ok(0)
        );
        state.powers.set(PowerId::Speedster, SlotWire::Int, 3);
        assert!(
            state
                .fanouts
                .set_after_card_drawn_order(&[PowerId::Speedster, PowerId::CorrosiveWave])
        );
        let mut events = Vec::new();
        expire_corrosive_wave_side_end(&mut state, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::CorrosiveWave), 0);
        assert_eq!(state.powers.value(PowerId::Speedster), 3);
        assert_eq!(
            state.fanouts.after_card_drawn_order(),
            &[PowerId::Speedster]
        );
        assert!(events.iter().any(|event| matches!(
            event,
            Event::PowerChanged {
                subject: Subject::Player,
                power: PowerId::CorrosiveWave,
                amount: 0,
            }
        )));

        let catalog = CatalogBuilder::new().build();
        for malformed in [
            {
                let mut state = HotState::at_defaults();
                state.powers.set(PowerId::CorrosiveWave, SlotWire::Int, 2);
                state
            },
            {
                let mut state = HotState::at_defaults();
                state.powers.set(PowerId::CorrosiveWave, SlotWire::Int, 2);
                state.powers.set(PowerId::Speedster, SlotWire::Int, 3);
                assert!(
                    state
                        .fanouts
                        .set_after_card_drawn_order(&[PowerId::CorrosiveWave])
                );
                state
            },
            {
                let mut state = HotState::at_defaults();
                state.powers.set(PowerId::CorrosiveWave, SlotWire::Int, 2);
                assert!(
                    state
                        .fanouts
                        .set_after_card_drawn_order(&[PowerId::CorrosiveWave, PowerId::Speedster,])
                );
                state
            },
            {
                let mut state = HotState::at_defaults();
                state.powers.set(PowerId::CorrosiveWave, SlotWire::Int, 2);
                state.powers.set(PowerId::Speedster, SlotWire::Int, 3);
                assert!(state.fanouts.set_after_card_drawn_order(&[
                    PowerId::CorrosiveWave,
                    PowerId::Speedster,
                    PowerId::Speedster,
                ]));
                state
            },
            {
                let mut state = HotState::at_defaults();
                assert!(
                    state
                        .fanouts
                        .set_after_card_drawn_order(&[PowerId::CorrosiveWave])
                );
                state
            },
        ] {
            let mut malformed = malformed;
            malformed.hp = 50;
            malformed.max_hp = 50;
            if malformed.powers.value(PowerId::CorrosiveWave) > 0 {
                assert_eq!(
                    malformed.fanouts.register_after_side_turn_end_power(
                        AfterSideTurnEndPowerToken::CorrosiveWave,
                    ),
                    Ok(0)
                );
            }
            let before = malformed.clone();
            let mut prior_events = vec![Event::TurnBegan { turn: 7 }];
            let before_events = prior_events.clone();
            assert_eq!(
                end_player_turn(&mut malformed, &catalog, &mut prior_events),
                Err(EngineRefusal::MalformedArgs(
                    "Corrosive Wave draw listener order"
                ))
            );
            assert_eq!(malformed, before);
            assert_eq!(prior_events, before_events);
        }
    }

    #[test]
    fn live_constrict_dark_and_hellraiser_execute_in_captured_order() {
        let mut builder = CatalogBuilder::new();
        builder.intern_private_constrict_strangler().unwrap();
        let dazed = builder
            .intern_reachable(CardIdentity {
                id: CardId::Dazed,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let strike = builder
            .intern_reachable(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        builder.mark_live_dark_embrace_reachable();
        builder.mark_live_hellraiser_reachable();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.powers.set(PowerId::DarkEmbrace, SlotWire::Int, 1);
        state.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
        assert!(state.fanouts.set_constrict_amount(3));
        for (uid, token) in [
            AfterSideTurnEndPowerToken::Constrict,
            AfterSideTurnEndPowerToken::DarkEmbrace,
            AfterSideTurnEndPowerToken::Hellraiser,
        ]
        .into_iter()
        .enumerate()
        {
            assert_eq!(
                state.fanouts.register_after_side_turn_end_power(token),
                Ok(u32::try_from(uid).unwrap())
            );
        }
        assert!(
            state
                .fanouts
                .set_after_card_exhausted_order(&[PowerId::DarkEmbrace])
        );
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 1,
            atom: dazed,
            flags: 0,
        });
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 2,
            atom: strike,
            flags: 0,
        });
        let mut owner = HotMonster::new(MonsterKind::SlitheringStrangler, 55);
        owner.max_hp = 55;
        owner.uid = 17;
        assert!(owner.random_ai.set_next(Some(STRANGLER_THWACK_INDEX)));
        assert!(
            owner
                .random_ai
                .set_log(&[STRANGLER_CONSTRICT_INDEX, STRANGLER_THWACK_INDEX])
        );
        state.monsters_mut().push(owner);
        let mut events = Vec::new();

        end_player_turn(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.hp, 39, "Constrict precedes the later Dark callback");
        assert_eq!(
            state.monsters[0].hp, 24,
            "Hellraiser plays the drawn Strike"
        );
        assert_eq!(state.fanouts.dark_embrace_ethereal(), 0);
        assert!(
            events
                .iter()
                .any(|event| matches!(event, Event::CardPlayed { uid: 2, .. }))
        );
    }

    #[test]
    fn dark_hellraiser_nested_temporary_acquisition_appends_but_is_deferred() {
        for (child_id, expected_token, expected_amount) in [
            (
                CardId::SetupStrike,
                AfterSideTurnEndPowerToken::TemporaryStrength,
                3,
            ),
            (
                CardId::FocusedStrike,
                AfterSideTurnEndPowerToken::TemporaryFocus,
                1,
            ),
        ] {
            let mut builder = CatalogBuilder::new();
            let child = builder
                .intern_reachable(CardIdentity {
                    id: child_id,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap();
            builder.intern_monster(MonsterKind::Toadpole).unwrap();
            builder.mark_live_dark_embrace_reachable();
            builder.mark_live_hellraiser_reachable();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.max_hp = 50;
            state.next_card_uid = 3;
            state.powers.set(PowerId::DarkEmbrace, SlotWire::Int, 1);
            state.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
            state.fanouts.set_dark_embrace_ethereal(1);
            for (uid, token) in [
                AfterSideTurnEndPowerToken::DarkEmbrace,
                AfterSideTurnEndPowerToken::Hellraiser,
            ]
            .into_iter()
            .enumerate()
            {
                assert_eq!(
                    state.fanouts.register_after_side_turn_end_power(token),
                    Ok(u32::try_from(uid).unwrap())
                );
            }
            assert!(
                state
                    .fanouts
                    .set_after_card_exhausted_order(&[PowerId::DarkEmbrace])
            );
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid: 2,
                atom: child,
                flags: 0,
            });
            let mut monster = HotMonster::new(MonsterKind::Toadpole, 1_000);
            monster.max_hp = 1_000;
            state.monsters_mut().push(monster);

            let record = capture_after_side_turn_end_power_record(&state, false)
                .unwrap()
                .unwrap();
            let record_index = state
                .frames
                .push_after_side_turn_end_power(&record)
                .unwrap();
            assert!(
                !drive_after_side_turn_end_power(
                    &mut state,
                    &catalog,
                    &mut Vec::new(),
                    record_index,
                )
                .unwrap()
            );
            state.frames.pop_top_after_side_turn_end_power().unwrap();

            assert_eq!(
                state.fanouts.after_side_turn_end_power_order(),
                &[
                    AfterSideTurnEndPowerEntry {
                        token: AfterSideTurnEndPowerToken::DarkEmbrace,
                        uid: 0,
                    },
                    AfterSideTurnEndPowerEntry {
                        token: AfterSideTurnEndPowerToken::Hellraiser,
                        uid: 1,
                    },
                    AfterSideTurnEndPowerEntry {
                        token: expected_token,
                        uid: 2,
                    },
                ],
                "{child_id:?} appends one fresh object after the frozen walk"
            );
            let amount = if child_id == CardId::SetupStrike {
                state.temp_strength
            } else {
                state.orbs.temp_focus()
            };
            assert_eq!(amount, expected_amount, "the new wrapper is deferred");
        }
    }

