    fn ethereal_drum_turn_fixture(replays: &[Option<i32>], energy: i16) -> (HotState, Catalog) {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let drum = builder
            .intern(CardIdentity {
                id: CardId::DrumOfBattle,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.energy = energy;
        for (index, replay) in replays.iter().copied().enumerate() {
            let uid = 70 + u32::try_from(index).unwrap();
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid,
                atom: drum,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
            let mut instance = state.card_states.get(uid);
            instance.set_local_ethereal(true);
            instance.set_base_replay_count(replay).unwrap();
            state.card_states.set(uid, instance);
        }
        (state, catalog)
    }

