    fn uids(state: &HotState, pile: PileId) -> Vec<u32> {
        state
            .piles
            .get(pile)
            .as_slice()
            .iter()
            .map(|card| card.uid)
            .collect()
    }

    /// #3042: `<ResolveTurnEndCardEffects>d__134` RVA `0x3f64bc` reads the
    /// current keywords after the body (IL `0x00f3-0x00fe`); a Hexed turn-end
    /// card under Hex is Ethereal and exhausts with `causedByEthereal`, while
    /// an un-Hexed sibling in the same snapshot still discards.
    #[test]
    fn hexed_turn_end_card_exhausts_by_ethereal_and_unhexed_sibling_discards() {
        let (mut state, catalog, decay) = hexed_decay_fixture(&[]);
        state.powers.set(PowerId::FeelNoPain, SlotWire::Int, 3);
        state.powers.set(PowerId::DarkEmbrace, SlotWire::Int, 1);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 1,
                atom: decay,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE | crate::hot::CARD_FLAG_HEXED,
            },
            HotCard {
                uid: 2,
                atom: decay,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        let mut events = Vec::new();

        run_turn_end_in_hand_cards(&mut state, &catalog, &mut events).unwrap();

        // Both bodies ran: 2 + 2 damage. Feel No Pain's 3 Block from the
        // Hexed exhaust precedes the un-Hexed body and absorbs 2 of it.
        assert_eq!(state.hp, 48);
        assert_eq!(state.block, 1);
        assert_eq!(uids(&state, PileId::Exhaust), [1]);
        assert_eq!(uids(&state, PileId::Discard), [2]);
        assert!(state.piles.get(PileId::Hand).is_empty());
        assert!(state.piles.get(PileId::Play).is_empty());
        // causedByEthereal defers Dark Embrace to its Ethereal tally.
        assert_eq!(state.fanouts.dark_embrace_ethereal(), 1);
        assert!(state.history.owner_card_exhausted_this_turn);
        assert!(events.contains(&Event::CardResolved {
            uid: 1,
            pile: PileId::Exhaust,
        }));
        assert!(events.contains(&Event::CardResolved {
            uid: 2,
            pile: PileId::Discard,
        }));
    }

