    #[test]
    fn doubt_and_shame_mark_fresh_only_when_the_prior_amount_was_zero() {
        let doubt = CardIdentity {
            id: CardId::Doubt,
            upgrade: 0,
            enchantment: None,
        };
        let shame = CardIdentity {
            id: CardId::Shame,
            upgrade: 0,
            enchantment: None,
        };
        let mut builder = CatalogBuilder::new();
        let doubt_atom = builder.intern(doubt).unwrap();
        let shame_atom = builder.intern(shame).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 1,
                atom: doubt_atom,
                flags: 0,
            },
            HotCard {
                uid: 2,
                atom: shame_atom,
                flags: 0,
            },
        ]);
        let mut events = Vec::new();

        run_turn_end_in_hand_cards(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::PlayerWeak), 1);
        assert_eq!(state.powers.value(PowerId::PlayerWeakFresh), 1);
        assert_eq!(state.powers.value(PowerId::PlayerFrail), 1);
        assert_eq!(state.powers.value(PowerId::PlayerFrailFresh), 1);
        assert_eq!(state.piles.get(PileId::Discard).len(), 2);

        state
            .powers
            .set(PowerId::PlayerWeakFresh, SlotWire::Bool, 0);
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 3,
            atom: doubt_atom,
            flags: 0,
        });
        run_turn_end_in_hand_cards(&mut state, &catalog, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::PlayerWeak), 2);
        assert_eq!(state.powers.value(PowerId::PlayerWeakFresh), 0);
    }

