    fn curse_catalog(ids: &[CardId]) -> (Catalog, Vec<crate::catalog::CardAtom>) {
        let mut builder = CatalogBuilder::new();
        let atoms = ids
            .iter()
            .map(|id| {
                builder
                    .intern(CardIdentity {
                        id: *id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .unwrap()
            })
            .collect();
        (builder.build(), atoms)
    }

    fn curse_card(uid: u32, atom: crate::catalog::CardAtom) -> HotCard {
        HotCard {
            uid,
            atom,
            flags: 0,
        }
    }

    #[test]
    fn bad_luck_turn_end_loses_thirteen_unblockable_and_routes_to_discard() {
        // #2561: `BadLuck/<OnTurnEndInHand>d__11` RVA 0x38ae1c is Beckon's
        // Damage(HpLoss, ValueProp 14) with HpLoss 13.
        let (catalog, atoms) = curse_catalog(&[CardId::BadLuck]);
        let mut state = HotState::at_defaults();
        state.hp = 20;
        state.max_hp = 20;
        state.block = 99;
        state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(curse_card(7, atoms[0]));
        let mut events = Vec::new();
        run_turn_end_in_hand_cards(&mut state, &catalog, &mut events).unwrap();
        assert_eq!((state.hp, state.block), (7, 99));
        assert!(state.piles.get(PileId::Hand).is_empty());
        assert!(state.piles.get(PileId::Play).is_empty());
        assert_eq!(state.piles.get(PileId::Discard).as_slice()[0].uid, 7);
        assert!(events.iter().any(|event| matches!(
            event,
            Event::CardResolved {
                uid: 7,
                pile: PileId::Discard
            }
        )));

        // Lethal: the source stays in Play and no discard suffix runs.
        let mut lethal = HotState::at_defaults();
        lethal.hp = 13;
        lethal.max_hp = 20;
        lethal
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(curse_card(7, atoms[0]));
        run_turn_end_in_hand_cards(&mut lethal, &catalog, &mut Vec::new()).unwrap();
        assert!(lethal.history.over);
        assert_eq!(lethal.piles.get(PileId::Play).as_slice()[0].uid, 7);
        assert!(lethal.piles.get(PileId::Discard).is_empty());
    }

    #[test]
    fn regret_loses_its_recorded_hand_count_unblockable_and_routes_to_discard() {
        // #2561: `Regret::BeforeSideTurnEnd` RVA 0xe9638 records the whole
        // Hand (itself included); `<OnTurnEndInHand>d__12` RVA 0x3b6ce8
        // deals that count with ValueProp 14.
        let (catalog, atoms) = curse_catalog(&[CardId::Regret, CardId::Injury]);
        let mut state = HotState::at_defaults();
        state.hp = 20;
        state.max_hp = 20;
        state.block = 99;
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            curse_card(3, atoms[1]),
            curse_card(4, atoms[0]),
            curse_card(5, atoms[1]),
        ]);
        run_turn_end_in_hand_cards(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!((state.hp, state.block), (17, 99));
        assert_eq!(
            state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [3, 5]
        );
        assert_eq!(state.piles.get(PileId::Discard).as_slice()[0].uid, 4);

        // The recorded count, not the live Hand: a Hand that shrank after
        // the BeforeSideTurnEnd pass (an ordinary Ethereal exhaust) still
        // deals the recorded four.
        let mut recorded = HotState::at_defaults();
        recorded.hp = 20;
        recorded.max_hp = 20;
        recorded
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(curse_card(4, atoms[0]));
        run_turn_end_in_hand_cards_with_regret(
            &mut recorded,
            &catalog,
            Some((4, vec![2, 4, 6, 8])),
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(recorded.hp, 16);

        // Lethal: the source stays in Play.
        let mut lethal = HotState::at_defaults();
        lethal.hp = 2;
        lethal.max_hp = 20;
        lethal
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .extend([curse_card(4, atoms[0]), curse_card(5, atoms[1])]);
        run_turn_end_in_hand_cards(&mut lethal, &catalog, &mut Vec::new()).unwrap();
        assert!(lethal.history.over);
        assert_eq!(lethal.piles.get(PileId::Play).as_slice()[0].uid, 4);
    }

    #[test]
    fn regret_refuses_where_its_recorded_count_is_not_provably_exact() {
        let (catalog, atoms) = curse_catalog(&[CardId::Regret]);
        let refusal = Err(EngineRefusal::PowerOrderNotModeled(
            "Regret BeforeSideTurnEnd hand count",
        ));
        // The pass moved the Hand while a Regret was in it (either side).
        assert_eq!(
            regret_before_side_turn_end_count(Some(vec![4, 5]), Some(vec![4])),
            refusal
        );
        assert_eq!(
            regret_before_side_turn_end_count(None, Some(vec![4])),
            refusal
        );
        assert_eq!(
            regret_before_side_turn_end_count(Some(vec![4]), None),
            refusal
        );
        assert_eq!(regret_before_side_turn_end_count(None, None), Ok(None));
        assert_eq!(
            regret_before_side_turn_end_count(Some(vec![5, 4]), Some(vec![5, 4])),
            Ok(Some((2, vec![5, 4])))
        );

        // A Regret that reached Hand after the pass (no count recorded, or
        // not in the recorded Hand) refuses before any mutation.
        for recorded in [None, Some((2, vec![5, 9]))] {
            let mut state = HotState::at_defaults();
            state.hp = 20;
            state
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .push(curse_card(4, atoms[0]));
            let before = state.clone();
            assert_eq!(
                run_turn_end_in_hand_cards_with_regret(
                    &mut state,
                    &catalog,
                    recorded,
                    &mut Vec::new()
                ),
                Err(EngineRefusal::PowerOrderNotModeled(
                    "Regret BeforeSideTurnEnd hand count"
                ))
            );
            assert_eq!(state, before);
        }
    }

