    #[test]
    fn demise_phases_ledger_expiry_and_events_by_acquisition_order() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        for demise_first in [false, true] {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            state.max_hp = 100;
            let mut owner = HotMonster::new(MonsterKind::Toadpole, 20);
            owner.max_hp = 20;
            owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
            owner.powers.set(PowerId::Shrink, SlotWire::Int, 4);
            owner.powers.set(PowerId::Conqueror, SlotWire::Int, 2);
            owner.powers.set(PowerId::SicEm, SlotWire::Int, 3);
            owner.powers.set(PowerId::Strangle, SlotWire::Int, 2);
            let peers = [
                MiseryToken::Shrink,
                MiseryToken::Conqueror,
                MiseryToken::SicEm,
                MiseryToken::Strangle,
            ];
            if !demise_first {
                for token in peers {
                    owner.misery_debuff_order.push(token);
                }
            }
            owner.misery_debuff_order.push(MiseryToken::Demise);
            if demise_first {
                for token in peers {
                    owner.misery_debuff_order.push(token);
                }
            }
            let uid = owner.uid;
            state.monsters_mut().push(owner);
            let mut events = Vec::new();

            run_enemy_phase(&mut state, &catalog, &mut events).unwrap();

            assert_eq!(state.monsters[0].hp, 11);
            assert_eq!(state.monsters[0].powers.value(PowerId::Shrink), 3);
            assert_eq!(state.monsters[0].powers.value(PowerId::Conqueror), 1);
            assert_eq!(state.monsters[0].powers.value(PowerId::SicEm), 0);
            assert_eq!(state.monsters[0].powers.value(PowerId::Strangle), 0);
            let demise_event = events
                .iter()
                .position(|event| {
                    matches!(
                        event,
                        Event::MonsterDamaged {
                            uid: event_uid,
                            unblocked: 9,
                            ..
                        } if *event_uid == uid
                    )
                })
                .expect("Demise publishes one damage result");
            for power in [
                PowerId::Shrink,
                PowerId::Conqueror,
                PowerId::SicEm,
                PowerId::Strangle,
            ] {
                let power_event = events
                    .iter()
                    .position(|event| {
                        matches!(
                            event,
                            Event::PowerChanged {
                                subject: Subject::Monster(event_uid),
                                power: event_power,
                                ..
                            } if *event_uid == uid && *event_power == power
                        )
                    })
                    .expect("ordered peer publishes PowerChanged");
                assert_eq!(
                    demise_event < power_event,
                    demise_first,
                    "{power:?} must remain on its authenticated side of Demise"
                );
            }
        }
    }

    #[test]
    fn demise_order_projection_does_not_require_broader_misery_clone_eligibility() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        builder.intern_monster(MonsterKind::TerrorEel).unwrap();
        let catalog = builder.build();
        for extra in [PowerId::TempStrength, PowerId::Shriek] {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            state.max_hp = 100;
            let kind = if extra == PowerId::Shriek {
                MonsterKind::TerrorEel
            } else {
                MonsterKind::Toadpole
            };
            let mut owner = HotMonster::new(kind, 20);
            owner.max_hp = 20;
            owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
            owner.misery_debuff_order.push(MiseryToken::Demise);
            if extra == PowerId::TempStrength {
                owner.powers.set(PowerId::Strength, SlotWire::Int, -7);
                owner.powers.set(PowerId::TempStrength, SlotWire::Int, -7);
            } else {
                owner.powers.set(PowerId::Shriek, SlotWire::Bool, 1);
            }
            state.monsters_mut().push(owner);

            end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();

            assert_eq!(state.monsters[0].hp, 11, "{extra:?}");
            if extra == PowerId::TempStrength {
                assert_eq!(state.monsters[0].powers.value(PowerId::TempStrength), 0);
                assert_eq!(state.monsters[0].powers.value(PowerId::Strength), 0);
            }
        }
    }

    #[test]
    fn inferred_legacy_demise_singleton_remains_exact_without_cold_publication() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        state.max_hp = 100;
        let mut owner = HotMonster::new(MonsterKind::Toadpole, 20);
        owner.max_hp = 20;
        owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
        state.monsters_mut().push(owner);

        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(state.monsters[0].hp, 11);
        assert!(state.monsters[0].misery_debuff_order.is_empty());
    }

    #[test]
    fn lethal_demise_suppresses_only_later_weak_and_vulnerable_ticks() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        for demise_first in [false, true] {
            let mut state = HotState::at_defaults();
            state.hp = 100;
            state.max_hp = 100;
            let mut owner = HotMonster::new(MonsterKind::Toadpole, 9);
            owner.max_hp = 20;
            owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
            owner.powers.set(PowerId::Weak, SlotWire::Int, 3);
            owner.powers.set(PowerId::Vuln, SlotWire::Int, 2);
            let peers = [MiseryToken::Weak, MiseryToken::Vuln];
            if !demise_first {
                for token in peers {
                    owner.misery_debuff_order.push(token);
                }
            }
            owner.misery_debuff_order.push(MiseryToken::Demise);
            if demise_first {
                for token in peers {
                    owner.misery_debuff_order.push(token);
                }
            }
            state.monsters_mut().push(owner);

            run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();

            assert!(state.monsters[0].hp <= 0);
            assert_eq!(
                state.monsters[0].powers.value(PowerId::Weak),
                if demise_first { 3 } else { 2 }
            );
            assert_eq!(
                state.monsters[0].powers.value(PowerId::Vuln),
                if demise_first { 2 } else { 1 }
            );
        }
    }

    /// A pressured Waterfall Giant (#3428) carrying Demise, about to act
    /// PRESSURIZE (loop 0), which only adds Steam Pressure.
    fn waterfall_demise_owner(hp: i32, pressure: i32) -> (HotState, Catalog) {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::WaterfallGiant).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        state.max_hp = 100;
        let mut owner = HotMonster::new(MonsterKind::WaterfallGiant, hp);
        owner.max_hp = 250;
        owner.pressure_gun_damage = 23;
        owner.loop_pos = 0;
        owner
            .powers
            .set(PowerId::SteamPressure, SlotWire::Int, pressure);
        owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
        state.monsters_mut().push(owner);
        (state, catalog)
    }

    fn push_demise_peer(state: &mut HotState, power: PowerId, token: MiseryToken, amount: i32) {
        let owner = &mut state.monsters_mut()[0];
        owner.powers.set(power, SlotWire::Int, amount);
        owner.misery_debuff_order.push(token);
    }

    fn assert_waterfall_sentinel(state: &HotState) {
        let sentinel = &state.monsters[0];
        assert!(sentinel.is_about_to_blow());
        assert_eq!(sentinel.hp, 999_999_999);
        assert_eq!(sentinel.loop_pos, 6, "the side-end RollMove keeps ABOUT");
        assert_eq!(sentinel.powers.value(PowerId::Demise), 0);
        assert!(sentinel.powers.value(PowerId::SteamPressure) > 0);
        assert!(sentinel.misery_debuff_order.is_empty());
        assert!(!state.history.over, "SteamEruption keeps the combat going");
    }

    #[test]
    fn lethal_demise_revives_a_waterfall_when_no_later_listener_exists() {
        let (mut state, catalog) = waterfall_demise_owner(9, 20);
        state.monsters_mut()[0]
            .misery_debuff_order
            .push(MiseryToken::Demise);
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_waterfall_sentinel(&state);

        // The legacy singleton (no ledger token) infers the same order.
        let (mut legacy, catalog) = waterfall_demise_owner(9, 20);
        run_enemy_phase(&mut legacy, &catalog, &mut Vec::new()).unwrap();
        assert_waterfall_sentinel(&legacy);
    }

    #[test]
    fn lethal_demise_revival_admits_a_ledger_prefix_and_inert_powers() {
        let (mut state, catalog) = waterfall_demise_owner(9, 20);
        push_demise_peer(&mut state, PowerId::Weak, MiseryToken::Weak, 2);
        state.monsters_mut()[0]
            .misery_debuff_order
            .push(MiseryToken::Demise);
        let owner = &mut state.monsters_mut()[0];
        // No AfterSideTurnEnd override (Strength, Poison, Artifact), or one
        // that leaves on the Enemy side (Doom).
        owner.powers.set(PowerId::Strength, SlotWire::Int, 2);
        owner.powers.set(PowerId::Artifact, SlotWire::Int, 1);
        owner.powers.set(PowerId::Doom, SlotWire::Int, 3);
        owner.misery_debuff_order.push(MiseryToken::Doom);
        run_enemy_phase(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_waterfall_sentinel(&state);
        assert_eq!(state.monsters[0].powers.value(PowerId::Weak), 0);
        assert_eq!(state.monsters[0].powers.value(PowerId::Strength), 0);
    }

