    #[test]
    fn demise_and_soul_fysh_intangible_follow_acquisition_order() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::SoulFysh).unwrap();
        let catalog = builder.build();

        let mut late = HotState::at_defaults();
        late.hp = 100;
        late.max_hp = 100;
        let mut late_owner = HotMonster::new(MonsterKind::SoulFysh, 221);
        late_owner.max_hp = 221;
        late_owner.loop_pos = 4;
        late_owner.powers.set(PowerId::Intangible, SlotWire::Int, 1);
        late_owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
        late_owner.powers.set(PowerId::Shrink, SlotWire::Int, 4);
        late_owner.misery_debuff_order.push(MiseryToken::Shrink);
        late_owner.misery_debuff_order.push(MiseryToken::Demise);
        late_owner.set_demise_after_intangible(true);
        let late_uid = late_owner.uid;
        late.monsters_mut().push(late_owner);

        let mut late_events = Vec::new();
        run_enemy_phase(&mut late, &catalog, &mut late_events).unwrap();
        assert_eq!(late.monsters[0].powers.value(PowerId::Intangible), 0);
        assert_eq!(late.monsters[0].powers.value(PowerId::Shrink), 3);
        assert_eq!(late.monsters[0].hp, 212, "late Demise runs after expiry");
        assert!(!late.monsters[0].demise_after_intangible());
        let late_position = |predicate: &dyn Fn(&Event) -> bool| {
            late_events.iter().position(predicate).expect("late event")
        };
        let late_intangible = late_position(&|event| {
            matches!(
                event,
                Event::PowerChanged {
                    subject: Subject::Monster(uid),
                    power: PowerId::Intangible,
                    ..
                } if *uid == late_uid
            )
        });
        let late_shrink = late_position(&|event| {
            matches!(
                event,
                Event::PowerChanged {
                    subject: Subject::Monster(uid),
                    power: PowerId::Shrink,
                    ..
                } if *uid == late_uid
            )
        });
        let late_demise = late_position(
            &|event| matches!(event, Event::MonsterDamaged { uid, unblocked: 9, .. } if *uid == late_uid),
        );
        assert!(late_intangible < late_shrink && late_shrink < late_demise);

        let mut early = HotState::at_defaults();
        early.hp = 100;
        early.max_hp = 100;
        let mut early_owner = HotMonster::new(MonsterKind::SoulFysh, 221);
        early_owner.max_hp = 221;
        early_owner.loop_pos = 3;
        early_owner.powers.set(PowerId::Demise, SlotWire::Int, 9);
        early_owner.powers.set(PowerId::Shrink, SlotWire::Int, 4);
        early_owner.misery_debuff_order.push(MiseryToken::Demise);
        early_owner.misery_debuff_order.push(MiseryToken::Shrink);
        let early_uid = early_owner.uid;
        early.monsters_mut().push(early_owner);

        let mut early_events = Vec::new();
        run_enemy_phase(&mut early, &catalog, &mut early_events).unwrap();
        assert_eq!(early.monsters[0].powers.value(PowerId::Intangible), 1);
        assert_eq!(early.monsters[0].powers.value(PowerId::Shrink), 3);
        assert_eq!(
            early.monsters[0].hp, 220,
            "early Demise is capped before expiry"
        );
        assert!(!early.monsters[0].demise_after_intangible());
        let early_demise = early_events
            .iter()
            .position(|event| {
                matches!(event, Event::MonsterDamaged { uid, unblocked: 1, .. } if *uid == early_uid)
            })
            .expect("early Demise event");
        let early_shrink = early_events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::PowerChanged {
                        subject: Subject::Monster(uid),
                        power: PowerId::Shrink,
                        ..
                    } if *uid == early_uid
                )
            })
            .expect("early Shrink event");
        let early_intangible = early_events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::PowerChanged {
                        subject: Subject::Monster(uid),
                        power: PowerId::Intangible,
                        amount: 1,
                    } if *uid == early_uid
                )
            })
            .expect("early Intangible event");
        assert!(early_demise < early_shrink && early_shrink < early_intangible);
    }

