    #[test]
    fn turn_start_ticks_fold_resources_draws_and_ordered_power_effects() {
        let mut builder = CatalogBuilder::new();
        let strike = CardIdentity {
            id: CardId::StrikeIronclad,
            upgrade: 0,
            enchantment: None,
        };
        let atom = builder.intern(strike).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        state.turn = 2;
        state.block = 11;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 30));
        state.orbs.set_slots(2);
        state.orbs.set_orbs(vec![
            HotOrb::from_parts(OrbKind::Lightning, None).unwrap(),
            HotOrb::from_parts(OrbKind::Frost, None).unwrap(),
        ]);
        for uid in 1..=8 {
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid,
                atom,
                flags: 0,
            });
        }
        for (power, amount) in [
            (PowerId::Barricade, 1),
            (PowerId::Blur, 2),
            (PowerId::Plating, 3),
            (PowerId::Demesne, 1),
            (PowerId::Pyre, 2),
            (PowerId::DrawNextTurn, 1),
            (PowerId::MachineLearning, 1),
            (PowerId::DemonForm, 3),
            (PowerId::WraithForm, 1),
            (PowerId::NoxiousFumes, 2),
            (PowerId::Countdown, 6),
            (PowerId::Neurosurge, 3),
            (PowerId::PrepTime, 4),
            (PowerId::Coolant, 2),
        ] {
            state.powers.set(power, SlotWire::Int, amount);
            if AfterSideTurnStartToken::from_power(power).is_some() {
                assert!(state.fanouts.register_after_side_turn_start(power));
            }
        }
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(state.energy, 6);
        assert_eq!(state.piles.get(PileId::Hand).len(), 8);
        assert_eq!(state.powers.value(PowerId::DrawNextTurn), 0);
        assert_eq!(state.powers.value(PowerId::Strength), 3);
        assert_eq!(state.powers.value(PowerId::Dexterity), -1);
        assert_eq!(state.monsters[0].powers.value(PowerId::Poison), 2);
        assert_eq!(state.monsters[0].powers.value(PowerId::Doom), 6);
        assert_eq!(state.powers.value(PowerId::Doom), 3);
        assert!(state.history.doom_applied_by_player_this_turn);
        assert_eq!(state.powers.value(PowerId::Vigor), 4);
        assert_eq!(state.powers.value(PowerId::Blur), 1);
        assert_eq!(state.powers.value(PowerId::Plating), 2);
        assert_eq!(state.block, 15); // Barricade/Blur retain 11; Coolant adds 2 kinds * 2.
    }

