    #[test]
    fn clarity_peer_turn_walk_executes_all_permutations_and_ending_is_a_noop() {
        use crate::hot::AfterSideTurnStartToken as Token;

        let catalog = CatalogBuilder::new().build();
        let permutations = [
            [Token::Clarity, Token::DemonForm, Token::PrepTime],
            [Token::Clarity, Token::PrepTime, Token::DemonForm],
            [Token::DemonForm, Token::Clarity, Token::PrepTime],
            [Token::DemonForm, Token::PrepTime, Token::Clarity],
            [Token::PrepTime, Token::Clarity, Token::DemonForm],
            [Token::PrepTime, Token::DemonForm, Token::Clarity],
        ];
        for order in permutations {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.max_hp = 50;
            assert!(state.fanouts.set_clarity(2));
            state.powers.set(PowerId::DemonForm, SlotWire::Int, 3);
            state.powers.set(PowerId::PrepTime, SlotWire::Int, 4);
            assert!(state.set_after_side_turn_start_power_order(&order));
            let mut events = Vec::new();
            // The in-frame (unpaused) walk owns the side-start tail (#3050).
            let _window = SetupPlayerTurnWindowGuard::enter();

            finish_player_turn_start_after_hand_choices(&mut state, &catalog, &mut events).unwrap();

            assert_eq!(state.fanouts.clarity(), 1);
            assert_eq!(state.powers.value(PowerId::Strength), 3);
            assert_eq!(state.powers.value(PowerId::Vigor), 4);
            let applied = events
                .iter()
                .filter_map(|event| match event {
                    Event::PowerChanged {
                        subject: Subject::Player,
                        power: PowerId::Strength,
                        ..
                    } => Some(Token::DemonForm),
                    Event::PowerChanged {
                        subject: Subject::Player,
                        power: PowerId::Vigor,
                        ..
                    } => Some(Token::PrepTime),
                    _ => None,
                })
                .collect::<Vec<_>>();
            let expected = order
                .into_iter()
                .filter(|token| *token != Token::Clarity)
                .collect::<Vec<_>>();
            assert_eq!(applied, expected);

            let mut ending = state.clone();
            ending.history.over = true;
            let before = (
                ending.fanouts.clarity(),
                ending.powers.value(PowerId::Strength),
                ending.powers.value(PowerId::Vigor),
            );
            finish_player_turn_start_after_hand_choices(&mut ending, &catalog, &mut Vec::new())
                .unwrap();
            assert_eq!(
                (
                    ending.fanouts.clarity(),
                    ending.powers.value(PowerId::Strength),
                    ending.powers.value(PowerId::Vigor),
                ),
                before
            );
        }
    }

    #[test]
