    #[test]
    fn resumed_hand_draw_leaves_the_side_start_tail_to_its_pause() {
        // #3050: a suspended hand draw is a `SetupPlayerTurn` pause, so native
        // `StartTurn` ran `AfterSideTurnStart` at the pause
        // (`<StartTurn>d__100` IL_06cf then IL_07bf). The resumed hook action
        // finishes `SetupPlayerTurn` and `RunAutoPrePlayPhase` only.
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.turn = 2;
        state.powers.set(PowerId::PrepTime, SlotWire::Int, 4);
        state.powers.set(PowerId::DemonForm, SlotWire::Int, 3);
        assert!(
            state
                .fanouts
                .register_after_side_turn_start(PowerId::PrepTime)
        );
        assert!(
            state
                .fanouts
                .register_after_side_turn_start(PowerId::DemonForm)
        );
        let mut events = Vec::new();

        resume_player_turn_start_after_hand_draw(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(state.powers.value(PowerId::Vigor), 0);
        assert_eq!(state.powers.value(PowerId::Strength), 0);
        assert!(
            !events.iter().any(|event| matches!(
                event,
                Event::PowerChanged {
                    power: PowerId::Vigor | PowerId::Strength,
                    ..
                }
            )),
            "the resumed remainder never re-enters the side-start tail"
        );
        assert_eq!(state.player_phase, PHASE_ORDINARY_ACTIONS);
        assert!(events.contains(&Event::TurnBegan { turn: 2 }));
    }

    // --- #3050: a paused SetupPlayerTurn choice lets StartTurn's side-start
    // tail run first (`<StartTurn>d__100` IL_06cf, then IL_07bf/IL_08b5,
    // checksum IL_0975); the resumed hook action runs only the remainder and
    // `RunAutoPrePlayPhase`.

    fn paused_setup_catalog(
        relics: &[RelicId],
        ordered: bool,
    ) -> (Catalog, crate::catalog::CardAtom) {
        let mut builder = CatalogBuilder::new();
        let strike = builder
            .intern_reachable(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        for name in ["ORANGE_DOUGH", "CHOICES_PARADOX"] {
            let pool = crate::content_tables::GENERATION_RELIC_POOLS
                .iter()
                .find_map(|(candidate, pool)| (*candidate == name).then_some(*pool))
                .unwrap();
            for id in pool {
                builder
                    .intern_reachable(CardIdentity {
                        id: *id,
                        upgrade: 0,
                        enchantment: None,
                    })
                    .unwrap();
            }
        }
        builder.set_relics_ordered(relics, ordered).unwrap();
        (builder.build(), strike)
    }

    fn paused_setup_state(strike: crate::catalog::CardAtom, turn: i16, draw: u32) -> HotState {
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.turn = turn;
        state.next_card_uid = draw + 1;
        // Orange Dough's Colorless draw needs a recorded profile (#3325).
        state.fully_unlocked_card_pool_epochs = true;
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((1..=draw).map(|uid| HotCard {
                uid,
                atom: strike,
                flags: 0,
            }));
        let seeded = crate::rng::Xoshiro256StarStar::from_seed(17);
        state.rng.set(
            crate::hot::RngStream::Generation,
            crate::hot::RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        state
    }

    fn turn_began(events: &[Event]) -> usize {
        events
            .iter()
            .filter(|event| matches!(event, Event::TurnBegan { .. }))
            .count()
    }

    #[test]
    fn gambling_chip_pause_runs_lantern_first_and_the_resume_does_not_repeat_it() {
        // fba5c41635d22930 (Vantom): native energy 4 at the opening checkpoint
        // with the Gambling Chip choice still pending.
        let (catalog, strike) =
            paused_setup_catalog(&[RelicId::RelicGamblingChip, RelicId::RelicLantern], false);
        let mut state = paused_setup_state(strike, 1, 6);
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert!(super::super::relics::relic_pending_is_exact(
            &state, &catalog
        ));
        assert_eq!(state.energy, BASE_ENERGY + 1, "Lantern ran at the pause");
        assert_eq!(state.piles.get(PileId::Hand).len(), 5);
        assert_eq!(
            turn_began(&events),
            0,
            "RunAutoPrePlayPhase waits for the remainder"
        );

        super::super::relics::resume_relic_selection(&mut state, &catalog, 0, &mut events).unwrap();

        assert!(state.pending.is_none());
        assert_eq!(
            state.energy,
            BASE_ENERGY + 1,
            "the resumed remainder skips the tail"
        );
        assert_eq!(state.player_phase, PHASE_ORDINARY_ACTIONS);
        assert_eq!(turn_began(&events), 1);
    }

