    fn exhausted_uids(state: &HotState) -> Vec<u32> {
        state
            .piles
            .get(PileId::Exhaust)
            .as_slice()
            .iter()
            .map(|card| card.uid)
            .collect()
    }

    /// #3273 witness — a one-card Hand. Toasty Mittens' prefs are non-manual
    /// with `MinSelect` 1 (`<AfterPlayerTurnStart>d__6` RVA `0x33285c`
    /// IL_005b-0061), so `FromHand` (RVA `0x3e7568` IL_0167-018d) returns the
    /// sole card with no prompt: it is exhausted and Strength applies. The
    /// side-start tail still runs once, at the pause ahead of the Hand read.
    #[test]
    fn toasty_mittens_over_one_card_exhausts_it_without_parking() {
        let (catalog, strike) =
            paused_setup_catalog(&[RelicId::RelicToastyMittens, RelicId::RelicLantern], false);
        let mut state = paused_setup_state(strike, 1, 1);
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert!(state.pending.is_none(), "one candidate parks nothing");
        assert!(state.fanouts.batch_nine_relic_pending().is_none());
        assert!(state.piles.get(PileId::Hand).is_empty());
        assert_eq!(exhausted_uids(&state), [1]);
        assert_eq!(state.powers.value(PowerId::Strength), 1);
        assert_eq!(state.energy, BASE_ENERGY + 1, "Lantern exactly once");
        assert_eq!(turn_began(&events), 1);
    }

    /// #3273 witness — the resumed (detached) route. Gambling Chip pauses
