    /// #3400 witness: the same lethal horizon on a vouched inventory runs
    /// the two relics in their recorded order, and the order shows.
    /// `LunarPastry/<AfterSideTurnEnd>d__4` (RVA `0x32a08c`) gains a Star,
    /// which Black Hole answers with 1 to the 6-HP Toadpole; then
    /// `ParryingShield/<AfterSideTurnEnd>d__4` (RVA `0x32d7b0`, Block 10)
    /// deals the killing 6. Parrying Shield first kills, and the Star is not
    /// gained: `PlayerCmd/<GainStars>d__6` (RVA `0x3eec94`) returns once the
    /// fight is ending (IL_0019-0025).
    #[test]
    fn lunar_pastry_and_parrying_shield_follow_the_vouched_inventory() {
        use crate::ids::RelicId;
        for lunar_first in [true, false] {
            let relics = if lunar_first {
                [RelicId::RelicLunarPastry, RelicId::RelicParryingShield]
            } else {
                [RelicId::RelicParryingShield, RelicId::RelicLunarPastry]
            };
            let mut builder = CatalogBuilder::new();
            builder.set_relics_ordered(&relics, true).unwrap();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.max_hp = 50;
            state.block = 10;
            state.stars = 0;
            state.powers.set(PowerId::BlackHole, SlotWire::Int, 1);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 6));
            let mut events = Vec::new();

            run_after_side_turn_end_ordinary_nonlocal(&mut state, &catalog, &mut events)
                .unwrap_or_else(|refusal| panic!("{relics:?}: {refusal:?}"));

            assert!(state.history.over, "{relics:?}");
            assert!(state.monsters[0].hp <= 0, "{relics:?}");
            assert_eq!(state.stars, i16::from(lunar_first), "{relics:?}");
        }
    }

