    fn sentry_before_hand_draw_fixture(random_power: PowerId) -> (Catalog, HotState) {
        let mut builder = CatalogBuilder::new();
        let pool: &[CardId] = match random_power {
            PowerId::CreativeAi => &crate::content_tables::CREATIVE_AI_POWER_POOL_V1101,
            PowerId::SpectrumShift => {
                &crate::content_tables::REGENT_COLORLESS_GENERATION_POOL_V1101
            }
            _ => panic!("fixture owns only represented random-pool listeners"),
        };
        for id in pool
            .iter()
            .copied()
            .chain([CardId::InfiniteBlades, CardId::SentryMode])
        {
            builder
                .intern(CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap();
        }
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.turn = 2;
        if random_power == PowerId::CreativeAi {
            state.reward_card_pool = Some(RewardPool::Defect);
            state.set_creative_ai_generation_pool(true);
        } else {
            state.reward_card_pool = Some(RewardPool::Regent);
            state.entropy_card_pool = Some(RewardPool::Regent);
            state.set_spectrum_shift_generation_pool(true);
        }
        state.fully_unlocked_card_pool_epochs = true;
        state.rng.set(
            RngStream::Generation,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        for power in [PowerId::InfiniteBlades, random_power, PowerId::SentryMode] {
            state.powers.set(power, SlotWire::Int, 1);
        }
        (builder.build(), state)
    }

    #[test]
    fn every_reachable_sentry_before_hand_draw_permutation_dispatches_in_frozen_order() {
        fn visit(
            index: usize,
            order: &mut [PowerId; 3],
            catalog: &Catalog,
            seed: &HotState,
            seen: &mut usize,
        ) {
            if index == order.len() {
                let mut state = seed.clone();
                assert!(state.fanouts.set_before_hand_draw_order(order));
                begin_player_turn(&mut state, catalog, &mut Vec::new()).unwrap();
                let ids = state
                    .piles
                    .get(PileId::Hand)
                    .as_slice()
                    .iter()
                    .map(|card| catalog.spec(card.atom).unwrap().identity.id)
                    .collect::<Vec<_>>();
                assert_eq!(ids.len(), 3);
                assert_eq!(
                    ids[order
                        .iter()
                        .position(|power| *power == PowerId::InfiniteBlades)
                        .unwrap()],
                    CardId::Shiv
                );
                assert_eq!(
                    ids[order
                        .iter()
                        .position(|power| *power == PowerId::SentryMode)
                        .unwrap()],
                    CardId::SweepingGaze
                );
                *seen += 1;
                return;
            }
            for candidate in index..order.len() {
                order.swap(index, candidate);
                visit(index + 1, order, catalog, seed, seen);
                order.swap(index, candidate);
            }
        }

        let mut seen = 0;
        for random_power in [PowerId::CreativeAi, PowerId::SpectrumShift] {
            let (catalog, seed) = sentry_before_hand_draw_fixture(random_power);
            let mut order = [PowerId::InfiniteBlades, random_power, PowerId::SentryMode];
            visit(0, &mut order, &catalog, &seed, &mut seen);
        }
        assert_eq!(seen, 12);
    }

    #[test]
    fn sentry_mode_late_turn_refusal_rolls_back_the_complete_turn_prefix() {
        let mut builder = CatalogBuilder::new();
        builder
            .intern(CardIdentity {
                id: CardId::SentryMode,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.turn = 2;
        state.energy = 0;
        state.next_generated_hook_uid = i32::MAX - 1;
        state.powers.set(PowerId::SentryMode, SlotWire::Int, 2);
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::SentryMode])
        );
        let before = state.clone();
        let mut events = vec![Event::TurnEnded { turn: 77 }];
        let before_events = events.clone();

        assert_eq!(
            begin_player_turn(&mut state, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("next_generated_hook_uid"))
        );
        assert_eq!(state, before, "energy/history/first Gaze all roll back");
        assert_eq!(events, before_events);

        let mut public = HotState::at_defaults();
        public.hp = 50;
        public.max_hp = 50;
        public.next_generated_hook_uid = i32::MAX - 1;
        public.powers.set(PowerId::SentryMode, SlotWire::Int, 2);
        assert!(
            public
                .fanouts
                .set_before_hand_draw_order(&[PowerId::SentryMode])
        );
        let before = public.clone();
        let mut events = vec![Event::TurnBegan { turn: 78 }];
        let before_events = events.clone();

        assert_eq!(
            end_player_turn(&mut public, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("next_generated_hook_uid"))
        );
        assert_eq!(
            public, before,
            "the whole public end-turn action rolls back"
        );
        assert_eq!(events, before_events);

        let mut missing_order = HotState::at_defaults();
        missing_order.hp = 50;
        missing_order.max_hp = 50;
        missing_order.energy = 1;
        missing_order.turn = 3;
        missing_order.history.round_number = 4;
        missing_order
            .powers
            .set(PowerId::SentryMode, SlotWire::Int, 2);
        assert!(missing_order.fanouts.before_hand_draw_order().is_empty());
        let before = missing_order.clone();
        let mut events = vec![Event::TurnBegan { turn: 79 }];
        let before_events = events.clone();

        assert_eq!(
            end_player_turn(&mut missing_order, &catalog, &mut events),
            Err(EngineRefusal::MalformedArgs("sentry mode turn state"))
        );
        assert_eq!(
            missing_order, before,
            "missing frozen order refuses before energy/turn/round/phase mutation"
        );
        assert_eq!(events, before_events);

        let mut incomplete_order = HotState::at_defaults();
        incomplete_order.hp = 50;
        incomplete_order.max_hp = 50;
        incomplete_order.energy = 2;
        incomplete_order.turn = 5;
        incomplete_order.history.round_number = 6;
        incomplete_order
            .powers
            .set(PowerId::SentryMode, SlotWire::Int, 1);
        incomplete_order
            .powers
            .set(PowerId::InfiniteBlades, SlotWire::Int, 1);
        assert!(
            incomplete_order
                .fanouts
                .set_before_hand_draw_order(&[PowerId::InfiniteBlades])
        );
        let before = incomplete_order.clone();
        let mut events = vec![Event::TurnBegan { turn: 80 }];
        let before_events = events.clone();

        assert_eq!(
            end_player_turn(&mut incomplete_order, &catalog, &mut events),
            Err(EngineRefusal::MalformedArgs("sentry mode turn state"))
        );
        assert_eq!(
            incomplete_order, before,
            "incomplete nonempty order refuses before silently skipping Gaze"
        );
        assert_eq!(events, before_events);
    }

    #[test]
    fn owner_listeners_preserve_shuffle_multiplicity_and_cold_generated_instances() {
        for owner in [
            RewardPool::Ironclad,
            RewardPool::Silent,
            RewardPool::Regent,
            RewardPool::Necrobinder,
            RewardPool::Defect,
        ] {
            for power in [
                PowerId::CreativeAi,
                PowerId::HelloWorld,
                PowerId::CallOfTheVoid,
            ] {
                let mut state = HotState::at_defaults();
                state.reward_card_pool = Some(owner);
                state.entropy_card_pool = Some(owner);
                state.fully_unlocked_card_pool_epochs = true;
                state.hp = 80;
                state.max_hp = 80;
                state.powers.set(power, SlotWire::Int, 3);
                assert!(state.fanouts.register_before_hand_draw(power));
                state.rng.set(
                    RngStream::Generation,
                    RngStreamState {
                        words: [1, 2, 3, 4],
                        counter: 0,
                    },
                );
                let doc = crate::boundary::HotBoundary::to_canonical(
                    &state,
                    &CatalogBuilder::new().build(),
                );
                let catalog = crate::boundary::HotBoundary::catalog_from_canonical(&doc).unwrap();
                let pool = catalog.owner_listener_pool(owner, power);
                let mut oracle = crate::rng::Xoshiro256StarStar {
                    words: [1, 2, 3, 4],
                    counter: 0,
                };
                let expected = if power == PowerId::HelloWorld {
                    let mut shuffled = pool.clone();
                    oracle.shuffle(&mut shuffled).unwrap();
                    shuffled[..3].to_vec()
                } else {
                    (0..3)
                        .map(|_| {
                            let mut shuffled = pool.clone();
                            oracle.shuffle(&mut shuffled).unwrap();
                            shuffled[0]
                        })
                        .collect::<Vec<_>>()
                };
                match power {
                    PowerId::CreativeAi => {
                        run_creative_ai_before_hand_draw(&mut state, &catalog, &mut Vec::new())
                            .unwrap()
                    }
                    PowerId::HelloWorld => {
                        run_hello_world_before_hand_draw(&mut state, &catalog, &mut Vec::new())
                            .unwrap()
                    }
                    _ => {
                        run_call_of_the_void_before_hand_draw(&mut state, &catalog, &mut Vec::new())
                            .unwrap()
                    }
                }
                let actual = state
                    .piles
                    .get(PileId::Hand)
                    .as_slice()
                    .iter()
                    .map(|c| catalog.spec(c.atom).unwrap().identity.id)
                    .collect::<Vec<_>>();
                assert_eq!(actual, expected, "{owner:?}/{power:?}");
                assert_eq!(state.rng.get(RngStream::Generation).counter, oracle.counter);
                assert_eq!(state.rng.get(RngStream::Generation).words, oracle.words);
                assert_eq!(state.next_card_uid, 3);
                assert_eq!(state.history.owner_generated_cards_combat, 3);
                for card in state.piles.get(PileId::Hand).as_slice() {
                    assert_eq!(
                        state.card_states.get(card.uid).local_ethereal(),
                        power == PowerId::CallOfTheVoid
                    );
                }
                let wire =
                    crate::boundary::HotBoundary::try_to_canonical(&state, &catalog).unwrap();
                let cold_catalog =
                    crate::boundary::HotBoundary::catalog_from_canonical(&wire).unwrap();
                let cold =
                    crate::boundary::HotBoundary::from_canonical(&wire, &cold_catalog).unwrap();
                assert_eq!(
                    crate::boundary::HotBoundary::try_to_canonical(&cold, &cold_catalog).unwrap(),
                    wire
                );
                let field = match power {
                    PowerId::CreativeAi => "creative_ai_generation_pool",
                    PowerId::HelloWorld => "hello_world_generation_pool",
                    _ => "call_of_the_void_generation_pool",
                };
                let mut explicit = wire.clone();
                explicit.player.insert(
                    field.into(),
                    serde_json::json!(pool.iter().map(|id| id.as_str()).collect::<Vec<_>>()),
                );
                let reloaded =
                    crate::boundary::HotBoundary::from_canonical(&explicit, &cold_catalog).unwrap();
                assert_eq!(
                    crate::boundary::HotBoundary::try_to_canonical(&reloaded, &cold_catalog)
                        .unwrap(),
                    explicit
                );
                explicit.player.insert(
                    field.into(),
                    serde_json::json!(pool.iter().rev().map(|id| id.as_str()).collect::<Vec<_>>()),
                );
                assert!(
                    crate::boundary::HotBoundary::from_canonical(&explicit, &cold_catalog).is_err()
                );
            }
        }
    }

    /// #3230: Creative AI beside another live BeforeHandDraw Generation
    /// consumer draws in the frozen listener snapshot's order, which is the
    /// owner's power application order
    /// (`CombatState/<IterateHookListeners>d__69::MoveNext` RVA `0x3f9720`,
    /// `Creature.Powers` AddRange IL `0x0092-0x0097`). Each listener shuffles
    /// the live Generation stream (`CreativeAiPower/<BeforeHandDraw>d__4`
    /// RVA `0x338180` IL `0x00af-0x00b4`; `HelloWorldPower/<BeforeHandDraw>d__4`
    /// RVA `0x33bfd0` IL `0x00ba-0x00da`), so the second listener reads the
    /// stream the first one left. Both acquisition orders are witnessed
    /// against an independent oracle, and they mint different hands.
    #[test]
    fn creative_ai_and_hello_world_draw_generation_in_acquisition_order() {
        let seed = [11, 22, 33, 44];
        let mut hands = Vec::new();
        for order in [
            [PowerId::CreativeAi, PowerId::HelloWorld],
            [PowerId::HelloWorld, PowerId::CreativeAi],
        ] {
            let mut state = HotState::at_defaults();
            state.reward_card_pool = Some(RewardPool::Defect);
            state.entropy_card_pool = Some(RewardPool::Defect);
            state.fully_unlocked_card_pool_epochs = true;
            state.hp = 80;
            state.max_hp = 80;
            for power in order {
                state.powers.set(power, SlotWire::Int, 1);
                assert!(state.fanouts.register_before_hand_draw(power));
            }
            assert_eq!(state.fanouts.before_hand_draw_order(), order.as_slice());
            state.rng.set(
                RngStream::Generation,
                RngStreamState {
                    words: seed,
                    counter: 0,
                },
            );
            let doc =
                crate::boundary::HotBoundary::to_canonical(&state, &CatalogBuilder::new().build());
            let catalog = crate::boundary::HotBoundary::catalog_from_canonical(&doc).unwrap();
            let mut oracle = crate::rng::Xoshiro256StarStar {
                words: seed,
                counter: 0,
            };
            let expected = order
                .iter()
                .map(|power| {
                    let mut shuffled = catalog.owner_listener_pool(RewardPool::Defect, *power);
                    oracle.shuffle(&mut shuffled).unwrap();
                    shuffled[0]
                })
                .collect::<Vec<_>>();

            let listeners = state.fanouts.before_hand_draw_order().to_vec();
            assert!(
                !run_before_hand_draw_power_suffix(
                    &mut state,
                    &catalog,
                    &listeners,
                    0,
                    &mut Vec::new()
                )
                .unwrap()
            );
            let actual = state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|c| catalog.spec(c.atom).unwrap().identity.id)
                .collect::<Vec<_>>();
            assert_eq!(actual, expected, "{order:?}");
            assert_eq!(state.rng.get(RngStream::Generation).counter, oracle.counter);
            assert_eq!(state.rng.get(RngStream::Generation).words, oracle.words);
            hands.push(actual);
        }
        // Same seed, same pools: only the order differs, and it changes what
        // both listeners mint (Creative AI draws Powers, Hello World Commons,
        // so the witness is the positional pair, not a permutation).
        assert_ne!(
            hands[0],
            vec![hands[1][1], hands[1][0]],
            "acquisition order must be observable in the draws"
        );
    }

