    #[test]
    fn aggression_moves_physical_attacks_from_discard_and_upgrades_them() {
        let mut builder = CatalogBuilder::new();
        let strike = CardIdentity {
            id: CardId::StrikeIronclad,
            upgrade: 0,
            enchantment: None,
        };
        let defend = CardIdentity {
            id: CardId::DefendIronclad,
            upgrade: 0,
            enchantment: None,
        };
        let strike_atom = builder.intern(strike).unwrap();
        let defend_atom = builder.intern(defend).unwrap();
        builder.intern_aggression_upgrade_closure().unwrap();
        let catalog = builder.build();
        let upgraded_atom = catalog
            .atom(&CardIdentity {
                upgrade: 1,
                ..strike
            })
            .unwrap();
        let mut state = HotState::at_defaults();
        state.next_card_uid = 43;
        state.powers.set(PowerId::Aggression, SlotWire::Int, 1);
        state.piles.get_mut(PileId::Discard).make_mut().extend([
            HotCard {
                uid: 41,
                atom: defend_atom,
                flags: 0,
            },
            HotCard {
                uid: 42,
                atom: strike_atom,
                flags: 0,
            },
        ]);

        tick_aggression(&mut state, &catalog, &mut Vec::new()).unwrap();

        assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 42);
        assert_eq!(
            state.piles.get(PileId::Hand).as_slice()[0].atom,
            upgraded_atom
        );
        assert_eq!(state.piles.get(PileId::Discard).as_slice()[0].uid, 41);
        assert!(!state.exact_piles);
    }

    fn aggression_retained_overflow_fixture(
        hand_len: usize,
        amount: i32,
    ) -> (HotState, Catalog, [u16; 3]) {
        let mut builder = crate::catalog::CatalogBuilder::new();
        let attacks = [CardId::StrikeIronclad, CardId::Anger, CardId::Bash].map(|id| {
            builder
                .intern(CardIdentity {
                    id,
                    upgrade: 0,
                    enchantment: None,
                })
                .unwrap()
        });
        let defend = builder
            .intern(CardIdentity {
                id: CardId::DefendIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        builder.intern_aggression_upgrade_closure().unwrap();
        let catalog = builder.build();
        let upgraded = attacks.map(|atom| {
            let identity = catalog.spec(atom).unwrap().identity;
            catalog
                .atom(&CardIdentity {
                    upgrade: identity.upgrade + 1,
                    ..identity
                })
                .unwrap()
        });
        let mut state = HotState::at_defaults();
        state.next_card_uid = 100;
        state.powers.set(PowerId::Aggression, SlotWire::Int, amount);
        state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .extend((0..hand_len).map(|index| crate::hot::HotCard {
                uid: 20 + index as u32,
                atom: defend,
                flags: 0,
            }));
        state.piles.get_mut(PileId::Discard).make_mut().extend([
            crate::hot::HotCard {
                uid: 1,
                atom: defend,
                flags: 0,
            },
            crate::hot::HotCard {
                uid: 10,
                atom: attacks[0],
                flags: 0,
            },
            crate::hot::HotCard {
                uid: 11,
                atom: attacks[1],
                flags: 0,
            },
            crate::hot::HotCard {
                uid: 12,
                atom: attacks[2],
                flags: 0,
            },
            crate::hot::HotCard {
                uid: 2,
                atom: defend,
                flags: 0,
            },
        ]);
        state.rng.set(
            RngStream::Sel,
            RngStreamState {
                words: [13, 14, 15, 16],
                counter: 0,
            },
        );
        (state, catalog, upgraded)
    }

    #[test]
    fn aggression_serially_redirects_retained_hand_overflow_and_reappends_discard() {
        let expected_rng = RngStreamState {
            words: [
                1_055_531_162_664_991,
                1_835_037,
                262_161,
                422_214_478_331_904,
            ],
            counter: 2,
        };
        let (mut nine, catalog, upgraded) = aggression_retained_overflow_fixture(9, 3);
        let sibling = nine.clone();
        let mut events = Vec::new();
        tick_aggression(&mut nine, &catalog, &mut events).unwrap();
        assert_eq!(sibling.piles.get(PileId::Hand).len(), 9);
        assert_eq!(sibling.piles.get(PileId::Discard).len(), 5);
        assert_eq!(nine.rng.get(RngStream::Sel), expected_rng);
        assert_eq!(
            nine.piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [20, 21, 22, 23, 24, 25, 26, 27, 28, 11]
        );
        assert_eq!(
            nine.piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [1, 2, 12, 10]
        );
        assert_eq!(nine.piles.get(PileId::Hand).as_slice()[9].atom, upgraded[1]);
        assert_eq!(
            nine.piles.get(PileId::Discard).as_slice()[2].atom,
            upgraded[2]
        );
        assert_eq!(
            nine.piles.get(PileId::Discard).as_slice()[3].atom,
            upgraded[0]
        );
        assert_eq!(
            events,
            [
                Event::CardResolved {
                    uid: 11,
                    pile: PileId::Hand,
                },
                Event::CardResolved {
                    uid: 12,
                    pile: PileId::Discard,
                },
                Event::CardResolved {
                    uid: 10,
                    pile: PileId::Discard,
                },
            ]
        );

        let (mut full, catalog, upgraded) = aggression_retained_overflow_fixture(10, 3);
        tick_aggression(&mut full, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(full.piles.get(PileId::Hand).len(), 10);
        assert_eq!(
            full.piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [1, 2, 11, 12, 10]
        );
        assert_eq!(
            full.piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .skip(2)
                .map(|card| card.atom)
                .collect::<Vec<_>>(),
            [upgraded[1], upgraded[2], upgraded[0]]
        );
        assert_eq!(full.rng.get(RngStream::Sel), expected_rng);
    }

