    /// A local temporary-stat carrier (`state.temp_strength` or the player's
    /// `TempDexterity`) at 2, registered in the side-end ledger, beside a
    /// Toadpole the Sleight arm would target if it were enemy-owned.
    fn temporary_stat_expiry_fixture(temporary: PowerId) -> (Catalog, HotState) {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.player_phase = PHASE_ORDINARY_ACTIONS;
        state.powers.set(PowerId::Strength, SlotWire::Int, 1);
        state.powers.set(PowerId::Dexterity, SlotWire::Int, 1);
        if temporary == PowerId::TempStrength {
            state.temp_strength = 2;
        } else {
            state.powers.set(temporary, SlotWire::Int, 2);
        }
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 40));
        hydrate_after_side_turn_end_power_order_for_test(&mut state);
        (catalog, state)
    }

    /// #2951, replacing the #1539 Python-parity refusal. The expiry's one
    /// `PowerCmd::Apply<StrengthPower|DexterityPower>` (`0x348ba8`
    /// IL_00a3-IL_00c4, `0x348498` IL_00a4-IL_00c4) is player-owned with the
    /// player as applier, and every represented listener returns before its
    /// effect: Vicious on `isinst VulnerablePower` (`0x34a6f8`
    /// IL_004a-IL_0057), Shroud on `isinst DoomPower` (`0x3446a4`
    /// IL_0030-IL_003d), Sleight of Flesh on `power.Owner.IsEnemy` (`0x344dc4`
    /// IL_0050-IL_0062), Sword Sage on `isinst SwordSagePower` (`0xa902c`
    /// IL_000c-IL_0019). So each listener set, alone or all four in either
    /// acquisition order, must end the turn exactly as the listener-free
    /// control does: same events, same player, same monsters, same piles.
    #[test]
    fn temporary_stat_expiry_walks_every_represented_listener_inertly() {
        use PowerId::{Shroud, SleightOfFlesh, SwordSage, Vicious};
        let listener_sets: [&[PowerId]; 6] = [
            &[Vicious],
            &[Shroud],
            &[SleightOfFlesh],
            &[SwordSage],
            &[Vicious, Shroud, SleightOfFlesh, SwordSage],
            &[SwordSage, SleightOfFlesh, Shroud, Vicious],
        ];
        for temporary in [PowerId::TempStrength, PowerId::TempDexterity] {
            let (catalog, control) = temporary_stat_expiry_fixture(temporary);
            let mut expected = control.clone();
            let mut expected_events = Vec::new();
            end_player_turn(&mut expected, &catalog, &mut expected_events).unwrap();
            assert_eq!(expected.temp_strength, 0);
            assert_eq!(expected.powers.value(PowerId::TempDexterity), 0);
            assert_eq!(expected.powers.value(PowerId::Strength), 1);
            assert_eq!(expected.powers.value(PowerId::Dexterity), 1);

            for listeners in listener_sets {
                let mut state = control.clone();
                for (amount, listener) in (3..).zip(listeners.iter().copied()) {
                    state.powers.set(listener, SlotWire::Int, amount);
                }
                assert!(
                    state
                        .fanouts
                        .set_after_power_amount_changed_order(listeners)
                );
                let mut events = Vec::new();
                end_player_turn(&mut state, &catalog, &mut events).unwrap_or_else(|refusal| {
                    panic!("{temporary:?} with {listeners:?} refused: {refusal:?}")
                });

                let label = format!("{temporary:?} with {listeners:?}");
                assert_eq!(events, expected_events, "{label}: events");
                assert_eq!(state.hp, expected.hp, "{label}: hp");
                assert_eq!(state.block, expected.block, "{label}: block");
                assert_eq!(state.temp_strength, 0, "{label}: temp strength");
                for power in [
                    PowerId::Strength,
                    PowerId::Dexterity,
                    PowerId::TempDexterity,
                ] {
                    assert_eq!(
                        state.powers.value(power),
                        expected.powers.value(power),
                        "{label}: {power:?}"
                    );
                }
                assert_eq!(state.monsters, expected.monsters, "{label}: monsters");
                assert_eq!(state.piles, expected.piles, "{label}: piles");
                assert_eq!(state.history, expected.history, "{label}: history");
                assert_eq!(
                    &*state.fanouts.after_power_amount_changed_order(),
                    listeners,
                    "{label}: the walk leaves its acquisition order alone"
                );
            }
        }
    }

    /// The listener walk is still authenticated: a recorded order that names
    /// a listener the player does not hold, omits one that is live, or
    /// repeats one is a malformed ledger, and it refuses before `TurnEnded`
    /// or any mutation, exactly as the #1539 preflight did.
    #[test]
    fn temporary_stat_expiry_refuses_a_malformed_listener_order_before_mutation() {
        use PowerId::{Shroud, SleightOfFlesh, Vicious};
        let cases: [(&[PowerId], &[PowerId]); 3] = [
            // A recorded Sleight row with no Sleight of Flesh power.
            (&[], &[SleightOfFlesh]),
            // A live Vicious missing from the recorded order.
            (
                &[Vicious, SleightOfFlesh, Shroud],
                &[SleightOfFlesh, Shroud],
            ),
            // A duplicated row.
            (&[SleightOfFlesh], &[SleightOfFlesh, SleightOfFlesh]),
        ];
        for temporary in [PowerId::TempStrength, PowerId::TempDexterity] {
            for (held, recorded) in cases {
                let (catalog, mut state) = temporary_stat_expiry_fixture(temporary);
                for power in held.iter().copied() {
                    state.powers.set(power, SlotWire::Int, 3);
                }
                assert!(state.fanouts.set_after_power_amount_changed_order(recorded));
                assert!(!crate::engine::damage::player_type_one_listener_order_is_exact(&state));
                let before = state.clone();
                let mut events = vec![Event::TurnEnded {
                    turn: state.turn - 1,
                }];
                let before_events = events.clone();

                assert_eq!(
                    end_player_turn(&mut state, &catalog, &mut events),
                    Err(EngineRefusal::MalformedArgs(
                        "after-power-amount-changed listener order"
                    )),
                    "{temporary:?} {held:?} {recorded:?}"
                );
                assert_eq!(state, before, "{temporary:?} refusal mutated state");
                assert_eq!(
                    events, before_events,
                    "{temporary:?} refusal emitted events"
                );
            }
        }
    }

    #[test]
    fn enemy_doom_waits_until_every_monster_has_acted_then_uses_death_cleanup() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        let mut doomed = HotMonster::new(MonsterKind::Toadpole, 4);
        doomed.powers.set(PowerId::Doom, SlotWire::Int, 4);
        doomed.powers.set(PowerId::Poison, SlotWire::Int, 2);
        state.monsters_mut().push(doomed);
        let mut events = Vec::new();

        run_enemy_phase(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(state.hp, 88); // The Toadpole's three 4-damage hits precede Doom's kill.
        assert_eq!(state.monsters[0].hp, 0);
        assert_eq!(state.monsters[0].powers.value(PowerId::Doom), 0);
        assert_eq!(state.monsters[0].powers.value(PowerId::Poison), 0);
        assert!(state.history.over);
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, Event::MonsterDamaged { .. }))
        );

        let mut ended = HotState::at_defaults();
        ended.history.over = true;
        let mut doomed = HotMonster::new(MonsterKind::Toadpole, 4);
        doomed.powers.set(PowerId::Doom, SlotWire::Int, 4);
        ended.monsters_mut().push(doomed);
        let before = ended.clone();
        doom_enemy_side_end(&mut ended, &CatalogBuilder::new().build(), &mut Vec::new()).unwrap();
        assert_eq!(ended, before, "IsOverOrEnding suppresses the Doom batch");
    }

    /// A Gremlin Horn state with `draws` Strikes in the draw pile and one
    /// Toadpole per `(hp, doom)` row, uids in roster order (#3166).
    fn gremlin_horn_roster(rows: &[(i32, i32)], draws: u32) -> (HotState, Catalog) {
        let mut builder = CatalogBuilder::new();
        let atom = builder
            .intern(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.fanouts.set_gremlin_horn_owned(true);
        for uid in 0..draws {
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid,
                atom,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        }
        state.next_card_uid = draws;
        for (uid, &(hp, doom)) in rows.iter().enumerate() {
            let mut monster = HotMonster::new(MonsterKind::Toadpole, hp);
            monster.uid = uid as u32;
            if doom > 0 {
                monster.powers.set(PowerId::Doom, SlotWire::Int, doom);
            }
            state.monsters_mut().push(monster);
        }
        (state, catalog)
    }

    /// #3166 (fda9a60c2984af50, f692cad2797d9b2a): enemy Doom kills with
    /// Gremlin Horn owned used to reach the catalogless death entry and
    /// refuse "Gremlin Horn death catalog". `DoomPower/<DoomKill>d__6`
    /// (`0x3392c8`) awaits one `CreatureCmd.Kill` per doomed creature
    /// (IL_00df), and each Kill's AfterDeath walk reaches
    /// `GremlinHorn/<AfterDeath>d__6` (`0x326170`): GainEnergy (IL_0062)
    /// then Draw (IL_00d9). Two doomed Toadpoles beside a survivor therefore
    /// grant two energy and two cards; a lone doomed Toadpole ends the
    /// combat, and the ending gate suppresses both.
    #[test]
    fn enemy_doom_kills_run_gremlin_horn_per_death_with_the_catalog() {
        let (mut state, catalog) = gremlin_horn_roster(&[(4, 4), (50, 0), (7, 9)], 3);
        let energy = state.energy;
        doom_enemy_side_end(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(
            state.monsters.iter().map(|m| m.hp).collect::<Vec<_>>(),
            [0, 50, 0]
        );
        assert!(!state.history.over);
        assert_eq!(state.energy, energy + 2);
        assert_eq!(state.piles.get(PileId::Hand).len(), 2);
        assert_eq!(state.piles.get(PileId::Draw).len(), 1);

        let (mut lone, catalog) = gremlin_horn_roster(&[(4, 4)], 1);
        let energy = lone.energy;
        doom_enemy_side_end(&mut lone, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(lone.monsters[0].hp, 0);
        assert!(lone.history.over);
        assert_eq!(lone.energy, energy, "the ending gate suppresses GainEnergy");
        assert_eq!(lone.piles.get(PileId::Draw).len(), 1, "and Draw");
    }

    /// #3166 (fdbe7eba832f6b12): a Hailstorm kill with Gremlin Horn owned.
    /// `HailstormPower/<BeforeSideTurnEnd>d__10` (`0x33ba50`) awaits one
    /// `CreatureCmd.Damage` over `HittableEnemies` (IL_009f-IL_00bb), so the
    /// catalog-bearing batch commits both Toadpoles before the dead one's
    /// AfterDeath walk runs Gremlin Horn's GainEnergy + Draw. Before the fix
    /// the per-target catalogless loop refused.
    #[test]
    fn hailstorm_kill_runs_gremlin_horn_with_the_catalog() {
        let (mut state, catalog) = gremlin_horn_roster(&[(6, 0), (50, 0)], 1);
        state.powers.set(PowerId::Hailstorm, SlotWire::Int, 6);
        assert!(
            state
                .fanouts
                .register_before_side_turn_end(PowerId::Hailstorm)
        );
        state.orbs.set_slots(1);
        state
            .orbs
            .set_orbs(vec![HotOrb::from_parts(OrbKind::Frost, None).unwrap()]);
        let energy = state.energy;
        run_before_side_turn_end_player_powers(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(
            state.monsters.iter().map(|m| m.hp).collect::<Vec<_>>(),
            [0, 44]
        );
        assert!(!state.history.over);
        assert_eq!(state.energy, energy + 1);
        assert_eq!(state.piles.get(PileId::Hand).len(), 1);
        assert!(state.piles.get(PileId::Draw).is_empty());
    }

    /// #3172: a due Bomb with Gremlin Horn owned used to reach the
    /// catalogless per-target damage entry and refuse "Gremlin Horn death
    /// catalog". `TheBombPower/<BeforeSideTurnEnd>d__9` (`0x349244`) awaits
    /// ONE `CreatureCmd.Damage` over `HittableEnemies` (IL_01f7-IL_0212), so
    /// all three Toadpoles are committed before either death's AfterDeath
    /// walk: two deaths beside a survivor grant two energy and two cards. A
    /// Bomb that kills the whole roster ends the combat, and the ending gate
    /// suppresses the Horn for both deaths even though the first death's
    /// walk runs before the second is processed.
    #[test]
    fn the_bomb_kills_run_gremlin_horn_per_death_with_the_catalog() {
        let (mut state, catalog) = gremlin_horn_roster(&[(6, 0), (50, 0), (7, 0)], 3);
        add_test_bomb(&mut state, 1, 40);
        let energy = state.energy;
        run_before_side_turn_end_player_powers(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert!(state.fanouts.the_bomb_instances_are_empty());
        assert_eq!(
            state
                .monsters
                .iter()
                .map(|m| m.hp.max(0))
                .collect::<Vec<_>>(),
            [0, 10, 0]
        );
        assert!(!state.history.over);
        assert_eq!(state.energy, energy + 2);
        assert_eq!(state.piles.get(PileId::Hand).len(), 2);
        assert_eq!(state.piles.get(PileId::Draw).len(), 1);

        let (mut wiped, catalog) = gremlin_horn_roster(&[(6, 0), (7, 0)], 2);
        add_test_bomb(&mut wiped, 1, 40);
        let energy = wiped.energy;
        run_before_side_turn_end_player_powers(&mut wiped, &catalog, &mut Vec::new()).unwrap();
        assert!(wiped.history.over);
        assert_eq!(
            wiped.energy, energy,
            "the ending gate suppresses GainEnergy"
        );
        assert_eq!(wiped.piles.get(PileId::Draw).len(), 2, "and Draw");
    }

    /// A Phrog Parasite at `hp` with lethal-enough Poison, seeded Niche.
    fn poisoned_phrog_state(hp: i32, poison: i32) -> (HotState, Catalog) {
        let mut builder = crate::catalog::CatalogBuilder::new();
        builder.intern_monster(MonsterKind::PhrogParasite).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 80;
        state.max_hp = 80;
        state.turn = 6;
        state.player_phase = PHASE_ORDINARY_ACTIONS;
        state.player_side_active = true;
        state.exact_piles = true;
        state.rng.set(
            RngStream::Niche,
            crate::hot::RngStreamState {
                words: crate::rng::Xoshiro256StarStar::from_seed(11).words,
                counter: 0,
            },
        );
        let mut phrog = HotMonster::new(MonsterKind::PhrogParasite, hp);
        phrog.max_hp = 66;
        phrog.loop_pos = 1;
        phrog.powers.set(PowerId::Poison, SlotWire::Int, poison);
        phrog.poison_uid = 0;
        phrog.misery_debuff_order.push(MiseryToken::Poison);
        state.next_poison_uid = 1;
        state.monsters_mut().push(phrog);
        (state, catalog)
    }

    /// 0QQ4T432GXT6 node 11: the enemy side's Poison tick kills the Phrog
    /// and `InfestedPower.AfterDeath` adds four Wrigglers after
    /// `SwitchSides`. They are `SpawnedThisTurn`, so `Creature.TakeTurn`
    /// (`<TakeTurn>d__140` RVA `0x3db0d0` IL_003a-IL_0044) skips them this
    /// enemy turn; the next performs the unperformed `SPAWNED_MOVE`, and only
    /// the one after bites (native: no damage and no Infection until turn 8).
    #[test]
    fn wrigglers_added_by_the_enemy_side_start_skip_that_enemy_turn() {
        let (mut state, catalog) = poisoned_phrog_state(3, 5);

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert_eq!(state.monsters.len(), 5);
        assert!(
            state.monsters[1..].iter().all(|monster| monster.spawn_noop),
            "no Wriggler acted in the turn that added it"
        );
        assert_eq!(state.hp, 80);

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert!(
            state.monsters[1..]
                .iter()
                .all(|monster| !monster.spawn_noop)
        );
        assert_eq!(state.hp, 80, "SPAWNED_MOVE does nothing");
        assert!(state.piles.get(PileId::Discard).is_empty());

        end_player_turn(&mut state, &catalog, &mut Vec::new()).unwrap();
        assert!(state.hp < 80, "wriggler1/wriggler3 bite on the third turn");
    }

    /// Only the Wriggler's unperformed SPAWNED shape is modeled for a creature
    /// the enemy side start adds; any other such creature refuses by name.
    #[test]
    fn enemy_side_start_act_roster_refuses_an_unmodeled_added_creature() {
        let (mut state, _) = poisoned_phrog_state(66, 0);
        let switched = SwitchedRoster {
            len: 1,
            max_uid: Some(0),
        };
        assert_eq!(enemy_side_start_act_roster(&state, switched), Ok(None));
        let mut wriggler = HotMonster::new(MonsterKind::Wriggler, 18);
        wriggler.uid = 1;
        wriggler.spawn_noop = true;
        state.monsters_mut().push(wriggler);
        assert_eq!(
            enemy_side_start_act_roster(&state, switched),
            Ok(Some(vec![0]))
        );
        state.monsters_mut()[1].spawn_noop = false;
        assert_eq!(
            enemy_side_start_act_roster(&state, switched),
            Err(EngineRefusal::MonsterLoopNotModeled(MonsterKind::Wriggler))
        );
        // A creature removed while another was added cannot hide the add.
        let removed = SwitchedRoster {
            len: 2,
            max_uid: Some(0),
        };
        state.monsters_mut()[1].spawn_noop = true;
        assert_eq!(
            enemy_side_start_act_roster(&state, removed),
            Err(EngineRefusal::MalformedArgs(
                "enemy side start removed a creature"
            ))
        );
    }

    /// #3172: a lethal Poison tick with Gremlin Horn owned. Each trigger of
    /// `PoisonPower.AfterSideTurnStart` is one `CreatureCmd.Damage`; the
    /// dying Toadpole's AfterDeath walk reaches `GremlinHorn/<AfterDeath>d__6`
    /// (`0x326170`) GainEnergy (IL_0062) + Draw (IL_00d9) with the side
    /// start's catalog instead of refusing "Gremlin Horn death catalog". The
    /// survivor keeps combat running, so the Horn is not ending-gated.
    #[test]
    fn poison_tick_kill_runs_gremlin_horn_with_the_catalog() {
        let (mut state, catalog) = gremlin_horn_roster(&[(3, 0), (50, 0)], 1);
        let poisoned = &mut state.monsters_mut()[0];
        poisoned.powers.set(PowerId::Poison, SlotWire::Int, 5);
        poisoned.poison_uid = 0;
        poisoned.misery_debuff_order.push(MiseryToken::Poison);
        state.next_poison_uid = 1;
        let energy = state.energy;
        assert!(
            super::super::damage::tick_monster_poison_after_catalog_auth(
                &mut state,
                &catalog,
                &mut Vec::new(),
            )
            .unwrap()
        );
        assert_eq!(
            state
                .monsters
                .iter()
                .map(|m| m.hp.max(0))
                .collect::<Vec<_>>(),
            [0, 50]
        );
        assert!(!state.history.over);
        assert_eq!(state.energy, energy + 1);
        assert_eq!(state.piles.get(PileId::Hand).len(), 1);
        assert!(state.piles.get(PileId::Draw).is_empty());

        // The public catalogless tick still refuses by design: it genuinely
        // has no catalog for the Horn's Draw.
        let (mut catalogless, _) = gremlin_horn_roster(&[(3, 0), (50, 0)], 1);
        let poisoned = &mut catalogless.monsters_mut()[0];
        poisoned.powers.set(PowerId::Poison, SlotWire::Int, 5);
        poisoned.poison_uid = 0;
        poisoned.misery_debuff_order.push(MiseryToken::Poison);
        catalogless.next_poison_uid = 1;
        let before = catalogless.clone();
        assert_eq!(
            super::super::damage::tick_monster_poison(&mut catalogless, &mut Vec::new()),
            Err(EngineRefusal::MalformedArgs("Gremlin Horn death catalog"))
        );
        assert_eq!(catalogless, before);
    }

