    /// #3159 witness: Self-Forming Clay's relic hook applies its own power.
    /// A fully blocked hit grants nothing (UnblockedDamage > 0, RVA
    /// `0x330ae4` IL_0049-IL_0055); each unblocked hit stacks 3 into ONE
    /// SelfFormingClayPower listener; BlockNextTurn is never touched.
    #[test]
    fn self_forming_clay_relic_stacks_its_own_power_not_block_next_turn() {
        let mut builder = CatalogBuilder::new();
        builder
            .set_relics(&[crate::ids::RelicId::RelicSelfFormingClay])
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 40;
        state.max_hp = 40;
        state.block = 2;
        state.fanouts.set_self_forming_clay_owned(true);
        let mut events = Vec::new();

        super::super::damage::damage_player_from_card_with_catalog(
            &mut state,
            &catalog,
            2,
            true,
            &mut events,
        )
        .unwrap();
        assert_eq!(state.hp, 40);
        assert_eq!(state.powers.value(PowerId::SelfFormingClayPower), 0);
        assert!(state.fanouts.after_block_cleared_order().is_empty());

        for expected in [3, 6] {
            super::super::damage::damage_player_from_card_with_catalog(
                &mut state,
                &catalog,
                4,
                true,
                &mut events,
            )
            .unwrap();
            assert_eq!(state.powers.value(PowerId::SelfFormingClayPower), expected);
        }
        assert_eq!(state.hp, 32);
        assert_eq!(state.powers.value(PowerId::BlockNextTurn), 0);
        assert_eq!(
            state.fanouts.after_block_cleared_order(),
            &[PowerId::SelfFormingClayPower]
        );
    }

    /// #3159 witness: BlockNextTurnPower and SelfFormingClayPower are two
    /// `AfterBlockCleared` listeners walked in acquisition order, each with
    /// its own GainBlock and its own `AfterBlockGained` walk (Juggernaut
    /// fires once per grant), then each removes itself.
    #[test]
    fn self_forming_clay_power_grants_separately_in_acquisition_order() {
        for clay_first in [false, true] {
            let catalog = CatalogBuilder::new().build();
            let mut state = HotState::at_defaults();
            state.turn = 2;
            state.powers.set(PowerId::Juggernaut, SlotWire::Int, 2);
            assert!(
                state
                    .fanouts
                    .register_after_block_gained(PowerId::Juggernaut)
            );
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 50));
            let mut events = Vec::new();
            if clay_first {
                super::super::damage::apply_self_forming_clay_power(&mut state, 3, &mut events)
                    .unwrap();
            }
            super::super::damage::apply_block_next_turn(&mut state, 7, &mut events).unwrap();
            super::super::damage::apply_self_forming_clay_power(&mut state, 3, &mut events)
                .unwrap();
            if !clay_first {
                super::super::damage::apply_self_forming_clay_power(&mut state, 3, &mut events)
                    .unwrap();
            }
            let expected_order: &[PowerId] = if clay_first {
                &[PowerId::SelfFormingClayPower, PowerId::BlockNextTurn]
            } else {
                &[PowerId::BlockNextTurn, PowerId::SelfFormingClayPower]
            };
            assert_eq!(state.fanouts.after_block_cleared_order(), expected_order);
            assert_eq!(state.powers.value(PowerId::SelfFormingClayPower), 6);
            assert_eq!(state.powers.value(PowerId::BlockNextTurn), 7);
            events.clear();

            begin_player_turn(&mut state, &catalog, &mut events).unwrap();

            assert_eq!(state.block, 13);
            assert_eq!(state.powers.value(PowerId::SelfFormingClayPower), 0);
            assert_eq!(state.powers.value(PowerId::BlockNextTurn), 0);
            assert!(state.fanouts.after_block_cleared_order().is_empty());
            let gains: Vec<i32> = events
                .iter()
                .filter_map(|event| match event {
                    Event::PlayerBlockGained { amount, .. } => Some(*amount),
                    _ => None,
                })
                .collect();
            assert_eq!(gains, if clay_first { vec![6, 7] } else { vec![7, 6] });
            assert_eq!(
                state.monsters[0].hp, 46,
                "Juggernaut answers each of the two grants"
            );
        }
    }

    /// #3159 witness: the listener array holds two delayed-Block powers; a
