    #[test]
    fn knights_prepare_preserves_branch_order_and_exact_rng_consumption() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::FlailKnight).unwrap();
        builder.intern_monster(MonsterKind::SpectralKnight).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        let mut flail = HotMonster::new(MonsterKind::FlailKnight, 108);
        assert!(flail.random_ai.set_next(Some(2)));
        assert!(flail.random_ai.set_log(&[2]));
        let mut spectral = HotMonster::new(MonsterKind::SpectralKnight, 97);
        assert!(spectral.random_ai.set_next(Some(0)));
        assert!(spectral.random_ai.set_log(&[0]));
        state.monsters_mut().extend([flail, spectral]);
        // Nonzero stream words with an exact-zero first output exercise the
        // native subtract-then-<=0 edge; no mocked random selector.
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: [1, 0, 2, 3],
                counter: 0,
            },
        );
        prepare_random_ai(&mut state, &catalog).unwrap();
        assert_eq!(state.rng.get(RngStream::Ai).counter, 1);
        assert_eq!(state.monsters[0].random_ai.next(), Some(0));
        assert_eq!(state.monsters[1].random_ai.next(), Some(1));
        // HEX consumed no draw. A subsequent SLASH traversal does consume one,
        // even though only FLAME has positive weight; an exact zero repeats SLASH.
        state.monsters_mut()[0].hp = 0;
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: [1, 0, 2, 3],
                counter: 0,
            },
        );
        prepare_random_ai(&mut state, &catalog).unwrap();
        assert_eq!(state.rng.get(RngStream::Ai).counter, 1);
        assert_eq!(state.monsters[1].random_ai.next(), Some(1));
        assert!(valid_random_ai_state(&state.monsters[1], 3));
        let mut saw_repeat = false;
        let mut saw_flame = false;
        for seed in 0..32 {
            let mut candidate = state.clone();
            assert!(candidate.monsters_mut()[1].random_ai.set_log(&[0, 1]));
            let rng = Xoshiro256StarStar::from_seed(seed);
            candidate.rng.set(
                RngStream::Ai,
                RngStreamState {
                    words: rng.words,
                    counter: 0,
                },
            );
            prepare_random_ai(&mut candidate, &catalog).unwrap();
            saw_repeat |= candidate.monsters[1].random_ai.next() == Some(1);
            saw_flame |= candidate.monsters[1].random_ai.next() == Some(2);
            assert_eq!(candidate.rng.get(RngStream::Ai).counter, 1);
            // Two SLASHes disable SLASH except the exact-zero edge above.
            assert!(candidate.monsters_mut()[1].random_ai.set_next(Some(1)));
            assert!(candidate.monsters_mut()[1].random_ai.set_log(&[0, 1, 1]));
            candidate.rng.set(
                RngStream::Ai,
                RngStreamState {
                    words: rng.words,
                    counter: 0,
                },
            );
            prepare_random_ai(&mut candidate, &catalog).unwrap();
            assert_eq!(candidate.monsters[1].random_ai.next(), Some(2));
        }
        assert!(
            saw_repeat && saw_flame,
            "SLASH allows a second consecutive attack"
        );
        let mut malformed = state.monsters[1].clone();
        assert!(malformed.random_ai.set_next(Some(2)));
        assert!(malformed.random_ai.set_log(&[0, 2]));
        assert!(!valid_random_ai_state(&malformed, 3));
        state.monsters_mut()[1] = malformed;
        let before = state.rng.get(RngStream::Ai);
        assert!(prepare_random_ai(&mut state, &catalog).is_err());
        assert_eq!(state.rng.get(RngStream::Ai), before);
    }

