    /// The RAND is one `NextFloat(6.0)` over three equal weight-2 windows, in
    /// `AddBranch` order WRITHE / BULK / CONSTRICT — table positions 0 / 2 / 1.
    /// It is spent in the shared roster-order `MonsterAi` pass, so it must
    /// advance `RngStream::Ai` exactly once (I6).
    #[test]
    fn the_reattach_rand_spends_one_shared_ai_draw_across_its_three_windows() {
        let catalog = CatalogBuilder::new().build();
        let mut base = HotState::at_defaults();
        let mut segment = HotMonster::new(MonsterKind::DecimillipedeSegment, 25);
        segment.max_hp = 48;
        segment.loop_pos = 1;
        segment.revive_stage = super::super::monsters::SEGMENT_REVIVE_RAND;
        base.monsters_mut().push(segment);
        base.monsters_mut()
            .push(HotMonster::new(MonsterKind::DecimillipedeSegment, 40));

        let mut seen = std::collections::BTreeSet::new();
        for seed in 0_u64..64 {
            let mut state = base.clone();
            let seeded = Xoshiro256StarStar::from_seed(seed);
            state.rng.set(
                RngStream::Ai,
                RngStreamState {
                    words: seeded.words,
                    counter: seeded.counter,
                },
            );
            let before = state.rng.get(RngStream::Ai).counter;

            prepare_random_ai(&mut state, &catalog).unwrap();

            assert_eq!(
                state.rng.get(RngStream::Ai).counter,
                before + 1,
                "exactly one MonsterAi draw per reattach roll"
            );
            assert_eq!(state.monsters[0].revive_stage, 0);
            seen.insert(state.monsters[0].loop_pos);
        }
        assert_eq!(
            seen,
            [0, 1, 2].into_iter().collect(),
            "all three equal-weight branches are reachable"
        );
    }

