    #[test]
    fn rat_roll_pins_readiness_cooldown_repeat_and_use_once() {
        let mut base = HotState::at_defaults();
        let mut actor = rat_for_turn(0, RAT_SCRATCH_INDEX, 0);
        assert!(
            actor
                .random_ai
                .set_log(&[RAT_SCREECH_INDEX, RAT_SCRATCH_INDEX])
        );
        base.monsters_mut().extend([
            actor,
            rat_for_turn(1, RAT_DISEASE_BITE_INDEX, 2),
            rat_for_turn(2, RAT_SCREECH_INDEX, 2),
        ]);
        assert_eq!(rat_can_summon(&base, 0), Ok(true));

        let seed = (0_u64..256)
            .find(|seed| {
                let mut state = base.clone();
                let seeded = Xoshiro256StarStar::from_seed(*seed);
                state.rng.set(
                    RngStream::Ai,
                    RngStreamState {
                        words: seeded.words,
                        counter: seeded.counter,
                    },
                );
                roll_rat_intent(&mut state, 0).unwrap();
                state.monsters[0].random_ai.next() == Some(RAT_CALL_FOR_BACKUP_INDEX)
            })
            .expect("the 3/4 CALL branch must be reachable");

        let seeded = Xoshiro256StarStar::from_seed(seed);
        base.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        roll_rat_intent(&mut base, 0).unwrap();
        assert_eq!(base.rng.get(RngStream::Ai).counter, 1);
        assert_eq!(
            base.monsters[0].random_ai.next(),
            Some(RAT_CALL_FOR_BACKUP_INDEX)
        );
        assert_eq!(
            base.monsters[0].random_ai.once_at(0),
            Some(RAT_CALL_FOR_BACKUP_INDEX)
        );

        // The same RNG state with the call already used leaves Disease Bite
        // as the sole branch: Scratch cannot repeat and Screech is cooling
        // down across the complete trailing-three window.
        let mut used = base.clone();
        let rat = &mut used.monsters_mut()[0];
        assert!(rat.random_ai.set_next(Some(RAT_SCRATCH_INDEX)));
        assert!(rat.random_ai.set_log(&[
            RAT_SCREECH_INDEX,
            RAT_DISEASE_BITE_INDEX,
            RAT_SCRATCH_INDEX,
        ]));
        let seeded = Xoshiro256StarStar::from_seed(seed);
        used.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        roll_rat_intent(&mut used, 0).unwrap();
        assert_eq!(
            used.monsters[0].random_ai.next(),
            Some(RAT_DISEASE_BITE_INDEX)
        );
    }

    #[test]
    fn rat_readiness_frees_dead_slots_and_counts_only_living_pending_calls() {
        let mut state = HotState::at_defaults();
        state.monsters_mut().extend([
            rat_for_turn(0, RAT_SCRATCH_INDEX, 0),
            rat_for_turn(1, RAT_DISEASE_BITE_INDEX, 2),
            rat_for_turn(2, RAT_SCREECH_INDEX, 2),
        ]);
        assert_eq!(rat_can_summon(&state, 0), Ok(true));
        assert!(
            state.monsters_mut()[1]
                .random_ai
                .set_next(Some(RAT_CALL_FOR_BACKUP_INDEX))
        );
        assert!(
            state.monsters_mut()[1]
                .random_ai
                .set_log(&[RAT_CALL_FOR_BACKUP_INDEX])
        );
        assert_eq!(rat_can_summon(&state, 0), Ok(false));
        state.monsters_mut()[1].hp = 0;
        assert_eq!(rat_can_summon(&state, 0), Ok(true));
        state.monsters_mut()[0].set_rat_turns_until_summonable(1);
        assert_eq!(rat_can_summon(&state, 0), Ok(false));

        // #3146: `GetNextSlot` reads `Enemies`. Five live rats hold every
        // slot; once one dies its slot is free again and the call is ready.
        let mut full = HotState::at_defaults();
        full.monsters_mut().extend([
            rat_for_turn(4, RAT_SCRATCH_INDEX, 2),
            rat_for_turn(3, RAT_SCRATCH_INDEX, 2),
            rat_for_turn(0, RAT_SCRATCH_INDEX, 0),
            rat_for_turn(1, RAT_DISEASE_BITE_INDEX, 2),
            rat_for_turn(2, RAT_SCREECH_INDEX, 2),
        ]);
        assert_eq!(rat_can_summon(&full, 2), Ok(false));
        full.monsters_mut()[3].hp = 0;
        assert_eq!(rat_can_summon(&full, 2), Ok(true));
        // A corpse under a represented keep-on-death veto would still hold
        // its slot; readiness refuses by name rather than guess.
        full.monsters_mut()[3]
            .powers
            .set(PowerId::PainfulStabs, SlotWire::Int, 1);
        assert!(rat_can_summon(&full, 2).is_err());
    }

    #[test]
    fn rat_enemy_phase_spawns_once_debits_tus_and_skips_fresh_reroll() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::TwoTailedRat).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 100;
        state.max_hp = 100;
        let mut caller = rat_for_turn(0, RAT_CALL_FOR_BACKUP_INDEX, 0);
        assert!(caller.random_ai.set_log(&[
            RAT_SCRATCH_INDEX,
            RAT_DISEASE_BITE_INDEX,
            RAT_CALL_FOR_BACKUP_INDEX,
        ]));
        assert!(caller.random_ai.set_once(&[RAT_CALL_FOR_BACKUP_INDEX]));
        state.monsters_mut().extend([
            caller,
            rat_for_turn(1, RAT_SCRATCH_INDEX, 2),
            rat_for_turn(2, RAT_DISEASE_BITE_INDEX, 2),
        ]);
        let niche_before = state.rng.get(RngStream::Niche).counter;
        let ai_before = state.rng.get(RngStream::Ai).counter;
        let mut events = Vec::new();

        run_enemy_phase(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(state.hp, 84, "only the two initial attack intents act");
        let by_uid = |uid: u32| {
            state
                .monsters
                .iter()
                .find(|rat| rat.uid == uid)
                .expect("rat uid")
        };
        assert_eq!(by_uid(1).rat_turns_until_summonable(), 1);
        assert_eq!(by_uid(2).rat_turns_until_summonable(), 1);
        assert_eq!(state.rng.get(RngStream::Niche).counter, niche_before + 1);
        assert_eq!(
            state.rng.get(RngStream::Ai).counter,
            ai_before + 4,
            "one spawn roll plus three original-rat side-end rolls"
        );
        assert_eq!(
            state
                .monsters
                .iter()
                .map(|rat| (rat.slot, rat.uid))
                .collect::<Vec<_>>(),
            // Label 4 is native `second` (index 1), which `SortEnemiesBySlotName`
            // puts ahead of the initial `third`..`fifth` rats (#3146).
            [(4, 3), (0, 0), (1, 1), (2, 2)]
        );
        assert!(
            state
                .monsters
                .iter()
                .all(|rat| rat.rat_call_for_backup_count() == 1 && !rat.rat_spawn_fresh())
        );
        assert!(super::super::monsters::rat_roster_is_valid(&state));
    }

