    #[test]
    fn consuming_shadow_lethal_prefix_transfers_later_local_temporary_wrapper() {
        fn lethal_state() -> HotState {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.max_hp = 50;
            state.powers.set(PowerId::ConsumingShadow, SlotWire::Int, 1);
            state.orbs.set_base_slots(1);
            state.orbs.set_slots(1);
            state
                .orbs
                .push(HotOrb::from_parts(OrbKind::Dark, Some(6)).unwrap());
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 5));
            assert_eq!(
                state.fanouts.register_after_side_turn_end_power(
                    AfterSideTurnEndPowerToken::ConsumingShadow,
                ),
                Ok(0)
            );
            state
        }

        let catalog = CatalogBuilder::new().build();
        for dexterity in [false, true] {
            let mut state = lethal_state();
            if dexterity {
                state.powers.set(PowerId::TempDexterity, SlotWire::Int, 4);
                assert_eq!(
                    state.fanouts.register_after_side_turn_end_power(
                        AfterSideTurnEndPowerToken::TemporaryDexterity,
                    ),
                    Ok(1)
                );
            } else {
                state.temp_strength = 4;
                assert_eq!(
                    state.fanouts.register_after_side_turn_end_power(
                        AfterSideTurnEndPowerToken::TemporaryStrength,
                    ),
                    Ok(1)
                );
            }
            let mut events = vec![Event::TurnBegan { turn: 99 }];

            end_player_turn(&mut state, &catalog, &mut events).unwrap();
            assert!(state.history.over);
            if dexterity {
                assert_eq!(state.powers.value(PowerId::TempDexterity), 0);
                assert_eq!(state.powers.value(PowerId::Dexterity), 4);
            } else {
                assert_eq!(state.temp_strength, 0);
                assert_eq!(state.powers.value(PowerId::Strength), 4);
            }
        }

        // The remote wrapper belongs to the later fixed Player owner. A
        // lethal local Consuming Shadow therefore preserves it exactly and
        // must not trigger the local acquisition-order refusal.
        let mut remote = lethal_state();
        remote.multiplayer_ally_key = 1;
        assert!(
            remote
                .fanouts
                .set_multiplayer_ally(crate::hot::MultiplayerAllyState {
                    key: 1,
                    temp_dexterity: 4,
                    ..crate::hot::MultiplayerAllyState::default()
                })
        );
        end_player_turn(&mut remote, &catalog, &mut Vec::new()).unwrap();
        assert!(remote.history.over);
        assert_eq!(remote.fanouts.multiplayer_ally().temp_dexterity, 4);
    }

