    fn howl_auto_post_fixture(
        upgrade: u8,
        pile: PileId,
        monster_hps: &[i32],
    ) -> (HotState, Catalog, u32) {
        let mut builder = CatalogBuilder::new();
        let mut atoms = [None, None];
        for level in 0..=1 {
            atoms[level as usize] = Some(
                builder
                    .intern(CardIdentity {
                        id: CardId::HowlFromBeyond,
                        upgrade: level,
                        enchantment: None,
                    })
                    .unwrap(),
            );
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.exact_piles = true;
        state.next_card_uid = 100;
        let uid = 41;
        state
            .piles
            .get_mut(pile)
            .make_mut()
            .push(crate::hot::HotCard {
                uid,
                atom: atoms[upgrade as usize].unwrap(),
                flags: 0,
            });
        for (index, hp) in monster_hps.iter().copied().enumerate() {
            let mut monster = HotMonster::new(MonsterKind::Toadpole, hp);
            monster.max_hp = hp;
            monster.slot = index as i32;
            monster.uid = index as u32;
            state.monsters_mut().push(monster);
        }
        (state, catalog, uid)
    }

    #[test]
    fn bombardment_auto_pre_freezes_all_piles_and_runs_before_normal_mayhem() {
        let mut builder = CatalogBuilder::new();
        let bombardment = builder
            .intern(CardIdentity {
                id: CardId::Bombardment,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let strike = builder
            .intern(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.exact_piles = true;
        state.next_card_uid = 60;
        for (pile, uid) in [
            (PileId::Hand, 11),
            (PileId::Exhaust, 41),
            (PileId::Exhaust, 42),
        ] {
            state
                .piles
                .get_mut(pile)
                .make_mut()
                .push(crate::hot::HotCard {
                    uid,
                    atom: bombardment,
                    flags: 0,
                });
        }
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 50,
                atom: strike,
                flags: 0,
            });
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        monster.uid = 71;
        state.monsters_mut().push(monster);
        state.powers.set(PowerId::Mayhem, SlotWire::Int, 1);
        let transaction_fixture = state.clone();

        assert_eq!(
            capture_bombardment_auto_pre_listeners(&mut state, &catalog).unwrap(),
            [11, 41, 42]
        );
        let mut events = Vec::new();
        finish_player_turn_start_after_hand_choices(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(
            events
                .iter()
                .filter_map(|event| match event {
                    Event::CardPlayed { uid, energy: 0, .. } => Some(*uid),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [41, 42, 50],
            "AutoPre/Early finishes before AutoPre/Normal Mayhem"
        );
        assert_eq!(state.monsters[0].hp, 58);
        assert_eq!(
            state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [41, 42]
        );
        assert_eq!(state.player_phase, PHASE_ORDINARY_ACTIONS);
        assert!(state.frames.is_empty());

        let mut rollback = transaction_fixture;
        rollback.history.card_plays_finished_combat = i32::MAX;
        let before = rollback.clone();
        let mut rollback_events = vec![Event::TurnBegan { turn: 99 }];
        let before_events = rollback_events.clone();
        assert_eq!(
            end_player_turn(&mut rollback, &catalog, &mut rollback_events),
            Err(EngineRefusal::CounterOverflow("card_plays_finished_combat"))
        );
        assert_eq!(rollback, before, "the complete public turn rolls back");
        assert_eq!(rollback_events, before_events, "no event prefix leaks");
    }

