    #[test]
    fn howl_auto_post_freezes_native_pile_order_and_only_live_exhaust_executes() {
        let (mut state, catalog, exhaust_uid) =
            howl_auto_post_fixture(0, PileId::Exhaust, &[100, 100]);
        let atom = catalog
            .atom(&CardIdentity {
                id: CardId::HowlFromBeyond,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        for (pile, uid) in [
            (PileId::Hand, 11),
            (PileId::Draw, 12),
            (PileId::Discard, 13),
            (PileId::Exhaust, 42),
            (PileId::Play, 15),
        ] {
            state
                .piles
                .get_mut(pile)
                .make_mut()
                .push(crate::hot::HotCard {
                    uid,
                    atom,
                    flags: 0,
                });
        }
        state.powers.set(PowerId::Strength, SlotWire::Int, 2);
        state.energy = 7;
        let rng_before = state.rng.clone();

        let listeners = capture_card_auto_post_listeners(&mut state, &catalog).unwrap();
        assert_eq!(
            listeners,
            [11, 12, 13, exhaust_uid, 42, 15].map(|uid| AutoPostListener::Howl { uid })
        );
        let mut events = Vec::new();
        run_card_auto_post_listeners(&mut state, &catalog, &listeners, &mut events).unwrap();

        assert_eq!(state.monsters[0].hp, 60);
        assert_eq!(state.monsters[1].hp, 60);
        assert_eq!(state.energy, 7, "direct AutoPlay spends no Energy");
        assert_eq!(
            state.rng, rng_before,
            "all-opponents targeting consumes no RNG"
        );
        assert!(state.piles.get(PileId::Exhaust).is_empty());
        assert_eq!(
            state
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [13, exhaust_uid, 42],
            "both surviving direct plays naturally route in frozen order"
        );
        assert_eq!(
            events
                .iter()
                .filter_map(|event| match event {
                    Event::CardPlayed { uid, energy: 0, .. } => Some(*uid),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            [exhaust_uid, 42],
            "non-Exhaust captured objects quietly skip"
        );
        assert_eq!(state.history.plays_this_turn, 2);
        assert_eq!(state.history.card_plays_finished_combat, 2);
        assert_eq!(state.history.owner_card_plays_finished_this_turn, 2);
        assert_eq!(state.history.manual_card_plays_finished_this_turn, 0);
        assert_eq!(state.history.owner_attack_plays_started_this_turn, 2);
        assert_eq!(
            state.history.zero_energy_attack_plays_started_this_turn, 0,
            "Feral's count reads EnergyValue, Howl's resolved cost 3 (#3168)"
        );
        assert_eq!(state.history.attack_skill_plays_started_this_turn, 2);
        assert_eq!(state.history.attack_plays_finished_this_turn, 2);
    }

