    #[test]
    fn invincible_auto_post_capture_freezes_physical_membership_but_reads_live_upgrade() {
        let mut builder = CatalogBuilder::new();
        let atoms = [0, 1].map(|upgrade| {
            builder
                .intern(CardIdentity {
                    id: CardId::IAmInvincible,
                    upgrade,
                    enchantment: None,
                })
                .unwrap()
        });
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.exact_piles = true;
        state.next_card_uid = 50;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 41,
                atom: atoms[0],
                flags: 0,
            });
        let listeners = capture_card_auto_post_listeners(&mut state, &catalog).unwrap();
        assert_eq!(listeners, [AutoPostListener::Invincible { uid: 41 }]);
        state.piles.get_mut(PileId::Draw).make_mut()[0].atom = atoms[1];
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 42,
                atom: atoms[0],
                flags: 0,
            });
        let mut events = Vec::new();
        super::super::play::autoplay_invincible_from_draw_top(
            &mut state,
            &catalog,
            41,
            &mut events,
        )
        .unwrap();
        assert_eq!(state.block, 13);
        assert_eq!(state.piles.get(PileId::Draw).as_slice()[0].uid, 42);
        let before = state.clone();
        super::super::play::autoplay_invincible_from_draw_top(
            &mut state,
            &catalog,
            41,
            &mut events,
        )
        .unwrap();
        assert_eq!(
            state, before,
            "the moved original cannot substitute the new top copy"
        );
    }

