    #[test]
    fn lethal_howl_stays_in_play_and_leaves_the_public_turn_in_auto_post() {
        let (mut state, catalog, first_uid) = howl_auto_post_fixture(0, PileId::Exhaust, &[18]);
        let atom = state.piles.get(PileId::Exhaust).as_slice()[0].atom;
        state
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 42,
                atom,
                flags: 0,
            });
        let rng_before = state.rng.clone();
        let mut events = Vec::new();

        end_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert!(state.history.over);
        assert_eq!(state.player_phase, PHASE_AUTO_POST);
        assert_eq!(state.rng, rng_before);
        assert_eq!(
            state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [42],
            "terminal CardPlay suppresses routing and every captured suffix body"
        );
        assert_eq!(state.piles.get(PileId::Play).as_slice()[0].uid, first_uid);
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, Event::CardPlayed { .. }))
                .count(),
            1
        );
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, Event::CardResolved { .. }))
        );
    }

