    #[test]
    fn direct_howl_auto_post_exposes_the_hook_native_checkpoint_only_with_a_listener() {
        // #3242: the frame-free Howl path passes the same AutoPost dispatch
        // boundary; a turn with no AutoPost listener records nothing.
        use crate::engine::native_checkpoint::{NativeCheckpointKind, record};
        let (state, catalog, uid) = howl_auto_post_fixture(0, PileId::Exhaust, &[100]);
        let mut plain = state.clone();
        end_player_turn(&mut plain, &catalog, &mut Vec::new()).unwrap();
        let mut recorded_state = state.clone();
        let (result, recorded) =
            record(|| end_player_turn(&mut recorded_state, &catalog, &mut Vec::new()));
        result.unwrap();
        assert_eq!(recorded_state, plain);
        assert_eq!(recorded.len(), 1);
        let (kind, checkpoint) = &recorded[0];
        assert_eq!(*kind, NativeCheckpointKind::AutoPostHookFinished);
        assert_eq!(checkpoint.turn, state.turn);
        assert_eq!(checkpoint.player_phase, PHASE_AUTO_POST);
        assert_eq!(checkpoint.monsters[0].hp, 82, "after Howl's AutoPlay");
        assert_eq!(
            checkpoint
                .piles
                .get(PileId::Discard)
                .as_slice()
                .last()
                .unwrap()
                .uid,
            uid
        );

        let mut quiet = state.clone();
        quiet.piles.get_mut(PileId::Exhaust).make_mut().clear();
        let (result, recorded) = record(|| end_player_turn(&mut quiet, &catalog, &mut Vec::new()));
        result.unwrap();
        assert!(recorded.is_empty());
    }

