    #[test]
    fn public_turn_end_rolls_back_a_late_toric_juggernaut_death_catalog_refusal() {
        let mut builder = crate::catalog::CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 500;
        state.max_hp = 500;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 1));
        let mut second = HotMonster::new(MonsterKind::Toadpole, 1);
        second.slot = 1;
        second.uid = 1;
        state.monsters_mut().push(second);
        state.powers.set(PowerId::Juggernaut, SlotWire::Int, 10);
        assert!(
            state
                .fanouts
                .register_after_block_gained(PowerId::Juggernaut)
        );
        assert!(state.fanouts.register_after_block_gained(PowerId::Accuracy));
        assert_eq!(
            state
                .fanouts
                .apply_toric_toughness(2, crate::decimal::DotNetDecimal::from_i64(1),),
            Ok(2)
        );
        assert!(super::super::admission::delayed_block_power_state_is_exact(
            &state
        ));

        let before = state.clone();
        let before_rng = RngStream::ALL.map(|stream| state.rng.get(stream));
        let mut events = vec![Event::TurnBegan { turn: 91 }];
        let before_events = events.clone();

        assert_eq!(
            end_player_turn(&mut state, &catalog, &mut events),
            Err(EngineRefusal::PowerHookNotModeled {
                power: PowerId::Accuracy,
                event: crate::hooks::HookEvent::AfterBlockGained,
            })
        );
        assert_eq!(
            state, before,
            "the complete preceding turn prefix rolls back"
        );
        assert_eq!(events, before_events);
        for (stream, expected) in RngStream::ALL.into_iter().zip(before_rng) {
            assert_eq!(state.rng.get(stream), expected, "{stream:?}");
        }
    }

    #[test]
    fn public_turn_end_rejects_malformed_toric_listener_state_atomically() {
        let catalog = crate::catalog::CatalogBuilder::new().build();
        for record_without_listener in [false, true] {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.max_hp = 50;
            if record_without_listener {
                assert!(state.fanouts.set_toric_toughness(Some(
                    crate::hot::ToricToughnessInstance {
                        duration: 2,
                        block: crate::decimal::DotNetDecimal::from_i64(5),
                    },
                )));
            } else {
                assert!(
                    state
                        .fanouts
                        .register_after_block_cleared(PowerId::ToricToughness)
                );
            }
            let before = state.clone();
            let before_rng = RngStream::ALL.map(|stream| state.rng.get(stream));
            let mut events = vec![Event::TurnEnded { turn: 92 }];
            let before_events = events.clone();

            assert_eq!(
                end_player_turn(&mut state, &catalog, &mut events),
                Err(EngineRefusal::MalformedArgs(
                    "after-block-cleared power order"
                ))
            );
            assert_eq!(state, before);
            assert_eq!(events, before_events);
            for (stream, expected) in RngStream::ALL.into_iter().zip(before_rng) {
                assert_eq!(state.rng.get(stream), expected, "{stream:?}");
            }
        }
    }

    #[test]
    fn turn_transaction_covers_every_reachable_late_failure_owner() {
        fn needed(state: &HotState) -> bool {
            let before_hand_draw = before_hand_draw_turn_reachability(state);
            turn_end_transaction_needed(
                state,
                crate::steps::regent_uncommon::monologue_listener_is_reachable(state)
                    || crate::steps::regent_uncommon::void_form_listener_is_reachable(state)
                    || furnace_turn_is_reachable(state)
                    || before_hand_draw != 0
                    || crate::moves::spawned::constrict_listener_is_reachable(state)
                    || crate::moves::spawned::tender_listener_is_reachable(state),
            )
        }
        let mut state = HotState::at_defaults();
        assert_eq!(before_hand_draw_turn_reachability(&state), 0);
        assert!(!needed(&state));

        let mut toric = HotState::at_defaults();
        assert_eq!(
            toric
                .fanouts
                .apply_toric_toughness(2, crate::decimal::DotNetDecimal::from_i64(5),),
            Ok(2)
        );
        assert!(needed(&toric), "live Toric needs the whole-turn COW");

        state.powers.set(PowerId::Strength, SlotWire::Int, 3);
        assert_eq!(before_hand_draw_turn_reachability(&state), 0);
        assert!(!needed(&state));
        state.powers.set(PowerId::Strength, SlotWire::Int, 0);

        let mut monster = HotMonster::new(MonsterKind::Toadpole, 10);
        monster.powers.set(PowerId::TempStrength, SlotWire::Int, -1);
        state.monsters_mut().push(monster);
        assert!(
            needed(&state),
            "negative monster TempStrength needs turn COW"
        );
        state.monsters_mut().clear();
        assert!(!needed(&state));

        for power in [
            PowerId::Loop,
            PowerId::RollingBoulder,
            PowerId::SummonNextTurn,
            PowerId::Inferno,
            PowerId::CrimsonMantle,
            PowerId::ToolsOfTheTrade,
            PowerId::Tyranny,
            PowerId::Entropy,
        ] {
            state.powers.set(power, SlotWire::Int, 1);
            assert!(
                state.set_after_player_turn_start_order(&[power]),
                "{power:?}"
            );
            assert!(needed(&state), "unified {power:?} order");
            assert!(state.set_after_player_turn_start_order(&[]));
            state.powers.set(power, SlotWire::Int, 0);
        }

        let bomb_uid = state.fanouts.begin_the_bomb(3).unwrap();
        state.fanouts.set_the_bomb_damage(bomb_uid, 40).unwrap();
        assert!(
            needed(&state),
            "a live Bomb makes the whole turn transactional"
        );
        state.fanouts.remove_the_bomb(bomb_uid).unwrap();
        assert!(!needed(&state));

        for power in [
            PowerId::ConsumingShadow,
            PowerId::CreativeAi,
            PowerId::DoubleDamage,
            PowerId::Mayhem,
            PowerId::ShadowStep,
            PowerId::SpectrumShift,
            PowerId::SummonNextTurn,
        ] {
            state.powers.set(power, SlotWire::Int, 1);
            assert!(needed(&state), "{power:?}");
            state.powers.set(power, SlotWire::Int, 0);
        }
        for power in [
            PowerId::ConsumingShadow,
            PowerId::CreativeAi,
            PowerId::DoubleDamage,
            PowerId::Mayhem,
            PowerId::ShadowStep,
            PowerId::SpectrumShift,
        ] {
            state.powers.set(power, SlotWire::Int, -1);
            assert!(!needed(&state), "{power:?}");
            state.powers.set(power, SlotWire::Int, 0);
        }
        state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, -1);
        assert!(needed(&state));
        state.powers.set(PowerId::SummonNextTurn, SlotWire::Int, 0);

        state.powers.set(PowerId::HexPower, SlotWire::Int, 2);
        assert!(needed(&state), "live Hex protects a late Doom death suffix");
        state.powers.set(PowerId::HexPower, SlotWire::Int, 0);

        state.powers.set(PowerId::Furnace, SlotWire::Int, 1);
        assert!(needed(&state));
        state.powers.set(PowerId::Furnace, SlotWire::Int, 0);
        assert!(!needed(&state));
        state.powers.set(PowerId::Foregone, SlotWire::Int, 1);
        assert_eq!(
            before_hand_draw_turn_reachability(&state),
            FOREGONE_TURN_REACHABLE
        );
        assert!(needed(&state));
        state.powers.set(PowerId::Foregone, SlotWire::Int, 0);
        assert!(!needed(&state));
        for (power, wire, value) in [
            (PowerId::Foregone, SlotWire::Bool, 1),
            (PowerId::Foregone, SlotWire::Int, -1),
            (PowerId::SentryMode, SlotWire::Bool, 1),
            (PowerId::SentryMode, SlotWire::Int, -1),
        ] {
            state.powers.set(power, wire, value);
            let malformed = before_hand_draw_turn_reachability(&state);
            assert_eq!(
                malformed & FOREGONE_TURN_REACHABLE != 0,
                power == PowerId::Foregone
            );
            assert_eq!(
                malformed & SENTRY_MODE_TURN_REACHABLE != 0,
                power == PowerId::SentryMode
            );
            assert!(needed(&state), "{power:?} {wire:?} {value}");
            state.powers.set(power, SlotWire::Int, 0);
        }
        state.powers.set(PowerId::SentryMode, SlotWire::Int, 1);
        assert!(
            needed(&state),
            "a live Sentry slot needs rollback even before its order token"
        );
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::SentryMode])
        );
        assert!(needed(&state));
        state.powers.set(PowerId::SentryMode, SlotWire::Int, 0);
        assert!(
            needed(&state),
            "an orphan Sentry token still needs rollback"
        );
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::SentryMode, PowerId::Foregone])
        );
        let orphan = before_hand_draw_turn_reachability(&state);
        assert_eq!(orphan, SENTRY_MODE_TURN_REACHABLE | FOREGONE_TURN_REACHABLE);
        assert!(needed(&state), "both orphan tokens need rollback");
        assert!(state.fanouts.set_before_hand_draw_order(&[]));
        assert!(!needed(&state));
        assert!(
            state
                .fanouts
                .set_after_side_turn_start_order(&[AfterSideTurnStartToken::Furnace])
        );
        assert!(
            needed(&state),
            "an orphan Furnace token also needs whole-action rollback"
        );
    }

    #[test]
    fn public_turn_end_rolls_back_every_unified_nonselective_listener_refusal() {
        fn assert_atomic(
            label: &str,
            state: &mut HotState,
            catalog: &Catalog,
            expected: EngineRefusal,
        ) {
            let before = state.clone();
            let mut events = vec![Event::TurnBegan { turn: 91 }];
            let before_events = events.clone();

            assert_eq!(
                end_player_turn(state, catalog, &mut events),
                Err(expected),
                "{label}"
            );
            assert_eq!(*state, before, "{label}");
            assert_eq!(events, before_events, "{label}");
        }

        let catalog = CatalogBuilder::new().build();

        let mut loop_state = HotState::at_defaults();
        loop_state.hp = 50;
        loop_state.max_hp = 50;
        loop_state.block = i32::MAX;
        // Frost's GainBlock gates on IsOverOrEnding (#3218): a live enemy
        // keeps the end-of-turn Frost passive, whose Block overflows, live.
        loop_state
            .monsters_mut()
            .push(crate::hot::HotMonster::new(MonsterKind::Toadpole, 99));
        loop_state.orbs.set_slots(1);
        loop_state
            .orbs
            .set_orbs(vec![HotOrb::from_parts(OrbKind::Frost, None).unwrap()]);
        loop_state.powers.set(PowerId::Loop, SlotWire::Int, 1);
        assert!(
            loop_state
                .fanouts
                .set_after_player_turn_start_order(&[PowerId::Loop])
        );
        assert_atomic(
            "Loop",
            &mut loop_state,
            &catalog,
            EngineRefusal::CounterOverflow("player block"),
        );

        let mut boulder = HotState::at_defaults();
        boulder.hp = 50;
        boulder.max_hp = 50;
        boulder
            .powers
            .set(PowerId::RollingBoulder, SlotWire::Int, i32::MAX);
        assert!(
            boulder
                .fanouts
                .set_after_player_turn_start_order(&[PowerId::RollingBoulder])
        );
        assert_atomic(
            "Rolling Boulder",
            &mut boulder,
            &catalog,
            EngineRefusal::CounterOverflow("rolling boulder"),
        );

        let mut inferno = HotState::at_defaults();
        inferno.hp = 50;
        inferno.max_hp = 50;
        inferno
            .powers
            .set(PowerId::Strength, SlotWire::Int, i32::MAX);
        inferno.powers.set(PowerId::Rupture, SlotWire::Int, 1);
        inferno.powers.set(PowerId::Inferno, SlotWire::Int, 1);
        inferno.powers.set(PowerId::InfernoSelf, SlotWire::Int, 1);
        assert!(
            inferno
                .fanouts
                .set_after_player_turn_start_order(&[PowerId::Inferno])
        );
        assert_atomic(
            "Inferno",
            &mut inferno,
            &catalog,
            EngineRefusal::CounterOverflow("player strength"),
        );

        let mut crimson = HotState::at_defaults();
        crimson.hp = 50;
        crimson.max_hp = 50;
        crimson.powers.set(PowerId::CrimsonMantle, SlotWire::Int, 1);
        crimson.powers.set(PowerId::CrimsonSelf, SlotWire::Int, 1);
        crimson.powers.set(PowerId::Juggernaut, SlotWire::Int, 1);
        assert!(
            crimson
                .fanouts
                .set_after_block_gained_order(&[PowerId::Juggernaut])
        );
        let mut phrog = HotMonster::new(MonsterKind::PhrogParasite, 1);
        phrog.uid = u32::MAX;
        phrog.override_state = MonsterOverride::Stunned;
        crimson.monsters_mut().push(phrog);
        assert!(
            crimson
                .fanouts
                .set_after_player_turn_start_order(&[PowerId::CrimsonMantle])
        );
        let mut crimson_builder = CatalogBuilder::new();
        crimson_builder
            .intern_monster(MonsterKind::PhrogParasite)
            .unwrap();
        let crimson_catalog = crimson_builder.build();
        assert_atomic(
            "Crimson Mantle",
            &mut crimson,
            &crimson_catalog,
            EngineRefusal::CounterOverflow("monster uid"),
        );
    }

