    #[cfg(feature = "allocation-counting")]
    #[test]
    fn consuming_shadow_turn_transaction_has_bounded_cow_allocations() {
        fn lethal_state() -> HotState {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.powers.set(PowerId::ConsumingShadow, SlotWire::Int, 1);
            state.orbs.set_base_slots(1);
            state.orbs.set_slots(1);
            state
                .orbs
                .push(HotOrb::from_parts(OrbKind::Dark, Some(6)).unwrap());
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 5));
            hydrate_after_side_turn_end_power_order_for_test(&mut state);
            state
        }

        let catalog = CatalogBuilder::new().build();
        let mut warm = lethal_state();
        end_player_turn(&mut warm, &catalog, &mut Vec::with_capacity(16)).unwrap();

        let mut state = lethal_state();
        let mut events = Vec::with_capacity(16);
        let (before_allocations, before_bytes) = crate::allocation::thread_snapshot();
        end_player_turn(&mut state, &catalog, &mut events).unwrap();
        let (after_allocations, after_bytes) = crate::allocation::thread_snapshot();
        let allocations = after_allocations - before_allocations;
        let bytes = after_bytes - before_bytes;
        // Measured on aarch64-apple-darwin: eight COW detachments totaling
        // 432 bytes for the whole lethal turn transaction. This uncommon
        // power-owned path must not turn into an unbounded per-listener cost.
        assert!(
            allocations <= 8 && bytes <= 432,
            "Consuming Shadow turn transaction allocated {allocations} times ({bytes} bytes)"
        );
    }

    #[test]
    fn consuming_shadow_late_evoke_refusal_rolls_back_the_complete_turn_end() {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::TheLost).unwrap();
        builder.intern_monster(MonsterKind::TheForgotten).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.powers.set(PowerId::ConsumingShadow, SlotWire::Int, 1);
        state.orbs.set_base_slots(1);
        state.orbs.set_slots(1);
        state
            .orbs
            .push(HotOrb::from_parts(OrbKind::Dark, Some(6)).unwrap());
        let mut lost = HotMonster::new(MonsterKind::TheLost, super::super::monsters::THE_LOST_HP);
        lost.max_hp = super::super::monsters::THE_LOST_HP;
        lost.hp = 1;
        // Dark's passive is harmless. The later Consuming Shadow EvokeLast
        // kills this owner, whose after-death debit cannot be represented.
        lost.possess_strength_debit = i32::MIN;
        let mut forgotten = HotMonster::new(
            MonsterKind::TheForgotten,
            super::super::monsters::THE_FORGOTTEN_HP,
        );
        forgotten.max_hp = super::super::monsters::THE_FORGOTTEN_HP;
        forgotten.slot = 1;
        forgotten.uid = 1;
        state.monsters_mut().extend([lost, forgotten]);
        hydrate_after_side_turn_end_power_order_for_test(&mut state);
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 99 }];
        let before_events = events.clone();

        assert_eq!(
            end_player_turn(&mut state, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("Possess Strength restore"))
        );
        assert_eq!(
            state, before,
            "TurnEnded and every prior side-end mutation roll back"
        );
        assert_eq!(
            events, before_events,
            "the caller's event prefix is preserved"
        );
    }

    fn foregone_turn_fixture(amount: i32, draw: usize, discard: usize) -> (HotState, Catalog) {
        let identity = CardIdentity {
            id: CardId::ForegoneConclusion,
            upgrade: 0,
            enchantment: None,
        };
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.turn = 2;
        state.exact_piles = true;
        state.powers.set(PowerId::Foregone, SlotWire::Int, amount);
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::Foregone])
        );
        for uid in 0..draw as u32 {
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid: 100 + uid,
                atom,
                flags: 0,
            });
        }
        for uid in 0..discard as u32 {
            state
                .piles
                .get_mut(PileId::Discard)
                .make_mut()
                .push(HotCard {
                    uid: 200 + uid,
                    atom,
                    flags: 0,
                });
        }
        (state, catalog)
    }

    #[test]
    fn foregone_auto_take_moves_in_order_before_hand_draw_then_removes_whole_power() {
        let (mut state, catalog) = foregone_turn_fixture(2, 2, 0);
        let filler_atom = state.piles.get(PileId::Draw).as_slice()[0].atom;
        for uid in 0..9 {
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid,
                atom: filler_atom,
                flags: 0,
            });
        }
        let mut events = Vec::new();

        begin_player_turn(&mut state, &catalog, &mut events).unwrap();

        assert_eq!(
            state.piles.get(PileId::Hand).as_slice().last().unwrap().uid,
            100
        );
        assert_eq!(state.piles.get(PileId::Discard).as_slice()[0].uid, 101);
        assert!(state.piles.get(PileId::Draw).is_empty());
        assert_eq!(state.powers.value(PowerId::Foregone), 0);
        assert!(state.fanouts.before_hand_draw_order().is_empty());
        let moved = events
            .iter()
            .filter_map(|event| match event {
                Event::CardResolved { uid, pile } => Some((*uid, *pile)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(moved, [(100, PileId::Hand), (101, PileId::Discard)]);
        let removal = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::PowerChanged {
                        subject: Subject::Player,
                        power: PowerId::Foregone,
                        amount: 0,
                    }
                )
            })
            .unwrap();
        let last_move = events
            .iter()
            .rposition(|event| matches!(event, Event::CardResolved { .. }))
            .unwrap();
        assert!(
            last_move < removal,
            "native Add completes before PowerCmd::Remove"
        );
    }

    #[test]
    fn foregone_shuffle_precedes_auto_take_and_larger_choice_parks_without_removal() {
        let (mut shuffled, catalog) = foregone_turn_fixture(2, 0, 2);
        shuffled.rng.set(
            RngStream::Rng,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        let mut events = Vec::new();
        begin_player_turn(&mut shuffled, &catalog, &mut events).unwrap();
        assert_eq!(shuffled.piles.get(PileId::Hand).len(), 2);
        let reshuffle = events
            .iter()
            .position(|event| matches!(event, Event::Reshuffled { cards: 2 }))
            .unwrap();
        let first_move = events
            .iter()
            .position(|event| matches!(event, Event::CardResolved { .. }))
            .unwrap();
        assert!(reshuffle < first_move);
        assert_eq!(shuffled.rng.get(RngStream::Rng).counter, 1);

        let (mut choice, catalog) = foregone_turn_fixture(2, 3, 0);
        let mut events = vec![Event::TurnEnded { turn: 99 }];
        let before_events = events.clone();
        begin_player_turn(&mut choice, &catalog, &mut events).unwrap();
        assert!(choice.pending.is_some());
        assert_eq!(choice.powers.value(PowerId::Foregone), 2);
        assert_eq!(events, before_events, "opening the modal moves no card");
        assert_eq!(foregone_selection_action_count(&choice).unwrap(), 6);
        resume_foregone_before_hand_draw(&mut choice, &catalog, 5, &mut events).unwrap();
        assert!(choice.pending.is_none());
        assert!(choice.frames.is_empty());
        assert_eq!(choice.powers.value(PowerId::Foregone), 0);

        let (mut type_one_order, catalog) = foregone_turn_fixture(2, 1, 0);
        type_one_order
            .powers
            .set(PowerId::Vicious, SlotWire::Int, 1);
        let before = type_one_order.clone();
        let mut events = vec![Event::TurnEnded { turn: 98 }];
        let before_events = events.clone();
        assert_eq!(
            begin_player_turn(&mut type_one_order, &catalog, &mut events),
            Err(EngineRefusal::MalformedArgs(
                "foregone AfterPowerAmountChanged order"
            ))
        );
        assert_eq!(type_one_order, before);
        assert_eq!(events, before_events);
    }

