    #[test]
    fn furnace_public_end_turn_rolls_back_every_prefix_on_late_draw_refusal() {
        let (mut state, catalog, _) = furnace_turn_fixture(5, Some(10), true);
        state.cards_drawn_combat = i32::MAX;
        state.hp = 100;
        state.max_hp = 100;
        let mut mawler = HotMonster::new(MonsterKind::Mawler, 76);
        assert!(mawler.random_ai.set_next(Some(MAWLER_CLAW_INDEX)));
        assert!(mawler.random_ai.set_log(&[MAWLER_CLAW_INDEX]));
        mawler.powers.set(PowerId::Weak, SlotWire::Int, 1);
        mawler.misery_debuff_order.push(MiseryToken::Weak);
        state.monsters = std::sync::Arc::new(vec![mawler]);
        let seeded = Xoshiro256StarStar::from_seed(0);
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );

        let mut leaked = state.clone();
        let mut leaked_events = vec![Event::TurnBegan { turn: 700 }];
        assert_eq!(
            end_player_turn_inner(
                &mut leaked,
                &catalog,
                false,
                false,
                &[],
                false,
                &mut leaked_events,
            ),
            Err(EngineRefusal::CounterOverflow("cards_drawn_combat"))
        );
        assert_ne!(
            leaked.turn, state.turn,
            "the failing suffix follows turn advance"
        );
        assert_ne!(
            leaked.rng.get(RngStream::Ai),
            state.rng.get(RngStream::Ai),
            "the enemy random-AI successor was already sampled"
        );
        assert_eq!(
            leaked.monsters[0].powers.value(PowerId::Weak),
            0,
            "enemy-side duration expiry precedes the failing turn start"
        );
        assert!(
            leaked_events
                .iter()
                .any(|event| matches!(event, Event::TurnEnded { .. })),
            "the direct inner body exposes the TurnEnded prefix"
        );

        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 701 }];
        let before_events = events.clone();
        assert_eq!(
            end_player_turn(&mut state, &catalog, &mut events),
            Err(EngineRefusal::CounterOverflow("cards_drawn_combat"))
        );
        assert_eq!(state, before, "the public whole action is atomic");
        assert_eq!(events, before_events, "preexisting events are preserved");
    }

    #[test]
    fn furnace_turn_reachability_rejects_malformed_slot_and_order_atomically() {
        let (base, catalog, _) = furnace_turn_fixture(5, Some(10), false);
        let mut cases = Vec::new();

        let mut wrong_wire = base.clone();
        wrong_wire.powers.set(PowerId::Furnace, SlotWire::Bool, 1);
        cases.push((wrong_wire, "furnace turn state"));

        let mut negative = base.clone();
        negative.powers.set(PowerId::Furnace, SlotWire::Int, -1);
        cases.push((negative, "furnace turn state"));

        let mut missing = base.clone();
        assert!(missing.fanouts.set_after_side_turn_start_order(&[]));
        cases.push((missing, "furnace turn state"));

        let mut orphan = base.clone();
        orphan.powers.set(PowerId::Furnace, SlotWire::Int, 0);
        cases.push((orphan, "furnace turn state"));

        let mut duplicate = base.clone();
        assert!(duplicate.fanouts.set_after_side_turn_start_order(&[
            AfterSideTurnStartToken::Furnace,
            AfterSideTurnStartToken::Furnace,
        ]));
        cases.push((duplicate, "furnace turn state"));

        let mut unknown = base.clone();
        assert!(
            unknown
                .fanouts
                .set_after_side_turn_start_order(&[AfterSideTurnStartToken::BiasedCognition])
        );
        cases.push((unknown, "furnace turn state"));

        for (mut candidate, expected) in cases {
            let before = candidate.clone();
            let mut events = vec![Event::TurnEnded { turn: 12 }];
            let before_events = events.clone();
            assert_eq!(
                begin_player_turn(&mut candidate, &catalog, &mut events),
                Err(EngineRefusal::MalformedArgs(expected))
            );
            assert_eq!(candidate, before);
            assert_eq!(events, before_events);
        }

        let mut disjoint = base;
        disjoint.set_ringing(true);
        begin_player_turn(&mut disjoint, &catalog, &mut Vec::new())
            .expect("an unrelated admitted field is not Furnace-owned");
    }

    #[test]
    fn furnace_preflights_exhaust_payload_and_duplicate_uids_before_turn_prefix() {
        let (base, catalog, blade_uid) = furnace_turn_fixture(5, Some(10), false);
        let blade_uid = blade_uid.unwrap();
        let mut cases = Vec::new();

        let mut missing_payload = base.clone();
        let blade = missing_payload.piles.get_mut(PileId::Discard).make_mut()[0];
        missing_payload
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .clear();
        missing_payload
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(crate::hot::HotCard { flags: 0, ..blade });
        cases.push(missing_payload);

        let mut negative_payload = base.clone();
        negative_payload
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .clear();
        negative_payload
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(blade);
        negative_payload.card_states.set(
            blade_uid,
            crate::hot::CardInstanceState {
                damage_growth: -1,
                ..crate::hot::CardInstanceState::default()
            },
        );
        cases.push(negative_payload);

        let mut duplicate_uid = base.clone();
        duplicate_uid
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(blade);
        cases.push(duplicate_uid);

        let mut unknown_atom = base.clone();
        unknown_atom.piles.get_mut(PileId::Discard).make_mut()[0].atom = u16::MAX;
        cases.push(unknown_atom);

        let mut nonmonotonic_allocator = base.clone();
        nonmonotonic_allocator.next_card_uid = blade_uid;
        cases.push(nonmonotonic_allocator);

        for mut candidate in cases {
            let before = candidate.clone();
            let mut events = vec![Event::TurnEnded { turn: 13 }];
            let before_events = events.clone();
            assert!(begin_player_turn(&mut candidate, &catalog, &mut events).is_err());
            assert_eq!(candidate, before);
            assert_eq!(events, before_events);
        }

        let furnace_atom = catalog
            .atom(&CardIdentity {
                id: CardId::Furnace,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let (mut furnace_tail, catalog, _) = furnace_turn_fixture(5, None, false);
        furnace_tail
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(crate::hot::HotCard {
                uid: 44,
                atom: furnace_atom,
                flags: 0,
            });
        furnace_tail.card_states.set(
            44,
            crate::hot::CardInstanceState {
                damage_growth: 1,
                ..crate::hot::CardInstanceState::default()
            },
        );
        begin_player_turn(&mut furnace_tail, &catalog, &mut Vec::new())
            .expect("ordinary Furnace physical payload validation is admission-owned");

        // Furnace's turn reader does not claim ordinary non-Blade card-state
        // validation. Public admission owns that general invariant; keeping
        // this private reader narrow is what permits unrelated admitted card
        // mechanics to coexist.
        let mut unrelated_tail = base;
        unrelated_tail.card_states.set(
            55,
            crate::hot::CardInstanceState {
                local_retain: true,
                ..crate::hot::CardInstanceState::default()
            },
        );
        begin_player_turn(&mut unrelated_tail, &catalog, &mut Vec::new())
            .expect("ordinary card-state tails are admission-owned");
    }

