    #[cfg(feature = "allocation-counting")]
    #[test]
    fn furnace_public_turn_transaction_has_bounded_cow_allocations() {
        let (mut warm, catalog, _) = furnace_turn_fixture(5, None, false);
        end_player_turn(&mut warm, &catalog, &mut Vec::with_capacity(16)).unwrap();

        let (mut state, catalog, _) = furnace_turn_fixture(5, None, false);
        let mut events = Vec::with_capacity(16);
        let (before_allocations, before_bytes) = crate::allocation::thread_snapshot();
        end_player_turn(&mut state, &catalog, &mut events).unwrap();
        let (after_allocations, after_bytes) = crate::allocation::thread_snapshot();
        let allocations = after_allocations - before_allocations;
        let bytes = after_bytes - before_bytes;
        // Measured on aarch64-apple-darwin: fifteen allocations / 1,684
        // bytes. The public action owns one outer rehearsal; its nested
        // begin-turn call deliberately takes no second checkpoint. The
        // ordinary absent-Furnace direct-turn path is separately pinned cold.
        // The fixture gained a live Mawler in #3112 (a monsterless state is
        // IsOverOrEnding, where Forge is a no-op); its monster phase accounts
        // for the whole +1 / +666 over the former 14 / 1,018, measured
        // identically with the Forge gate reverted to `history.over`.
        // #2941 added The Scythe's cold `DeckVersion` link slot to the card
        // state store (one `Option<Arc<_>>`), whose one copy-on-write clone
        // here accounts for the +8 bytes over the former 1,684.
        assert!(
            allocations <= 15 && bytes <= 1_692,
            "Furnace turn transaction allocated {allocations} times ({bytes} bytes)"
        );
    }

    fn constrict_turn_fixture(intent: u8, amount: i32) -> (HotState, crate::catalog::Catalog) {
        let mut builder = CatalogBuilder::new();
        builder.intern_private_constrict_strangler().unwrap();
        builder
            .intern(CardIdentity {
                id: CardId::SentryMode,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        let mut owner = HotMonster::new(MonsterKind::SlitheringStrangler, 55);
        owner.max_hp = 55;
        owner.uid = 17;
        let mut ai = crate::hot::RandomAiState::new();
        assert!(ai.set_next(Some(intent)));
        let log: &[u8] = if intent == STRANGLER_CONSTRICT_INDEX {
            &[STRANGLER_CONSTRICT_INDEX]
        } else {
            &[STRANGLER_CONSTRICT_INDEX, intent]
        };
        assert!(ai.set_log(log));
        owner.random_ai = ai;
        state.monsters_mut().push(owner);
        assert!(state.fanouts.set_constrict_amount(amount));
        if amount > 0 {
            assert_eq!(
                state
                    .fanouts
                    .register_after_side_turn_end_power(AfterSideTurnEndPowerToken::Constrict),
                Ok(0)
            );
        }
        state.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 9,
            },
        );
        (state, catalog)
    }

    /// #3386 witness: Constrict's side-end damage fires the Centennial
    /// Puzzle, whose Draw reshuffles the flushed Hand against Stratagem 2.
    /// `ConstrictPower/<AfterSideTurnEnd>d__4` damages through its own
    /// deferred-choice listener context, so native starts every later
    /// ordinary side-end listener before that choice; the receipt carrier
    /// cannot, and the root and the Draw both refuse by name. The same turn
    /// with a spent Puzzle resolves.
    #[test]
    fn constrict_side_end_puzzle_draw_refuses_by_name() {
        let mut builder = CatalogBuilder::new();
        builder.intern_private_constrict_strangler().unwrap();
        let defend = builder
            .intern_reachable(CardIdentity {
                id: CardId::DefendSilent,
                upgrade: 0,
                enchantment: None,
            })
            .unwrap();
        builder
            .set_relics(&[RelicId::RelicCentennialPuzzle])
            .unwrap();
        let catalog = builder.build();
        let (mut state, _) = constrict_turn_fixture(STRANGLER_THWACK_INDEX, 3);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.fanouts.set_puzzle_armed(true);
        state.powers.set(PowerId::Stratagem, SlotWire::Int, 2);
        state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .extend((1..6).map(|uid| HotCard {
                uid,
                atom: defend,
                flags: crate::hot::CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            }));
        state.next_card_uid = 20;
        assert!(crate::engine::puzzle::root_refuses_under_for_test(
            &state,
            &catalog,
            CONSTRICT_PUZZLE_WALL
        ));
        assert_eq!(
            crate::engine::apply_action(&state, &catalog, &crate::engine::Action::EndTurn)
                .map(|_| ())
                .unwrap_err(),
            EngineRefusal::PowerOrderNotModeled(CONSTRICT_PUZZLE_WALL)
        );
        let mut spent = state.clone();
        spent.fanouts.set_puzzle_armed(false);
        let resolved =
            crate::engine::apply_action(&spent, &catalog, &crate::engine::Action::EndTurn)
                .unwrap()
                .state;
        assert!(resolved.hp < state.hp, "Constrict hit without the Puzzle");
    }

