    #[test]
    fn tender_and_constrict_execute_in_both_acquisition_orders() {
        let mut builder = CatalogBuilder::new();
        builder.intern_private_tender_hunter().unwrap();
        builder.intern_private_constrict_strangler().unwrap();
        let catalog = builder.build();
        for tender_first in [true, false] {
            let (mut state, _) = tender_turn_fixture(
                HUNTER_BITE_INDEX,
                &[HUNTER_GOOP_INDEX, HUNTER_BITE_INDEX],
                1,
            );
            let (constrict, _) = constrict_turn_fixture(STRANGLER_THWACK_INDEX, 3);
            state.monsters_mut().push(constrict.monsters[0].clone());
            assert!(state.fanouts.set_constrict_amount(3));
            state.powers.set(PowerId::Strength, SlotWire::Int, -1);
            state.powers.set(PowerId::Dexterity, SlotWire::Int, -1);
            if tender_first {
                assert_eq!(
                    state
                        .fanouts
                        .register_after_side_turn_end_power(AfterSideTurnEndPowerToken::Constrict,),
                    Ok(1)
                );
            } else {
                state.fanouts.set_next_after_side_turn_end_power_uid(2);
                assert!(state.fanouts.set_after_side_turn_end_power_order(&[
                    AfterSideTurnEndPowerEntry {
                        token: AfterSideTurnEndPowerToken::Constrict,
                        uid: 0,
                    },
                    AfterSideTurnEndPowerEntry {
                        token: AfterSideTurnEndPowerToken::Tender,
                        uid: 1,
                    },
                ]));
            }
            assert!(crate::moves::spawned::tender_private_state_is_exact(&state));
            assert!(crate::moves::spawned::constrict_private_state_is_exact(
                &state
            ));

            let mut events = Vec::new();
            run_after_side_turn_end_hook_for_test(&mut state, &catalog, &mut events).unwrap();
            assert_eq!(state.hp, 47);
            assert_eq!(state.fanouts.tender_cards_played(), 0);
            assert_eq!(state.powers.value(PowerId::Strength), 0);
            assert_eq!(state.powers.value(PowerId::Dexterity), 0);
            let damage_index = events
                .iter()
                .position(|event| matches!(event, Event::PlayerDamaged { .. }))
                .unwrap();
            let strength_index = events
                .iter()
                .position(|event| {
                    matches!(
                        event,
                        Event::PowerChanged {
                            power: PowerId::Strength,
                            ..
                        }
                    )
                })
                .unwrap();
            assert_eq!(strength_index < damage_index, tender_first);
        }
    }

