    #[test]
    fn hunter_bite_exact_zero_can_repeat_and_puncture_repeats_at_most_twice() {
        let (mut zero, _) = tender_turn_fixture(
            HUNTER_BITE_INDEX,
            &[HUNTER_GOOP_INDEX, HUNTER_BITE_INDEX],
            0,
        );
        zero.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: [0; 4],
                counter: 41,
            },
        );
        advance_hunter_killer_intent(&mut zero, 0).unwrap();
        assert_eq!(zero.monsters[0].random_ai.next(), Some(HUNTER_BITE_INDEX));
        assert_eq!(zero.rng.get(RngStream::Ai).counter, 42);
        assert!(hunter_killer_ai_state_is_exact(&zero.monsters[0]));

        let seed = (0_u64..256)
            .find(|seed| {
                let (mut candidate, _) = tender_turn_fixture(
                    HUNTER_BITE_INDEX,
                    &[HUNTER_GOOP_INDEX, HUNTER_BITE_INDEX],
                    0,
                );
                let rng = Xoshiro256StarStar::from_seed(*seed);
                candidate.rng.set(
                    RngStream::Ai,
                    RngStreamState {
                        words: rng.words,
                        counter: rng.counter,
                    },
                );
                advance_hunter_killer_intent(&mut candidate, 0).unwrap();
                candidate.monsters[0].random_ai.next() == Some(HUNTER_PUNCTURE_INDEX)
            })
            .expect("a positive Bite roll must reach Puncture");
        let (mut positive, _) = tender_turn_fixture(
            HUNTER_BITE_INDEX,
            &[HUNTER_GOOP_INDEX, HUNTER_BITE_INDEX],
            0,
        );
        let rng = Xoshiro256StarStar::from_seed(seed);
        positive.rng.set(
            RngStream::Ai,
            RngStreamState {
                words: rng.words,
                counter: rng.counter,
            },
        );
        advance_hunter_killer_intent(&mut positive, 0).unwrap();
        assert_eq!(
            positive.monsters[0].random_ai.next(),
            Some(HUNTER_PUNCTURE_INDEX)
        );

        // #3026: PUNCTURE is `maxRepeats = 2`, so two in a row are a legal
        // state and only a third is unreachable.
        let mut twice = positive.monsters[0].clone();
        assert!(twice.random_ai.set_log(&[
            HUNTER_GOOP_INDEX,
            HUNTER_PUNCTURE_INDEX,
            HUNTER_PUNCTURE_INDEX,
        ]));
        assert!(twice.random_ai.set_next(Some(HUNTER_PUNCTURE_INDEX)));
        assert!(hunter_killer_ai_state_is_exact(&twice));
        let mut impossible = twice.clone();
        assert!(impossible.random_ai.set_log(&[
            HUNTER_PUNCTURE_INDEX,
            HUNTER_PUNCTURE_INDEX,
            HUNTER_PUNCTURE_INDEX,
        ]));
        assert!(!hunter_killer_ai_state_is_exact(&impossible));
    }

    /// Native witness for #3026, `.mcr` `192324.722_mcr_0c8c0854`
    /// (fight `fd7f1a5e95d3f3c9`): the MonsterAi words before the turn-3 roll,
    /// counter 16. With log `[GOOP, PUNCTURE]` both branches weigh 1, the draw
    /// is 0.9496 × 2 and PUNCTURE repeats, as the capture records. After a
    /// second PUNCTURE the next draw (0.3563) has PUNCTURE at weight 0 and
    /// selects BITE over a total of 1.
    #[test]
    fn hunter_puncture_repeats_once_on_the_native_turn_three_draw() {
        let (mut state, _) = tender_turn_fixture(
            HUNTER_PUNCTURE_INDEX,
            &[HUNTER_GOOP_INDEX, HUNTER_PUNCTURE_INDEX],
            0,
        );
        let words = [
            0x4267_c9ba_6a98_5489,
            0xf510_7e2a_bb1b_88f9,
            0x9785_4b2c_36c6_ee02,
            0x6487_d20f_6ef2_164a,
        ];
        let mut expected = Xoshiro256StarStar { words, counter: 16 };
        let draw = expected.next_double();
        assert!((draw - 0.9496).abs() < 1e-4);
        assert!(((draw * 2.0) as f32) - 1.0 > 0.0);
        assert!(
            ((draw * 1.0) as f32) - 1.0 <= 0.0,
            "the old total-1 roll picked BITE"
        );
        state
            .rng
            .set(RngStream::Ai, RngStreamState { words, counter: 16 });

        advance_hunter_killer_intent(&mut state, 0).unwrap();

        let machine = state.monsters[0].random_ai;
        assert_eq!(machine.next(), Some(HUNTER_PUNCTURE_INDEX));
        assert_eq!(machine.log_len(), 3);
        assert_eq!(machine.log_at(1), Some(HUNTER_PUNCTURE_INDEX));
        assert_eq!(machine.log_at(2), Some(HUNTER_PUNCTURE_INDEX));
        assert_eq!(state.rng.get(RngStream::Ai).words, expected.words);
        assert_eq!(state.rng.get(RngStream::Ai).counter, 17);
        assert!(hunter_killer_ai_state_is_exact(&state.monsters[0]));

        // Turn 4 in the capture: 0.3563 with PUNCTURE exhausted -> BITE.
        advance_hunter_killer_intent(&mut state, 0).unwrap();
        assert_eq!(state.monsters[0].random_ai.next(), Some(HUNTER_BITE_INDEX));
        assert_eq!(state.rng.get(RngStream::Ai).counter, 18);
        assert!(hunter_killer_ai_state_is_exact(&state.monsters[0]));
    }

    fn gremlin_merc_turn_fixture(stolen: i32, gold: i32) -> (Catalog, HotState) {
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::GremlinMerc).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 200;
        state.max_hp = 200;
        state.gold = gold;
        state.rng.set(
            RngStream::Niche,
            RngStreamState {
                words: [5, 6, 7, 8],
                counter: 1,
            },
        );
        let mut merc = HotMonster::new(MonsterKind::GremlinMerc, 53);
        merc.max_hp = 53;
        merc.powers.set(PowerId::StolenGold, SlotWire::Int, stolen);
        state.monsters_mut().push(merc);
        assert!(super::super::monsters::gremlin_merc_state_is_valid(&state));
        (catalog, state)
    }

    fn kill_gremlin_merc(
        state: &mut HotState,
        events: &mut Vec<Event>,
    ) -> Result<(), EngineRefusal> {
        let damage = i64::from(state.monsters[0].hp) + i64::from(state.monsters[0].block);
        super::super::damage::damage_monster(
            state,
            0,
            crate::decimal::DotNetDecimal::from_i64(damage),
            false,
            false,
            events,
        )
        .map(|_| ())
    }

    #[test]
    fn gremlin_merc_cycle_steals_after_attack_and_applies_independent_riders() {
        let (catalog, mut state) = gremlin_merc_turn_fixture(0, 45);
        let mut events = Vec::new();

        monster_act(&mut state, &catalog, 0, &mut events).unwrap();
        assert_eq!((state.hp, state.gold), (184, 25));
        assert_eq!(state.monsters[0].powers.value(PowerId::StolenGold), 20);
        assert_eq!(state.monsters[0].loop_pos, 1);

        monster_act(&mut state, &catalog, 0, &mut events).unwrap();
        assert_eq!((state.hp, state.gold), (170, 5));
        assert_eq!(state.monsters[0].powers.value(PowerId::StolenGold), 40);
        assert_eq!(state.powers.value(PowerId::PlayerWeak), 2);
        assert_eq!(state.monsters[0].loop_pos, 2);

        monster_act(&mut state, &catalog, 0, &mut events).unwrap();
        assert_eq!((state.hp, state.gold), (161, 0));
        assert_eq!(state.monsters[0].powers.value(PowerId::StolenGold), 45);
        assert_eq!(state.monsters[0].powers.value(PowerId::Strength), 2);
        assert_eq!(state.monsters[0].loop_pos, 0);
    }

    #[test]
    fn gremlin_merc_terminal_player_and_thorns_death_gate_each_native_suffix() {
        let (catalog, mut terminal) = gremlin_merc_turn_fixture(i32::MAX, 40);
        terminal.hp = 1;
        terminal.max_hp = 1;
        monster_act(&mut terminal, &catalog, 0, &mut Vec::new()).unwrap();
        assert!(terminal.history.over);
        assert_eq!(terminal.gold, 40);
        assert_eq!(
            terminal.monsters[0].powers.value(PowerId::StolenGold),
            i32::MAX
        );

        for loop_pos in 0..=2 {
            let (catalog, mut state) = gremlin_merc_turn_fixture(i32::MAX, 40);
            state.monsters_mut()[0].hp = 1;
            state.monsters_mut()[0].loop_pos = loop_pos;
            state.powers.set(PowerId::Thorns, SlotWire::Int, 1);
            let hp_before = state.hp;
            monster_act(&mut state, &catalog, 0, &mut Vec::new()).unwrap();

            assert_eq!(state.monsters.len(), 3, "loop {loop_pos}");
            assert_eq!(state.gold, 40, "a dead Merc cannot steal");
            assert_eq!(state.monsters[0].powers.value(PowerId::StolenGold), 0);
            assert_eq!(
                state.powers.value(PowerId::PlayerWeak),
                if loop_pos == 1 { 2 } else { 0 },
                "Double's independent Weak suffix survives owner death"
            );
            assert_eq!(
                state.monsters[0].powers.value(PowerId::Strength),
                0,
                "Hehe's owner-scoped Strength suffix is suppressed"
            );
            assert_eq!(
                hp_before - state.hp,
                [8, 7, 9][loop_pos as usize],
                "Thorns cancels later Double hits after the first result"
            );
        }
    }

    #[test]
    fn gremlin_merc_rider_overflows_are_atomic_but_dead_owner_skips_hehe() {
        let (catalog, mut ledger) = gremlin_merc_turn_fixture(i32::MAX, 20);
        let ledger_before = ledger.clone();
        let mut ledger_events = vec![Event::TurnBegan { turn: 73 }];
        let ledger_events_before = ledger_events.clone();
        assert!(matches!(
            end_player_turn(&mut ledger, &catalog, &mut ledger_events),
            Err(EngineRefusal::CounterOverflow("Gremlin Merc StolenGold"))
        ));
        assert_eq!(ledger, ledger_before);
        assert_eq!(ledger_events, ledger_events_before);

        let (catalog, mut strength) = gremlin_merc_turn_fixture(0, 0);
        strength.monsters_mut()[0].loop_pos = 2;
        strength.monsters_mut()[0]
            .powers
            .set(PowerId::Strength, SlotWire::Int, i32::MAX - 1);
        strength.block = i32::MAX;
        assert_eq!(
            strength.monsters[0].powers.value(PowerId::Strength),
            i32::MAX - 1
        );
        let strength_before = strength.clone();
        let mut strength_events = vec![Event::TurnBegan { turn: 74 }];
        let strength_events_before = strength_events.clone();
        let strength_result = end_player_turn(&mut strength, &catalog, &mut strength_events);
        let strength_refusal = match strength_result {
            Err(refusal) => refusal,
            Ok(()) => panic!(
                "Hehe unexpectedly succeeded: hp={} player_hp={} loop={} strength={}",
                strength.monsters[0].hp,
                strength.hp,
                strength.monsters[0].loop_pos,
                strength.monsters[0].powers.value(PowerId::Strength),
            ),
        };
        assert_eq!(
            strength_refusal,
            EngineRefusal::CounterOverflow("Gremlin Merc Hehe Strength")
        );
        assert_eq!(strength, strength_before);
        assert_eq!(strength_events, strength_events_before);

        let (catalog, mut dead_owner) = gremlin_merc_turn_fixture(0, 0);
        dead_owner.monsters_mut()[0].loop_pos = 2;
        dead_owner.monsters_mut()[0].hp = 1;
        dead_owner.monsters_mut()[0]
            .powers
            .set(PowerId::Strength, SlotWire::Int, i32::MAX);
        dead_owner.powers.set(PowerId::Thorns, SlotWire::Int, 1);
        monster_act(&mut dead_owner, &catalog, 0, &mut Vec::new()).unwrap();
        assert_eq!(dead_owner.monsters.len(), 3);
        assert_eq!(
            dead_owner.monsters[0].powers.value(PowerId::Strength),
            i32::MAX
        );
    }

