    #[test]
    fn disintegration_late_terminal_damage_preserves_current_turn_counters() {
        let (catalog, mut blocked) = knowledge_demon_state_at(1, (6, 0, 0, 0));
        blocked.monsters_mut()[0].hp = 0;
        blocked.block = 9;
        blocked.hp = 20;
        blocked.max_hp = 20;
        blocked.history.plays_this_turn = 7;
        let mut blocked_events = Vec::new();
        end_player_turn(&mut blocked, &catalog, &mut blocked_events).unwrap();
        assert!(blocked_events.iter().any(|event| matches!(
            event,
            Event::PlayerDamaged {
                blocked: 6,
                hp_lost: 0,
                hp: 20
            }
        )));
        assert_eq!(blocked.hp, 20);
        assert_eq!(blocked.history.plays_this_turn, 0);

        let (catalog, mut partial) = knowledge_demon_state_at(1, (6, 0, 0, 0));
        partial.monsters_mut()[0].hp = 0;
        partial.block = 2;
        partial.hp = 20;
        partial.max_hp = 20;
        let mut partial_events = Vec::new();
        end_player_turn(&mut partial, &catalog, &mut partial_events).unwrap();
        assert!(partial_events.iter().any(|event| matches!(
            event,
            Event::PlayerDamaged {
                blocked: 2,
                hp_lost: 4,
                hp: 16
            }
        )));

        let (catalog, mut inferno) = knowledge_demon_state_at(1, (6, 0, 0, 0));
        inferno.hp = 100;
        inferno.max_hp = 100;
        inferno.powers.set(PowerId::Inferno, SlotWire::Int, 3);
        inferno.powers.set(PowerId::InfernoSelf, SlotWire::Int, 1);
        assert!(
            inferno
                .fanouts
                .set_after_player_turn_start_order(&[PowerId::Inferno])
        );
        let mut inferno_events = Vec::new();
        end_player_turn(&mut inferno, &catalog, &mut inferno_events).unwrap();
        let player_damage = inferno_events
            .iter()
            .position(|event| matches!(event, Event::PlayerDamaged { hp_lost: 6, .. }))
            .unwrap();
        let inferno_damage = inferno_events
            .iter()
            .position(|event| matches!(event, Event::MonsterDamaged { unblocked: 3, .. }))
            .unwrap();
        let enemy_move = inferno_events
            .iter()
            .position(|event| matches!(event, Event::MonsterMoved { .. }))
            .unwrap();
        assert!(player_damage < inferno_damage && inferno_damage < enemy_move);
        assert!(
            crate::engine::admission::IMPLEMENTED_RELICS
                .contains(&crate::ids::RelicId::RelicCentennialPuzzle)
        );

        let (catalog, mut lethal) = knowledge_demon_state_at(1, (6, 0, 0, 0));
        lethal.monsters_mut()[0].hp = 0;
        lethal.hp = 5;
        lethal.max_hp = 20;
        lethal.history.plays_this_turn = 7;
        let mut events = Vec::new();
        end_player_turn(&mut lethal, &catalog, &mut events).unwrap();
        assert_eq!(lethal.hp, 0);
        assert!(lethal.history.over);
        assert_eq!(
            lethal.history.plays_this_turn, 7,
            "terminal ordinary callbacks skip the post-Hook counter rollover"
        );
        assert!(matches!(
            events.last(),
            Some(Event::CombatOver { player_won: false })
        ));
    }

    #[test]
    fn knowledge_demon_public_rootless_and_late_suffix_refusals_are_atomic() {
        let (catalog, mut rootless) = knowledge_demon_state_at(0, (0, 0, 0, 0));
        end_player_turn(&mut rootless, &catalog, &mut Vec::new()).unwrap();
        assert!(kd_pending_is_exact(&rootless));
        assert!(!matches!(
            rootless.frames.as_slice().first(),
            Some(crate::frame::Frame::ActionReplay { .. })
        ));
        let rootless_before = rootless.clone();
        let mut events = Vec::new();
        assert_eq!(
            crate::engine::apply_action_into(
                &rootless,
                &catalog,
                &crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(0),
                },
                &mut events,
            ),
            // A rootless Knowledge Demon pending publishes no legal answer at
            // all, so this is a legality refusal and says so since #2473.
            Err(EngineRefusal::ActionNotLegal("public action legality"))
        );
        assert_eq!(rootless, rootless_before);
        assert!(events.is_empty());

        let (catalog, mut predecessor) = knowledge_demon_state_at(0, (0, 0, 0, 0));
        predecessor.turn = i16::MAX;
        let parked = public_kd_action(&predecessor, &catalog, crate::engine::Action::EndTurn);
        let parked_before = parked.clone();
        let rng_before = parked.rng.clone();
        let mut events = Vec::new();
        assert_eq!(
            crate::engine::apply_action_into(
                &parked,
                &catalog,
                &crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(0),
                },
                &mut events,
            ),
            Err(EngineRefusal::CounterOverflow("turn"))
        );
        assert_eq!(parked, parked_before);
        assert_eq!(parked.rng, rng_before);
        assert!(events.is_empty());

        let (catalog, mut late_end) = knowledge_demon_state_at(1, (0, 1, 0, 0));
        late_end.monsters_mut()[0].loop_pos = 1;
        late_end.turn = i16::MAX;
        let before = late_end.clone();
        let rng_before = late_end.rng.clone();
        let mut events = Vec::new();
        assert_eq!(
            crate::engine::apply_action_into(
                &late_end,
                &catalog,
                &crate::engine::Action::EndTurn,
                &mut events,
            ),
            Err(EngineRefusal::CounterOverflow("turn"))
        );
        assert_eq!(late_end, before);
        assert_eq!(late_end.rng, rng_before);
        assert!(events.is_empty());
    }

    #[test]
    fn knowledge_demon_boundary_rejects_malformed_counter_choice_frame_and_roster() {
        let (catalog, state) = knowledge_demon_state_at(0, (0, 0, 0, 0));
        let parked = public_kd_action(&state, &catalog, crate::engine::Action::EndTurn);
        let canonical = crate::boundary::HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let enemy_frame = canonical
            .continuations
            .iter()
            .position(|frame| frame.frame_type == crate::frame::FrameKind::EnemyPhase.as_str())
            .unwrap();

        let mut malformed = Vec::new();
        let mut low_hp = canonical.clone();
        low_hp.monsters[0].insert("hp".to_owned(), serde_json::json!(379));
        low_hp.monsters[0].insert("max_hp".to_owned(), serde_json::json!(379));
        malformed.push(low_hp);
        let mut counter = canonical.clone();
        counter.monsters[0].insert("curse_counter".to_owned(), serde_json::json!(4));
        malformed.push(counter);
        let mut options = canonical.clone();
        options.player.insert(
            "enemy_pending".to_owned(),
            serde_json::json!(["KD_CURSE", ["MIND_ROT", "DISINTEGRATION"], 0, []]),
        );
        malformed.push(options);
        let mut substituted = canonical.clone();
        substituted.player.insert(
            "enemy_pending".to_owned(),
            serde_json::json!(["KD_CURSE", ["DISINTEGRATION", "WASTE_AWAY"], 0, []]),
        );
        malformed.push(substituted);
        let mut stage = canonical.clone();
        stage.continuations[enemy_frame]
            .fields
            .insert("stage".to_owned(), serde_json::json!(1));
        stage.player.insert(
            "enemy_pending".to_owned(),
            serde_json::json!(["KD_CURSE", ["DISINTEGRATION", "MIND_ROT"], 1, []]),
        );
        malformed.push(stage);
        let mut tail = canonical.clone();
        tail.continuations[enemy_frame]
            .fields
            .insert("remaining_uids".to_owned(), serde_json::json!([0]));
        tail.player.insert(
            "enemy_pending".to_owned(),
            serde_json::json!(["KD_CURSE", ["DISINTEGRATION", "MIND_ROT"], 0, [0]]),
        );
        malformed.push(tail);
        let mut mixed = canonical.clone();
        mixed
            .continuations
            .push(mixed.continuations[enemy_frame].clone());
        malformed.push(mixed);
        let mut extra_roster = canonical.clone();
        extra_roster.monsters.push(extra_roster.monsters[0].clone());
        malformed.push(extra_roster);
        let mut rootless = canonical.clone();
        rootless.continuations.remove(0);
        malformed.push(rootless);

        for document in malformed {
            let catalog = crate::boundary::HotBoundary::catalog_from_canonical(&document);
            assert!(
                catalog
                    .and_then(|catalog| crate::boundary::HotBoundary::from_canonical(
                        &document, &catalog
                    )
                    .map(|_| catalog))
                    .is_err(),
                "malformed KD boundary document was admitted: {}",
                document.canonical_json()
            );
        }

        let (catalog, state) = knowledge_demon_state_at(2, (6, 0, 3, 0));
        let parked = public_kd_action(&state, &catalog, crate::engine::Action::EndTurn);
        let mut bad_private =
            crate::boundary::HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        bad_private
            .player
            .insert("cards_played_this_turn".to_owned(), serde_json::json!(-1));
        let rebuilt = crate::boundary::HotBoundary::catalog_from_canonical(&bad_private).unwrap();
        assert!(crate::boundary::HotBoundary::from_canonical(&bad_private, &rebuilt).is_err());
    }
